            ManualBlock(ManualKind.Heading, "Drums"),
            ManualBlock(ManualKind.Bullet, "**Hexbeat** - synthesized drums in the style of the classic small boxes."),
            ManualBlock(ManualKind.Bullet, "**Genesis** - the big drum box, with a kick that ducks its own bus."),
            ManualBlock(ManualKind.Bullet, "**Forage** - a sample drum machine with thirteen pads for your own sounds, each with a filter and envelope."),
            ManualBlock(ManualKind.Bullet, "**Dice** - a loop slicer with chance on every slice."),
            ManualBlock(ManualKind.Heading, "Samples and voice"),
            ManualBlock(ManualKind.Bullet, "**Pollen** - granular clouds from a file or the live input."),
            ManualBlock(ManualKind.Bullet, "**Mosaic** - a multisample player for SoundFonts and your own samples."),
            ManualBlock(ManualKind.Bullet, "**Molt** - sing a take in and the piano roll tunes it."),
            ManualBlock(ManualKind.Bullet, "**Diction** - a vocal synthesizer trained on your voice and taken to the next level."),
            ManualBlock(ManualKind.Bullet, "**Cipher** - a vocoder."),
            ManualBlock(ManualKind.Heading, "Modular"),
            ManualBlock(ManualKind.Bullet, "**Nexus** - a modular synth whose modules are the other machines."),
            ManualBlock(ManualKind.Heading, "Audio"),
            ManualBlock(ManualKind.Bullet, "**Bias** - a four-track for recordings, with four lanes per cell. A recording made over the song is cut at the scene lines. Its patches are tape types (cassette, reel, telephone, etc.) that colour the sound on the way out."),
            ManualBlock(ManualKind.Heading, "Velocity"),
            ManualBlock(ManualKind.Para, "Every machine plays quieter the softer you play. A note at half velocity is 12 dB down, at a quarter it's 24 dB down, and the softest notes are close to silent. **vel** on each panel sets how much velocity matters, and at zero every note plays at full volume, like a real organ. On Genesis, Resonance and Dice, **accent** does the same job."),
            ManualBlock(ManualKind.Para, "If a controller plays too loud or too soft, fix it with **velocity** in the MIDI window instead of on every machine."),
            ManualBlock(ManualKind.Heading, "Patches"),
            ManualBlock(ManualKind.Para, "Every machine comes with patches, sorted by family. The patch name at the top of the panel opens the browser. Add your own patches in the tab at the end."),
        ), listOf(
            ManualSection("Aviary", "Modelled birdsong: a syrinx with two voices, a throat and a beak, singing whistles, chirps, trills, warbles and calls in time with the song.", listOf(
                ManualBlock(ManualKind.Para, "Aviary doesn't play recordings. A bird sings from its syrinx, deep in its chest: two sources, one in each branch of its airway, each a pair of folds that start to swing once the air pressure passes a threshold and settle at a size set by how far past it the pressure goes. The two can sing at once, so one bird can sing two notes. Above them are a short trachea, a throat the bird tunes to the note it's singing, and the beak, opened wider for higher notes."),
                ManualBlock(ManualKind.Para, "Hold a note and a bird sings a song around it, two octaves up, in time with the tempo. Let go and it stops."),
                ManualBlock(ManualKind.Heading, "Song"),
                ManualBlock(ManualKind.Bullet, "**pattern** - **whistle** (one held note, sliding into it), **chirp** (a syllable that sweeps, then a gap), **trill** (fast short syllables), **warble** (wandering about the note), **call** (two notes a third apart, the rest of the flock answering in the gaps) or **chorus** (each bird in the flock singing its own song at its own pace)."),
                ManualBlock(ManualKind.Bullet, "**tune** - in cents."),
                ManualBlock(ManualKind.Bullet, "**rate** - syllables a beat: **1**, **2**, **4**, **8** or **16**."),
                ManualBlock(ManualKind.Bullet, "**length** - how much of each syllable's slot is sung."),
                ManualBlock(ManualKind.Bullet, "**sweep** - how far each syllable slides, in semitones: falling from above, or rising from below when it's negative."),
                ManualBlock(ManualKind.Heading, "Voice"),
                ManualBlock(ManualKind.Bullet, "**rasp** - the folds slapping shut: harsher, with more overtones."),
                ManualBlock(ManualKind.Bullet, "**two** - the syrinx's other side singing at once."),
                ManualBlock(ManualKind.Bullet, "**interval** - how far above (or below) the other side sings."),
                ManualBlock(ManualKind.Bullet, "**breath** - air in the sound."),
                ManualBlock(ManualKind.Bullet, "**throat** - how much the throat, tuned to the note, rings."),
                ManualBlock(ManualKind.Bullet, "**beak** - how wide the beak opens: wider is brighter."),
                ManualBlock(ManualKind.Heading, "Flock"),
                ManualBlock(ManualKind.Bullet, "**flock** - how many birds sing each note."),
                ManualBlock(ManualKind.Bullet, "**spread** - how far apart they sit, left to right."),
                ManualBlock(ManualKind.Bullet, "**space** - how far off they are: quieter and duller."),
                ManualBlock(ManualKind.Bullet, "**velocity**, **octave**, **bend** and **volume**."),
                ManualBlock(ManualKind.Para, "Pressure blows harder: louder and fuller. The mod wheel widens the sweeps."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "The patterns follow the tempo, so a chirp at **4** a beat lands on the sixteenths."),
                ManualBlock(ManualKind.Bullet, "**Call and Answer** needs at least two birds: one calls, the other answers."),
            )),
            ManualSection("Bias", "A four-track: recordings arranged along the song, four lanes at a time.", listOf(
                ManualBlock(ManualKind.Para, "Bias is the audio track. Instead of notes, each of its cells plays recordings, four lanes of them at once. Mute two takes to pick the third, or unmute a second lane to double a vocal."),
                ManualBlock(ManualKind.Heading, "How it fits the song"),
                ManualBlock(ManualKind.Para, "A Bias cell is a normal clip, so there's no separate timeline. A take recorded across four scenes becomes four cells that all point at the same file, each starting at a different place. Nothing is copied, and it works the same in the arranger and the clip launcher."),
                ManualBlock(ManualKind.Para, "A cell lasts its bars times the scene's repeats and plays straight through, so a scene played twice plays one continuous take."),
                ManualBlock(ManualKind.Heading, "Recording"),
                ManualBlock(ManualKind.Para, "Tap the red dot next to a lane, arm record on the transport and press play. The song plays while you record, and the other lanes keep playing.", "Click the red dot next to a lane, arm record on the transport and press play. The song plays while you record, and the other lanes keep playing."),
                ManualBlock(ManualKind.Para, "When you stop, the take is cut at the scene lines, one cell per scene, with new cells in scenes where the track was empty. The whole recording also stays in the sound library, so you can undo the split and place it by hand."),
                ManualBlock(ManualKind.Para, "One lane records at a time. If the recorder fell behind and left a gap in the take, it isn't split and is kept whole instead."),
                ManualBlock(ManualKind.Heading, "The editor"),
                ManualBlock(ManualKind.Para, "Opening a cell shows the four lanes:"),
                ManualBlock(ManualKind.Bullet, "drag a lane's **body** to move where it starts"),
                ManualBlock(ManualKind.Bullet, "drag either **end, top half** to trim it"),
                ManualBlock(ManualKind.Bullet, "drag either **end, bottom half** to fade it in or out. Fading one lane out while another fades in makes a crossfade"),
                ManualBlock(ManualKind.Bullet, "tap the number on the left to **mute** a lane, and the dot below it to arm it", "click the number on the left to **mute** a lane, and the dot below it to arm it"),
                ManualBlock(ManualKind.Para, "On a take longer than its cell, both halves of the right edge trim, so you have an end to fade."),
                ManualBlock(ManualKind.Heading, "Levels, mutes and automation"),
                ManualBlock(ManualKind.Para, "Each lane's level and mute are normal machine parameters, so you can automate them, map them to a controller and record them."),
                ManualBlock(ManualKind.Heading, "Tempo"),
                ManualBlock(ManualKind.Para, "**tempo › takes** chooses whether a take plays at the speed it was recorded at or follows the song's tempo. When it follows, it's time-stretched without changing pitch. When it doesn't, it starts on the bar and plays at its own speed, and the cell turns amber."),
                ManualBlock(ManualKind.Para, "A loop added from the library with **audio…** gets its tempo worked out the way Dice does it, from its length and where its hits fall. It loops round to fill the cell, and if its tempo isn't the scene's, **tempo › takes** switches to follow so it plays at the song's tempo."),
                ManualBlock(ManualKind.Heading, "Playing a guitar through it"),
                ManualBlock(ManualKind.Para, "**monitor**, under **tempo**, sends the input to this track's output before its effects, so you can hear an amp in the first insert slot while you play. The recording stays dry, so you can change the amp later."),
                ManualBlock(ManualKind.Para, "Monitor is off by default. Use headphones or an interface, since on the phone speaker it will feed back.", "Monitor is off by default. Use headphones or an interface, since on the computer speaker it will feed back."),
                ManualBlock(ManualKind.Para, "**printed in**, next to it, is for effects you want recorded into the take. They run before the recorder, so they're stuck in there. These are the same two input slots the recording window shows."),
                ManualBlock(ManualKind.Heading, "Flattening"),
                ManualBlock(ManualKind.Para, "**comp** mixes the four lanes (with their levels, mutes and fades) into one file in lane 1. The patch's tape colour isn't baked in, and the original recordings stay in the library."),
                ManualBlock(ManualKind.Heading, "Patches"),
                ManualBlock(ManualKind.Para, "Bias's patches are recording media (cassette, reel, telephone, wax cylinder, etc.). They colour the sound on playback but never change the recordings, so try them freely. **Init** plays the file back untouched."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Record first and decide later. The patch, tempo, fades and even the split can all change afterwards without touching the file."),
                ManualBlock(ManualKind.Bullet, "Takes can be long. Anything over two minutes is converted once in the background and streamed from storage, so a full-length vocal costs about the same as a short one."),
            )),
            ManualSection("Brazen", "Modelled brass, from trumpet to tuba, or a whole section.", listOf(
                ManualBlock(ManualKind.Para, "Brazen is a model of a brass instrument: lips buzzing against a tube with a bell on the end."),
                ManualBlock(ManualKind.Heading, "Blowing"),
                ManualBlock(ManualKind.Bullet, "**pressure** - how hard you blow. It's the main control, and it isn't a volume knob. Too little and nothing sounds, more and the note starts, more again and it gets brighter until it overblows."),
                ManualBlock(ManualKind.Bullet, "**breath** - air noise."),
                ManualBlock(ManualKind.Bullet, "**bite** and **tension** - how tight the lips are. Together with pressure they decide which note of the tube you land on, like a real player's embouchure."),
                ManualBlock(ManualKind.Bullet, "**lipdamp** - how damped the lips are."),
                ManualBlock(ManualKind.Heading, "The tube"),
                ManualBlock(ManualKind.Bullet, "**size** - how long the tube is, from trumpet to tuba."),
                ManualBlock(ManualKind.Bullet, "**bell** - how the tube flares, which changes how bright it is."),
                ManualBlock(ManualKind.Bullet, "**loss** - how much energy the tube loses."),
                ManualBlock(ManualKind.Bullet, "**brass** - the blare you get when brass is played loud."),
                ManualBlock(ManualKind.Heading, "A section"),
                ManualBlock(ManualKind.Para, "**lock** and **drift** turn one player into several who are nearly together. **growl** and **growlrate** add a growl into the mouthpiece."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Big instruments need more pressure. A tuba is blown hard."),
                ManualBlock(ManualKind.Bullet, "Automate pressure across a note for swells. It changes the tone as well as the level."),
                ManualBlock(ManualKind.Bullet, "Start from a patch and change **size** first."),
            )),
            ManualSection("Chanter", "Modelled bagpipes and hurdy-gurdy: drones that go on between notes, grace notes, and a wheel whose loose bridge buzzes in time.", listOf(
                ManualBlock(ManualKind.Para, "Chanter doesn't play recordings. A bagpipe here is a chanter, a conical pipe with a double reed (the same model as Timber's), and drones, narrow pipes with single reeds, all blown from a bag. The bag keeps the pressure up, so the drones carry on between notes and for a while after the last one. A chanter can't be tongued, so pipers set notes apart with grace notes: a quick, high note before each one."),
                ManualBlock(ManualKind.Para, "A hurdy-gurdy is a rosined wheel that bows its strings for as long as it turns: melody strings stopped by the keys, drone strings tuned to the key, and the trompette, whose bridge (the dog) sits loose, so once the wheel turns fast enough it hops and buzzes against the soundboard. Players push the wheel on the beat to make it buzz in rhythm."),
                ManualBlock(ManualKind.Heading, "Pipes"),
                ManualBlock(ManualKind.Bullet, "**model** - **highland** pipes (two tenor drones on the key and a bass an octave down), **smallpipes** (a quiet, closed chanter that stops for a moment between notes, drones on the key, the fifth and the octave), **gaita** (one bass drone and a sweet chanter) or **hurdy-gurdy**."),
                ManualBlock(ManualKind.Bullet, "**tune** - in cents."),
                ManualBlock(ManualKind.Bullet, "**tonic** - the key the drones are tuned to."),
                ManualBlock(ManualKind.Bullet, "**drones** - how loud the drones are."),
                ManualBlock(ManualKind.Bullet, "**bag** - how many seconds the drones go on after the last key is let go. On the hurdy-gurdy, how long the wheel keeps turning."),
                ManualBlock(ManualKind.Bullet, "**reed** - a soft or hard chanter reed: darker or brighter."),
                ManualBlock(ManualKind.Bullet, "**grace** - a quick high note before each note, in milliseconds. At 0, none."),
                ManualBlock(ManualKind.Bullet, "**drift** - how much the bag's pressure wanders as it's squeezed."),
                ManualBlock(ManualKind.Bullet, "**air** - breath in the reeds."),
                ManualBlock(ManualKind.Heading, "Hurdy-gurdy"),
                ManualBlock(ManualKind.Bullet, "**crank** - how fast the hurdy-gurdy's wheel turns. Faster is louder."),
                ManualBlock(ManualKind.Bullet, "**rosin** - how hard the rosin grips the strings: smooth or gritty."),
                ManualBlock(ManualKind.Bullet, "**dog** - how loud the trompette's buzz is."),
                ManualBlock(ManualKind.Bullet, "**threshold** - how fast the wheel must turn before the dog buzzes."),
                ManualBlock(ManualKind.Bullet, "**coup** - pushes the wheel **1**, **2** or **4** times a beat, in time with the song, so the dog buzzes in rhythm. **off** for none."),
                ManualBlock(ManualKind.Bullet, "**velocity**, **octave**, **bend** and **volume**."),
                ManualBlock(ManualKind.Para, "Pressure, or the mod wheel, squeezes the bag (a little louder and sharper) or pushes the hurdy-gurdy's wheel, so you can make the dog buzz by hand."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Both play one note at a time: the last key held sounds."),
                ManualBlock(ManualKind.Bullet, "Hold a note on a **drones** preset and let go: the drones carry on."),
                ManualBlock(ManualKind.Bullet, "On **Hurdy-Gurdy**, lean on a key or push the mod wheel to buzz."),
            )),
            ManualSection("Cipher", "A vocoder, where you can rearrange which bands drive which.", listOf(
                ManualBlock(ManualKind.Para, "Cipher is a vocoder. It splits one sound into frequency bands and puts that shape onto another sound. You can also change which band controls which, and that's where the unusual sounds come from."),
                ManualBlock(ManualKind.Heading, "The two sides"),
                ManualBlock(ManualKind.Para, "The **modulator** is the sound being analysed, usually a voice from the live input. The **carrier** is the sound being shaped. Cipher has its own carrier built in (an oscillator with **detune**, **pw**, **sub**, **noise** and **cardrive**), so you don't need a second track."),
                ManualBlock(ManualKind.Heading, "The bands"),
                ManualBlock(ManualKind.Bullet, "**bands** - how many. Fewer sounds robotic but clear, and more is smoother but less clear."),
                ManualBlock(ManualKind.Bullet, "**low**, **high** and **slope** - the range the bands cover and how they're spread over it."),
                ManualBlock(ManualKind.Bullet, "**q** - how narrow each band is."),
                ManualBlock(ManualKind.Heading, "The band map"),
                ManualBlock(ManualKind.Para, "Normally band 1 drives band 1. **remap** changes that: reverse the order so bright sounds come out dark, spread it wider, **freeze** the current shape while the carrier keeps playing, or **smear** neighbouring bands together."),
                ManualBlock(ManualKind.Para, "**role**, **dry** and **wet** set which side is which and how much of each you hear. **unvoiced** handles consonants so the words stay clear."),
                ManualBlock(ManualKind.Para, "**attack**, **release** and **smear** set how quickly each band follows. Fast is clear but can chatter, and slow is smooth but can slur."),
                ManualBlock(ManualKind.Heading, "Modulation"),
                ManualBlock(ManualKind.Para, "Two envelopes and two LFOs that can sync to the tempo, into eight matrix rows."),
                ManualBlock(ManualKind.Para, "Three sources come from the modulator itself: its level (**loud**), its brightness (**bright**) and its **pitch** (pitch needs **follow** on). For example, loudness on **smear** tightens the words up as they get louder."),
                ManualBlock(ManualKind.Para, "The destinations are the map controls (**shift**, **stretch**, **remap**, **freeze**, **smear**, **q** and the band edges) plus the carrier's pitch and mix."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Turn **unvoiced** up until the words are clear, then back off until it stops hissing."),
                ManualBlock(ManualKind.Bullet, "Freeze on a vowel and play chords under it for a vocal pad."),
                ManualBlock(ManualKind.Bullet, "Use fewer bands than you'd think. Sixteen usually beats forty for words."),
            )),
            ManualSection("Cumulus", "Pads built from a spectrum of partials.", listOf(
                ManualBlock(ManualKind.Para, "Cumulus doesn't use normal oscillators. You describe a spectrum (which partials, how loud, how wide), it builds a wavetable from that and plays it. It's for pads, drones and huge sounds."),
                ManualBlock(ManualKind.Heading, "How it works"),
                ManualBlock(ManualKind.Para, "Each partial has a width instead of being a single frequency, which makes it lush without needing a chorus."),
                ManualBlock(ManualKind.Para, "Building the table takes a moment, so it happens in the background whenever you change the spectrum. Everything from **morph** on changes straight away."),
                ManualBlock(ManualKind.Heading, "Spectrum controls"),
                ManualBlock(ManualKind.Bullet, "**bandwidth** and **bwscale** - how wide each partial is, and whether the high ones are wider than the low ones. This is the main control."),
                ManualBlock(ManualKind.Bullet, "**tilt** - the balance of bass to treble."),
                ManualBlock(ManualKind.Bullet, "**stretch** - pushes the partials off whole-number multiples, like a piano's top end or a bell. A little goes a long way."),
                ManualBlock(ManualKind.Bullet, "**comb** and **every** - cut regular notches in the spectrum."),
                ManualBlock(ManualKind.Bullet, "**vowel** and its amount - shape the spectrum towards a vowel."),
                ManualBlock(ManualKind.Bullet, "**odd** - odd against even partials. All odd sounds like a clarinet, and all even sounds hollow."),
                ManualBlock(ManualKind.Bullet, "**seed** - the random phases. Change it for a different take on the same sound."),
                ManualBlock(ManualKind.Heading, "Playing controls"),
                ManualBlock(ManualKind.Para, "**detune**, **spread** and **width** stack copies, and **drift**, **driftrate** and **scatter** keep the sound moving. Then there's a filter with its own envelope, an amp envelope and drive."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Use long attacks and releases and let the notes overlap."),
                ManualBlock(ManualKind.Bullet, "Move **morph** while playing instead of the spectrum controls, since morph changes straight away."),
            )),
            ManualSection("Dice", "A loop slicer with chance on every slice.", listOf(
                ManualBlock(ManualKind.Para, "Dice cuts a loop into slices and plays them back, with a chance of something different happening on each one. It's good for breaks."),
                ManualBlock(ManualKind.Heading, "Slicing"),
                ManualBlock(ManualKind.Para, "**slices** sets how many pieces, and **cut** sets where they fall, from even divisions to the loop's own hits. Each slice has its own **level**, **pan**, **pitch**, **decay** and **dir**."),
                ManualBlock(ManualKind.Heading, "The dice"),
                ManualBlock(ManualKind.Para, "Five chances, rolled on every slice:"),
                ManualBlock(ManualKind.Bullet, "**swap** - play a different slice."),
                ManualBlock(ManualKind.Bullet, "**reverse** - play it backwards."),
                ManualBlock(ManualKind.Bullet, "**stutter**, with **stutterdiv** - repeat part of it."),
                ManualBlock(ManualKind.Bullet, "**drop** - play nothing."),
                ManualBlock(ManualKind.Bullet, "**jump**, with **jumprange** - skip to somewhere else in the loop and carry on."),
                ManualBlock(ManualKind.Para, "**seed** decides the rolls and **hold** freezes them. Turn the dice up until you hear something you like, then hold it."),
                ManualBlock(ManualKind.Heading, "Playing"),
                ManualBlock(ManualKind.Para, "The slices sit on the grid like drum sounds, so you can reorder the loop by writing a pattern. **rate**, **gate**, **pitch**, **fine** and **accent** control playback, followed by a filter and drive."),
                ManualBlock(ManualKind.Heading, "Tempo"),
                ManualBlock(ManualKind.Para, "**plays at** decides whether the loop keeps its own tempo or follows the song. On **song**, the default, each slice is time-stretched to the song's tempo without changing its pitch, so a 90 bpm break fits a 126 bpm song with no gaps. **pitch** then only changes the pitch, and **rate** still speeds it up or slows it down."),
                ManualBlock(ManualKind.Para, "**bars** is how long the loop is, which is how its tempo is worked out. On **auto** it's guessed from the loop's length and where its hits fall, and the line under the loop's name says what it found, like \"2 bars at 90 bpm\". If that's wrong, set it yourself."),
                ManualBlock(ManualKind.Para, "A slice played backwards isn't stretched. It's sped up or slowed down like tape, so it goes a little out of tune when the song is far from the loop's tempo."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Unheld, Dice changes every bar. Held on a good roll, it becomes a part."),
                ManualBlock(ManualKind.Bullet, "For a break that swings, cut on the hits instead of evenly."),
                ManualBlock(ManualKind.Bullet, "The seed makes it repeatable, so an export sounds like what you arranged."),
            )),
            ManualSection("Diction", "A vocal synthesizer trained on your voice and taken to the next level.", listOf(
                ManualBlock(ManualKind.Para, "Diction sings. It's one singer, so it plays one note at a time, and it slides from note to note while you hold them. Give its notes words and it sings them. A note without words sings the **vowel** knob's vowel. Turn on **harmony** and it sings chords, and **singers** makes it a choir."),
                ManualBlock(ManualKind.Heading, "Words"),
                ManualBlock(ManualKind.Para, "Open the lane under the grid and pick **words**. Tap a note to type the words from that note on, a syllable a note:", "Open the lane under the grid and pick **words**. Click a note to type the words from that note on, a syllable a note:"),
                ManualBlock(ManualKind.Bullet, "`hel-lo world` sings *hel* on the first note, *lo* on the next and *world* on the third. A hyphen joins syllables into one word, so it's said as the word, not as two."),
                ManualBlock(ManualKind.Bullet, "`-` on its own holds the last vowel over another note."),
                ManualBlock(ManualKind.Bullet, "`_` is a note with no words."),
                ManualBlock(ManualKind.Bullet, "Put sounds in brackets to say a word your own way: `[t ah m ey t ow]`."),
                ManualBlock(ManualKind.Para, "Under the words is what each note will sing, as sounds. If a word comes out wrong, write it in brackets."),
                ManualBlock(ManualKind.Para, "To put words on some notes only, select them first and tap one of them in the lane: the line goes over the selected notes, and the others keep theirs. Each note shows its syllable on the roll too.", "To put words on some notes only, select them first and click one of them in the lane: the line goes over the selected notes, and the others keep theirs. Each note shows its syllable on the roll too."),
                ManualBlock(ManualKind.Para, "Consonants come before the vowel at the start of a note, and the ones after it when the note ends."),
                ManualBlock(ManualKind.Para, "A chord gets one syllable, on its top note. With **harmony** on, the rest of the chord sings it too."),
                ManualBlock(ManualKind.Heading, "The voice"),
                ManualBlock(ManualKind.Bullet, "**voice** - **built-in**, or a voice recorded in the Sound window's **voice** tab. A recorded voice sings in the voice that sang it, with its consonants as long as they were sung."),
                ManualBlock(ManualKind.Bullet, "**vowel** - oo, oh, ah, eh or ee, from the back of the mouth to the front. In between, it sings the vowel between them, so turning it moves through the vowels."),
                ManualBlock(ManualKind.Bullet, "**formant** - the size of the throat, without changing the pitch. Down is bigger and darker, up is smaller and brighter. Low notes with the formant down sound like a man, high notes with it up like a woman or a child, and in between is neither."),
                ManualBlock(ManualKind.Bullet, "**track** - moves the throat with the pitch. Up, high notes get a smaller throat, and all the way up it's a chipmunk an octave up. Below zero it goes the other way."),
                ManualBlock(ManualKind.Bullet, "**source** and **throat** - a recorded voice crossed with the built-in one. **source** swaps the singer's vocal folds for the built-in voice's: the singer's throat, sung by a perfectly steady buzz. **throat** swaps the singer's throat for the built-in voice's, which follows the words. Both up is the built-in voice singing with the recorded voice's timing. Consonants like S and T stay the singer's."),
                ManualBlock(ManualKind.Bullet, "**talk** - another track's sound mouths the words, like a talkbox. Play a synth on that track: Diction's notes only say when the words come, and what you hear is the synth at its own pitch, shaped into the words by the throat (yours with a recorded voice, or the built-in one with **throat** up). The S's and T's still come from Diction, so the words are clearer than a real talkbox's. Turn the synth track's fader down to hear only the talking; Diction still hears it."),
                ManualBlock(ManualKind.Bullet, "**morph** - a second recorded voice to morph to, and how far. The throat moves from one voice's to the other's, sung by the first voice. Choosing a voice to morph to loads the first voice again, which takes a moment."),
                ManualBlock(ManualKind.Bullet, "**consonants** - how long the consonants take."),
                ManualBlock(ManualKind.Bullet, "**level** - how loud a recorded voice's consonants are against its vowels."),
                ManualBlock(ManualKind.Bullet, "**from…** - which of a recorded voice's takes each consonant is formed from: the one sung between **ah**s, **ee**s or **oo**s, or **word**, the one whose vowel is nearest the word's. Ah is usually the clearest. The window has a page each for stops, hisses, and hums and glides."),
                ManualBlock(ManualKind.Bullet, "**accent** - how the words are said. **prairie** is Canadian as it's spoken in Alberta, **central** is Canadian as in Ontario, and **american** is General American."),
                ManualBlock(ManualKind.Heading, "Character"),
                ManualBlock(ManualKind.Bullet, "**breath** - how much air is in the voice. In a recorded voice, how much of the singer's own breath is kept: down is clean, all the way up is as it was sung."),
                ManualBlock(ManualKind.Bullet, "**clean** - takes more breath out of a recorded voice's vowels than **breath** can. All the way up, a held vowel sounds almost like an instrument. It does nothing to the built-in voice or to the consonants."),
                ManualBlock(ManualKind.Bullet, "**whisper** - whispers the words instead of singing them."),
                ManualBlock(ManualKind.Bullet, "**effort** - soft to belted. Up is brighter and louder, down is softer."),
                ManualBlock(ManualKind.Bullet, "**rasp** - a rough voice."),
                ManualBlock(ManualKind.Bullet, "**growl** - a pulse skipped every other time: a crackle at first, a growl an octave down at the top."),
                ManualBlock(ManualKind.Bullet, "**singers** - how many sing: one, or a choir of up to six."),
                ManualBlock(ManualKind.Bullet, "**spread** - how unlike each other the singers are. Up, they're later, more out of tune, with throats of their own, and wider apart."),
                ManualBlock(ManualKind.Bullet, "**harmony** - off, or a chord sings the words on every note. Hold a note while you play others and they join it; let one go and it stops."),
                ManualBlock(ManualKind.Heading, "Expression"),
                ManualBlock(ManualKind.Bullet, "**vibrato** - **depth**, **rate** and **delay**. A singer holds a note straight for a moment before the vibrato comes in, and **delay** is how long. The mod wheel adds more."),
                ManualBlock(ManualKind.Bullet, "**drift** - how unsteady the voice is. It wanders a little on a held note and scoops up into a new one."),
                ManualBlock(ManualKind.Bullet, "**glide** - how long it takes to slide from one note to the next."),
                ManualBlock(ManualKind.Bullet, "**scoop** - how far below its note each note starts, on top of the drift's own. Below zero, each note falls into place from above."),
                ManualBlock(ManualKind.Para, "Then **attack**, **release** and **velocity**, the tuning, and the level."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Hold one note while you play the next and it slides there without starting again. Let go first and it sings the new note fresh."),
                ManualBlock(ManualKind.Bullet, "Let go of a note while holding another and it goes back to the one still held."),
                ManualBlock(ManualKind.Bullet, "For a different vowel on each note, lock **vowel** on the steps."),
            )),
            ManualSection("Draw", "Modelled free reeds: harmonicas, accordions, melodica, harmonium and the reeds that sound through pipes.", listOf(
                ManualBlock(ManualKind.Para, "Draw doesn't play recordings. Each note is a reed, a thin tongue of metal in a slot, blown by the air pressing on it. It starts slowly, settles on its note and stops when the air does, the way a real reed does. Blow harder and it gets brighter and louder while the pitch hardly moves."),
                ManualBlock(ManualKind.Para, "The accordion, harmonium, melodica and harmonicas were fitted to recordings of real ones, and the bandoneon to the one recording there was."),
                ManualBlock(ManualKind.Heading, "Reeds"),
                ManualBlock(ManualKind.Bullet, "**model** - the instrument. The harmonicas (**diatonic**, **chromatic**, **tremolo harp**, **octave harp**), **accordion**, **bandoneon**, **concertina**, **melodica**, **harmonium**, the reeds in pipes (**sheng**, **shō**, **khaen**) and the **pitch pipe**."),
                ManualBlock(ManualKind.Bullet, "**tune** - in cents."),
                ManualBlock(ManualKind.Bullet, "**set** - how far each reed rests from its slot. Closer speaks sooner and brighter, and chokes sooner when blown hard."),
                ManualBlock(ManualKind.Bullet, "**chamber** - the size of the space behind each reed. It changes how the reed starts and the colour of the note."),
                ManualBlock(ManualKind.Bullet, "**register** - which reeds each note sounds, as an accordion's register switches do. They're named by footage: 8′ sounds the note, 16′ an octave down and 4′ an octave up, and up to three 8′ reeds can sound together. **auto** is the instrument's own: two 8′ on an accordion, 16′ and 8′ on a bandoneon, 8′ and 4′ on a harmonium, one 8′ on the rest."),
                ManualBlock(ManualKind.Bullet, "**detune** - how far a note's 8′ reeds are tuned apart, in cents. At 0 they agree (dry); 10 to 15 beats gently (tremolo); 25 and more beats fast (a wet musette). With three, one sits on the note and the others either side. On a harmonium, two 8′ reeds a little apart are its celeste."),
                ManualBlock(ManualKind.Bullet, "**cassotto** - the 16′ and the first 8′ reeds speak into a tone chamber, which makes them mellower."),
                ManualBlock(ManualKind.Bullet, "**high**, **low** - where the register's 4′ and 16′ ranks sound, in semitones: an octave up and down to start with, or any interval, as an organ's mutation stops. A 4′ moved to +7 gives every note a bare fifth; +16 a tenth. They move the sheng's and khaen's extra pipes too."),
                ManualBlock(ManualKind.Para, "Reeds never quite agree, so a note on two or three reeds beats, each harmonic at its own speed. That's most of what makes an accordion sound like one."),
                ManualBlock(ManualKind.Heading, "Harmonicas"),
                ManualBlock(ManualKind.Para, "A harmonica hole has two reeds, one for blowing and one for drawing, with your mouth behind them. Draw models the mouth too: where your tongue sits changes the note, which is how a player bends."),
                ManualBlock(ManualKind.Bullet, "**key** - the harp's key, G up to F♯. A diatonic harp has every note of its key and bends to most of the rest."),
                ManualBlock(ManualKind.Bullet, "**playing** - **player** puts each note where a player would find it on the harp: on a hole as it is, or bent down from the hole above it. Notes a player can't bend to, overblows among them, sound on a reed of their own. **straight** plays every note on a reed of its own, so none are bent."),
                ManualBlock(ManualKind.Para, "The chromatic harp's reeds each sit behind a valve, so every note is a reed of its own. A tremolo harp sounds two reeds a note, tuned apart by **detune**; an octave harp sounds the note and the octave above."),
                ManualBlock(ManualKind.Para, "Pitch bend down on a diatonic harp played like a player bends the note with your tongue, as far as its hole will go: a lot on holes 2 and 3, a little on the others. Bend up, and on the notes that don't bend, moves the note instead."),
                ManualBlock(ManualKind.Heading, "Pipes"),
                ManualBlock(ManualKind.Para, "The sheng, shō and khaen sound each reed into a bamboo pipe, which rings with it and takes most of its edge off: they're close to pure. The khaen's reeds are heard in its wind chest too, so it's buzzier."),
                ManualBlock(ManualKind.Para, "On the shō, **playing** set to **player** gives each key its chord (aitake) where the shō has one, at the shō's own pitch, tuned in fifths from A: A, B, C, C♯, D, E, F♯, G, G♯ and the high A each have one. The other keys, and **straight**, play single pipes. Its pipes are never filed quite alike, so its chords shimmer."),
                ManualBlock(ManualKind.Para, "The register works on the sheng and khaen as well: 4′ adds the octave above."),
                ManualBlock(ManualKind.Heading, "Breath"),
                ManualBlock(ManualKind.Bullet, "**pressure** - how hard the reeds are blown, from gently to hard. Velocity and pressure from your keyboard blow harder still."),
                ManualBlock(ManualKind.Bullet, "**attack** - how long the breath or bellows take to come up, in ms."),
                ManualBlock(ManualKind.Bullet, "**release** - how long they take to stop, in ms."),
                ManualBlock(ManualKind.Bullet, "**air** - the air you hear: the breath, and the turbulence of the air through each reed. No breath or bellows is quite even, and the reeds wander a little with it."),
                ManualBlock(ManualKind.Bullet, "**shake** - the bellows turned back and forth, turns a second, as an accordion player shakes them. Each turn the sound dips and the other set of reeds speaks. Only on the accordion, bandoneon and concertina."),
                ManualBlock(ManualKind.Bullet, "**sync** - turns the bellows on the song's grid instead: quarters, eighths, triplets, sixteenths and so on, in time with the song."),
                ManualBlock(ManualKind.Bullet, "**from track** - another track's sound blows the reeds: they speak as loud as it plays and fall silent when it stops. Hold the notes and let the other track play them in."),
                ManualBlock(ManualKind.Para, "The accordion, bandoneon, concertina and harmonium share one bellows, so a big chord lowers its pressure a little."),
                ManualBlock(ManualKind.Para, "Pressure added while a note is held, from aftertouch or a key that sends its own, makes that note louder and brighter."),
                ManualBlock(ManualKind.Heading, "Hands"),
                ManualBlock(ManualKind.Bullet, "**cup** - your hands round the harp, from open to closed. Closed is dark and hollow. The mod wheel closes them further, for a wah."),
                ManualBlock(ManualKind.Bullet, "**vibrato** - a throat vibrato. Like a player's, it's mostly in the level and no two cycles are quite alike."),
                ManualBlock(ManualKind.Bullet, "**rate** - its speed, in Hz."),
                ManualBlock(ManualKind.Bullet, "**words** - how much a clip's words shape a harmonica, as a talking-harp player does. Type words into the notes as you would for Diction: the vowels colour the sound and move the player's tongue, so a note that can bend bends with them, and m, b, p and w close the hands."),
                ManualBlock(ManualKind.Heading, "Out"),
                ManualBlock(ManualKind.Bullet, "**voices** - how many notes at once, up to eight."),
                ManualBlock(ManualKind.Bullet, "**velocity** - how much playing harder blows harder."),
                ManualBlock(ManualKind.Bullet, "**octave**, **bend** - the octave, and the pitch bend range in semitones."),
                ManualBlock(ManualKind.Bullet, "**volume**."),
            )),
            ManualSection("Fathom", "Modelled water and weather: bubbles, drips, rain, streams, surf, wind and fire, played from the keys.", listOf(
                ManualBlock(ManualKind.Para, "Fathom doesn't play recordings. Most of the sound of water is bubbles: a pocket of air caught under the surface rings like a spring, at a pitch set by its size (the smaller, the higher), and rises in pitch as it nears the top. A drip is a bubble and the tap of the drop; rain is many drips, and the sound of what they land on; a stream is a dense cloud of small bubbles and a few big ones. Surf is the rush of a wave rising and falling back. Wind is air rushing past things in gusts, whistling where it's caught in a gap; fire is crackles, hiss and roar.", "Fathom doesn't play recordings. Most of the sound of water is bubbles: a pocket of air caught under the surface rings like a spring, at a pitch set by its size (the smaller, the higher), and rises in pitch as it nears the top. A drip is a bubble and the click of the drop; rain is many drips, and the sound of what they land on; a stream is a dense cloud of small bubbles and a few big ones. Surf is the rush of a wave rising and falling back. Wind is air rushing past things in gusts, whistling where it's caught in a gap; fire is crackles, hiss and roar."),
                ManualBlock(ManualKind.Para, "Hold a note to keep it going. The note sets the size of the bubbles, or the note the wind whistles; the velocity sets how much."),
                ManualBlock(ManualKind.Heading, "Water"),
                ManualBlock(ManualKind.Bullet, "**model** - **bubbles**, **drips**, **rain**, **stream**, **surf**, **wind** or **fire**."),
                ManualBlock(ManualKind.Bullet, "**tune** - in cents."),
                ManualBlock(ManualKind.Bullet, "**density** - how many bubbles, drops or crackles. At 0, one comes with each note, so you can play a tune with them."),
                ManualBlock(ManualKind.Bullet, "**size** - how far the bubbles' sizes, and so their pitches, spread from the note, in semitones."),
                ManualBlock(ManualKind.Bullet, "**rise** - how far a bubble's pitch climbs as it nears the surface."),
                ManualBlock(ManualKind.Bullet, "**decay** - how long each bubble rings."),
                ManualBlock(ManualKind.Bullet, "**surface** - what the rain falls on: **water**, **leaves**, **tin** or a **window**."),
                ManualBlock(ManualKind.Heading, "Weather"),
                ManualBlock(ManualKind.Bullet, "**gust** - how much the wind, the fire and the waves come and go."),
                ManualBlock(ManualKind.Bullet, "**whistle** - wind caught in a gap, whistling on the note."),
                ManualBlock(ManualKind.Bullet, "**tone** - darker or brighter."),
                ManualBlock(ManualKind.Bullet, "**waves** - how many beats from one wave to the next. It follows the tempo."),
                ManualBlock(ManualKind.Bullet, "**spread** - how far apart the bubbles and drops land, left to right."),
                ManualBlock(ManualKind.Bullet, "**fade** - how long it takes to come in when a note's held, and to die away when it's let go."),
                ManualBlock(ManualKind.Bullet, "**velocity**, **octave**, **bend** and **volume**."),
                ManualBlock(ManualKind.Para, "Pressure, or the mod wheel, thickens it."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "**Bubble Notes** and **Drip Notes** have no density: each note is one bubble or drip, tuned, for melodies."),
                ManualBlock(ManualKind.Bullet, "**Whistling Wind** plays the note you hold: try slow chords."),
            )),
            ManualSection("Filament", "Modelled strings: plucked, picked, struck, bowed or blown.", listOf(
                ManualBlock(ManualKind.Para, "Filament doesn't play a recording. It simulates a vibrating string, so it reacts the way a real one does."),
                ManualBlock(ManualKind.Heading, "The exciter"),
                ManualBlock(ManualKind.Para, "**exciter** is what sets the string going: pluck, pick, hammer, bow, breath or **the live input**, so you can play a string with a microphone."),
                ManualBlock(ManualKind.Bullet, "**position** - where on the string it's excited. This changes the tone more than anything: near the end is thin and nasal, near the middle is round."),
                ManualBlock(ManualKind.Bullet, "**hardness** - how sharp the hammer is."),
                ManualBlock(ManualKind.Bullet, "**grit** and **length** - how noisy the excitation is and how long it lasts."),
                ManualBlock(ManualKind.Heading, "The string"),
                ManualBlock(ManualKind.Bullet, "**couple**, **detune** and **spread** - two strings per note, slightly apart, like a twelve-string or a piano's middle register."),
                ManualBlock(ManualKind.Bullet, "**damper** - a felt resting on the string at a position you choose, good for muted guitar sounds."),
                ManualBlock(ManualKind.Heading, "The body"),
                ManualBlock(ManualKind.Para, "Four resonances stand in for the instrument's body. **size** moves them, **bodydamp** widens them and **bodymix** sets how much you hear. There are also **sympathetic strings** that ring along with what you play."),
                ManualBlock(ManualKind.Heading, "Modulation"),
                ManualBlock(ManualKind.Para, "Two envelopes and two LFOs that can sync to the tempo, into eight matrix rows (source, destination, depth)."),
                ManualBlock(ManualKind.Para, "The envelopes do nothing until you route them. One of the sources is **level**, how loudly the string is ringing right now, so the string can react to itself."),
                ManualBlock(ManualKind.Para, "Destinations include **sustain**, **tone**, **position**, **pressure**, **damper**, **tension** and **detune**. **bright** changes the exciter (grit, or a hammer's hardness), and **rattle** and **volume** are per note. **body**, **drive** and **sympathy** apply to the whole instrument and follow the latest note."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Change **position** first, before the filter or body."),
                ManualBlock(ManualKind.Bullet, "A slow LFO on **position** brings a static pluck to life."),
                ManualBlock(ManualKind.Bullet, "If a note rings too long, shorten the decay instead of turning things down."),
            )),
            ManualSection("Forage", "A sample drum machine: thirteen pads for your own sounds.", listOf(
                ManualBlock(ManualKind.Para, "Forage plays your own samples on thirteen pads, each with some processing to help it fit."),
                ManualBlock(ManualKind.Heading, "A pad"),
                ManualBlock(ManualKind.Bullet, "**level**, **pan**, **pitch** and **decay**."),
                ManualBlock(ManualKind.Bullet, "**start** and **end** - which part of the file plays, so one long recording can feed several pads."),
                ManualBlock(ManualKind.Bullet, "**play** - once, loop or hold."),
                ManualBlock(ManualKind.Bullet, "**reverse** - forwards or backwards."),
                ManualBlock(ManualKind.Bullet, "**cutoff**, **reso** and **mode** (low or band pass), and **crush** for bit reduction."),
                ManualBlock(ManualKind.Bullet, "**pitch env** and its **decay**, under punch - a pitch drop, so a sample can fall like a drum does."),
                ManualBlock(ManualKind.Bullet, "**choke** - pads in the same choke group cut each other off, like an open hat stopping when the closed hat plays."),
                ManualBlock(ManualKind.Heading, "Slicing one file"),
                ManualBlock(ManualKind.Para, "There's a fourteenth slot above the pads for one file shared by the whole machine. Load a drum break into it, ask for thirteen slices and each pad plays one piece of it."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Put your hats in a choke group."),
                ManualBlock(ManualKind.Bullet, "Trim silence off the start of a sample, or it will play late."),
                ManualBlock(ManualKind.Bullet, "Automate **start** across a bar to turn one hit into a stutter."),
                ManualBlock(ManualKind.Bullet, "The sound library warns you before deleting a file a track still uses."),
            )),
            ManualSection("Formulate", "An 8-bit chip synth, and a waveform you can type in as a formula.", listOf(
                ManualBlock(ManualKind.Para, "Formulate is a chip synth with pulse, triangle and noise, like the old game consoles. It can also play a waveform you write as a formula."),
                ManualBlock(ManualKind.Heading, "The chip"),
                ManualBlock(ManualKind.Bullet, "**wave** - pulse, triangle, noise or the formula."),
                ManualBlock(ManualKind.Bullet, "**duty** - the pulse width. **pwmrate** and **pwmdepth** sweep it."),
                ManualBlock(ManualKind.Bullet, "**sub** - adds an octave below."),
                ManualBlock(ManualKind.Bullet, "**noiseshort** - switches the noise between a hiss and a metallic buzz."),
                ManualBlock(ManualKind.Bullet, "**bits**, **crush** and **smooth** - bit depth, sample rate and how much the steps are smoothed off."),
                ManualBlock(ManualKind.Heading, "Tracker tables"),
                ManualBlock(ManualKind.Para, "There are three, **arp**, **duty** and **vol**, typed in as text and stepped through per tick like a tracker instrument. An arp table of `0 4 7` played fast makes a chord from one voice."),
                ManualBlock(ManualKind.Heading, "The formula"),
                ManualBlock(ManualKind.Para, "**formula** is an expression where **x** goes from 0 to 1 over one cycle of the wave. `sin(x*2*pi)` is a sine, `x*2-1` is a saw and `(x<0.3)?1:-1` is a pulse with 30% duty."),
                ManualBlock(ManualKind.Para, "**formulamode** chooses whether the formula is worked out once per cycle or every sample. The three macro knobs **a**, **b** and **c** can be used by name in the formula, so you can give it controls. If a formula has an error, the panel tells you."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Use a macro in the formula and automate it. `sin(x*2*pi*a)` with **a** on a lane sweeps the tone."),
                ManualBlock(ManualKind.Bullet, "The tracker tables make a big difference. A plain patch with a good volume table often beats a clever formula without one."),
            )),
            ManualSection("Fret", "Modelled electric guitars and basses: strings, pickups, a player's hands and an amp loud enough to feed back.", listOf(
                ManualBlock(ManualKind.Para, "Fret doesn't play recordings. Each note is a string, plucked by a pick, a finger or a slapping thumb, and heard the way an electric guitar hears it: not in the air, but through a magnet sitting under the string. A pickup hears the string where it sits. Near the neck it hears a round, full note; by the bridge, a thin bright one; and a quarter of the way along it can't hear the 4th harmonic at all."),
                ManualBlock(ManualKind.Heading, "Guitar"),
                ManualBlock(ManualKind.Bullet, "**model** - **guitar**, **12-string** (the low four courses with an octave string, the top two doubled), **baritone** (a longer neck, tuned down), **bass** and **5-string** bass."),
                ManualBlock(ManualKind.Bullet, "**tune** - in cents."),
                ManualBlock(ManualKind.Bullet, "**pickup** - **neck**, **both** or **bridge**."),
                ManualBlock(ManualKind.Bullet, "**coil** - **single** (bright and clear) or **humbucker** (two coils side by side: thicker and darker)."),
                ManualBlock(ManualKind.Bullet, "**tone** - the guitar's tone knob: the coil's resonance falls as you turn it down."),
                ManualBlock(ManualKind.Bullet, "**sustain** - how long the strings ring."),
                ManualBlock(ManualKind.Bullet, "**bright** - how long they keep their top end."),
                ManualBlock(ManualKind.Heading, "Hands"),
                ManualBlock(ManualKind.Bullet, "**stroke** - **pick**, **finger** or **slap** (the thumb snapping the string against the frets)."),
                ManualBlock(ManualKind.Bullet, "**hardness** - a soft or hard pick or finger."),
                ManualBlock(ManualKind.Bullet, "**position** - where along the string it's struck: near the bridge is thin, further out is warmer."),
                ManualBlock(ManualKind.Bullet, "**mute** - the palm resting on the strings by the bridge. The mod wheel does the same, so you can mute as you play."),
                ManualBlock(ManualKind.Bullet, "**harmonic** - a finger touching the **12**th, **7**th or **5**th fret, for a bell-like harmonic an octave, a twelfth or two octaves up."),
                ManualBlock(ManualKind.Bullet, "**buzz** - lets the strings slap against the frets when played hard."),
                ManualBlock(ManualKind.Bullet, "**slide** - with one voice, a new note slides from the last instead of being picked again."),
                ManualBlock(ManualKind.Bullet, "**vibrato** - a finger rocking on the string. Pressure adds to it."),
                ManualBlock(ManualKind.Bullet, "**strum** - plays a chord across the strings, this many milliseconds between strings, instead of all at once."),
                ManualBlock(ManualKind.Bullet, "**direction** - strum **down** (low string first), **up**, or **both** ways in turn."),
                ManualBlock(ManualKind.Heading, "Amp"),
                ManualBlock(ManualKind.Bullet, "**drive** - the amp, from clean to flat out, with a speaker coming in as it does."),
                ManualBlock(ManualKind.Bullet, "**feedback** - how much the amp's sound shakes the strings back. With drive up, a held note sustains and can jump up to a harmonic."),
                ManualBlock(ManualKind.Bullet, "**voices**, **velocity**, **octave**, **bend** and **volume**."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "**Chug** and **Funk** use **mute**; try moving the mod wheel as you play to open the notes up."),
                ManualBlock(ManualKind.Bullet, "**Singing Lead** and **Feedback Swell** need held notes: let them ring and the amp takes over."),
                ManualBlock(ManualKind.Bullet, "For strummed chords, play all the notes at once and let **strum** spread them."),
                ManualBlock(ManualKind.Bullet, "Put Fret through the **Amp** effect for a bigger amp and cabinet than its own."),
            )),
            ManualSection("Genesis", "The big drum box, with a bus compressor the kick ducks.", listOf(
                ManualBlock(ManualKind.Para, "Genesis is the big drum machine, in the style of the boxes house and techno were made on. It has twelve voices, more weight than Hexbeat and two extras."),
                ManualBlock(ManualKind.Heading, "Drift"),
                ManualBlock(ManualKind.Para, "Real analogue drum machines are never exactly the same twice, and **drift** adds a bit of that variation from hit to hit."),
                ManualBlock(ManualKind.Heading, "The bus compressor"),
                ManualBlock(ManualKind.Para, "The whole kit goes through a compressor (**comp**, **compattack**, **comprelease**), and **duck** lets the kick push the rest of the kit down, so the kit pumps with the kick."),
                ManualBlock(ManualKind.Heading, "The kit"),
                ManualBlock(ManualKind.Bullet, "**kick** - tune, decay, level, **sweep** (the long pitch drop), **punch**, **click** (the attack) and **drive**."),
                ManualBlock(ManualKind.Bullet, "**snare**, **clap** (with spread and tone) and **rim**."),
                ManualBlock(ManualKind.Bullet, "**toms**, and **hats** with shared tone and tune and separate open and closed decays."),
                ManualBlock(ManualKind.Bullet, "**crash** and **ride**, with a **bell** on the ride."),
                ManualBlock(ManualKind.Bullet, "**cowbell**."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Set **duck** before the levels, since it changes how loud everything else sounds."),
                ManualBlock(ManualKind.Bullet, "If the kick disappears on a phone speaker, add kick **drive** instead of level."),
                ManualBlock(ManualKind.Bullet, "Keep drift low, enough that bars differ but not so much that the hats sound broken."),
            )),
            ManualSection("Hammer", "Modelled pianos and their relatives: hammers striking strings and bars, heard through a soundboard or pickups.", listOf(
                ManualBlock(ManualKind.Para, "Hammer doesn't play recordings. A felt hammer is thrown at real strings that ring through a soundboard, so it plays like a piano: harder is brighter as well as louder, the low notes ring for a long time, and the strings of one key beat against each other as they fade."),
                ManualBlock(ManualKind.Para, "Each key was measured against a recorded concert grand, and **Init** is that grand."),
                ManualBlock(ManualKind.Heading, "Instrument"),
                ManualBlock(ManualKind.Para, "**model** picks the instrument:"),
                ManualBlock(ManualKind.Bullet, "**grand** - a concert grand, as measured."),
                ManualBlock(ManualKind.Bullet, "**upright** - shorter strings and a smaller board: less bass, more middle, and notes that die sooner."),
                ManualBlock(ManualKind.Bullet, "**honky-tonk** - an old upright with the strings of each key tuned apart."),
                ManualBlock(ManualKind.Bullet, "**fortepiano** - a piano from around 1800: light leather hammers, thin strings, a quick, clear sound with a knock in it."),
                ManualBlock(ManualKind.Bullet, "**electric grand** - short strings heard by pickups instead of a board."),
                ManualBlock(ManualKind.Bullet, "**tine** - a hammer strikes a thin metal tine beside a tuned bar, and a pickup hears it: a bell on top, a long warm note, a bark when you dig in."),
                ManualBlock(ManualKind.Bullet, "**reed** - a steel reed and a pickup that hears it more on one side than the other: reedier, quicker to die, a growl when played hard."),
                ManualBlock(ManualKind.Bullet, "**tangent** - a metal tangent strikes a string and stays on it while the key is down; let go and the note stops dead. Two pickups under the strings."),
                ManualBlock(ManualKind.Bullet, "**celesta** - felt hammers on steel bars, each over a small wooden box: a soft bell, with dampers and a pedal."),
                ManualBlock(ManualKind.Bullet, "**toy** - hard little hammers on metal rods in a plastic box: clangy, short, never quite in tune (the seed picks how), no dampers."),
                ManualBlock(ManualKind.Bullet, "**dulcimer** - light wooden hammers on courses of thin strings, with no dampers at all, so everything rings into everything."),
                ManualBlock(ManualKind.Bullet, "**cimbalom** - a big dulcimer: heavier strings, soft hammers, and a damper pedal."),
                ManualBlock(ManualKind.Para, "**size** goes from a baby grand to a concert grand: a smaller one has a thinner, stiffer bass. **age** wears the piano in. The hammers get harder, the strings ring shorter and darker, and the keys drift out of tune. **seed** picks which way each key drifts."),
                ManualBlock(ManualKind.Heading, "Hammer"),
                ManualBlock(ManualKind.Bullet, "**hardness** - softer felt is darker and rounder, harder felt is brighter. **by key** makes the top harder and the bottom softer, or the other way."),
                ManualBlock(ManualKind.Bullet, "**weight** - a heavier hammer stays on the strings longer, which is darker."),
                ManualBlock(ManualKind.Bullet, "**strike at** - where on the string the hammer lands. Turned up, it lands further in from the end, which is rounder; down is thinner and brighter."),
                ManualBlock(ManualKind.Bullet, "**velocity** - how much how hard you play changes how loud a note is. The blow always follows your playing, so a soft note is still a darker one."),
                ManualBlock(ManualKind.Bullet, "**tacks** - metal tacks pushed into the felt: every note hard and bright, however softly you play. A tack piano."),
                ManualBlock(ManualKind.Bullet, "**moderator** - a strip of felt between the hammers and the strings: soft and muffled."),
                ManualBlock(ManualKind.Heading, "Strings"),
                ManualBlock(ManualKind.Bullet, "**sustain** - how long the strings ring. **by key** makes the top ring longer and the bottom shorter, or the other way."),
                ManualBlock(ManualKind.Bullet, "**tone** - how fast the top of the sound dies against the rest. Down is a piano going dark as it rings, up keeps it bright. **by key** tilts it across the keyboard, like sustain's."),
                ManualBlock(ManualKind.Bullet, "**stiffness** - how stiff the strings are. Stiff strings put their upper partials a little sharp, which is most of what makes a piano sound like a piano. **stretch** is how far the tuning follows that, as a piano tuner stretches the octaves."),
                ManualBlock(ManualKind.Bullet, "**strings** - how many strings each key has. **auto** is a grand's: one in the lowest notes, then two, then three."),
                ManualBlock(ManualKind.Bullet, "**unison** - how far apart the strings of one key are tuned. A little gives the long, slow aftersound; more is a honky-tonk."),
                ManualBlock(ManualKind.Bullet, "**couple** - how much the strings talk to each other through the bridge."),
                ManualBlock(ManualKind.Bullet, "**across** - how much the strings move across the soundboard as well as into it, which keeps a note ringing after the first fast fade."),
                ManualBlock(ManualKind.Heading, "Pedals"),
                ManualBlock(ManualKind.Para, "**dampers** is how firmly the felt stops a note when you let go of the key, and **time** how long that takes. The top keys have no dampers, as on a piano, so they ring on."),
                ManualBlock(ManualKind.Para, "The sustain pedal lifts the dampers, and Hammer follows it part of the way down: half a pedal lets them touch the strings, which takes the top off a note and lets the rest ring. **lifts at** is how far down the dampers start to leave the strings, and **span** how much further they're clear of them."),
                ManualBlock(ManualKind.Para, "With the pedal down, strings you didn't play ring along with the ones you did, an octave or a fifth away. **sympathy** is how much. **noises** is the thump of the dampers leaving the strings and landing on them again."),
                ManualBlock(ManualKind.Para, "The soft pedal is **una corda**: the hammer slides over to miss one string and meets the others with softer felt, so a note is quieter and darker. The knob sets how far. On an upright, the hammers move closer to the strings instead, so they hit more softly."),
                ManualBlock(ManualKind.Heading, "Sound"),
                ManualBlock(ManualKind.Para, "**board** is how loud the soundboard's thump is under each note. **lid** open is bright; closed takes the top off. **room** is how much of the room you hear."),
                ManualBlock(ManualKind.Para, "**mic** is where you listen from:"),
                ManualBlock(ManualKind.Bullet, "**player** - at the keys, bass on the left."),
                ManualBlock(ManualKind.Bullet, "**audience** - in front of the piano, the other way round and narrower."),
                ManualBlock(ManualKind.Bullet, "**close** - in the piano, wide and bright."),
                ManualBlock(ManualKind.Bullet, "**room** - across the room."),
                ManualBlock(ManualKind.Para, "**width** is how wide the keyboard spreads."),
                ManualBlock(ManualKind.Heading, "Prepare"),
                ManualBlock(ManualKind.Para, "Things put on the strings, as a prepared piano has them."),
                ManualBlock(ManualKind.Bullet, "**what** - **rubber** wedged between the strings mutes most of a note and leaves a dull ring. A **screw** puts the partials out of tune, like a bell. A **bolt** rattles. **paper** buzzes. **mixed** puts something different on each key."),
                ManualBlock(ManualKind.Bullet, "**keys** - which keys: all, the white or the black ones, the low or high half, or some of each at random (the seed picks)."),
                ManualBlock(ManualKind.Bullet, "**where** - how far along the string. Near the end changes less."),
                ManualBlock(ManualKind.Bullet, "**amount** - how heavy, how loose, how much."),
                ManualBlock(ManualKind.Heading, "Electric"),
                ManualBlock(ManualKind.Para, "For the tine, reed and tangent models."),
                ManualBlock(ManualKind.Bullet, "**near** - how close the pickup is. Nearer barks sooner."),
                ManualBlock(ManualKind.Bullet, "**offset** - how far the tine sits off the pickup's centre. Near the centre it sounds an octave up and hollow; further off it's the note, purer."),
                ManualBlock(ManualKind.Bullet, "**tonebar** - how much of a tine's note its tonebar holds: more is longer and smoother, less is more bell."),
                ManualBlock(ManualKind.Bullet, "**pickups** - which of the tangent's pickups you hear: the one by the **bridge** (bright), the **neck** one (fuller), **both**, or both **against** each other (thin and hollow). **mute** is a felt strip on the strings: short and plucky."),
                ManualBlock(ManualKind.Bullet, "**drive** - the amp, from clean to rough."),
                ManualBlock(ManualKind.Bullet, "**depth**, **rate** and **pan** are the tremolo. **sync** locks it to the tempo. With **pan** at the top it swings from side to side instead of up and down. The mod wheel brings the tremolo in."),
                ManualBlock(ManualKind.Heading, "Out"),
                ManualBlock(ManualKind.Para, "**volume** and **pan**, and the tuning: **bend**, **octave**, **transpose** and **fine**."),
                ManualBlock(ManualKind.Para, "**voices** is the most notes that ring at once. **detail** at **auto** follows the quality setting, so a slower phone plays a lighter piano; **full** always plays the whole model.", "**voices** is the most notes that ring at once. **detail** at **auto** follows the quality setting, so a slower computer plays a lighter piano; **full** always plays the whole model."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "A piano's colour is mostly the hammer. Try **hardness** before anything else."),
                ManualBlock(ManualKind.Bullet, "For an older piano, turn up **age**, or **tone** down and **unison** up a little."),
                ManualBlock(ManualKind.Bullet, "Hold the sustain pedal and play low: the strings ring into each other."),
                ManualBlock(ManualKind.Bullet, "For a tine piano that growls, turn **near** up and play hard."),
            )),
            ManualSection("Hexbeat", "Synthesized drums in the style of the classic small boxes, with a bigger kit.", listOf(
                ManualBlock(ManualKind.Para, "Hexbeat makes its drums with synthesis instead of samples. It has thirteen voices in the style of the small classic drum machines, punchy, dry and easy to sit in a mix."),
                ManualBlock(ManualKind.Heading, "The kit"),
                ManualBlock(ManualKind.Para, "Kick, rim, snare, clap, three toms, closed and open hat, crash, ride, cowbell and clave."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Para, "Every voice has a **level**, and most have **tune** and **decay**, plus a few of their own:"),
                ManualBlock(ManualKind.Bullet, "**kick** - tune, decay and **punch** (the pitch drop at the start)."),
                ManualBlock(ManualKind.Bullet, "**snare** - tune, decay, tone and **snappy** (drum against noise)."),
                ManualBlock(ManualKind.Bullet, "**hats** - shared tone and tune, and separate closed and open decays."),
                ManualBlock(ManualKind.Bullet, "**clap** - decay, tone and the spread of the little repeats that make it a clap."),
                ManualBlock(ManualKind.Bullet, "**cymbals** - decay and tone for crash and ride."),
                ManualBlock(ManualKind.Bullet, "**bell** and **clave** - tune and level."),
                ManualBlock(ManualKind.Para, "**accent** is how much a hard hit adds across the whole kit, and **vel** is how much velocity sets each hit's level."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "It opens on the drum grid, which is the best way to edit it."),
                ManualBlock(ManualKind.Bullet, "Changing the decays is a quick way to make a pattern tighter or roomier."),
                ManualBlock(ManualKind.Bullet, "Try probability on the hats and a ratchet on the snare so the loop doesn't repeat exactly."),
                ManualBlock(ManualKind.Bullet, "For drums from your own samples see Forage, and for a bigger, heavier kit see Genesis."),
            )),
            ManualSection("Manual", "The organ: two manuals and pedals, four models and a rotary cabinet.", listOf(
                ManualBlock(ManualKind.Para, "Manual is an organ with two keyboards and a pedalboard. They all share one set of 91 tonewheels like the real thing, so the same wheel plays the fifth of one note and the octave of another, which is why organ chords shimmer and beat a little."),
                ManualBlock(ManualKind.Heading, "Drawbars"),
                ManualBlock(ManualKind.Para, "Nine per manual, and they're most of the patch. Each one adds one harmonic of the note, as loud as you pull it."),
                ManualBlock(ManualKind.Heading, "The four models"),
                ManualBlock(ManualKind.Para, "**model** picks the kind of organ:"),
                ManualBlock(ManualKind.Bullet, "**combo** - a transistor organ, buzzy with its own attack."),
                ManualBlock(ManualKind.Bullet, "**tonewheel** - the classic console organ, with **leakage** (wheels bleeding into each other), **hum** and **age**."),
                ManualBlock(ManualKind.Bullet, "**reeds** - a reed organ, with **pressure**, **buzz** and a tremulant."),
                ManualBlock(ManualKind.Bullet, "**pipes** - a pipe organ with **principal**, **flute**, **string**, **reed** and **mixture** stops, **chiff** on the attack and **tracker** noise."),
                ManualBlock(ManualKind.Para, "Leakage, hum and blower wind noise fade in when the organ starts playing and fade out about half a second after it stops, so a track that sits out a scene is silent there."),
                ManualBlock(ManualKind.Heading, "Key click"),
                ManualBlock(ManualKind.Para, "A real tonewheel organ's key contacts close one after another, so each note starts with a little burst of clicks. **click** sets how loud that is, **clickoff** is the click when you let go and **contacts** spreads the contacts out. Without the click it sounds much less like an organ."),
                ManualBlock(ManualKind.Heading, "The cabinet"),
                ManualBlock(ManualKind.Para, "The rotary speaker is built in: a spinning horn over a drum spinning the other way, each with its own speed and ramp up and down, and two microphones you can move. The rotors' position can be a modulation source too."),
                ManualBlock(ManualKind.Heading, "Modulation"),
                ManualBlock(ManualKind.Para, "Two envelopes and two LFOs that can sync to the tempo, into eight matrix rows (source, destination, depth)."),
                ManualBlock(ManualKind.Para, "Four of the sources come from the organ itself: **horn** and **drum** (where the rotors are pointing), the **scanner** from the vibrato, and **wind** (the air pressure). Horn and drum don't move while the rotary is stopped."),
                ManualBlock(ManualKind.Para, "The destinations include each drawbar, and all the drawbars of a manual at once."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Switch the rotary speed while playing. The speeding up and slowing down is the best part."),
                ManualBlock(ManualKind.Bullet, "Percussion takes over the last drawbar when it's on, like the originals. It's usually best left that way."),
            )),
            ManualSection("Molt", "Sing a take in, and the piano roll tunes it.", listOf(
                ManualBlock(ManualKind.Para, "Molt turns a sung recording into an instrument. It finds the separate pulses of the voice and spaces them out again to change the pitch, so the voice keeps its character instead of going chipmunk."),
                ManualBlock(ManualKind.Heading, "The roll does the tuning"),
                ManualBlock(ManualKind.Para, "Draw the notes you want in the piano roll, sing anything, and the take is pulled onto those notes."),
                ManualBlock(ManualKind.Bullet, "**tune** - how hard it's pulled. All the way is hard-tune, and less is a gentle correction."),
                ManualBlock(ManualKind.Bullet, "**rate** - how fast it gets there. Slow sounds like a natural slide, fast sounds stepped."),
                ManualBlock(ManualKind.Bullet, "**robot** - flattens the pitch completely onto the note."),
                ManualBlock(ManualKind.Heading, "The voice"),
                ManualBlock(ManualKind.Bullet, "**formant** - moves the formants without changing the pitch, so the singer sounds bigger or smaller."),
                ManualBlock(ManualKind.Bullet, "**mega** - a megaphone."),
                ManualBlock(ManualKind.Bullet, "**start** and **loop** - which part of the take plays, and whether it loops."),
                ManualBlock(ManualKind.Para, "Then a filter, an amp envelope and drive."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Keep low rumble out of the recording. Handling noise from holding the phone can throw the pitch detection off. The recorder's low cut helps, and it's on by default for Molt."),
                ManualBlock(ManualKind.Bullet, "Consonants are copied instead of pitched, so they stay crisp."),
                ManualBlock(ManualKind.Bullet, "Singing roughly and letting the roll fix it works fine."),
            )),
            ManualSection("Mosaic", "A multisample player: zones across the keyboard and velocity, plus grain clouds.", listOf(
                ManualBlock(ManualKind.Para, "Mosaic plays maps of samples. Each sample (a zone) covers a range of keys and velocities, so together they make a playable instrument."),
                ManualBlock(ManualKind.Heading, "The map"),
                ManualBlock(ManualKind.Para, "A **zone** is a file, a key range, a velocity range, a root note and a tuning. Build zones by hand from your own recordings, or load a **SoundFont** to get a whole map at once."),
                ManualBlock(ManualKind.Bullet, "**keyfade** and **velfade** - crossfades between neighbouring zones so you don't hear the joins."),
                ManualBlock(ManualKind.Bullet, "**scan** and **scanamt** - move through the velocity layers with a knob instead of velocity. Put scan on the mod wheel to blend a soft and a loud sample."),
                ManualBlock(ManualKind.Heading, "Playing"),
                ManualBlock(ManualKind.Para, "**start**, **loop**, **reverse**, **envfrom** and **filemod** decide how each file is played. After that there's a filter with its own envelope and key tracking, two envelopes, two LFOs, glide and voice modes."),
                ManualBlock(ManualKind.Heading, "Grains"),
                ManualBlock(ManualKind.Para, "**grain** plays the map as a grain cloud instead, with **gsize**, **gdensity**, **gpos**, **gspray**, **gpitch** and **grate**."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Set the crossfades before judging how a map sounds."),
                ManualBlock(ManualKind.Bullet, "Check the root notes. A wrong root puts everything out of tune."),
                ManualBlock(ManualKind.Bullet, "Big maps use a lot of memory. The sound library shows what a song is using before you delete anything."),
            )),
            ManualSection("Nexus", "A modular synth whose modules are the other machines.", listOf(
                ManualBlock(ManualKind.Para, "Nexus lets you build your own machine. Its modules are the app's own instruments, so you can wire a Reflux filter, a Trinity oscillator and a Resonance mode bank together."),
                ManualBlock(ManualKind.Heading, "The patch is text"),
                ManualBlock(ManualKind.Para, "A Nexus patch is a list of modules and connections written out as text, so you can read it, copy it and send it to someone. It has its own screen, since a patch needs room."),
                ManualBlock(ManualKind.Para, "Its knobs are normal parameters, so anything in a patch can be automated, mapped to a controller and recorded."),
                ManualBlock(ManualKind.Para, "**fit** tidies the patch to the screen. It lays the modules out in the order the sound flows through them, left to right, in as many rows as suit the screen, then zooms to show all of it. Turn the phone and press it again for a layout that suits that way round. It's one step of undo, so the modules can go back where they were.", "**fit** tidies the patch to the screen. It lays the modules out in the order the sound flows through them, left to right, in as many rows as suit the screen, then zooms to show all of it. Make the window wider or taller and press it again for a layout that suits that shape. It's one step of undo, so the modules can go back where they were."),
                ManualBlock(ManualKind.Heading, "Modules on the canvas"),
                ManualBlock(ManualKind.Para, "Each module is a panel on rails, as wide as its knobs and jacks need. Inputs are the teal jacks and outputs the amber ones, in the dark box at the bottom. The colour along the top says what kind of module it is, and the light next to the name shows how hard it's working. Cables take the colour of the module they come from."),
                ManualBlock(ManualKind.Para, "Turn a knob on a panel by dragging up or down. Zoom in for finer moves, and tap twice to put it back. The same knobs are under the canvas when the module is selected. In mapping mode, tap a knob on a panel to map it and hold it to clear the mapping.", "Turn a knob on a panel by dragging up or down. Zoom in for finer moves, and click twice to put it back. The same knobs are under the canvas when the module is selected. In mapping mode, click a knob on a panel to map it and hold it to clear the mapping."),
                ManualBlock(ManualKind.Heading, "Effects as modules"),
                ManualBlock(ManualKind.Para, "The insert effects are modules too, so an effect can go anywhere in a patch and be moved by a cable: **reverb**, **chorus**, **phaser**, **crush**, **shift**, **drive** and **swell**. Each sounds exactly as it does on a track. Their second input moves the knob it's named after, like **size** on the reverb or **amount** on swell. Each runs a fraction of a millisecond late, which you won't hear."),
                ManualBlock(ManualKind.Heading, "Instruments from the other machines"),
                ManualBlock(ManualKind.Para, "More of the machines are modules, each with the part that makes its sound:"),
                ManualBlock(ManualKind.Bullet, "**bore** - Brazen's horn: lips on a tube with a bell."),
                ManualBlock(ManualKind.Bullet, "**pipe** - Timber's pipe, with a reed, a double reed or a flute's air jet."),
                ManualBlock(ManualKind.Bullet, "**reed** - Draw's free reed: harmonica, accordion, melodica, harmonium or concertina."),
                ManualBlock(ManualKind.Bullet, "**jaw** - Tongue's jaw harp reed, plucked by its **trig** input. Put it through a **throat** and move the vowel for the twang."),
                ManualBlock(ManualKind.Bullet, "**piano** - the whole of Hammer, played by a **pitch** and a **gate**."),
                ManualBlock(ManualKind.Bullet, "**throat** - Diction's vocal tract as a filter: anything through it becomes a vowel, from oo to ee."),
                ManualBlock(ManualKind.Bullet, "**formula** - Formulate's expressions, as an oscillator or as a shaper of what comes into **x**. Select it and press **edit** to type the formula."),
                ManualBlock(ManualKind.Bullet, "**follow** - Molt's ear: the pitch of whatever's in its input, a gate while it's sure of it, and its level. Sing into it to play the patch."),
                ManualBlock(ManualKind.Para, "The blown ones (**bore**, **pipe** and **reed**) take their air from the **breath** input, from an envelope or a pressure source. With nothing in it, the keys blow them."),
                ManualBlock(ManualKind.Heading, "Macros"),
                ManualBlock(ManualKind.Para, "Eight macros, **macro1** to **macro8**, plus **morph**. The patch decides what they control, so a big patch can be played with a few knobs."),
                ManualBlock(ManualKind.Heading, "MPE"),
                ManualBlock(ManualKind.Para, "The **touch** module gives each voice the pressure and slide of the finger playing it, from an MPE controller or a keyboard with poly aftertouch. Patch its **prs** and **slide** into anything, like a filter's cutoff or a VCA."),
                ManualBlock(ManualKind.Heading, "Audio input"),
                ManualBlock(ManualKind.Para, "There's an audio input module, so anything coming into the phone can go through a patch.", "There's an audio input module, so anything coming into the computer can go through a patch."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Keep patches small and name your macros."),
                ManualBlock(ManualKind.Bullet, "Wire **morph** to the two or three things that change the patch the most."),
                ManualBlock(ManualKind.Bullet, "Nexus isn't the easiest place to start. The other machines do most things more directly, and Nexus is for combinations they don't cover."),
            )),
            ManualSection("Palm", "Modelled hand drums: tabla and bayan, djembe, cajón, frame drum and talking drum, played with open, slap, muted, bass and rim strokes.", listOf(
                ManualBlock(ManualKind.Para, "Palm doesn't play recordings. Each note is a drum head tuned to the note. A plain head rings at the uneven ratios of a stretched circle, which is why most drums have no clear pitch; a tabla's head is loaded with a paste in the middle that pulls its overtones into a harmonic series, so it sings a note."),
                ManualBlock(ManualKind.Para, "The hand decides the rest: where it lands (the middle sounds the low modes, the edge the high ones), how long it stays on the head, and whether it stays there to damp it."),
                ManualBlock(ManualKind.Heading, "Drum"),
                ManualBlock(ManualKind.Bullet, "**model** - **tabla** (the small, tuned drum), **bayan** (its big bass partner), **djembe**, **cajon**, **frame drum** or **talking** drum."),
                ManualBlock(ManualKind.Bullet, "**tune** - in cents."),
                ManualBlock(ManualKind.Bullet, "**stroke** - **open** (the fingers flat near the edge, lifted at once), **slap** (the fingertips cracking, the hand left on the middle), **muted** (pressed down and held), **bass** (the palm in the middle), **rim** (the fingers on the edge), or **velocity**, which picks muted for soft notes, open for the middle and slap for the hardest."),
                ManualBlock(ManualKind.Bullet, "**position** - moves the stroke towards the middle or the edge."),
                ManualBlock(ManualKind.Bullet, "**hand** - soft fingertips and palms, to hard, quick fingers."),
                ManualBlock(ManualKind.Bullet, "**decay** - how long the head rings."),
                ManualBlock(ManualKind.Bullet, "**damp** - the other hand resting on the head."),
                ManualBlock(ManualKind.Heading, "Body"),
                ManualBlock(ManualKind.Bullet, "**pitch drop** - how sharp a hard stroke sends the head before it settles."),
                ManualBlock(ManualKind.Bullet, "**squeeze** - how many semitones pressure, or the mod wheel, bends the head up: the wrist pressing a bayan, the arm squeezing a talking drum."),
                ManualBlock(ManualKind.Bullet, "**rattle** - a cajón's snares, a djembe's rattles or a frame drum's jingles."),
                ManualBlock(ManualKind.Bullet, "**body** - a djembe's or a cajón's air, booming under a bass stroke."),
                ManualBlock(ManualKind.Heading, "Play"),
                ManualBlock(ManualKind.Bullet, "**rolls** - held notes struck again and again, this many times a second."),
                ManualBlock(ManualKind.Bullet, "**spread** - low drums to the left, high to the right."),
                ManualBlock(ManualKind.Bullet, "**voices**, **velocity**, **octave**, **bend** and **volume**."),
                ManualBlock(ManualKind.Para, "With MPE, sliding a finger up lays it on the head and damps it as it rings."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "The **By Touch** presets play every stroke from one key: play softly for muted, harder for open, hardest for a slap."),
                ManualBlock(ManualKind.Bullet, "**Bayan Swoop** and **Talking Squeeze** are for pressing: play a note, then lean on the key or push the mod wheel."),
            )),
            ManualSection("Pollen", "Granular clouds from a file or the live input, whose grains can spawn more grains.", listOf(
                ManualBlock(ManualKind.Para, "Pollen plays a sound as a cloud of short grains. The source is a file you load or the live input, recorded into a loop as you play."),
                ManualBlock(ManualKind.Heading, "The cloud"),
                ManualBlock(ManualKind.Bullet, "**size** and **sizespread** - how long each grain is, and how much that varies."),
                ManualBlock(ManualKind.Bullet, "**density** and **jitter** - how many grains per second, and how irregular."),
                ManualBlock(ManualKind.Bullet, "**window** and **skew** - the shape of each grain's fade in and out."),
                ManualBlock(ManualKind.Bullet, "**position**, **scan** and **spray** - where grains come from in the buffer, whether that point moves and how far they scatter around it."),
                ManualBlock(ManualKind.Bullet, "**snap** - lines grains up with the hits in the source, so rhythmic material stays rhythmic."),
                ManualBlock(ManualKind.Bullet, "**panspread** and **width**."),
                ManualBlock(ManualKind.Heading, "Live input"),
                ManualBlock(ManualKind.Para, "**source** switches to the input. **buffer** sets how much is kept, **freeze** holds it and **capture** grabs what's in it. A live buffer isn't saved with the song and is silent in an export, and the panel reminds you of that."),
                ManualBlock(ManualKind.Heading, "Pollination"),
                ManualBlock(ManualKind.Para, "**bloom** and **generations** let grains spawn more grains at a related position and pitch, up to the depth you set. A little thickens the sound, and a lot turns one note into a changing texture. **drift** and **mutate** set how far the new grains wander."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Density and size work against each other. Long grains at high density make a wall, and short ones make a texture."),
                ManualBlock(ManualKind.Bullet, "Use **snap** on anything with a beat."),
                ManualBlock(ManualKind.Bullet, "The pitch scatter can be locked to a scale so the cloud stays in key."),
                ManualBlock(ManualKind.Bullet, "On lean quality (Settings) the cloud uses half as many grains."),
            )),
            ManualSection("Ratio", "Six-operator FM, with a knob that morphs between two algorithms.", listOf(
                ManualBlock(ManualKind.Para, "Ratio is the FM synth. It has six operators, each a sine wave that's either a carrier (you hear it) or a modulator (it changes the sound of another). How they're connected is the algorithm."),
                ManualBlock(ManualKind.Heading, "Morphing algorithms"),
                ManualBlock(ManualKind.Para, "You pick two algorithms, `algoa` and `algob`, and **morph** blends between them. The in-between settings aren't on any standard algorithm list, and you can automate the morph, so a pad can open up from two operators to six over a few bars."),
                ManualBlock(ManualKind.Heading, "The operators"),
                ManualBlock(ManualKind.Para, "Each of the six has:"),
                ManualBlock(ManualKind.Bullet, "**ratio** - its frequency as a multiple of the note. **fixed** holds it at one frequency instead, which is good for formants."),
                ManualBlock(ManualKind.Bullet, "**level** - how much FM it adds as a modulator, or how loud it is as a carrier."),
                ManualBlock(ManualKind.Bullet, "**fb** - feedback into itself, from a sine towards a saw."),
                ManualBlock(ManualKind.Bullet, "**A D S R** - its own envelope. On a modulator this shapes the tone instead of the volume."),
                ManualBlock(ManualKind.Bullet, "**key** tracking, **fine** tune, **pan** and **mode**."),
                ManualBlock(ManualKind.Heading, "Everything else"),
                ManualBlock(ManualKind.Para, "A filter with its own envelope, three extra envelopes for modulation, three LFOs that can sync to the tempo and ten matrix rows (source, second source, destination, depth) that work like Trinity's."),
                ManualBlock(ManualKind.Para, "**snap** keeps ratios on useful values (whole numbers, odd numbers, semitones, bell partials), and **skew** bends them all away from those values together."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Whole-number ratios (1, 2, 3) sound harmonic, and others (1.41, 3.14) sound like bells and metal. Good patches often mix both."),
                ManualBlock(ManualKind.Bullet, "Give modulators shorter envelopes than carriers. A bright attack fading into a soft body is the classic electric piano."),
                ManualBlock(ManualKind.Bullet, "Feedback on the top operator of a stack is the cheapest way to add brightness."),
            )),
            ManualSection("Reflux", "Acid bass: one oscillator, one filter that screams, and lines you play in.", listOf(
                ManualBlock(ManualKind.Para, "Reflux is one oscillator, one filter and one envelope, set up so you can play a bassline in instead of building it step by step."),
                ManualBlock(ManualKind.Heading, "Accent and slide"),
                ManualBlock(ManualKind.Para, "Acid basslines come from accent and slide, and Reflux gets them from how you play:"),
                ManualBlock(ManualKind.Bullet, "Accent is velocity. Play a note harder and it's louder, brighter and has more filter envelope."),
                ManualBlock(ManualKind.Bullet, "Slide is legato. Overlap two notes and the second glides from the first instead of starting again. Leave a gap and it plucks."),
                ManualBlock(ManualKind.Para, "So play a line on the keyboard, or draw it in the roll with overlapping notes for the slides."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**osc** - the **wave**, saw or pulse, with **pw** for the pulse's width, a **sub** oscillator an octave down and **tune**."),
                ManualBlock(ManualKind.Bullet, "**filter** - **cutoff** and **reso**, **envmod** for how much the envelope opens the filter and **decay** for how long it lasts. Short decays are plucky and long ones are rubbery. **mode** is low pass or band pass. Most of the sound is here."),
                ManualBlock(ManualKind.Bullet, "**play** - **accent** is how much an accented note adds to level and filter, **slide** is how long a slide takes, and **vel** is how much velocity sets the level. A note that slides keeps the level of the note it slid from."),
                ManualBlock(ManualKind.Bullet, "**out** - **drive**, where the scream comes from, and **volume**."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Resonance and drive together make the classic sound. Most acid patches have both up and the cutoff moving."),
                ManualBlock(ManualKind.Bullet, "Record the cutoff knob as automation while the song plays instead of drawing it in."),
                ManualBlock(ManualKind.Bullet, "Two Refluxes playing the same clip, one plucked and one sliding, panned apart with slightly different cutoffs, still works great."),
                ManualBlock(ManualKind.Para, "*Reflux was called Subvert in earlier versions, and songs and patches from then open as Reflux.*"),
            )),
            ManualSection("Resonance", "Eight struck objects that ring into each other.", listOf(
                ManualBlock(ManualKind.Para, "Resonance is modal percussion. Each of its eight pads is an object (a drum, a bar, a bell, etc.) that rings at a set of frequencies, and playing a pad strikes it. Nothing is sampled."),
                ManualBlock(ManualKind.Heading, "A pad"),
                ManualBlock(ManualKind.Bullet, "**modes** - how many partials it has. Few sounds like a woodblock, many like a bell."),
                ManualBlock(ManualKind.Bullet, "**shape** - membrane, bar, plate, tube, bowl or metal. This sets how the partials are spaced, which is most of what makes a drum sound different from a bar."),
                ManualBlock(ManualKind.Bullet, "**inharm** - stretches the spacing."),
                ManualBlock(ManualKind.Bullet, "**decay** and **damp** - how long it rings, and whether the highs die first."),
                ManualBlock(ManualKind.Bullet, "**hard** - how hard the beater is (how much top end)."),
                ManualBlock(ManualKind.Bullet, "**hit** - where you strike it. Different places bring some partials out and hide others, so it changes the sound a lot."),
                ManualBlock(ManualKind.Bullet, "**bend** and **bendtime** - a drop in pitch after the hit, like a tom."),
                ManualBlock(ManualKind.Bullet, "**drive**, **pan**, **level** and **couple**."),
                ManualBlock(ManualKind.Heading, "Coupling"),
                ManualBlock(ManualKind.Para, "**coupling** sets how much the pads ring into each other. Hit one and the others answer quietly at their own pitches, so a kit sounds like objects in one room. **humanise** varies each hit a little."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Set **hit** and **shape** before tuning."),
                ManualBlock(ManualKind.Bullet, "Go easy on coupling. A little sounds like a room, and a lot feeds back."),
                ManualBlock(ManualKind.Bullet, "With long decays you can play melodies on the pads."),
            )),
            ManualSection("Sympath", "Modelled sitar, tanpura, veena and shamisen: plucked strings over a buzzing bridge, with strings ringing in sympathy.", listOf(
                ManualBlock(ManualKind.Para, "Sympath doesn't play recordings. Each note is a string lying over a wide, curved bridge. Once the string swings far enough towards the bridge it strikes it, harder the further it swings, and every strike sets the bridge ringing: the bright buzz on every cycle that goes on as long as the string swings wide enough to reach, and fades as the note dies down."),
                ManualBlock(ManualKind.Para, "Under the played strings lie sympathetic strings that are never touched. They're tuned to the scale of the piece, so any note that lands on one of theirs sets it ringing, and it rings on after the note has gone."),
                ManualBlock(ManualKind.Heading, "Strings"),
                ManualBlock(ManualKind.Bullet, "**model** - **sitar** (eleven sympathetic strings and two drone strings), **tanpura** (four strings it plucks by itself), **veena** (a flatter bridge and three drone strings at the side) or **shamisen** (a big plectrum that hits the skin too, and its low string buzzing on the neck)."),
                ManualBlock(ManualKind.Bullet, "**tune** - in cents."),
                ManualBlock(ManualKind.Bullet, "**sa** - the tonic the sympathetic and drone strings are tuned to."),
                ManualBlock(ManualKind.Bullet, "**scale** - the scale the sympathetic strings are tuned to: **bilawal** (major), **khamaj**, **kafi**, **asavari**, **bhairavi**, **bhairav**, **kalyan**, **marwa**, **purvi** or **todi**."),
                ManualBlock(ManualKind.Bullet, "**bridge** - how much the bridge buzzes. At 0 it's a plain, sharp edge."),
                ManualBlock(ManualKind.Bullet, "**curve** - how wide the string must swing before it lies on the bridge. Low, and even soft notes buzz; high, and only hard ones do."),
                ManualBlock(ManualKind.Bullet, "**pluck** - a soft or hard pluck."),
                ManualBlock(ManualKind.Bullet, "**position** - where along the string it's plucked."),
                ManualBlock(ManualKind.Bullet, "**sustain** - how long the strings ring."),
                ManualBlock(ManualKind.Bullet, "**bright** - how long they keep their top end."),
                ManualBlock(ManualKind.Heading, "Drones"),
                ManualBlock(ManualKind.Bullet, "**tarbs** - how loud the sympathetic strings ring."),
                ManualBlock(ManualKind.Bullet, "**chikari** - strikes the drone strings with each new note."),
                ManualBlock(ManualKind.Bullet, "**first** - the tanpura's first string: **pa**, **ma**, **ni** or **sa** an octave down. The other three are Sa, Sa and Sa an octave down."),
                ManualBlock(ManualKind.Bullet, "**cycle** - how many beats the tanpura takes to pluck its four strings and start again: **2**, **4**, **6** or **8**. It follows the tempo."),
                ManualBlock(ManualKind.Heading, "Hands"),
                ManualBlock(ManualKind.Bullet, "**meend** - with one voice, a new note slides from the last along the same string instead of being plucked again."),
                ManualBlock(ManualKind.Bullet, "**gamak** - shakes the note quickly. The mod wheel does the same."),
                ManualBlock(ManualKind.Bullet, "**voices**, **velocity**, **octave**, **bend** and **volume**."),
                ManualBlock(ManualKind.Para, "Pressure (from the keyboard or each note's own, with MPE) pulls the string sideways, bending the note up by as much as a whole tone."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Set **sa** to the key of the song and **scale** to its scale, and the sympathetic strings ring along with the tune."),
                ManualBlock(ManualKind.Bullet, "The tanpura only plucks while a note is held: hold Sa for as long as the drone should go."),
                ManualBlock(ManualKind.Bullet, "**Sitar** has one voice: play legato for meend, and press harder to pull a note up."),
            )),
            ManualSection("Timber", "Modelled woodwinds: reeds and flutes.", listOf(
                ManualBlock(ManualKind.Para, "Timber is the woodwind version of Brazen: a reed vibrating against a mouthpiece, or a jet of air blown across an edge, feeding a tube with holes in it."),
                ManualBlock(ManualKind.Heading, "The family"),
                ManualBlock(ManualKind.Para, "**family** picks the kind of instrument:"),
                ManualBlock(ManualKind.Bullet, "**reed** - clarinet and saxophone."),
                ManualBlock(ManualKind.Bullet, "**double** - a double reed, oboe and bassoon."),
                ManualBlock(ManualKind.Bullet, "**air** - a jet of air, the flute. **aim** sets how the air hits the edge, like a flute player's lips."),
                ManualBlock(ManualKind.Heading, "The tube"),
                ManualBlock(ManualKind.Bullet, "**shape** - the bore, a cylinder or a cone. A cylinder gives the hollow clarinet sound and a cone sounds more like a sax."),
                ManualBlock(ManualKind.Bullet, "**body** and **bell** - the shape of the end."),
                ManualBlock(ManualKind.Bullet, "**loss** - how much energy the tube loses."),
                ManualBlock(ManualKind.Bullet, "**fingering**, **below** and **answer** - the tone holes, including the part of the tube past the note you're playing."),
                ManualBlock(ManualKind.Bullet, "**forked** - cross-fingerings, which sound a little different from normal fingerings like on a real instrument."),
                ManualBlock(ManualKind.Heading, "Blowing"),
                ManualBlock(ManualKind.Para, "**pressure** and **breath** work like Brazen's. The flutes add **jet** and **aim**, and **tongue** adds articulation."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Pressure decides the register. Overblow a clarinet and it jumps up a twelfth instead of an octave, like the real one."),
                ManualBlock(ManualKind.Bullet, "The breath noise is a big part of the realism."),
                ManualBlock(ManualKind.Bullet, "Use **tongue** between notes so a phrase doesn't sound like one long note."),
            )),
            ManualSection("Tine", "Modelled bars, tines and pans: marimba, vibraphone, xylophone, glockenspiel, thumb piano, music box, steel pan, handpan and tongue drum.", listOf(
                ManualBlock(ManualKind.Para, "Tine doesn't play recordings. Each note is a handful of resonances tuned the way the thing struck is tuned. A marimba bar is carved away underneath so its first overtone sits two octaves up and the next two octaves and a third; a xylophone's is carved to a twelfth; a glockenspiel's steel bar is left as it is, its overtones far from any chord. A thumb piano's tine is held at one end, which puts its overtones higher still, and a pan's note is hammered until it rings its octave and twelfth."),
                ManualBlock(ManualKind.Para, "What strikes it matters as much. A soft mallet stays on the bar for a few milliseconds and can only set the note going; a hard one is gone before the overtones start, so they ring out."),
                ManualBlock(ManualKind.Heading, "Bar"),
                ManualBlock(ManualKind.Bullet, "**model** - **marimba**, **vibes**, **xylophone**, **glock**, **thumb** (piano), **music box**, **steel pan**, **handpan** or **tongue drum**."),
                ManualBlock(ManualKind.Bullet, "**tune** - in cents."),
                ManualBlock(ManualKind.Bullet, "**mallet** - how hard the mallet, finger or pin: soft yarn to bare metal. Playing harder makes it a little harder too."),
                ManualBlock(ManualKind.Bullet, "**position** - where it's struck. In the middle a bar's second overtone stays quiet; towards the end the note thins and the overtones come up."),
                ManualBlock(ManualKind.Bullet, "**decay** - how long the notes ring. Low notes always ring longer."),
                ManualBlock(ManualKind.Bullet, "**bright** - how much of the overtones, and how long they last."),
                ManualBlock(ManualKind.Bullet, "**damp** - the damper bar: how much a note stops when you let it go. The sustain pedal lifts it."),
                ManualBlock(ManualKind.Heading, "Body"),
                ManualBlock(ManualKind.Bullet, "**tube** - the tube under each bar, ringing along with the note (and its odd overtones). On the pans and the tongue drum it's the shell."),
                ManualBlock(ManualKind.Bullet, "**motor** - the discs turning in a vibraphone's tubes, in turns a second. At 0 they stand still."),
                ManualBlock(ManualKind.Bullet, "**depth** - how much the turning discs pulse the note. The mod wheel adds to it."),
                ManualBlock(ManualKind.Bullet, "**bloom** - on the pans, how much the octave grows out of the note after it's struck."),
                ManualBlock(ManualKind.Bullet, "**buzz** - a rattle that touches a tine when it swings wide."),
                ManualBlock(ManualKind.Heading, "Play"),
                ManualBlock(ManualKind.Bullet, "**rolls** - held notes struck again and again, this many times a second, never quite evenly. At 0 a note is struck once."),
                ManualBlock(ManualKind.Bullet, "**spread** - low notes to the left, high to the right."),
                ManualBlock(ManualKind.Bullet, "**voices**, **velocity**, **octave**, **bend** and **volume**."),
                ManualBlock(ManualKind.Para, "Pressure (from the keyboard or each note's own, with MPE) draws a bow across a held bar: the note swells up and sustains for as long as you press."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "**Vibraphone** stops each note when you let it go; hold the sustain pedal to let them ring, as a vibraphone player does."),
                ManualBlock(ManualKind.Bullet, "**Vibes Motor** and **Slow Motor** turn the discs; the mod wheel deepens the pulse."),
                ManualBlock(ManualKind.Bullet, "**Marimba Roll**, **Vibes Roll** and **Pan Roll** need held notes."),
            )),
            ManualSection("Tongue", "A modelled jaw harp: a reed ringing through a slot, and a mouth that picks out its harmonics.", listOf(
                ManualBlock(ManualKind.Para, "Tongue doesn't play recordings. A steel reed is plucked and swings through a slot in its frame, and each time it passes through it pushes a puff of air. That's the buzz, with every harmonic in it at much the same level. Your mouth is in front of it, and as it changes shape it brings one harmonic forward and then another: that's the tune, over a drone that stays on the note you play."),
                ManualBlock(ManualKind.Para, "There are ten kinds of harp, and the metal ones were fitted to recordings of real ones. A harp can have up to five reeds, tuned as a chord."),
                ManualBlock(ManualKind.Para, "The mod wheel moves the mouth, so you can play the drone with one hand and the tune with the other. Or put **play** on **mouth**, and the keys play the tune the way a player does, over a drone that stays put. Pressure is breath."),
                ManualBlock(ManualKind.Heading, "Harp"),
                ManualBlock(ManualKind.Bullet, "**model** - the kind of harp: - **steel** - the common steel harp, with a long ring. - **munnharpe** - a low Norwegian harp, soft and round. - **khomus** - a Sakha harp, darker on top than steel, often breathed through as it's played. - **morsing** - a big South Indian harp: low, dark and short, for rhythm. - **temir komuz** - a Kyrgyz harp: a close fit, bright and ringing. - **brass** - a thin brass harp cut from its own frame: high, buzzy and quiet, with the frame ringing too. - **bamboo** - a reed cut from a strip of bamboo: soft, airy and short, with a woody tock. - **mukkuri** - a bamboo harp played by pulling a string tied to its frame. - **genggong** - a palm harp, also string-pulled: a quick tug and a buzz. - **kouxian** - a harp of several reeds, three tuned to a pentatonic chord unless you set **reeds** and **chord** yourself."),
                ManualBlock(ManualKind.Bullet, "**tune** - in cents."),
                ManualBlock(ManualKind.Bullet, "**set** - where the reed rests in the slot. In the middle the puffs come evenly and the odd harmonics are louder; off to one side the even ones come up with them."),
                ManualBlock(ManualKind.Bullet, "**fit** - how closely the reed fits the slot. A close fit makes sharper puffs and more high harmonics; a loose one is softer and hollower."),
                ManualBlock(ManualKind.Bullet, "**ring** - how long a steel harp rings, in seconds. The other kinds ring longer or shorter than that."),
                ManualBlock(ManualKind.Para, "**set**, **fit** and **pluck** start where each kind sits, so a morsing with those knobs at their defaults is already a morsing."),
                ManualBlock(ManualKind.Heading, "Pluck"),
                ManualBlock(ManualKind.Bullet, "**pluck** - how sharp the flick is. Up is a quick flick with a click in it, down is a soft push with the pad of the finger."),
                ManualBlock(ManualKind.Bullet, "**overtones** - how much of the pluck goes into the reed's own overtones, the metallic ping at the start."),
                ManualBlock(ManualKind.Bullet, "**velocity** - how much playing harder changes the level."),
                ManualBlock(ManualKind.Para, "Pluck a key that's still ringing and the finger catches the reed first, so it doesn't keep getting louder. The string-pulled kinds are drawn back and let go instead, and **pluck** sets how quickly."),
                ManualBlock(ManualKind.Heading, "Reeds"),
                ManualBlock(ManualKind.Bullet, "**reeds** - how many reeds the harp has, or **auto** for the kind's own."),
                ManualBlock(ManualKind.Bullet, "**chord** - how they're tuned against the note you play: **unison** (a few cents apart), **octaves**, **fifths**, **major**, **minor** or **pentatonic**, or **auto** for the kind's own."),
                ManualBlock(ManualKind.Bullet, "**strum** - the time between one reed and the next, in ms. At 0 they're plucked together."),
                ManualBlock(ManualKind.Bullet, "**order** - **up** or **down** the chord, **scatter** in a different order each time, or **in turn**: each note plucks only the next reed, and the others keep ringing, so playing a rhythm on one key plays the chord."),
                ManualBlock(ManualKind.Heading, "Mouth"),
                ManualBlock(ManualKind.Bullet, "**vowel** - the shape of the mouth: oo, oh, ah, eh, ee. The mod wheel adds to it."),
                ManualBlock(ManualKind.Bullet, "**focus** - how narrow the mouth's resonances are. Up, each one picks out a single harmonic and the tune gets clearer."),
                ManualBlock(ManualKind.Bullet, "**depth** - how much of the sound goes through the mouth."),
                ManualBlock(ManualKind.Bullet, "**glide** - how long the mouth takes to move to a new vowel, in ms."),
                ManualBlock(ManualKind.Bullet, "**words** - how far a clip's words move the mouth. See below."),
                ManualBlock(ManualKind.Para, "The mouth keeps the level steady, so moving it changes the colour and not the loudness."),
                ManualBlock(ManualKind.Heading, "Words and following"),
                ManualBlock(ManualKind.Para, "Tongue can talk. Give its notes words in the editor's **words** lane, as for Diction, and the mouth shapes each note's word: the vowel held while the note is down, the sounds before it on the way in, and the ones after it when you let go. An S or a T hisses. A harp only talks so clearly, so short, open words with plenty of vowel come through best."),
                ManualBlock(ManualKind.Para, "The mouth can also follow another track. Set **follow** to that track, and its melody moves the mouth onto the drone's nearest harmonic, as the keys do in mouth mode. Its octave doesn't matter: every note is brought into the harmonics the mouth picks out best, the 3rd to the 12th. When that track goes quiet the mouth goes back to the keys. Hold a drone with a pattern on and the harp plays the other track's tune."),
                ManualBlock(ManualKind.Heading, "Breath"),
                ManualBlock(ManualKind.Bullet, "**breath** - air blown through the harp while you play. Pressure adds to it."),
                ManualBlock(ManualKind.Bullet, "**air** - how much of that air you hear as a hiss."),
                ManualBlock(ManualKind.Bullet, "**sustain** - breath hard enough to keep the reed going while the key is down. With **breath** and **sustain** both up, a held note doesn't die."),
                ManualBlock(ManualKind.Heading, "Keys"),
                ManualBlock(ManualKind.Bullet, "**play** - what the keys do. - **drone** - each key plucks a harp at its own pitch. - **mouth** - one harp stays on the **drone** note, and each key moves the mouth onto the drone's harmonic nearest to it, so the tune is in the harmonics, as on a real harp. Keys snap to the nearest harmonic, from the 2nd up. Letting go of a key goes back to the one still down."),
                ManualBlock(ManualKind.Bullet, "**drone** - the drone's note in mouth mode."),
                ManualBlock(ManualKind.Bullet, "**repluck** - in mouth mode, when a key plucks the harp again: **every** key, only the **first** after the others are let go, or **loud** keys (velocity 100 and up)."),
                ManualBlock(ManualKind.Heading, "Rhythm"),
                ManualBlock(ManualKind.Para, "While a key is down the harp is plucked again in a rhythm, in time with the song, even when it's stopped."),
                ManualBlock(ManualKind.Bullet, "**pattern** - **off**, **eighths**, **sixteenths**, **gallop** (long, short, short), **triplets**, **runs** (quick runs of four and a rest, as a genggong is pulled) or **groupings** (sixteenths in groups of four and three, as on a morsing)."),
                ManualBlock(ManualKind.Bullet, "**accent** - how much softer the weak steps are."),
                ManualBlock(ManualKind.Bullet, "**ratchet** - how often a step is two or three quick plucks."),
                ManualBlock(ManualKind.Para, "In mouth mode the pattern plucks the drone while the keys play the tune."),
                ManualBlock(ManualKind.Heading, "Out"),
                ManualBlock(ManualKind.Bullet, "**stop** - letting go of a key puts a finger on the reed. Down, it rings on; up, it stops quickly."),
                ManualBlock(ManualKind.Bullet, "**voices** - one harp, or up to four. With one, a new note replucks the same harp at the new pitch."),
                ManualBlock(ManualKind.Bullet, "**octave**, **bend** - the octave, and the pitch bend range in semitones."),
                ManualBlock(ManualKind.Bullet, "**volume**."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Start with the **model**. The kinds differ more than any knob moves them."),
                ManualBlock(ManualKind.Bullet, "The tune is in the mouth. Leave **play** on **drone**, hold a note, and move the mod wheel, or put **play** on **mouth** and play the tune on the keys."),
                ManualBlock(ManualKind.Bullet, "A **pattern** on one held note is most of jaw harp playing. Try **gallop**."),
                ManualBlock(ManualKind.Bullet, "Low drones talk best: around D3 and below, the harmonics the mouth picks are close together and the tune comes through clearly."),
                ManualBlock(ManualKind.Bullet, "For a sound that never stops, turn **breath** and **sustain** up."),
            )),
            ManualSection("Trinity", "Three oscillators, wavetables, two filters and a mod matrix: the all-rounder.", listOf(
                ManualBlock(ManualKind.Para, "Trinity is the general-purpose poly synth, three oscillators into two filters with a modulation matrix on top."),
                ManualBlock(ManualKind.Heading, "Oscillators"),
                ManualBlock(ManualKind.Para, "Each oscillator plays a wavetable, a row of waveshapes that **pos** moves through. Automate **pos** to sweep the tone."),
                ManualBlock(ManualKind.Bullet, "**density** stacks copies of the oscillator, **detune** spreads them out and **drift** makes each copy wander a little. This is how you get a big supersaw sound."),
                ManualBlock(ManualKind.Bullet, "**hard** is oscillator sync and **pw** is pulse width."),
                ManualBlock(ManualKind.Bullet, "**fm21** and **fm32** are FM between the oscillators (2 into 1, 3 into 2), for metallic and bell sounds."),
                ManualBlock(ManualKind.Bullet, "**noise** and its **colour** are for breath, snare tails, etc."),
                ManualBlock(ManualKind.Heading, "Filters"),
                ManualBlock(ManualKind.Para, "There are two. **route** puts them in series, in parallel or split with **balance** between them, and each has its own type, drive, key tracking and envelope amount."),
                ManualBlock(ManualKind.Heading, "Modulation"),
                ManualBlock(ManualKind.Para, "Six envelopes and three LFOs feed twelve matrix rows."),
                ManualBlock(ManualKind.Para, "The **a** envelope is the amplitude and **f** is the filter, and the other four do nothing until you route them. Each LFO has a wave, a rate that can sync to the tempo, delay, phase, key sync, one-shot and slew."),
                ManualBlock(ManualKind.Para, "A matrix row has a source, a second source, a destination and a depth. The second source scales the first, so an envelope with the mod wheel as its second source is an envelope you can fade in with the wheel."),
                ManualBlock(ManualKind.Para, "The mod wheel also opens both filters, whatever the matrix says, and **wheel** in the voice section sets how much. At zero the wheel only does what the matrix tells it to."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Start with the oscillators (table position and density) instead of the filter. That's where Trinity's character is."),
                ManualBlock(ManualKind.Bullet, "High density costs the most CPU. If a song is struggling, freeze the Trinity clip with the biggest stack."),
            )),
        )),
        ManualSection("Effects and mixing", "", listOf(
            ManualBlock(ManualKind.Heading, "Inserts"),
            ManualBlock(ManualKind.Para, "Each track has two insert effect slots. **fx** in the editor's bottom bar shows them in place of the machine panel."),
            ManualBlock(ManualKind.Para, "There are twenty-nine effects. Each one has the usual controls plus one extra, shown in the accent colour. Every effect ends with **gain**, an output level trim, since turning up the wet/dry mix can change the level."),
            ManualBlock(ManualKind.Para, "Each effect has its own page below."),
            ManualBlock(ManualKind.Heading, "Time"),
            ManualBlock(ManualKind.Bullet, "**Delay** - echoes on a note value, and it can duck while you play."),
            ManualBlock(ManualKind.Bullet, "**Reverb** - a room that can also freeze, gate, shimmer or crush itself down to 8 bits."),
            ManualBlock(ManualKind.Bullet, "**Grain** - a cloud of short slices of what the track just played, which can freeze."),
            ManualBlock(ManualKind.Bullet, "**Tape** - a worn tape machine: wow, flutter, saturation and hiss, and a switch that slows it to a stop."),
            ManualBlock(ManualKind.Bullet, "**Slicer** - cuts the track into slices on the beat and repeats, reverses or drops some of them."),
            ManualBlock(ManualKind.Heading, "Tone"),
            ManualBlock(ManualKind.Bullet, "**Eq** - three bands and a tilt."),
            ManualBlock(ManualKind.Bullet, "**Filter** - low, band or high pass, moved by an LFO, the signal's level or another track."),
            ManualBlock(ManualKind.Bullet, "**Width** - wider, narrower, mono below a frequency or rotated."),
            ManualBlock(ManualKind.Bullet, "**Acid** - the acid bass filter on any track, opened by each note or by a pattern on the beat."),
            ManualBlock(ManualKind.Bullet, "**Mouth** - vowels, moved by an LFO, the track's level or another track."),
            ManualBlock(ManualKind.Bullet, "**Spectral** - freeze, blur, smear or robotise the track's frequencies."),
            ManualBlock(ManualKind.Heading, "Drive"),
            ManualBlock(ManualKind.Bullet, "**Distortion** - four kinds of clipping and a bias control."),
            ManualBlock(ManualKind.Bullet, "**Amp** - a guitar amp with a cabinet you can resize."),
            ManualBlock(ManualKind.Bullet, "**Bitcrusher** - fewer bits and a lower sample rate, with an unsteady clock if you want it."),
            ManualBlock(ManualKind.Bullet, "**Magneto** - the sound of a small recordable disc's formats, from the clean original to the long-play swirl, copied up to four times."),
            ManualBlock(ManualKind.Bullet, "**Formula** - type a formula and it shapes the track, a sample at a time."),
            ManualBlock(ManualKind.Heading, "Level"),
            ManualBlock(ManualKind.Bullet, "**Compressor** - the usual controls, a sidechain from any track and a tempo-synced pump."),
            ManualBlock(ManualKind.Bullet, "**Gate** - a noise gate that another track can open."),
            ManualBlock(ManualKind.Bullet, "**Swell** - upward compression, in one band or three: the quiet parts come up to meet the loud ones."),
            ManualBlock(ManualKind.Bullet, "**Smash** - three bands squashed from both sides: loud parts down, quiet parts up."),
            ManualBlock(ManualKind.Heading, "Movement"),
            ManualBlock(ManualKind.Bullet, "**Chorus** - two to four detuned voices that drift."),
            ManualBlock(ManualKind.Bullet, "**Flanger** - a short sweeping delay, with negative feedback for the hollow sound."),
            ManualBlock(ManualKind.Bullet, "**Phaser** - two to eight stages."),
            ManualBlock(ManualKind.Bullet, "**Tremolo** - volume on an LFO, or auto-pan."),
            ManualBlock(ManualKind.Bullet, "**Rotary** - the organ's rotating speaker cabinet, slow, fast or on the beat."),
            ManualBlock(ManualKind.Heading, "Pitch"),
            ManualBlock(ManualKind.Bullet, "**Shifter** - frequency shifting, for metallic and detuned sounds."),
            ManualBlock(ManualKind.Bullet, "**Harmonizer** - adds two voices at scale steps, so they stay in key."),
            ManualBlock(ManualKind.Bullet, "**Resonator** - strings tuned to a key, ringing in sympathy with the track."),
            ManualBlock(ManualKind.Bullet, "**Horn** - the track plays a horn, a clarinet, an oboe or a flute, following its pitch and level."),
            ManualBlock(ManualKind.Heading, "Input effects"),
            ManualBlock(ManualKind.Para, "There are two more effect slots on the **input**. They're at the top of the recording window's **record** page (under **printed into the recording**), and on Bias's panel under **printed in**."),
            ManualBlock(ManualKind.Bullet, "An effect **on the input** runs before anything else hears the audio, so it's **recorded into the take**."),
            ManualBlock(ManualKind.Bullet, "An effect **on a track** runs on playback, so you can change it later."),
            ManualBlock(ManualKind.Para, "So put an amp on the input if you've decided on the sound, or on the track to keep your options open. Input effects keep their **mix** control."),
            ManualBlock(ManualKind.Heading, "The mixer"),
            ManualBlock(ManualKind.Para, "The mixer button opens a strip for each track, plus the master. The tabs down its left edge switch between the mixer and the three perform pages."),
            ManualBlock(ManualKind.Bullet, "**Fader and meter** for each track, with mute and solo."),
            ManualBlock(ManualKind.Bullet, "**Two send amounts** per track, going to two effects shared by the whole song."),
            ManualBlock(ManualKind.Bullet, "**Pan**, and a MIDI row for what the track sends out."),
            ManualBlock(ManualKind.Bullet, "A **∿ next to a track's name** means something on that channel is automated. Tap it to see which lanes, and to clear them from every clip on the track. Notes aren't touched.", "A **∿ next to a track's name** means something on that channel is automated. Click it to see which lanes, and to clear them from every clip on the track. Notes aren't touched."),
            ManualBlock(ManualKind.Para, "After the tracks come the **groups**, if the song has any, and a **+ group** button. Last is the master strip, with the master fader, the limiter's **limit drive** and the loudness readout. Under that is a grid of buttons: the two sends on top, the two master inserts (**fx1**, **fx2**) in the middle, and the limiter (**lim**) and the click (**♩**) at the bottom. Tap one to turn it on or off, and hold a send or insert to choose its effect and set it up.", "After the tracks come the **groups**, if the song has any, and a **+ group** button. Last is the master strip, with the master fader, the limiter's **limit drive** and the loudness readout. Under that is a grid of buttons: the two sends on top, the two master inserts (**fx1**, **fx2**) in the middle, and the limiter (**lim**) and the click (**♩**) at the bottom. Click one to turn it on or off, and hold a send or insert to choose its effect and set it up."),
            ManualBlock(ManualKind.Heading, "Perform"),
            ManualBlock(ManualKind.Para, "The tabs down the mixer's left edge are **mix**, **hold**, **pad** and **live**. The last three are for playing the song live."),
            ManualBlock(ManualKind.Para, "The effects on **hold** and **pad** work on the whole mix, after the master inserts, and they're only on while you hold them unless **latch** is on. With latch on, a tap turns something on and another tap turns it off, and the pad stays where you leave it. Turning latch off lets go of everything on that page.", "The effects on **hold** and **pad** work on the whole mix, after the master inserts, and they're only on while you hold them unless **latch** is on. With latch on, a click turns something on and another click turns it off, and the pad stays where you leave it. Turning latch off lets go of everything on that page."),
            ManualBlock(ManualKind.Para, "If the song has groups, **on all** picks what the effects work on: the whole mix or just one group, like repeating only the drums. Tap it to go through the groups.", "If the song has groups, **on all** picks what the effects work on: the whole mix or just one group, like repeating only the drums. Click it to go through the groups."),
            ManualBlock(ManualKind.Para, "If you're recording, everything you do on **hold** and **pad** is recorded into the clip of the last track you opened, as automation. Stopping the song lets go of anything held."),
            ManualBlock(ManualKind.Subheading, "Hold"),
            ManualBlock(ManualKind.Bullet, "**repeat** loops the last slice of the song. The five buttons are the slice length, from a beat down to a sixteenth, and you can slide along them without letting go. While the song plays the slice starts on the beat, so it stays in time."),
            ManualBlock(ManualKind.Bullet, "**gate** chops the sound on and off in time. The five buttons are how fast: eighths, sixteenths, thirty-seconds or eighth and sixteenth triplets."),
            ManualBlock(ManualKind.Bullet, "**reverse** plays the last beat backwards, over and over, in time with the song. Hold it with a repeat and the repeat plays backwards."),
            ManualBlock(ManualKind.Bullet, "**stop** slows the song to a stop like a tape machine losing power, and spins back up when you let go. **stop** under it sets how long it takes."),
            ManualBlock(ManualKind.Bullet, "**riser** builds up to a drop. A high pass climbs and noise rises under it over 1, 2 or 4 bars (**riser** under it), then snaps back when you let go."),
            ManualBlock(ManualKind.Subheading, "Pad"),
            ManualBlock(ManualKind.Para, "Left and right is a filter, low pass to the left of the middle and high pass to the right. Up is how much of the mix goes into an echo. Let go and the echo keeps repeating and dies away. **echo** sets its time and **feedback** how long it lasts."),
            ManualBlock(ManualKind.Para, "**x** and **y** change what the pad does:"),
            ManualBlock(ManualKind.Bullet, "**x crush** makes left and right a bit crusher instead of a filter, with fewer samples to the left of the middle and fewer bits to the right. It crushes a quiet mix as much as a loud one."),
            ManualBlock(ManualKind.Bullet, "**y wash** throws into a short smeared echo that sounds more like a big reverb than repeats. It has no time setting, and **feedback** still sets how long it lasts."),
            ManualBlock(ManualKind.Para, "Under the pad, **kill low**, **kill mid** and **kill high** take that part of the sound out while you hold them: below 250 Hz, 250 Hz to 2.5 kHz, and above 2.5 kHz."),
            ManualBlock(ManualKind.Subheading, "Live"),
            ManualBlock(ManualKind.Para, "A mute button for every track (the same mute as the mixer's), and **fill**."),
            ManualBlock(ManualKind.Para, "While the song plays, a mute waits for the next bar and lands on it, so tracks drop in and out in time. The button is outlined until it does. **mute on** sets what it waits for: a bar, a beat or nothing (**now**). When the song is stopped, mutes happen straight away. If you're recording, the mutes are recorded into each track's own clip."),
            ManualBlock(ManualKind.Para, "Notes set to play on fill only play while **fill** is held. Fill isn't recorded."),
            ManualBlock(ManualKind.Heading, "Master inserts"),
            ManualBlock(ManualKind.Para, "**fx1** and **fx2** process the whole mix, including the sends, before the master fader and the limiter. Use them for things that apply to the whole song, like a gentle EQ, a bit of glue compression, some tape drive or narrowing the low end."),
            ManualBlock(ManualKind.Para, "A send is added alongside the mix, and each track chooses how much to send. A master insert processes everything equally. So reverb and delay usually go on sends, and EQ and compression for the whole song go on the master inserts."),
            ManualBlock(ManualKind.Heading, "Groups"),
            ManualBlock(ManualKind.Para, "A group is a strip in the mixer that tracks can be routed through. It has no machine and no clips, and it isn't in the song grid."),
            ManualBlock(ManualKind.Para, "Tap **+ group** in the mixer to add one (up to four). Tap a group's name to rename it, and the **✕** beside it or holding the name deletes it. Once the song has a group, each track strip gets an extra row at the bottom. Tap it to send that track to the master or to one of the groups.", "Click **+ group** in the mixer to add one (up to four). Click a group's name to rename it, and the **✕** beside it or holding the name deletes it. Once the song has a group, each track strip gets an extra row at the bottom. Click it to send that track to the master or to one of the groups."),
            ManualBlock(ManualKind.Para, "A group strip has a fader, pan, mute and solo, and lists the tracks going into it."),
            ManualBlock(ManualKind.Para, "Everything routed into a group goes through the group's two effects (**fx1**, **fx2**) and its fader before the master, so you can put one compressor on all the drums or turn a whole section down with one fader."),
            ManualBlock(ManualKind.Bullet, "A track's **sends** still go straight to the send effects, not through the group."),
            ManualBlock(ManualKind.Bullet, "**Solo** a group to hear all of it. Solo a track inside a group to hear just that track, still through the group's effects."),
            ManualBlock(ManualKind.Bullet, "Deleting a group sends its tracks back to the master."),
            ManualBlock(ManualKind.Bullet, "When you export **stems**, each group is a stem with its tracks in it, and those tracks don't get their own stems."),
            ManualBlock(ManualKind.Heading, "Sidechain"),
            ManualBlock(ManualKind.Para, "The compressor, gate and filter can follow another track instead of their own input. Set **sidechain** in the effect to the track you want. The classic use is a compressor on the bass keyed to the kick, so the bass ducks on every kick."),
            ManualBlock(ManualKind.Para, "The sidechain hears the other track before its fader and mute, so turning the kick down doesn't weaken the ducking, and a muted kick still works as a trigger."),
            ManualBlock(ManualKind.Heading, "The two sends"),
            ManualBlock(ManualKind.Para, "They start as a reverb and a delay, but either can hold any effect. The send buttons on the master strip show what's on them. Tap to turn one on or off, and hold to choose and set up the effect. The send sliders on each track are named after what's on the sends.", "They start as a reverb and a delay, but either can hold any effect. The send buttons on the master strip show what's on them. Click to turn one on or off, and hold to choose and set up the effect. The send sliders on each track are named after what's on the sends."),
            ManualBlock(ManualKind.Para, "A send is always fully wet, since the dry sound is already in the mix, so a send's editor has no mix control."),
            ManualBlock(ManualKind.Para, "Some effects are fun on a send, like a pitch shifter fed a little from several tracks, or a bitcrusher for a trashed copy of the mix sitting behind it."),
            ManualBlock(ManualKind.Heading, "Tempo and song settings"),
            ManualBlock(ManualKind.Para, "Tap the tempo in the song header to open the song's settings.", "Click the tempo in the song header to open the song's settings."),
            ManualBlock(ManualKind.Bullet, "**beats a minute** - type a number or use the buttons either side. **tap** sets it from four taps."),
            ManualBlock(ManualKind.Bullet, "**bar** - the time signature, from 4/4 to 7/8. A scene can have its own."),
            ManualBlock(ManualKind.Bullet, "**swing** - how late the offbeats are. **triplet** is the classic shuffle. **swing on** chooses whether it swings sixteenths or eighths."),
            ManualBlock(ManualKind.Bullet, "**key** - the song's key and scale. The piano roll shades notes outside it, and a new track gets a matching scale. It doesn't change any notes, or a track with its own scale."),
            ManualBlock(ManualKind.Bullet, "**tuning** - how the notes are tuned. Hold it for the list."),
            ManualBlock(ManualKind.Para, "The **click** and **link** pages are in the same window."),
            ManualBlock(ManualKind.Heading, "Tunings"),
            ManualBlock(ManualKind.Para, "Equal temperament is the usual tuning, with every semitone the same size. The others make some intervals purer and others rougher."),
            ManualBlock(ManualKind.Bullet, "**just** - fifths and thirds as pure as they get. Great in the key it's tuned to, and rough in keys far from it."),
            ManualBlock(ManualKind.Bullet, "**pythagorean** - pure fifths, bright thirds."),
            ManualBlock(ManualKind.Bullet, "**meantone** - pure thirds, slightly narrow fifths."),
            ManualBlock(ManualKind.Bullet, "**werckmeister** - a well temperament, where every key works and each is a little different."),
            ManualBlock(ManualKind.Bullet, "**19 equal** and **24 equal** - more than twelve notes an octave. The octave is 19 or 24 keys up, so the keyboard plays small steps. 24 is quarter tones."),
            ManualBlock(ManualKind.Para, "A tuning is counted from the song's **root**. The root's own note in the middle of the keyboard keeps its usual pitch, so an A tuning leaves A at 440 and the rest move around it. Change the root and the tuning follows."),
            ManualBlock(ManualKind.Para, "A track can have its own tuning in its settings (hold the track's name), where **song** means it uses the song's. Drum machines always play in equal temperament."),
            ManualBlock(ManualKind.Para, "Bring in your own tunings as Scala files (.scl) with **Import…** in the file menu and they join the list. The tuning is saved in the song, so it plays the same on a phone that has never seen the file."),
            ManualBlock(ManualKind.Heading, "How swing works"),
            ManualBlock(ManualKind.Para, "Swing moves the offbeats later without changing the order of notes, so a loosely played part swings along with everything else."),
            ManualBlock(ManualKind.Para, "A track can have its own swing, like swung drums over a straight bass. Set it in the track's settings by holding the track's name."),
            ManualBlock(ManualKind.Para, "What you record is stored straight. When you play against a swung song, the swing is taken back out before the notes are written, so the roll shows where you meant the notes and turning the swing down later leaves the part straight."),
            ManualBlock(ManualKind.Para, "The click is never swung."),
        ), listOf(
            ManualSection("Acid", "Reflux's filter on any track, swept by the track's hits or a pattern.", listOf(
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**cutoff** - where the filter rests, 40 Hz to 12 kHz."),
                ManualBlock(ManualKind.Bullet, "**resonance** - how much it rings. Near the top it screams."),
                ManualBlock(ManualKind.Bullet, "**env** - how far each sweep opens it, up to four octaves."),
                ManualBlock(ManualKind.Bullet, "**decay** - how fast it falls back, 30 ms to 3 s."),
                ManualBlock(ManualKind.Bullet, "**accent** *(extra)* - how much further an accented sweep goes, and how much louder it is."),
                ManualBlock(ManualKind.Bullet, "**pattern** *(extra)* - what starts the sweep. **track** is the track itself: each hit opens it, and a loud one is an accent. The other eight are sixteen-step patterns on the tempo, with accents."),
                ManualBlock(ManualKind.Bullet, "**drive** - saturation after the filter."),
                ManualBlock(ManualKind.Bullet, "**mode** - low pass or band pass."),
                ManualBlock(ManualKind.Bullet, "**mix** - the dry sound against the filtered one."),
                ManualBlock(ManualKind.Bullet, "**gain** - the level out."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Put it on a held chord with **pattern** at **16ths** for an acid line out of a pad."),
                ManualBlock(ManualKind.Bullet, "On a drum loop with **pattern** at **track**, every hit barks."),
                ManualBlock(ManualKind.Bullet, "Band pass with the track as the pattern is a wah that follows the playing."),
            )),
            ManualSection("Amp", "A guitar amp with a cabinet you can resize.", listOf(
                ManualBlock(ManualKind.Para, "A guitar amp with the full chain: a preamp, a tone stack, a power stage and a speaker cabinet. The tone stack sits between the preamp and the power stage like on a real amp."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**drive** and **bias** - the preamp. Bias makes the clipping lopsided for an older, woollier sound."),
                ManualBlock(ManualKind.Bullet, "**bass**, **mid**, **treble** and **stack** - these interact like a real amp's tone controls, so bass and treble up scoops the mids. **stack** (us, uk or modern) changes the whole character of the amp."),
                ManualBlock(ManualKind.Bullet, "**presence** - pushes the power stage harder in the upper mids."),
                ManualBlock(ManualKind.Bullet, "**master** - how hard the power stage is driven. Low drive with high master sounds different from the other way round at the same volume."),
                ManualBlock(ManualKind.Bullet, "**sag** - how much the power supply droops when you play hard, which makes the amp feel springy."),
                ManualBlock(ManualKind.Bullet, "**cab** - the cabinet, or off."),
                ManualBlock(ManualKind.Bullet, "**size** and **cone** *(extra)* - resize the cabinet smoothly, from a small combo to a 4x12 to a big bass cab, and anything in between."),
                ManualBlock(ManualKind.Bullet, "**mic**, **edge** and **room** - where the microphone is: angle, centre of the cone or edge, and distance."),
                ManualBlock(ManualKind.Bullet, "**mix** - wet against dry."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Set **drive** and **master** before the tone controls."),
                ManualBlock(ManualKind.Bullet, "If it sounds harsh, move the mic with **edge** before turning down treble."),
                ManualBlock(ManualKind.Bullet, "Keep **mix** low on a bass or synth for some grit without losing the low end."),
                ManualBlock(ManualKind.Bullet, "Amp uses the most CPU of any effect. One is fine, a dozen is a lot."),
            )),
            ManualSection("Bitcrusher", "Fewer bits and a lower sample rate, with an unsteady clock if you want it.", listOf(
                ManualBlock(ManualKind.Para, "**bits** lowers the resolution and **rate** lowers the sample rate. They sound quite different, so they have their own controls."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**bits** - 16 down to 1. Adds noise that follows the signal."),
                ManualBlock(ManualKind.Bullet, "**rate** - 48 kHz down to 500 Hz, for the metallic lo-fi sound."),
                ManualBlock(ManualKind.Bullet, "**jitter** *(extra)* - makes the sample clock unsteady, like old samplers."),
                ManualBlock(ManualKind.Bullet, "**tone** *(extra)* - a low-pass after the crushing to take off some of the fizz."),
                ManualBlock(ManualKind.Bullet, "**mix** - wet against dry."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Most of the lo-fi sound comes from **rate**. **bits** on its own mostly adds hiss."),
                ManualBlock(ManualKind.Bullet, "A little **jitter** makes it sound more like an old machine."),
                ManualBlock(ManualKind.Bullet, "On a send with **tone** around 4 kHz, you get a trashed copy of the song behind the clean one."),
            )),
            ManualSection("Chorus", "Two to four detuned voices that drift.", listOf(
                ManualBlock(ManualKind.Para, "A chorus made of several voices at different delays, each swept by its own part of the LFO, so it sounds like a group instead of one doubled copy."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**rate** - how fast the voices sweep, as a note value."),
                ManualBlock(ManualKind.Bullet, "**depth** - how far each one moves. Small thickens, large gets seasick."),
                ManualBlock(ManualKind.Bullet, "**voices** - two, three or four. Two sounds like doubling and four like an ensemble."),
                ManualBlock(ManualKind.Bullet, "**spread** - how wide the voices are in stereo."),
                ManualBlock(ManualKind.Bullet, "**drift** *(extra)* - each voice wanders randomly, like an old analogue chorus with an unsteady clock."),
                ManualBlock(ManualKind.Bullet, "**mix** - wet against dry."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "If it sounds fake, use more voices and less depth."),
                ManualBlock(ManualKind.Bullet, "A little **drift** makes it sound analogue."),
                ManualBlock(ManualKind.Bullet, "It's wide by default, so turn **spread** down on a lead or bass."),
            )),
            ManualSection("Compressor", "The usual controls, a sidechain from any track and a tempo-synced pump.", listOf(
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**threshold** - the level it starts working above, -60 to 0 dB."),
                ManualBlock(ManualKind.Bullet, "**ratio** - how hard it compresses, 1:1 to 20:1. Above about 10:1 it acts as a limiter."),
                ManualBlock(ManualKind.Bullet, "**attack** - how fast it reacts, 0.1 to 100 ms. Slower lets the start of each hit through, which makes drums punchier."),
                ManualBlock(ManualKind.Bullet, "**release** - how fast it lets go, 10 to 1000 ms."),
                ManualBlock(ManualKind.Bullet, "**makeup** - adds level back, up to 24 dB."),
                ManualBlock(ManualKind.Bullet, "**pump** *(extra)* - ducks the sound in time with the song, like a sidechain from a kick that isn't there."),
                ManualBlock(ManualKind.Bullet, "**pumprate** *(extra)* - how often it pumps: 1/16, 1/8, 1/4 or 1/2."),
                ManualBlock(ManualKind.Bullet, "**sidechain** - what the compressor listens to: **own** (this track) or another track, which pushes this one down whenever that track is loud. It hears the other track before its fader and mute, so a muted kick still works as a trigger."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "On drums, **attack** changes the tone. Around 20 ms is punchier and 1 ms is flatter."),
                ManualBlock(ManualKind.Bullet, "To duck the bass under the kick, set **sidechain** on the bass's compressor to the drums, ratio 8:1 or more, the fastest attack and release 80-150 ms, then lower the threshold until it ducks 6-10 dB on each kick."),
                ManualBlock(ManualKind.Bullet, "A real sidechain follows the actual drums, fills included. **pump** needs no routing and never misses a beat, which is handy before the drums are written."),
                ManualBlock(ManualKind.Bullet, "On the master, go gentle: 2:1, with 2-3 dB of reduction on the loud parts."),
            )),
            ManualSection("Delay", "Echoes on a note value, and it can duck while you play.", listOf(
                ManualBlock(ManualKind.Para, "A delay timed to the song. **time** is a note value, so a dotted-eighth delay stays a dotted eighth when the tempo changes."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**time** - the gap between echoes, from 1/32 to a whole bar, including dotted and triplet values."),
                ManualBlock(ManualKind.Bullet, "**feedback** - how much of each echo is fed back in, up to 0.95."),
                ManualBlock(ManualKind.Bullet, "**tone** - a low-pass on the echoes, so each repeat is duller than the last."),
                ManualBlock(ManualKind.Bullet, "**pingpong** - how much the echoes bounce between left and right."),
                ManualBlock(ManualKind.Bullet, "**mix** - how much of the echo you hear."),
                ManualBlock(ManualKind.Bullet, "**duck** *(extra)* - turns the echoes down while the dry sound plays and brings them back in the gaps."),
                ManualBlock(ManualKind.Bullet, "**wobble** *(extra)* - makes the delay time drift slowly like a tape machine. A little warms it up, and more detunes the echoes."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Bring **tone** down to a few kHz so long feedback fades into the background instead of piling up."),
                ManualBlock(ManualKind.Bullet, "Use **duck** instead of lowering the mix to stop the delay swamping a part."),
                ManualBlock(ManualKind.Bullet, "On a send the delay is always fully wet, and each track's send slider sets how much goes to it."),
            )),
            ManualSection("Distortion", "Four kinds of clipping and a bias control.", listOf(
                ManualBlock(ManualKind.Para, "Drive into clipping, with a tone control after it."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**drive** - how hard the signal is pushed, 1 to 40."),
                ManualBlock(ManualKind.Bullet, "**tone** - a low-pass after the clipping, to tame the fizz."),
                ManualBlock(ManualKind.Bullet, "**mix** - wet against dry. A little distortion mixed under the clean sound thickens it without making it dirty."),
                ManualBlock(ManualKind.Bullet, "**mode** *(extra)* - soft, hard, fold or diode. Soft rounds the peaks, hard squares them off, fold changes character as it gets louder and diode is lopsided."),
                ManualBlock(ManualKind.Bullet, "**bias** *(extra)* - makes the top and bottom of the wave clip differently, for warmer, tube-like harmonics."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "A little bias is what makes distortion sound warm."),
                ManualBlock(ManualKind.Bullet, "Fold changes the tone as you play harder instead of just getting louder."),
                ManualBlock(ManualKind.Bullet, "This one isn't oversampled like Amp is, so it has some rough edges on purpose."),
            )),
            ManualSection("Eq", "Three bands and a tilt.", listOf(
                ManualBlock(ManualKind.Para, "A low shelf, a sweepable mid band and a high shelf."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**lowgain** and **lowfreq** - a shelf up to 15 dB either way, from 40 to 500 Hz."),
                ManualBlock(ManualKind.Bullet, "**midgain**, **midfreq** and **midq** - the mid band. **midq** goes from broad (0.3) to very narrow (6)."),
                ManualBlock(ManualKind.Bullet, "**highgain** and **highfreq** - the high shelf, from 1.5 to 16 kHz."),
                ManualBlock(ManualKind.Bullet, "**tilt** *(extra)* - one knob that lifts the top and lowers the bottom, or the other way round."),
                ManualBlock(ManualKind.Bullet, "**gain** - output level."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Cutting usually helps more than boosting."),
                ManualBlock(ManualKind.Bullet, "To get rid of a ringing frequency, boost with a narrow Q, sweep until it's worst, then cut. For changing the tone, use a broad Q and small moves."),
                ManualBlock(ManualKind.Bullet, "Try **tilt** first when something sounds too dark or too thin."),
            )),
            ManualSection("Filter", "Low, band or high pass, moved by an LFO, the signal's level or another track.", listOf(
                ManualBlock(ManualKind.Para, "A resonant filter that can move on its own, in time with the song or with the sound going through it."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**cutoff** - 20 Hz to 20 kHz."),
                ManualBlock(ManualKind.Bullet, "**reso** - resonance, up to the edge of self-oscillation."),
                ManualBlock(ManualKind.Bullet, "**mode** - low pass, band pass or high pass."),
                ManualBlock(ManualKind.Bullet, "**lforate** *(extra)* - the LFO speed as a note value, so it stays in time: 1/32 to 8 bars, with the triplets (**T**) and dotted ones (**.**) between."),
                ManualBlock(ManualKind.Bullet, "**lfodepth** *(extra)* - how far the LFO moves the cutoff. Negative sweeps down instead of up."),
                ManualBlock(ManualKind.Bullet, "**envdepth** *(extra)* - how much the signal's level moves the cutoff. Positive opens it when you play harder (auto-wah), and negative closes it."),
                ManualBlock(ManualKind.Bullet, "**sidechain** - whose level moves it: **own** or another track. With a negative **envdepth** and the kick as the source, the filter closes on every kick and opens again after."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "A negative depth leaves the filter open and makes it dip, which sounds quite different from a sweep up."),
                ManualBlock(ManualKind.Bullet, "Combine a slow LFO with a little envelope so it moves with the song and with what's played."),
                ManualBlock(ManualKind.Bullet, "Resonance and band pass lose level, so use **gain** to make it up."),
                ManualBlock(ManualKind.Bullet, "For a dubstep wobble, put it after a thick bass and start from a **wobble** patch. A wobble talks by changing speed: lock **lforate** on the steps (1/4, 1/8, 1/8T, 1/16), or map it to a knob or the mod wheel and play it. Distortion after it makes it gnarly. Trinity's **Wobble** and **Wub** bass patches have the same thing built in, on LFO 1's **sync**."),
            )),
            ManualSection("Flanger", "A short sweeping delay, with negative feedback for the hollow sound.", listOf(
                ManualBlock(ManualKind.Para, "One very short delay, swept and mixed back with the dry sound."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**rate** - the sweep speed, as a note value."),
                ManualBlock(ManualKind.Bullet, "**depth** - how far the sweep travels."),
                ManualBlock(ManualKind.Bullet, "**feedback** - up to 0.95. Low is a gentle whoosh and high is the jet plane."),
                ManualBlock(ManualKind.Bullet, "**negative** *(extra)* - flips the feedback for a hollow sound instead of a ringing one."),
                ManualBlock(ManualKind.Bullet, "**spread** - how far out of step the two channels sweep."),
                ManualBlock(ManualKind.Bullet, "**mix** - wet against dry. Half is the strongest effect."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Keep the mix around half, since fully wet loses most of the effect."),
                ManualBlock(ManualKind.Bullet, "Try **negative** on sustained chords."),
                ManualBlock(ManualKind.Bullet, "A slow rate and small depth on a send adds some movement to a mix."),
            )),
            ManualSection("Formula", "Type a formula and it shapes the track, a sample at a time.", listOf(
                ManualBlock(ManualKind.Para, "Formula uses the same small language as the Formulate machine: whole numbers and the operators of C (`+ - * / % & | ^ << >>`, comparisons, `? :`) and `sin`, `abs`, `min` and `max`. The track comes in as `x`, from 0 to 255 with silence at 128. Whatever the formula gives, taken as 0 to 255, goes out. So `x` on its own is the track cut to eight bits, and everything else bends it from there."),
                ManualBlock(ManualKind.Para, "Tap **edit…** above the knobs to write one, or pick an example to start from. The formula is only applied when you press OK, and if it can't be read the reason shows in red. With no formula the track passes through untouched.", "Click **edit…** above the knobs to write one, or pick an example to start from. The formula is only applied when you press OK, and if it can't be read the reason shows in red. With no formula the track passes through untouched."),
                ManualBlock(ManualKind.Heading, "What a formula can read"),
                ManualBlock(ManualKind.Bullet, "**x** - the track, 0 to 255."),
                ManualBlock(ManualKind.Bullet, "**t** - a counter that goes up at **rate**."),
                ManualBlock(ManualKind.Bullet, "**a**, **b**, **c** - the three knobs, 0 to 255."),
                ManualBlock(ManualKind.Bullet, "**r** - a fresh random number, 0 to 255, every sample."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**a**, **b**, **c** - read by the formula, or ignored if it doesn't use them."),
                ManualBlock(ManualKind.Bullet, "**rate** *(extra)* - how fast `t` counts, 1 to 48 kHz. At 8 kHz most formulas written for this kind of thing sound as they were meant to."),
                ManualBlock(ManualKind.Bullet, "**drive** - pushes the track harder into the formula, up to 24 dB."),
                ManualBlock(ManualKind.Bullet, "**smooth** *(extra)* - rounds off the steps the formula leaves. At the top it's off."),
                ManualBlock(ManualKind.Bullet, "**mix** - the dry track against the formula's."),
                ManualBlock(ManualKind.Bullet, "**gain** - the level out."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "`x & (255 << (a >> 5))` throws bits away as **a** goes up."),
                ManualBlock(ManualKind.Bullet, "`t >> 11 & 1 ? x : 128` chops the track on and off with the counter."),
                ManualBlock(ManualKind.Bullet, "The output is always within full scale, but it can be harsh: start with **mix** low or **smooth** down."),
            )),
            ManualSection("Gate", "A noise gate, with a filter on what it listens to and a sidechain.", listOf(
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**threshold** - the level it opens at, -80 to 0 dB."),
                ManualBlock(ManualKind.Bullet, "**hyst** - how far below the threshold the signal has to drop before it closes, up to 24 dB, so it doesn't flicker on a note near the threshold."),
                ManualBlock(ManualKind.Bullet, "**attack** - how fast it opens, 0.05 to 50 ms."),
                ManualBlock(ManualKind.Bullet, "**hold** - how long it stays open after the signal drops, up to 500 ms."),
                ManualBlock(ManualKind.Bullet, "**release** - how fast it closes once the hold is over."),
                ManualBlock(ManualKind.Bullet, "**duck** *(extra)* - how far down closed is. All the way is a full gate, and around -12 dB suits drums."),
                ManualBlock(ManualKind.Bullet, "**key** *(extra)* - a high-pass filter on what the gate listens to, not on the sound. Raise it so the gate ignores hum and rumble but still opens for the notes."),
                ManualBlock(ManualKind.Bullet, "**sidechain** - what opens it: **own** or another track. The **key** filter still applies."),
                ManualBlock(ManualKind.Para, "There's no mix control, since a half-open gate would just be the noise at half level."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "If it chatters, make **hold** longer before touching release."),
                ManualBlock(ManualKind.Bullet, "For a guitar with mains hum, set **key** to about 120 Hz."),
                ManualBlock(ManualKind.Bullet, "Key a sustained pad's gate to the hi-hat track to chop it into a rhythm, with **duck** at about -12 dB so the gaps aren't silent."),
                ManualBlock(ManualKind.Bullet, "Before an amp it removes the pickup's hiss, and after it the amp's. On an input slot it cleans up the recording itself."),
            )),
            ManualSection("Grain", "A cloud of short slices of what the track just played.", listOf(
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**size** - how long each grain is, 5 to 500 ms."),
                ManualBlock(ManualKind.Bullet, "**density** - how many grains start a second, 1 to 100."),
                ManualBlock(ManualKind.Bullet, "**spray** - how far back into the last four seconds they can reach. At 0 they follow the part closely, at 1 they come from anywhere."),
                ManualBlock(ManualKind.Bullet, "**pitch** - what pitch they play at, two octaves either way."),
                ManualBlock(ManualKind.Bullet, "**scatter** - the chance a grain jumps an octave up or down."),
                ManualBlock(ManualKind.Bullet, "**reverse** - the chance a grain plays backwards."),
                ManualBlock(ManualKind.Bullet, "**freeze** *(extra)* - stops listening, so the cloud keeps playing what it has. A switch to play live."),
                ManualBlock(ManualKind.Bullet, "**feedback** *(extra)* - feeds the cloud back into what it listens to, so it grows on itself."),
                ManualBlock(ManualKind.Bullet, "**width** - how far apart the grains are spread across the stereo field."),
                ManualBlock(ManualKind.Bullet, "**mix** - the dry sound against the cloud."),
                ManualBlock(ManualKind.Bullet, "**gain** - the level out."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Map **freeze** to a button and catch the end of a phrase to hold under the next one."),
                ManualBlock(ManualKind.Bullet, "Long grains with a little **spray** blur a part. Short ones with a lot make a swarm."),
                ManualBlock(ManualKind.Bullet, "**feedback** with **pitch** at +7 makes a cloud that climbs in fifths."),
            )),
            ManualSection("Harmonizer", "Adds two voices at scale steps, so they stay in key.", listOf(
                ManualBlock(ManualKind.Para, "A pitch shifter that knows the key. You set the intervals in scale steps instead of semitones, so a third comes out major or minor depending on the note, like a real harmony part."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**interval** and **interval2** - the two added voices, -7 to +7 scale steps."),
                ManualBlock(ManualKind.Bullet, "**scale** *(extra)* - which scale the steps are counted in, from the same list as the Scale modifier."),
                ManualBlock(ManualKind.Bullet, "**key** *(extra)* - the key."),
                ManualBlock(ManualKind.Bullet, "**window** - 10 to 120 ms. Short follows fast parts but sounds grainier, and long is smoother but blurs attacks."),
                ManualBlock(ManualKind.Bullet, "**feedback** - feeds the output back in, stacking the interval on itself."),
                ManualBlock(ManualKind.Bullet, "**mix** - wet against dry."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Set the key, or it's just a pitch shifter and some thirds will be wrong."),
                ManualBlock(ManualKind.Bullet, "On drums or anything percussive, use a short window (around 20 ms)."),
                ManualBlock(ManualKind.Bullet, "A fifth or an octave below is often more useful than a third above, and shows up tuning less."),
                ManualBlock(ManualKind.Bullet, "Two steps with feedback stacks up a chord."),
            )),
            ManualSection("Horn", "The track plays a wind instrument.", listOf(
                ManualBlock(ManualKind.Para, "Horn listens for the pitch of the track and how loud it is, and plays the same line on a horn, a clarinet, an oboe or a flute: the level becomes the breath. It follows one note at a time, so give it a lead, a bass line or a voice rather than chords. Sing into an input track and you play a trumpet."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**kind** - **brass**, **clarinet** (a single reed), **oboe** (a double reed) or **flute** (an air jet)."),
                ManualBlock(ManualKind.Bullet, "**octave** - plays up to two octaves away from the track."),
                ManualBlock(ManualKind.Bullet, "**tone** - the lips' bite on the brass, or how stiff the reed is."),
                ManualBlock(ManualKind.Bullet, "**bell** - how bright the bell lets the sound out."),
                ManualBlock(ManualKind.Bullet, "**air** - breath noise."),
                ManualBlock(ManualKind.Bullet, "**glide** - how fast it moves to a new note, 1 to 500 ms."),
                ManualBlock(ManualKind.Bullet, "**breath** *(extra)* - how hard a given level blows it. Turn it up for a quiet track."),
                ManualBlock(ManualKind.Bullet, "**snap** *(extra)* - **free** follows the pitch as it is, slides and all; **semi** lands every note on a semitone."),
                ManualBlock(ManualKind.Bullet, "**mix** - the dry track against the instrument."),
                ManualBlock(ManualKind.Bullet, "**gain** - the level out."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "**Low Brass** under a bass line doubles it with a tuba-like horn."),
                ManualBlock(ManualKind.Bullet, "**Sung Brass** on a sung part adds a horn that follows the singer."),
                ManualBlock(ManualKind.Bullet, "If it wobbles between notes, raise **glide** or switch **snap** to **semi**."),
            )),
            ManualSection("Magneto", "The sound of a small recordable disc, in each of its formats.", listOf(
                ManualBlock(ManualKind.Para, "Those discs held more than they had room for by throwing away what the ear was least likely to miss. Each format threw away more than the last, and what it threw away is the sound. Magneto works the same way: the track is cut into short frames, each split into bands, and each frame has only so many bits to spend."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**mode** - the format: - **SP** - the original. The top stays nearly all the way up, with a fine grain through the mids and highs. - **LP2** - half the bits. The top is cut a little below 16 kHz, it turns grainy and hits smear a little. - **LP4** - half again, with left and right sharing their bits. The highs flicker in and out above the cut at 14 kHz, quiet high detail disappears, and the upper mids narrow almost to mono. - **HQ** - the later high-rate format. The cleanest, nearly clear. - **XLP** - the later format at its lowest rate, between LP2 and LP4."),
                ManualBlock(ManualKind.Bullet, "**dubs** *(extra)* - copies it again, one to four generations, each losing a little more, as when one disc was recorded from another."),
                ManualBlock(ManualKind.Bullet, "**mix** - the dry sound against the copy."),
                ManualBlock(ManualKind.Bullet, "**gain** - the level out."),
                ManualBlock(ManualKind.Para, "The copy runs a little behind the track: about 20 ms for each generation. The dry sound in **mix** is held back to match, so the two stay in step."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "**LP4** on a whole mix is the instant late-nineties portable."),
                ManualBlock(ManualKind.Bullet, "**Fourth Generation** on pads and keys turns them watery and swirling."),
                ManualBlock(ManualKind.Bullet, "Turn **mix** down for the grit without losing the top."),
            )),
            ManualSection("Mouth", "Diction's throat on any track: it shapes whatever goes through into a vowel.", listOf(
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**vowel** - oo, oh, ah, eh, ee from bottom to top."),
                ManualBlock(ManualKind.Bullet, "**size** - the throat's size, big and dark to small and bright."),
                ManualBlock(ManualKind.Bullet, "**nasal** - opens the nose."),
                ManualBlock(ManualKind.Bullet, "**move** *(extra)* - what moves the vowel: **lfo** on the tempo, the track's own **level** (louder opens the mouth), or another track through the **sidechain** (**key**)."),
                ManualBlock(ManualKind.Bullet, "**rate** - the LFO's note value."),
                ManualBlock(ManualKind.Bullet, "**depth** - how far the vowel moves from where it's set."),
                ManualBlock(ManualKind.Bullet, "**mix** - the dry sound against the vowel."),
                ManualBlock(ManualKind.Bullet, "**gain** - the level out."),
                ManualBlock(ManualKind.Bullet, "**sidechain** - the track that moves it when **move** is **key**."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "On a synth lead with **move** at **level**, harder notes say \"ah\"."),
                ManualBlock(ManualKind.Bullet, "Point the sidechain at a drum loop and a pad talks in its rhythm."),
                ManualBlock(ManualKind.Bullet, "Slow **lfo** sweeps from oo to ah sound like a wah played by a voice."),
            )),
            ManualSection("Phaser", "Two to eight stages.", listOf(
                ManualBlock(ManualKind.Para, "Sweeping notches from a chain of allpass filters. The notches aren't evenly spaced like a flanger's, which gives a phaser its own sound."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**rate** - the sweep speed, as a note value."),
                ManualBlock(ManualKind.Bullet, "**depth** - how far the notches travel."),
                ManualBlock(ManualKind.Bullet, "**feedback** - up to 0.9. Makes the notches ring."),
                ManualBlock(ManualKind.Bullet, "**stages** - two, four, six or eight. More stages means more notches and a stronger effect."),
                ManualBlock(ManualKind.Bullet, "**spread** *(extra)* - sweeps the two channels out of step so it's wide. Great on pads."),
                ManualBlock(ManualKind.Bullet, "**mix** - wet against dry."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Change **stages** first to set the character. Four is the classic pedal."),
                ManualBlock(ManualKind.Bullet, "More feedback makes the sweep more obvious."),
                ManualBlock(ManualKind.Bullet, "A slow phaser on a send adds movement without being noticeable."),
            )),
            ManualSection("Resonator", "Strings tuned to a key, ringing in sympathy with the track.", listOf(
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**key** and **scale** - the strings' key. Set them to the song's."),
                ManualBlock(ManualKind.Bullet, "**low** - the lowest string, as a note. The strings climb the scale from the first note of the key at or above it."),
                ManualBlock(ManualKind.Bullet, "**strings** - how many, 4 to 16."),
                ManualBlock(ManualKind.Bullet, "**decay** - how long they ring, 0.2 to 12 s."),
                ManualBlock(ManualKind.Bullet, "**tone** - how bright they are."),
                ManualBlock(ManualKind.Bullet, "**metal** *(extra)* - stiffness in the strings, which pulls their overtones sharp, from a string toward a bell."),
                ManualBlock(ManualKind.Bullet, "**width** - how far apart low and high strings sit in the stereo."),
                ManualBlock(ManualKind.Bullet, "**mix** - the dry sound against the strings."),
                ManualBlock(ManualKind.Bullet, "**gain** - the level out."),
                ManualBlock(ManualKind.Para, "A note in the key sets its strings ringing. A note out of it mostly doesn't, so a part in the key blooms like the open strings of a sitar or a piano with its dampers up."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "On drums, it gives every hit a pitch in the key."),
                ManualBlock(ManualKind.Bullet, "A long **decay** with a low **low** turns a part into a drone under it."),
                ManualBlock(ManualKind.Bullet, "Put it on a send, so several tracks set the same strings ringing."),
            )),
            ManualSection("Reverb", "A room that can also freeze, gate, shimmer or crush itself.", listOf(
                ManualBlock(ManualKind.Para, "A reverb with the usual size, damping and predelay, plus some extras."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**size** - how big the space is."),
                ManualBlock(ManualKind.Bullet, "**damp** - how absorbent the room is. Damped sounds like carpet and undamped like tiles."),
                ManualBlock(ManualKind.Bullet, "**tone** - a low-pass on the reverb tail."),
                ManualBlock(ManualKind.Bullet, "**predelay** - a gap before the reverb starts, up to 200 ms."),
                ManualBlock(ManualKind.Bullet, "**mix** - wet against dry."),
                ManualBlock(ManualKind.Bullet, "**freeze** *(extra)* - holds the tail forever."),
                ManualBlock(ManualKind.Bullet, "**gate** *(extra)* - cuts the tail off sharply, for the classic 80s gated snare."),
                ManualBlock(ManualKind.Bullet, "**shimmer** *(extra)* - feeds the tail back an octave up, so a held chord keeps rising."),
                ManualBlock(ManualKind.Bullet, "**bits** and **crush** *(extra)* - bit reduction and sample-rate reduction on the tail only."),
                ManualBlock(ManualKind.Bullet, "**wobble** *(extra)* - makes the tail drift a little so it's never quite still."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "If the reverb makes things muddy, try 30-60 ms of **predelay** before making it smaller."),
                ManualBlock(ManualKind.Bullet, "Shimmer works best with a low mix and a long tail."),
                ManualBlock(ManualKind.Bullet, "Put **bits** and **crush** on a send for a lo-fi copy of the mix behind the clean one."),
            )),
            ManualSection("Rotary", "The organ's rotating speaker cabinet, for any track.", listOf(
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**speed** - brake, slow or fast."),
                ManualBlock(ManualKind.Bullet, "**slow** - how fast the horn turns at slow, 0.1 to 2 Hz."),
                ManualBlock(ManualKind.Bullet, "**fast** - how fast it turns at fast, 2 to 10 Hz. The drum turns a little slower than the horn at both."),
                ManualBlock(ManualKind.Bullet, "**ramp** - how long the rotors take to reach a new speed. Slowing down takes nearly twice as long, as it does with the real motors."),
                ManualBlock(ManualKind.Bullet, "**distance** - how far the microphones are from the cabinet. Close is a deep swing, far a gentle one."),
                ManualBlock(ManualKind.Bullet, "**angle** - how far apart the two microphones point."),
                ManualBlock(ManualKind.Bullet, "**width** - how much of the stereo the microphones give."),
                ManualBlock(ManualKind.Bullet, "**tempo** *(extra)* - turns the horn once a note value (1/1 to 1/8 triplet) instead of at its own speed, so the swirl sits on the beat."),
                ManualBlock(ManualKind.Bullet, "**mix** - the dry sound against the cabinet."),
                ManualBlock(ManualKind.Bullet, "**gain** - the level out."),
                ManualBlock(ManualKind.Para, "The cabinet has one input, so a stereo track is summed before it, as an organ's would be."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Automate **speed** between slow and fast and let **ramp** do the rest. The speed-up and slow-down are the sound."),
                ManualBlock(ManualKind.Bullet, "On a guitar or electric piano, **mix** at about 0.6 keeps the attack clear."),
                ManualBlock(ManualKind.Bullet, "With **tempo** on, a pad pulses in time with no LFO to set up."),
            )),
            ManualSection("Shifter", "Frequency shifting, for metallic and detuned sounds.", listOf(
                ManualBlock(ManualKind.Para, "A frequency shifter moves every harmonic of a sound up or down by the same number of hertz, so the sound stops being in tune with itself. A pitch shifter keeps them in proportion instead."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**shift** - -500 to +500 Hz. Small amounts are the most useful."),
                ManualBlock(ManualKind.Bullet, "**fine** - ±20 Hz, for tiny shifts that just beat slowly."),
                ManualBlock(ManualKind.Bullet, "**spread** *(extra)* - shifts the two channels in opposite directions. A couple of hertz makes a mono sound wide and slowly swirling."),
                ManualBlock(ManualKind.Bullet, "**feedback** - feeds the output back in so it shifts again each pass, for metallic cascades."),
                ManualBlock(ManualKind.Bullet, "**mix** - wet against dry."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Under 1 Hz it's a very slow, wide modulation. Lovely on pads."),
                ManualBlock(ManualKind.Bullet, "A few hertz or more makes held notes sound out of tune with themselves, which is great on drums, bells and noise and usually wrong on chords."),
                ManualBlock(ManualKind.Bullet, "Feedback with a small shift turns a hit into a rising metallic ladder."),
            )),
            ManualSection("Slicer", "The track cut on the tempo, some slices repeated, reversed or dropped.", listOf(
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**rate** - the slice: a quarter, eighth, sixteenth or thirty-second note."),
                ManualBlock(ManualKind.Bullet, "**chance** - how likely a slice is to change."),
                ManualBlock(ManualKind.Bullet, "**repeat**, **reverse**, **drop** - the proportions of what a changed slice does: repeat the one before it, play it backwards, or go silent."),
                ManualBlock(ManualKind.Bullet, "**gate** - shortens every slice."),
                ManualBlock(ManualKind.Bullet, "**pitch** *(extra)* - shifts the repeats, an octave either way."),
                ManualBlock(ManualKind.Bullet, "**seed** *(extra)* - which slices change. The same slices change every time the song plays, so a part can be written around them."),
                ManualBlock(ManualKind.Bullet, "**mix** - the dry sound against the sliced one."),
                ManualBlock(ManualKind.Bullet, "**gain** - the level out."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "On a drum loop, **Stutter** adds fills you didn't program."),
                ManualBlock(ManualKind.Bullet, "Try seeds until a bar sounds right; it'll stay that way."),
                ManualBlock(ManualKind.Bullet, "With **chance** at 0, **gate** alone chops a pad in time."),
            )),
            ManualSection("Smash", "Three bands, each squashed from above and lifted from below.", listOf(
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**depth** - how much of it is mixed in with the track as it was. A little is density and presence; all of it is every tail and breath brought up to the level of the hits."),
                ManualBlock(ManualKind.Bullet, "**time** - scales every band's attack and release together. Slow is smooth, fast pumps and grinds."),
                ManualBlock(ManualKind.Bullet, "**threshold** - the level each band is pushed toward, -48 to 0 dB."),
                ManualBlock(ManualKind.Bullet, "**down** - how hard anything over the threshold is pushed down."),
                ManualBlock(ManualKind.Bullet, "**up** *(extra)* - how hard anything under it is pulled up. Hiss and hum far below are left down."),
                ManualBlock(ManualKind.Bullet, "**low**, **mid**, **high** - each band's level after it, ±12 dB. The bands split at 300 Hz and 5 kHz."),
                ManualBlock(ManualKind.Bullet, "**in** - drives it harder, up to +24 dB."),
                ManualBlock(ManualKind.Bullet, "**gain** - the level out."),
                ManualBlock(ManualKind.Para, "At depth 0, or with **up** and **down** both at 0, the track comes through untouched."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "On a bass that disappears on a phone speaker, **Loud** brings it up front."),
                ManualBlock(ManualKind.Bullet, "On a reverb or delay send, **Air** brings the tails up without touching the hits."),
                ManualBlock(ManualKind.Bullet, "Fast **time** with **in** turned up grinds a bass into a snarl."),
            )),
            ManualSection("Spectral", "The track taken apart into its frequencies and put back together.", listOf(
                ManualBlock(ManualKind.Para, "About forty times a second, Spectral splits the sound into its frequencies, changes them, and puts it back. With nothing turned, what comes out is what went in."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**freeze** *(extra)* - **hold** keeps the sound as it is at that moment, a chord or a vowel that goes on for as long as it's held. **run** lets go."),
                ManualBlock(ManualKind.Bullet, "**blur** - lets each frequency fade instead of stopping, so notes run into each other. At the top, a note trails for seconds."),
                ManualBlock(ManualKind.Bullet, "**smear** - scrambles the timing within each slice, for a washed, distant, whispered sound."),
                ManualBlock(ManualKind.Bullet, "**robot** - throws the timing away, for a flat, buzzing voice."),
                ManualBlock(ManualKind.Bullet, "**peaks** *(extra)* - keeps only the strongest frequencies, a glassy, whistling sound. Further up, fewer are left."),
                ManualBlock(ManualKind.Bullet, "**tilt** - leans everything darker or brighter, turning about 1 kHz."),
                ManualBlock(ManualKind.Bullet, "**mix** - the dry track against the changed one."),
                ManualBlock(ManualKind.Bullet, "**gain** - the level out."),
                ManualBlock(ManualKind.Para, "The changed sound runs about 40 ms behind the track. The dry sound in **mix** is held back to match, so the two stay in step."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Map **freeze** to a button and hold a chord under the next part."),
                ManualBlock(ManualKind.Bullet, "**Robot Voice** on a sung or spoken track is the classic flat robot."),
                ManualBlock(ManualKind.Bullet, "**Ice** on a pad or a piano leaves a glassy shimmer of its loudest notes."),
            )),
            ManualSection("Swell", "Upward compression: the quiet parts come up to meet the loud ones, in one band or three.", listOf(
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**floor** - everything louder than this is brought up, -80 to 0 dB. Anything more than 12 dB under it is left exactly as it is, so the hiss and hum at the bottom of a recording stay where they were."),
                ManualBlock(ManualKind.Bullet, "**ceiling** - the level everything above the floor is pulled toward, -30 to 0 dB. A sound already over the ceiling is brought down to it."),
                ManualBlock(ManualKind.Bullet, "**amount** - how far. At 0 nothing moves, at 1 every sound above the floor ends up at the ceiling, and halfway brings it halfway."),
                ManualBlock(ManualKind.Bullet, "**split** *(extra)* - from one band (0) to three (1), split at 300 Hz and 5 kHz. Split, a quiet top end or a thin low end comes up on its own, which is where the air and the breath come from. The bands add back to exactly the input, so splitting never changes a sound that isn't being lifted."),
                ManualBlock(ManualKind.Bullet, "**release** - how fast it lets go after a loud moment, 5 ms to 2 s. Slow is close to normalising and keeps the shape of a phrase. Fast follows every hit, and very fast follows the waveform itself and turns into distortion."),
                ManualBlock(ManualKind.Bullet, "**mix** - the dry sound against the lifted one."),
                ManualBlock(ManualKind.Bullet, "**gain** - the level out, to make up for how much louder it gets."),
                ManualBlock(ManualKind.Para, "It looks a few samples ahead so a sudden loud sound is already turned down when it arrives. That's 8 samples, under 0.2 ms."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Start at the **Loud** preset on a mix bus and bring **amount** up until the quiet parts are where you want them."),
                ManualBlock(ManualKind.Bullet, "For drums, **Room** brings up everything between the hits. Lower **floor** to bring up more of the room."),
                ManualBlock(ManualKind.Bullet, "For a wall of sound, push **amount** to 1 and **release** under 50 ms, then bring **mix** down until the dynamics come back."),
                ManualBlock(ManualKind.Bullet, "On a reverb or delay send it brings the tails up, so a short reverb sounds like a long one."),
                ManualBlock(ManualKind.Bullet, "Set **ceiling** a few dB under the master limiter's so the two don't fight."),
            )),
            ManualSection("Tape", "A worn tape machine, and a stop button.", listOf(
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**wow** - slow wandering in the speed, and so the pitch."),
                ManualBlock(ManualKind.Bullet, "**flutter** - fast wobble in the speed."),
                ManualBlock(ManualKind.Bullet, "**drive** - saturation, as tape driven hard."),
                ManualBlock(ManualKind.Bullet, "**tone** - where the highs roll off, 2 to 20 kHz."),
                ManualBlock(ManualKind.Bullet, "**hiss** - the noise underneath."),
                ManualBlock(ManualKind.Bullet, "**age** - how worn: the wow wanders less evenly and the low end bumps up."),
                ManualBlock(ManualKind.Bullet, "**stop** *(extra)* - slows the tape to a halt, the pitch falling with it. Switched off, it's back at speed at once."),
                ManualBlock(ManualKind.Bullet, "**stoptime** *(extra)* - how long the stop takes, 0.1 to 4 s."),
                ManualBlock(ManualKind.Bullet, "**mix** - the dry sound against the tape."),
                ManualBlock(ManualKind.Bullet, "**gain** - the level out."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Map **stop** to a button and use it at the end of a phrase."),
                ManualBlock(ManualKind.Bullet, "**Cassette** on a whole mix makes it sound like a tape found in a drawer."),
                ManualBlock(ManualKind.Bullet, "**Seasick** on keys and pads makes them drift out of tune."),
            )),
            ManualSection("Tremolo", "Volume on an LFO, or auto-pan.", listOf(
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**rate** - the pulse speed, as a note value."),
                ManualBlock(ManualKind.Bullet, "**depth** - how deep each dip goes. At full, the sound cuts out between pulses."),
                ManualBlock(ManualKind.Bullet, "**shape** - sine, triangle or square. Square gives a chopped sound."),
                ManualBlock(ManualKind.Bullet, "**pan** *(extra)* - moves the two channels out of step. At zero it's a tremolo, at full it's an auto-pan, and in between it wobbles around."),
                ManualBlock(ManualKind.Bullet, "**skew** *(extra)* - changes the shape of each pulse, either a stab (fast down, slow up) or a swell (slow down, fast up)."),
                ManualBlock(ManualKind.Bullet, "**mix** - wet against dry, which on a tremolo is really the depth."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Square shape with **skew** hard over at a sixteenth rate turns a held chord into a rhythm."),
                ManualBlock(ManualKind.Bullet, "Try **pan** around a third of the way for movement that never sits on one side."),
            )),
            ManualSection("Width", "Wider, narrower, mono below a frequency or rotated.", listOf(
                ManualBlock(ManualKind.Para, "Controls the stereo image."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**width** - 0 is mono, 1 is unchanged and 2 is twice as wide. Anything in the centre stays in the centre."),
                ManualBlock(ManualKind.Bullet, "**below** *(extra)* - makes everything under this frequency mono, from 20 to 500 Hz."),
                ManualBlock(ManualKind.Bullet, "**haas** *(extra)* - delays one side by up to 20 ms. A few milliseconds makes a sound wider without changing its tone."),
                ManualBlock(ManualKind.Bullet, "**rotate** - turns the whole image left or right without changing its width."),
                ManualBlock(ManualKind.Heading, "Tips"),
                ManualBlock(ManualKind.Bullet, "Set **below** to around 120 Hz on most things. Bass doesn't need stereo, and stereo bass can vanish on mono speakers."),
                ManualBlock(ManualKind.Bullet, "**haas** holds up better than **width** when the mix is played in mono."),
            )),
        )),
        ManualSection("Modifiers", "", listOf(
            ManualBlock(ManualKind.Para, "Every track has three modifiers, in the row just above the keyboard. Tap one to turn it on or off, and hold it to open its settings.", "Every track has three modifiers, in the row just above the keyboard. Click one to turn it on or off, and hold it to open its settings."),
            ManualBlock(ManualKind.Para, "A modifier changes what you play before it's written down. Play one key with the chord modifier on and you hear three notes, and if you're recording the clip gets three notes. Notes from a MIDI keyboard or controller go through the modifiers too."),
            ManualBlock(ManualKind.Heading, "Scale"),
            ManualBlock(ManualKind.Para, "Thirty-three scales, in any key. With a scale on, the keyboard only shows notes in the scale, so you get more range on a small screen and can't hit a wrong note. MIDI notes outside the scale move to the nearest one that fits."),
            ManualBlock(ManualKind.Para, "The **scl** corner of the piano roll chooses how the scale is shown: all notes, scale notes highlighted or only scale notes. On a track without its own scale, the roll uses the song's key (set behind the tempo button)."),
            ManualBlock(ManualKind.Heading, "Chord"),
            ManualBlock(ManualKind.Para, "Turns every note into a chord, either a fixed shape or the chord the scale builds on that note so it stays in key. **strum** spreads the notes out in time, and recordings keep the strum."),
            ManualBlock(ManualKind.Heading, "Arpeggio"),
            ManualBlock(ManualKind.Para, "Plays the notes you're holding one at a time. You choose the order, speed, octave range, note length and a chance for each step to be skipped."),
            ManualBlock(ManualKind.Para, "Recording with the arp on writes out every note it plays, so a held chord becomes a line you can edit afterwards."),
        )),
        ManualSection("MIDI and playing with others", "", listOf(
            ManualBlock(ManualKind.Para, "You can use MIDI with a variety of keyboards and controllers, including MPE. Special support has been added for the Intuitive Instruments Exquis and Novation Launchpad Pro MK3 (as I have these myself)."),
            ManualBlock(ManualKind.Heading, "Playing from a keyboard"),
            ManualBlock(ManualKind.Para, "USB and Bluetooth MIDI keyboards work straight away. Notes go to whichever track is open, or to a track you pin so it stays the same whatever you're looking at."),
            ManualBlock(ManualKind.Para, "If a controller plays everything too loud or too soft, turn **velocity** on the **notes** tab. **softer** brings the middle of the range down and **harder** brings it up, and the softest and hardest notes stay where they are. The readout next to it shows each note's velocity as the app gets it."),
            ManualBlock(ManualKind.Subheading, "MPE"),
            ManualBlock(ManualKind.Para, "With an MPE controller every finger has its own bend, pressure and slide, so bending one note leaves the others alone. Leave **zone** on **auto** and the app follows the controller, using the zone and bend range it announces or picking it up as soon as two fingers are down on separate channels. The card says what it found. Choose **lower** or **upper** to set the zone and bend range by hand."),
            ManualBlock(ManualKind.Para, "What each gesture does:"),
            ManualBlock(ManualKind.Bullet, "**Bend** moves the note's pitch on every melodic machine except Reflux, the organ and Diction, which bend as a whole. On a Draw harmonica played like a player, bending down bends with the tongue, as far as the hole goes."),
            ManualBlock(ManualKind.Bullet, "**Pressure** opens the sound up and makes it louder. On Brazen, Timber, Draw and Tongue it's breath, and on Filament it leans on the bow too. Hammer takes none: a piano has nothing to press once it's struck. **press** on a machine's panel sets how much."),
            ManualBlock(ManualKind.Bullet, "**Slide** (CC 74) brightens the note. It opens the filter on Trinity, Ratio and Mosaic, moves the pick up the string on Filament, tightens the lips or reed on Brazen and Timber, brings Draw's reeds closer to their slots, fits Tongue's reed tighter in its frame, and moves Cumulus's morph. **slide** on the panel sets how much. In Nexus, the **touch** module gives each voice its finger's pressure and slide to patch."),
            ManualBlock(ManualKind.Para, "A keyboard that sends poly aftertouch presses each note on its own too, with no zone needed. Other controllers on a finger's channel, like the mod wheel or the sustain pedal, act on the whole track as usual."),
            ManualBlock(ManualKind.Para, "Per-note bend, pressure and slide are recorded with the notes."),
            ManualBlock(ManualKind.Subheading, "Exquis"),
            ManualBlock(ManualKind.Para, "Plug in an Exquis over USB and its pads show the scale of the track it plays, the track's own Scale modifier if it has one or the song's key if not, the same as the piano roll. It changes when you open another track or change the scale. With **pinned** it's the pinned track, and with **by channel** it's the track for the channel the Exquis plays on. MPE fingers aren't routed by channel, so with MPE it's the open track or the pinned one."),
            ManualBlock(ManualKind.Para, "**exquis pads** in the MIDI window's devices tab chooses how:"),
            ManualBlock(ManualKind.Bullet, "**own colours** sets the Exquis's own tonic and scale, so the pads show it in the colours you gave them. A scale the Exquis doesn't have shows as the nearest one that has all its notes, or chromatic."),
            ManualBlock(ManualKind.Bullet, "**highlight** lights the notes in the Exquis's highlight green instead, one pad per note, over whatever scale the Exquis is set to."),
            ManualBlock(ManualKind.Bullet, "**off** leaves the pads alone."),
            ManualBlock(ManualKind.Para, "Its buttons work the app too: **play/stop** starts and stops the song, **record** arms recording, **loop** loops the scene, **clips** switches to clip mode, and **undo** and **redo** do what they say. Their lights follow the app, so play is green while playing, record is red while armed, and loop and clips are lit while they're on. The pads, knobs, slider and octave buttons stay the Exquis's own. **exquis buttons** in the devices tab gives the buttons back to the Exquis, and closing the app does too."),
            ManualBlock(ManualKind.Subheading, "Launchpad Pro"),
            ManualBlock(ManualKind.Para, "Plug in a Launchpad Pro [MK3] over USB and Acidulous takes over every pad and button, lit in your tracks' colours. **launchpad** in the MIDI window's devices tab gives it back, and so does closing the app. The buttons along the top choose what the grid is:"),
            ManualBlock(ManualKind.Bullet, "**Note** - a piano keyboard like the one on screen, with white keys on one row and black keys on the row above, four octaves up the grid. The notes in the scale (the track's own, or the song's key) are lit in the track's colour with the root brightest, and the rest are faint but still play. When the track has its own **Scale** modifier on, only the scale's notes are there, an octave a row from the root, which fits eight octaves. On a drum machine it's the machine's pads, laid out like on screen. Up and down change the octave."),
            ManualBlock(ManualKind.Bullet, "**Session** - the song grid, laid out like on screen with tracks down and scenes across. A clip pulses while it plays and flashes while it waits. Tap a clip to launch it in clip mode, or to play from that scene in song mode."),
            ManualBlock(ManualKind.Bullet, "**Sequencer** - the open track's clip in the current scene, eight steps at a time. Tap a pad to add or remove a note. Left and right move a step at a time, and up and down move through the notes. A drum machine's rows run down from the kick, like its grid on screen."),
            ManualBlock(ManualKind.Bullet, "**Custom** - the mixer, laid out like the song grid, with a row for each track and its fader running left to right. **Volume**, **Pan** and **Sends** on the bottom row choose what the faders are, and **Device** makes the rows the played machine's first eight knobs."),
            ManualBlock(ManualKind.Bullet, "**Chord** - chords in the key, a column for each note of the scale and a row for each kind of chord."),
            ManualBlock(ManualKind.Bullet, "**Projects** - the perform effects: repeat and gate along the top, reverse, tape stop, the riser, the three kills and an XY pad. Hold to play."),
            ManualBlock(ManualKind.Para, "The buttons round the edge work on every page:"),
            ManualBlock(ManualKind.Bullet, "**Play** and **Record** do what they say. **Shift** and **Play** stops everything."),
            ManualBlock(ManualKind.Bullet, "**Shift** and **Clear** undoes, and **Shift** and **Duplicate** redoes."),
            ManualBlock(ManualKind.Bullet, "Hold **Clear** and tap a clip to clear it. Hold **Duplicate** and tap a clip to copy it into the next scene if that's empty, or tap a scene button to duplicate the scene."),
            ManualBlock(ManualKind.Bullet, "The buttons down the right are the tracks, top to bottom like the grid's rows. Tap one to choose the track the Launchpad plays. Hold **Mute** or **Solo** and tap one to mute or solo it."),
            ManualBlock(ManualKind.Bullet, "The row under the grid is the scenes, left to right. Tap one to play it, like tapping a scene's header."),
            ManualBlock(ManualKind.Bullet, "On **Session** and **Custom**, up and down move through the tracks and left and right through the scenes, one at a time. On the other pages, hold **Shift** to do the same. An arrow is lit when there's more that way."),
            ManualBlock(ManualKind.Bullet, "**Quantise** quantises the open clip the way the quantise window was last set."),
            ManualBlock(ManualKind.Bullet, "**Stop Clip** stops the clips, or the song."),
            ManualBlock(ManualKind.Para, "Its pads send velocity and pressure, and both are recorded like any keyboard."),
            ManualBlock(ManualKind.Subheading, "Pedals"),
            ManualBlock(ManualKind.Para, "A pedal plugged into your keyboard works on every melodic machine:"),
            ManualBlock(ManualKind.Bullet, "**Sustain** (the right pedal) keeps notes sounding after you let go of the keys, until you lift it. On Filament it also lifts the dampers, so the strings you aren't playing ring along."),
            ManualBlock(ManualKind.Bullet, "**Sostenuto** (the middle one) holds only the keys that were down when you pressed it, and notes you play after that stop as usual."),
            ManualBlock(ManualKind.Bullet, "**Soft** (the left one) plays notes in more quietly while it's down."),
            ManualBlock(ManualKind.Para, "Hammer takes a pedal part of the way down, as a piano does: half a sustain pedal lets the dampers only touch the strings. Every other machine hears a pedal as up or down, with the halfway point counting as down. MIDI out sends the pedal as far down as it is."),
            ManualBlock(ManualKind.Para, "Pedals are recorded as lanes in the automation strip, one each, and you can draw them there by hand too. On Hammer a lane keeps how far down the pedal was, and where it moved; on everything else it's up or down. Drum machines ignore them."),
            ManualBlock(ManualKind.Heading, "Mapping a controller"),
            ManualBlock(ManualKind.Para, "Long-press redo to enter mapping mode. Controls that can be mapped are highlighted. Tap one, then move a knob or press a key on your controller to link them. Knobs, faders, mixer controls and transport buttons can all be mapped to a CC or a note.", "Hold the mouse button down on redo, or right-click it, to enter mapping mode. Controls that can be mapped are highlighted. Click one, then move a knob or press a key on your controller to link them. Knobs, faders, mixer controls and transport buttons can all be mapped to a CC or a note."),
            ManualBlock(ManualKind.Para, "A mapped knob records into automation like moving it by hand. Mapped buttons like play, stop and fill don't record."),
            ManualBlock(ManualKind.Heading, "Clock"),
            ManualBlock(ManualKind.Para, "The app can send MIDI clock (with start, stop and song position) to hardware, and follow an incoming clock, taking its tempo from the other device."),
            ManualBlock(ManualKind.Para, "**follow** on the MIDI window's **control** tab has three settings:"),
            ManualBlock(ManualKind.Bullet, "**on** always follows, even with nothing coming in."),
            ManualBlock(ManualKind.Bullet, "**auto** follows a clock when one arrives and goes back to the song's own tempo a second after it stops."),
            ManualBlock(ManualKind.Bullet, "**off** ignores incoming clock."),
            ManualBlock(ManualKind.Para, "**send**, next to it, turns clock out on and off. Whether a track's notes go out is set per track, in its settings or on its mixer strip."),
            ManualBlock(ManualKind.Heading, "Link"),
            ManualBlock(ManualKind.Para, "Ableton Link shares tempo and bar position with other Link apps on the same network, both ways. Turn it on and the number of connected apps shows up. It keeps everyone's downbeat together without anyone being in charge."),
        )),
        ManualSection("Recording and samples", "", listOf(
            ManualBlock(ManualKind.Heading, "The recording window"),
            ManualBlock(ManualKind.Para, "One window handles recording, and it opens wherever a machine needs audio: a pad on Forage, a loop for Dice, a buffer for Pollen or a take for Molt."),
            ManualBlock(ManualKind.Bullet, "**Record** - choose the input, watch the level and record. - **source** is **in** for the microphone or what's plugged in, or **resample** to record what the app is playing. - **mic** is **raw** for an instrument, or **clean** for a voice, with noise suppression and level control. - The **tuner** in the input card shows the nearest note and how many cents off you are, and turns green within four cents. It listens before the input effects, and shows nothing unless it's sure of the note. - **printed into the take** holds two effects that are recorded into the file, like a guitar amp. Effects on a track can be changed any time instead.", "**Record** - choose the input, watch the level and record. - **source** is **in** for the microphone or what's plugged in, or **resample** to record what the app is playing. - In a browser, **mic** is **raw** for an instrument, or **clean** for a voice, with noise suppression and level control. - The **tuner** in the input card shows the nearest note and how many cents off you are, and turns green within four cents. It listens before the input effects, and shows nothing unless it's sure of the note. - **printed into the take** holds two effects that are recorded into the file, like a guitar amp. Effects on a track can be changed any time instead."),
            ManualBlock(ManualKind.Bullet, "**Edit** - play the take back, trim the ends, set the level and cut low rumble. **norm** and **rev** at the top normalise and reverse the whole file. Changes show and play straight away. **apply** writes them to the file, and **revert** takes them all back."),
            ManualBlock(ManualKind.Bullet, "**Library** - everything you've recorded or imported."),
            ManualBlock(ManualKind.Bullet, "**Voice** - records your voice for Diction, a short prompt at a time. - **new voice** starts one, and **delete** deletes the one chosen, with its takes. **share** sends it as a zip, its takes and all, and **import…** takes in a voice someone shared. **note** is the note every prompt is sung on; pick one that's easy for you, since it can't change after the first take. - Tap **sing** and listen to the note. It counts 3, 2, 1, then the prompt turns red: sing it on the note, in whatever octave suits your voice. The bar under it shows where each part goes. **ah-sah** is ah, then sah, in one breath, with the s where the bar marks it: it's the consonant going in and out of a vowel that's being recorded. A vowel that moves, like **eye**, holds its first vowel and moves to the second at the mark near the end: aaah-ee. It moves on to the next prompt by itself. - Each take is checked as soon as it's sung. One that has to be sung again stays on screen in pink and says why, such as **too loud** or **no consonant heard**. The counts only count takes that are fine. - **mic** shows the level. Sing loud enough to keep it well up the bar. A take always records the mic raw, without the effects printed into a take. - **◀** and **▶** go back and forward, **play** plays a take back, and **again** records it over. - **cut…** shows the take with the part it was cut to marked: the held vowel, a vowel's move, or the consonant. Drag a mark to move it, and **part** plays what the marks hold. **keep** saves it, and a take that said to sing it again is used as you marked it. **as cut** puts back where it was cut first. - **to sing** counts what a voice needs: every vowel, and every consonant between ahs. After it come the consonants **between ees** and **between oos**, which you can leave out. Diction's **from…** window chooses between them for each consonant. A voice is saved as you go, so you can stop and finish it another day.", "**Voice** - records your voice for Diction, a short prompt at a time. - **new voice** starts one, and **delete** deletes the one chosen, with its takes. **share** sends it as a zip, its takes and all, and **import…** takes in a voice someone shared. **note** is the note every prompt is sung on; pick one that's easy for you, since it can't change after the first take. - Click **sing** and listen to the note. It counts 3, 2, 1, then the prompt turns red: sing it on the note, in whatever octave suits your voice. The bar under it shows where each part goes. **ah-sah** is ah, then sah, in one breath, with the s where the bar marks it: it's the consonant going in and out of a vowel that's being recorded. A vowel that moves, like **eye**, holds its first vowel and moves to the second at the mark near the end: aaah-ee. It moves on to the next prompt by itself. - Each take is checked as soon as it's sung. One that has to be sung again stays on screen in pink and says why, such as **too loud** or **no consonant heard**. The counts only count takes that are fine. - **mic** shows the level. Sing loud enough to keep it well up the bar. A take always records the mic raw, without the effects printed into a take. - **◀** and **▶** go back and forward, **play** plays a take back, and **again** records it over. - **cut…** shows the take with the part it was cut to marked: the held vowel, a vowel's move, or the consonant. Drag a mark to move it, and **part** plays what the marks hold. **keep** saves it, and a take that said to sing it again is used as you marked it. **as cut** puts back where it was cut first. - **to sing** counts what a voice needs: every vowel, and every consonant between ahs. After it come the consonants **between ees** and **between oos**, which you can leave out. Diction's **from…** window chooses between them for each consonant. A voice is saved as you go, so you can stop and finish it another day."),
            ManualBlock(ManualKind.Para, "The result is a file, so the same recording can be used by more than one machine."),
            ManualBlock(ManualKind.Heading, "Importing"),
            ManualBlock(ManualKind.Para, "You can import WAV, AIFF, FLAC and MP3. Everything is converted to WAV once on the way in, so songs load quickly."),
            ManualBlock(ManualKind.Heading, "Recording onto a track"),
            ManualBlock(ManualKind.Para, "**Bias** is the audio track. Open a Bias cell, tap the red dot next to a lane, arm record on the transport and press play. The song plays while you record, and the other lanes keep playing.", "**Bias** is the audio track. Open a Bias cell, click the red dot next to a lane, arm record on the transport and press play. The song plays while you record, and the other lanes keep playing."),
            ManualBlock(ManualKind.Para, "When you stop, the take is cut at the scene lines. One recording over the whole song becomes one cell per scene, all pointing at the same file, with new cells in scenes where the track was empty. The full recording also stays in the sound library, so you can undo the split and place it by hand."),
            ManualBlock(ManualKind.Para, "Trimming, fades, crossfades, flattening lanes and tempo following are on **Bias**'s page. None of them change the file."),
            ManualBlock(ManualKind.Para, "Takes can be up to half an hour. Anything over two minutes is converted once in the background and streamed from storage, so there may be a short wait the first time a long take is used."),
            ManualBlock(ManualKind.Para, "Only one lane records at a time, and arming a second lane disarms the first."),
            ManualBlock(ManualKind.Para, "If the recorder fell behind and left a gap in the take, it isn't split, and the whole take is kept in the library. If the transport never played, nothing was recorded against a scene, and the app tells you."),
            ManualBlock(ManualKind.Heading, "Machines that use audio"),
            ManualBlock(ManualKind.Bullet, "**Forage** - one sample per pad, with a filter, crusher and pitch envelope."),
            ManualBlock(ManualKind.Bullet, "**Mosaic** - zones across the keyboard and velocity, from your own files or a SoundFont."),
            ManualBlock(ManualKind.Bullet, "**Pollen** - grains from a file or the live input."),
            ManualBlock(ManualKind.Bullet, "**Dice** - a loop cut into slices."),
            ManualBlock(ManualKind.Bullet, "**Molt** - a sung take, tuned by the piano roll."),
            ManualBlock(ManualKind.Bullet, "**Cipher** and **Filament** can use the live input."),
            ManualBlock(ManualKind.Bullet, "**Bias** - four lanes of recordings along the song. Its recordings belong to its cells instead of the machine."),
        )),
        ManualSection("Importing and exporting", "", listOf(
            ManualBlock(ManualKind.Para, "**Export…** in the file menu renders the song faster than real time, through the same engine that plays it, tails included."),
            ManualBlock(ManualKind.Para, "You can export the whole song, the current scene or stems."),
            ManualBlock(ManualKind.Heading, "Formats"),
            ManualBlock(ManualKind.Bullet, "**WAV** and **AIFF** - 16 or 24 bit, or 32-bit float."),
            ManualBlock(ManualKind.Bullet, "**FLAC** - lossless and smaller."),
            ManualBlock(ManualKind.Bullet, "**MP3** and **AAC** - at the bitrate you choose.", "**MP3** - at the bitrate you choose. AAC is only on the phone."),
            ManualBlock(ManualKind.Bullet, "**MIDI** - the notes without the sound, with each track's transpose and fixed velocity applied, and its pedal, mod wheel and pressure lanes. Drum tracks go on channel 10 as General MIDI drums, so other programs hear the right sounds."),
            ManualBlock(ManualKind.Bullet, "**Song bundle** - the song and the samples it uses, in one file you can share."),
            ManualBlock(ManualKind.Heading, "Stems"),
            ManualBlock(ManualKind.Para, "Stems writes each track to its own file in one pass, along with the full mix. Each mixer group is a stem too, and a track routed into a group is part of the group's stem instead of having its own, so the stems add up to the mix."),
            ManualBlock(ManualKind.Heading, "Loudness"),
            ManualBlock(ManualKind.Para, "**loudness** is either **as mixed** or **-14 LUFS**. With -14 the song is rendered twice, once to measure it and again with the gain that brings it to -14 LUFS, which is about where streaming services play things. The gain is held back if it would push the true peak over -1 dBTP, so a very dynamic song may end up a little under -14. Stems get the same gain, so they still add up to the mix."),
            ManualBlock(ManualKind.Para, "The master strip in the mixer shows the same measurement while you play: integrated LUFS, and under it the short-term reading (**S**) and the true peak (**TP**). TP turns red above -1 dBTP. It resets every time you press play, or when you tap it.", "The master strip in the mixer shows the same measurement while you play: integrated LUFS, and under it the short-term reading (**S**) and the true peak (**TP**). TP turns red above -1 dBTP. It resets every time you press play, or when you click it."),
            ManualBlock(ManualKind.Heading, "Exports are repeatable"),
            ManualBlock(ManualKind.Para, "Exporting the same song twice gives identical files, since every machine is reset before the render starts."),
            ManualBlock(ManualKind.Heading, "Importing"),
            ManualBlock(ManualKind.Para, "**Import…** in the file menu takes a file from anywhere on the phone, and what happens depends on what it is:", "**Import…** in the file menu takes a file from anywhere on the computer, and what happens depends on what it is:"),
            ManualBlock(ManualKind.Bullet, "**A MIDI file** opens a window showing each part in the file with a machine picked for it. Tap a machine to change it, or pick **skip** to leave the part out. Drums on channel 10 go to Hexbeat, with each drum moved to the matching sound. Parts that say what instrument they are get a fitting machine, like an organ going to Manual and brass to Brazen.", "**A MIDI file** opens a window showing each part in the file with a machine picked for it. Click a machine to change it, or pick **skip** to leave the part out. Drums on channel 10 go to Hexbeat, with each drum moved to the matching sound. Parts that say what instrument they are get a fitting machine, like an organ going to Manual and brass to Brazen."),
            ManualBlock(ManualKind.Bullet, "The file is cut into scenes of 4, 8 or 16 bars. A stretch that's the same as the one before becomes a repeat, so a loop comes in as one scene played several times. The tempo and time signature come from the file, and where the tempo changes, the scenes after it get a tempo of their own."),
            ManualBlock(ManualKind.Bullet, "Pedals, the mod wheel and pressure come in as lanes, and pitch bend as bends on the notes."),
            ManualBlock(ManualKind.Bullet, "Words in the file, including a karaoke file's, go on the notes they start with, and that part goes to Diction to sing them."),
            ManualBlock(ManualKind.Bullet, "It opens as a new song and is saved straight away."),
            ManualBlock(ManualKind.Bullet, "**A song bundle** (a .zip made by Export) opens as a song, with its samples. If you already have a sample with the same name, yours is kept and the bundle's comes in under a new name."),
            ManualBlock(ManualKind.Bullet, "**A sound** (WAV, AIFF, FLAC or MP3) goes into the sound library, up to ten minutes of it."),
            ManualBlock(ManualKind.Bullet, "**A tuning** (a Scala .scl file) joins the tuning list, under key in the tempo window and in each track's settings."),
            ManualBlock(ManualKind.Para, "An imported song never replaces one you've saved. If the name is taken, it gets a number after it."),
            ManualBlock(ManualKind.Heading, "Sharing"),
            ManualBlock(ManualKind.Para, "When an export finishes, **Share** sends it straight on through the phone's share sheet: email, Drive, a chat or another app. Stems go as all their files together.", "When an export finishes, **Share** opens the folder it was saved in, to send it on from there."),
            ManualBlock(ManualKind.Para, "**Share song…** in the file menu sends the open song as a bundle, samples included, for someone else to open in Acidulous.", "**Share song…** in the file menu saves the open song as a bundle, samples included, and opens its folder so you can send it to someone."),
            ManualBlock(ManualKind.Para, "The other way works too. Open a MIDI file, a bundle, a shared voice or a sound with Acidulous, or share one to it, and it goes wherever **Import…** would have put it; a voice goes to the voice page in **Sound**.", ""),
        )),
        ManualSection("Settings", "", listOf(
            ManualBlock(ManualKind.Heading, "display"),
            ManualBlock(ManualKind.Bullet, "**theme** - dark, light, high contrast or follow the phone. High contrast is white on black, with brighter colours and outlines round every control.", "**theme** - dark, light, high contrast or follow the system. High contrast is white on black, with brighter colours and outlines round every control."),
            ManualBlock(ManualKind.Bullet, "**language** - the app's language: the phone's own, English or French. Not in a browser, which uses its own.", "**language** - the app's language: the computer's own, English or French. Not in a browser, which uses its own."),
            ManualBlock(ManualKind.Bullet, "**size** - makes everything bigger, in four steps."),
            ManualBlock(ManualKind.Bullet, "", "**screen scale** - how big the whole window is drawn. **system** takes the computer's own setting."),
            ManualBlock(ManualKind.Bullet, "**while playing** - whether the screen can turn off while playing.", ""),
            ManualBlock(ManualKind.Bullet, "**keyboard** - **keys…** opens the list of shortcuts, where you can change them and choose how letters play notes. See A keyboard."),
            ManualBlock(ManualKind.Heading, "audio"),
            ManualBlock(ManualKind.Bullet, "", "**output** - which output to play through, or the system default. On Windows an interface's own driver is listed too, marked **low latency**. It's the quickest way to the interface, and while it plays the recorder's inputs are that interface's inputs, two at a time."),
            ManualBlock(ManualKind.Bullet, "**buffer** - tight, balanced or safe. Tight has the lowest latency but may crackle on a slower phone, and safe gives the phone more time. If the sound still breaks up, the buffer grows by itself, then comes back down to the smallest size the device can hold, and remembers it for next time.", "**buffer** - tight, balanced or safe. Tight has the lowest latency but may crackle on a slower computer, and safe gives the computer more time. If the sound still breaks up, the buffer grows by itself, then comes back down to the smallest size the device can hold, and remembers it for next time."),
            ManualBlock(ManualKind.Bullet, "**voices** - how many notes a track can hold at once. The oldest note is dropped first."),
            ManualBlock(ManualKind.Bullet, "**cores** - how many cores the tracks are made on at once. **auto** uses all of the phone's fast cores but one, which it leaves for the screen. **1** makes every track on the same core. A light song stays on one core either way.", "**cores** - how many cores the tracks are made on at once. **auto** uses half the computer's cores. **1** makes every track on the same core. A light song stays on one core either way."),
            ManualBlock(ManualKind.Bullet, "**quality** - what to give up when the phone can't keep up. **lean**: - runs the **amp** and **distortion** without oversampling (about half the amp's cost) - halves the **reverb**'s size (about half its cost) - halves the partials in **Resonance** patches that use more than twelve - halves **Trinity**'s unison stacks (never below two), and lets at most six released notes ring at once, fading older tails out quickly. Held notes aren't affected - halves the number of grains in **Pollen** **auto** switches to lean by itself when the phone is struggling. Notes you're holding keep the quality they started with, and only tails you've already let go of can be cut short. Exports and freezing always use full quality.", "**quality** - what to give up when the computer can't keep up. **lean**: - runs the **amp** and **distortion** without oversampling (about half the amp's cost) - halves the **reverb**'s size (about half its cost) - halves the partials in **Resonance** patches that use more than twelve - halves **Trinity**'s unison stacks (never below two), and lets at most six released notes ring at once, fading older tails out quickly. Held notes aren't affected - halves the number of grains in **Pollen** **auto** switches to lean by itself when the computer is struggling. Notes you're holding keep the quality they started with, and only tails you've already let go of can be cut short. Exports and freezing always use full quality."),
            ManualBlock(ManualKind.Heading, "record"),
            ManualBlock(ManualKind.Bullet, "**depth** - the bit depth for recordings and exports."),
            ManualBlock(ManualKind.Bullet, "**count-in** - bars of clicks before recording starts."),
            ManualBlock(ManualKind.Bullet, "**quantise** - moves what you play onto the clip's grid. **off** leaves notes exactly where you played them, and **amount** moves them only part of the way."),
            ManualBlock(ManualKind.Bullet, "**take** - **add** puts what you play in with the notes already there. **replace** takes out the notes the playhead passes from your first note on, so what's left is what you played. Either way the take is one step of undo."),
            ManualBlock(ManualKind.Bullet, "**start** - **on play** records from when you press play. **first note** waits: arm, then play a note and the song starts with it, with no count-in."),
            ManualBlock(ManualKind.Bullet, "**passes** - **loop** keeps recording round and round until you stop it. **once** stops recording after one pass of the clip and leaves it playing."),
            ManualBlock(ManualKind.Heading, "songs"),
            ManualBlock(ManualKind.Para, "What a new song starts with: tempo, time signature, the first track's machine, and whether it starts with a scale set."),
            ManualBlock(ManualKind.Heading, "TalkBack", ""),
            ManualBlock(ManualKind.Para, "TalkBack is turned on in the phone's own settings. With it on, every control says what it is and what it's set to. On a knob or a fader, swipe up or down to change it. Anything you'd hold to open, like a clip's settings, is in TalkBack's actions menu.", ""),
            ManualBlock(ManualKind.Para, "The piano roll says how many notes a clip has and the lowest and highest, but not each note. To add notes, record them from the keys.", ""),
            ManualBlock(ManualKind.Para, "With TalkBack on, the song grid shows as many scenes as fit and doesn't scroll sideways. **Previous scenes** and **Next scenes** above it move a page at a time. When the last page is full, add a scene from a scene's own menu.", ""),
        )),
        ManualSection("A keyboard", "", listOf(
            ManualBlock(ManualKind.Para, "Acidulous works with built in, USB, or Bluetooth keyboards.", "Acidulous works with the computer's keyboard."),
            ManualBlock(ManualKind.Para, "Press **Shift+/** (or **Alt+Q**) at any time to see the keys that work on the screen you're on."),
            ManualBlock(ManualKind.Heading, "Play mode"),
            ManualBlock(ManualKind.Para, "Letters either run shortcuts or play notes. **`** (or **Sym**) switches between the two, and so does tapping the octave number in the editor's keyboard strip. The number is lit while letters are notes.", "Letters either run shortcuts or play notes. **`** (or **Sym**) switches between the two, and so does clicking the octave number in the editor's keyboard strip. The number is lit while letters are notes."),
            ManualBlock(ManualKind.Para, "With play mode on:"),
            ManualBlock(ManualKind.Bullet, "**A S D F G H J K L** are white keys, and **W E T Y U O P** the black keys between them like on a piano. A is C."),
            ManualBlock(ManualKind.Bullet, "**Z** and **X** move down and up an octave. In the editor they move the on-screen keyboard too."),
            ManualBlock(ManualKind.Bullet, "**C** and **V** make notes softer and harder."),
            ManualBlock(ManualKind.Bullet, "Shift plays a note an octave up."),
            ManualBlock(ManualKind.Para, "Notes go to the track of the last clip you opened, like a MIDI keyboard, so they record and the track's chord, scale and arp apply. On a drum machine the keys are its pads, in order."),
            ManualBlock(ManualKind.Para, "Space still plays and stops, and anything with Ctrl or Alt still works as a shortcut."),
            ManualBlock(ManualKind.Subheading, "Tracker layout"),
            ManualBlock(ManualKind.Para, "A full keyboard has room for two octaves. Choose **tracker** under **notes** in the keys window (see **Changing the keys** below):"),
            ManualBlock(ManualKind.Bullet, "**Z** to **/** is the lower octave, with **S D G H J** as its black keys."),
            ManualBlock(ManualKind.Bullet, "**Q** to **P** is the upper octave, with the number row as its black keys."),
            ManualBlock(ManualKind.Bullet, "**-** and **=** move the octave, and **[** and **]** change how hard."),
            ManualBlock(ManualKind.Heading, "Shortcuts"),
            ManualBlock(ManualKind.Bullet, "play / stop - **Space**"),
            ManualBlock(ManualKind.Bullet, "record - **R**, or **Alt+R**"),
            ManualBlock(ManualKind.Bullet, "loop - **L**, or **Alt+L**"),
            ManualBlock(ManualKind.Bullet, "undo - **Ctrl+Z**, or **Alt+Z**"),
            ManualBlock(ManualKind.Bullet, "redo - **Ctrl+Shift+Z**, or **Alt+Y**"),
            ManualBlock(ManualKind.Bullet, "stop everything - **Ctrl+.**, or **Alt+P**"),
            ManualBlock(ManualKind.Bullet, "keys play notes - **`**, or **Sym**"),
            ManualBlock(ManualKind.Bullet, "save - **Ctrl+S**, or **Alt+S**"),
            ManualBlock(ManualKind.Bullet, "file menu - **F**, or **Alt+F**"),
            ManualBlock(ManualKind.Bullet, "mixer and perform pages - **M**, or **Alt+M**"),
            ManualBlock(ManualKind.Bullet, "manual - **F1**, or **Alt+H**"),
            ManualBlock(ManualKind.Bullet, "the list of keys - **Shift+/**, or **Alt+Q**"),
            ManualBlock(ManualKind.Bullet, "back - **Esc**"),
            ManualBlock(ManualKind.Bullet, "", "full screen - **F11**"),
            ManualBlock(ManualKind.Para, "In the editor:"),
            ManualBlock(ManualKind.Bullet, "previous / next page - **[ and ]**, or **Alt+B and Alt+N**"),
            ManualBlock(ManualKind.Bullet, "previous / next track - **Shift+[ and Shift+]**"),
            ManualBlock(ManualKind.Bullet, "draw or select - **D**, or **Alt+D**"),
            ManualBlock(ManualKind.Bullet, "step view - **T**, or **Alt+T**"),
            ManualBlock(ManualKind.Bullet, "lock steps - **K**, or **Alt+K**"),
            ManualBlock(ManualKind.Bullet, "generate notes - **G**, or **Alt+G**"),
            ManualBlock(ManualKind.Bullet, "quantise - **Q**, or **Alt+U**"),
            ManualBlock(ManualKind.Bullet, "fold the panel - **P**, or **Alt+V**"),
            ManualBlock(ManualKind.Bullet, "fold the keyboard - **B**, or **Alt+J**"),
            ManualBlock(ManualKind.Para, "The first key is for a full keyboard and the second for a small one. Keys without Alt or Ctrl only work as shortcuts when play mode is off."),
            ManualBlock(ManualKind.Para, "In a window with tabs, previous and next page step through the tabs."),
            ManualBlock(ManualKind.Heading, "Moving around"),
            ManualBlock(ManualKind.Para, "The arrows, or swipes on a touchpad, move between controls. Tab and Shift+Tab do too, and a ring shows where you are. **Enter** presses a button or a switch.", "The arrows move between controls. Tab and Shift+Tab do too, and a ring shows where you are. **Enter** presses a button or a switch."),
            ManualBlock(ManualKind.Para, "On a knob or fader, **Enter** grabs it and the ring turns pink. The arrows then turn it, Shift+arrows turn it finely, Page Up and Page Down in big steps, and Home and End go to either end. **Enter** or **Esc** lets go. **+** and **-** turn a knob without grabbing it."),
            ManualBlock(ManualKind.Para, "Anything you'd hold has the same choices on **Alt+Enter** or the Menu key, like a clip's settings, a scene's menu or a knob's list of values."),
            ManualBlock(ManualKind.Para, "A window opened from the keys puts you on its first control, and **Esc** closes it."),
            ManualBlock(ManualKind.Heading, "In the editor"),
            ManualBlock(ManualKind.Para, "The piano roll, the note lanes under it and the automation lanes each take **Enter** to start editing, and a pink cursor appears. **Esc** stops."),
            ManualBlock(ManualKind.Para, "In the piano roll:"),
            ManualBlock(ManualKind.Bullet, "the arrows move the cursor a grid step, or a semitone. Page Up and Page Down move it an octave."),
            ManualBlock(ManualKind.Bullet, "**Enter** adds a note or takes one away, like a tap. **Delete** removes the note under the cursor.", "**Enter** adds a note or takes one away, like a click. **Delete** removes the note under the cursor."),
            ManualBlock(ManualKind.Bullet, "**Shift+Left** and **Shift+Right** shorten and lengthen the note under the cursor."),
            ManualBlock(ManualKind.Bullet, "**Alt** and an arrow moves the note along with the cursor."),
            ManualBlock(ManualKind.Para, "In a note lane, Left and Right walk from note to note, and Up and Down change the note's value, finely with Shift. Showing words, Enter opens them."),
            ManualBlock(ManualKind.Para, "In an automation lane, Left and Right move a grid step, and Up and Down set the value there, adding a point if there isn't one."),
            ManualBlock(ManualKind.Para, "Every change is one step of undo, like it would be by touch."),
            ManualBlock(ManualKind.Heading, "A game controller"),
            ManualBlock(ManualKind.Para, "A controller's buttons work like the keys, so the app can be used without touching the screen, on a handheld like the Retroid Pocket."),
            ManualBlock(ManualKind.Bullet, "**d-pad** - moves between controls, and moves the cursor in the editor."),
            ManualBlock(ManualKind.Bullet, "**A** - presses, like Enter. On a knob it grabs it, the d-pad turns it, and **A** again lets go."),
            ManualBlock(ManualKind.Bullet, "**B** - back: closes a window, or leaves the editor."),
            ManualBlock(ManualKind.Bullet, "**X** - what a long press does: a control's list of actions."),
            ManualBlock(ManualKind.Bullet, "**Y** - play / stop."),
            ManualBlock(ManualKind.Bullet, "**L1** and **R1** - previous and next page in the editor, and a window's tabs."),
            ManualBlock(ManualKind.Bullet, "**L2** and **R2** - previous and next track in the editor."),
            ManualBlock(ManualKind.Bullet, "**Start** - play mode."),
            ManualBlock(ManualKind.Bullet, "**Select** - the file menu."),
            ManualBlock(ManualKind.Bullet, "**left stick** - turns the highlighted knob or fader, faster the further it's pushed. One push is one step of undo."),
            ManualBlock(ManualKind.Bullet, "**right stick** - a fast d-pad: the further it's pushed, the faster it moves."),
            ManualBlock(ManualKind.Para, "If nothing is highlighted, the first press of the d-pad or **A** highlights something to start from."),
            ManualBlock(ManualKind.Para, "**Start** switches play mode on and off. In play mode the controller is an instrument for the track MIDI plays:"),
            ManualBlock(ManualKind.Bullet, "the **d-pad** and the four buttons are eight notes of the track's scale (its scale chip, or the song's key, or else major), going round each clockwise from the bottom: the d-pad has the first four, the buttons the next four. On a drum machine they're its first eight pads."),
            ManualBlock(ManualKind.Bullet, "**L1** and **R1** move the octave."),
            ManualBlock(ManualKind.Bullet, "the **right stick** bends the pitch sideways and adds mod upwards, and the **left stick** pushed up is pressure."),
            ManualBlock(ManualKind.Bullet, "pull **R2** or **L2** partway while you play to set how hard notes play."),
            ManualBlock(ManualKind.Bullet, "**Select** is play / stop, since **Y** is a note."),
            ManualBlock(ManualKind.Heading, "Changing the keys"),
            ManualBlock(ManualKind.Para, "**Settings › display › keyboard › keys…** lists every shortcut with its keys, and each can have two. Tap a key, or move to it and press Enter, then press the new key or combination. **+** adds a second key.", "**Settings › display › keyboard › keys…** lists every shortcut with its keys, and each can have two. Click a key, or move to it and press Enter, then press the new key or combination. **+** adds a second key."),
            ManualBlock(ManualKind.Para, "If the new key already belonged to something else, it moves, and the window tells you what lost it. **Alt+Enter** on a key removes it. **reset** puts every key back as it was."),
            ManualBlock(ManualKind.Para, "The **controller** card lists a controller's buttons and what each does. Tap one to choose from a list: **press**, **back**, **actions list**, **nothing**, or any shortcut. **reset** puts these back too. Play mode's notes stay where they are.", "The **controller** card lists a controller's buttons and what each does. Click one to choose from a list: **press**, **back**, **actions list**, **nothing**, or any shortcut. **reset** puts these back too. Play mode's notes stay where they are."),
        )),
    )

    private val fr: List<ManualSection> = listOf(
        ManualSection("Un premier morceau", "", listOf(
            ManualBlock(ManualKind.Para, "Un morceau a jusqu’à seize pistes. Chaque piste porte une machine : un synthé, une boîte à rythmes, un échantillonneur, etc. Un morceau peut avoir plusieurs fois la même machine."),
            ManualBlock(ManualKind.Para, "", "Sur un ordinateur, un clic vaut un toucher, et un clic droit ou un bouton maintenu vaut un maintien. La molette fait défiler les grilles, de côté avec Maj enfoncée, et Ctrl avec la molette les agrandit. **F11** active et désactive le plein écran."),
            ManualBlock(ManualKind.Heading, "La grille du morceau"),
            ManualBlock(ManualKind.Para, "Le premier écran est la grille du morceau. Les pistes sont à gauche, de haut en bas, et les scènes en haut, de gauche à droite. Là où une piste croise une scène se trouve un clip : les notes que cette piste joue dans cette scène."),
            ManualBlock(ManualKind.Para, "La barre du bas est sur chaque écran, et son bout droit a toujours annuler, rétablir, mixage, enregistrer et jouer."),
            ManualBlock(ManualKind.Heading, "Faire un son"),
            ManualBlock(ManualKind.Step, "Touchez **+ piste** et choisissez une machine. Un nouveau morceau en a déjà une.", "Cliquez **+ piste** et choisissez une machine. Un nouveau morceau en a déjà une."),
            ManualBlock(ManualKind.Step, "Touchez le clip vide où la piste croise la première scène pour ouvrir l’éditeur.", "Cliquez le clip vide où la piste croise la première scène pour ouvrir l’éditeur."),
            ManualBlock(ManualKind.Step, "Jouez sur le clavier du bas. Touchez le nom du son en haut du panneau pour essayer les sons d’usine.", "Jouez sur le clavier du bas. Cliquez le nom du son en haut du panneau pour essayer les sons d’usine."),
            ManualBlock(ManualKind.Step, "Dessinez des notes dans la grille, ou appuyez sur enregistrer et jouez-les."),
            ManualBlock(ManualKind.Step, "Touchez la flèche de retour pour revenir au morceau, et appuyez sur jouer.", "Cliquez la flèche de retour pour revenir au morceau, et appuyez sur jouer."),
            ManualBlock(ManualKind.Heading, "Les scènes"),
            ManualBlock(ManualKind.Para, "Une scène est une section du morceau, comme une intro ou un couplet. Tous les clips d’une scène jouent ensemble, et la scène se répète autant de fois que l’indique son en-tête avant que le morceau passe à la suivante."),
            ManualBlock(ManualKind.Para, "Les clips d’une scène peuvent avoir des longueurs différentes. Un clip de batterie d’une mesure sous un clip d’accords de quatre mesures joue simplement quatre fois en boucle."),
            ManualBlock(ManualKind.Heading, "Sauvegarder"),
            ManualBlock(ManualKind.Para, "Le morceau en cours est sauvegardé au fur et à mesure et revient la prochaine fois que vous ouvrez l’appli. **sauver** dans l’en-tête le sauvegarde sous son nom, et **fichier** a nouveau morceau, enregistrer sous et vos autres morceaux."),
            ManualBlock(ManualKind.Heading, "Le morceau de démo"),
            ManualBlock(ManualKind.Para, "À la première ouverture, l’appli charge **Squelch**, un morceau acid house à explorer et à démonter. Il utilise presque tout ce que l’appli sait faire :"),
            ManualBlock(ManualKind.Bullet, "Deux lignes acid avec accents, glissés, balayages de filtre et verrous de pas."),
            ManualBlock(ManualKind.Bullet, "Des effets de jeu enregistrés dans le morceau, et des roulements de caisse claire qui ne jouent que pendant qu’on maintient fill."),
            ManualBlock(ManualKind.Bullet, "Des percussions avec probabilités, ratchets et coups qui tombent un passage sur deux."),
            ManualBlock(ManualKind.Bullet, "Un arpège joué à partir d’accords tenus, une montée dessinée en bend et des bips sur le modulaire."),
            ManualBlock(ManualKind.Bullet, "Un pad atténué sous la grosse caisse, un groupe de batterie avec son propre compresseur et des effets sur la sortie principale."),
            ManualBlock(ManualKind.Para, "Vous pouvez le rouvrir n’importe quand avec **fichier · Morceaux…**."),
        )),
        ManualSection("La grille du morceau", "", listOf(
            ManualBlock(ManualKind.Para, "La grille sert d’arrangeur ou de lanceur de clips. Passez de l’un à l’autre avec le bouton du coin supérieur gauche de la grille."),
            ManualBlock(ManualKind.Heading, "En arrangeur"),
            ManualBlock(ManualKind.Para, "C’est le mode par défaut. Le morceau joue scène par scène, de gauche à droite. Chaque scène joue tous ses clips, se répète autant de fois que l’indique son en-tête, puis la scène suivante commence."),
            ManualBlock(ManualKind.Bullet, "Touchez l’en-tête d’une scène pour commencer là. Avec **⟳**, cette scène se répète, et avec **⇥ fin**, le morceau joue à partir d’elle jusqu’à la fin et s’arrête.", "Cliquez l’en-tête d’une scène pour commencer là. Avec **⟳**, cette scène se répète, et avec **⇥ fin**, le morceau joue à partir d’elle jusqu’à la fin et s’arrête."),
            ManualBlock(ManualKind.Bullet, "Maintenez l’en-tête d’une scène pour son menu : réglages, insérer, dupliquer, supprimer et déplacer à gauche ou à droite."),
            ManualBlock(ManualKind.Bullet, "Touchez le bouton de boucle à gauche de la barre du bas pour boucler tout le morceau ou seulement la scène en cours. Maintenez-le pour choisir **⟳** pour boucler sans fin ou **⇥ fin** pour jouer une fois jusqu’au bout et arrêter.", "Cliquez le bouton de boucle à gauche de la barre du bas pour boucler tout le morceau ou seulement la scène en cours. Maintenez-le pour choisir **⟳** pour boucler sans fin ou **⇥ fin** pour jouer une fois jusqu’au bout et arrêter."),
            ManualBlock(ManualKind.Bullet, "Après un arrêt, jouer reprend au début du morceau."),
            ManualBlock(ManualKind.Bullet, "L’affichage au-dessus de la barre du bas montre la scène qui joue, à quelle répétition elle en est (**×1/2** est la première de deux) et la mesure et le temps. Le temps à sa droite montre où vous êtes dans le morceau et sa durée. Touchez-le pour voir plutôt le temps qui reste, ou le temps depuis que vous avez appuyé sur jouer, et touchez encore pour revenir.", "L’affichage au-dessus de la barre du bas montre la scène qui joue, à quelle répétition elle en est (**×1/2** est la première de deux) et la mesure et le temps. Le temps à sa droite montre où vous êtes dans le morceau et sa durée. Cliquez-le pour voir plutôt le temps qui reste, ou le temps depuis que vous avez appuyé sur jouer, et cliquez encore pour revenir."),
            ManualBlock(ManualKind.Bullet, "Si quelque chose continue de sonner, maintenez jouer pour couper chaque note, écho et queue. **Panique** dans À propos… fait la même chose."),
            ManualBlock(ManualKind.Bullet, "La lecture s’arrête d’elle-même quand un appel entre, qu’une autre appli se met à jouer ou qu’on débranche les écouteurs.", ""),
            ManualBlock(ManualKind.Bullet, "Si Acidulous se ferme sans prévenir, il le dit à la prochaine ouverture et offre de partager un rapport. Les rapports restent sur le téléphone sauf si vous en partagez un, et le dernier est aussi dans À propos.", "Si Acidulous se ferme sans prévenir, il le dit à la prochaine ouverture et offre de partager un rapport. Les rapports restent sur cet ordinateur sauf si vous en partagez un, et le dernier est aussi dans À propos."),
            ManualBlock(ManualKind.Subheading, "Le tempo d’une scène"),
            ManualBlock(ManualKind.Para, "Dans les réglages d’une scène, **tempo** peut suivre le morceau ou être propre à la scène, soit en sautant au début de la scène, soit en glissant sur sa première mesure."),
            ManualBlock(ManualKind.Para, "**Rampe à la fin** amène le tempo au bpm réglé par **vers** sur les dernières mesures réglées par **sur**, pour ralentir vers la scène suivante ou accélérer sur toute une scène. Ça se fait au dernier passage de la scène, et la scène suivante commence à son propre tempo. Une scène avec une rampe montre ↘ ou ↗ dans son en-tête, et un export MIDI l’écrit comme un changement de tempo à chaque temps."),
            ManualBlock(ManualKind.Heading, "Les pistes"),
            ManualBlock(ManualKind.Para, "Touchez le nom d’une piste pour son menu : changer de machine, réglages, renommer, figer, dupliquer et supprimer. Maintenez le nom, ou choisissez **Réglages…**, pour les réglages de la piste :", "Cliquez le nom d’une piste pour son menu : changer de machine, réglages, renommer, figer, dupliquer et supprimer. Maintenez le nom, ou choisissez **Réglages…**, pour les réglages de la piste :"),
            ManualBlock(ManualKind.Bullet, "**nom** et **couleur**. Sinon, la couleur d’une piste vient de sa place."),
            ManualBlock(ManualKind.Bullet, "**transposer** - déplace chaque note vers le haut ou le bas pendant qu’elle joue, celles du clip comme celles de vos doigts. Le clip garde ce qui est écrit, donc revenir à 0 remet la partie comme avant. Pas sur les boîtes à rythmes."),
            ManualBlock(ManualKind.Bullet, "**accordage** - celui du morceau, ou celui de la piste. Voir Accordages."),
            ManualBlock(ManualKind.Bullet, "**vélocité** - **telle que jouée**, ou toutes les notes à une même vélocité."),
            ManualBlock(ManualKind.Bullet, "**swing** - celui du morceau, ou une quantité propre à la piste."),
            ManualBlock(ManualKind.Bullet, "**sortie midi** et **canal** - **non**, **les deux** (la machine et le matériel) ou **seule** (le matériel seulement)."),
            ManualBlock(ManualKind.Bullet, "**sortie** - la sortie principale ou un des groupes du mixage."),
            ManualBlock(ManualKind.Para, "Les deux derniers sont aussi sur la tranche de mixage de la piste."),
            ManualBlock(ManualKind.Heading, "En lanceur"),
            ManualBlock(ManualKind.Para, "Touchez le bouton du coin et la grille devient un lanceur de clips, où chaque piste joue son propre clip, de n’importe quelle scène.", "Cliquez le bouton du coin et la grille devient un lanceur de clips, où chaque piste joue son propre clip, de n’importe quelle scène."),
            ManualBlock(ManualKind.Bullet, "Touchez un clip pour le lancer. Il part sur la prochaine ligne de temps pour tomber en mesure.", "Cliquez un clip pour le lancer. Il part sur la prochaine ligne de temps pour tomber en mesure."),
            ManualBlock(ManualKind.Bullet, "Le bouton **q :** règle ce qu’il attend. **fin** attend que le clip qui joue termine sa boucle, et les autres attendent un nombre de mesures."),
            ManualBlock(ManualKind.Bullet, "Touchez l’en-tête d’une scène pour passer à cette scène. Ses clips partent et toutes les autres pistes s’arrêtent, sur la même ligne. Un clip qui joue déjà continue.", "Cliquez l’en-tête d’une scène pour passer à cette scène. Ses clips partent et toutes les autres pistes s’arrêtent, sur la même ligne. Un clip qui joue déjà continue."),
            ManualBlock(ManualKind.Bullet, "Touchez un clip qui joue pour l’arrêter à la fin de sa boucle. Touchez arrêter deux fois pour tout arrêter.", "Cliquez un clip qui joue pour l’arrêter à la fin de sa boucle. Cliquez arrêter deux fois pour tout arrêter."),
            ManualBlock(ManualKind.Bullet, "Chaque piste garde sa propre position, et arrêter les laisse où elles sont. L’affichage au-dessus de la barre du bas montre où en est chacune, et à droite le temps depuis que vous avez appuyé sur jouer."),
            ManualBlock(ManualKind.Subheading, "Boucler"),
            ManualBlock(ManualKind.Para, "Dans le lanceur, une case vide est un looper."),
            ManualBlock(ManualKind.Bullet, "Touchez une case vide. Elle devient un clip, part sur la prochaine ligne et enregistre ce que vous jouez. Son bord pulse en rouge pendant l’enregistrement.", "Cliquez une case vide. Elle devient un clip, part sur la prochaine ligne et enregistre ce que vous jouez. Son bord pulse en rouge pendant l’enregistrement."),
            ManualBlock(ManualKind.Bullet, "Touchez-la encore pour fermer la boucle sur la barre de mesure la plus proche. Sinon, elle se ferme d’elle-même à 16 mesures.", "Cliquez-la encore pour fermer la boucle sur la barre de mesure la plus proche. Sinon, elle se ferme d’elle-même à 16 mesures."),
            ManualBlock(ManualKind.Bullet, "Une fois fermée, elle continue d’enregistrer par-dessus elle-même à chaque tour, avec un bord rouge fixe. Touchez pour arrêter d’y ajouter, et touchez encore pour en ajouter.", "Une fois fermée, elle continue d’enregistrer par-dessus elle-même à chaque tour, avec un bord rouge fixe. Cliquez pour arrêter d’y ajouter, et cliquez encore pour en ajouter."),
            ManualBlock(ManualKind.Bullet, "Pour que les boucles se ferment à une longueur fixe, choisissez-en une sous **durée des boucles enregistrées** dans la fenêtre **q :**."),
            ManualBlock(ManualKind.Para, "Le résultat est un clip normal. Touchez-le deux fois pour le modifier.", "Le résultat est un clip normal. Cliquez-le deux fois pour le modifier."),
            ManualBlock(ManualKind.Heading, "Le zoom"),
            ManualBlock(ManualKind.Para, "Glissez à deux doigts pour vous déplacer dans la grille et pincez pour agrandir ou réduire les cases. Un doigt ouvre et lance toujours les clips.", "La molette déplace la grille, de côté avec Maj enfoncée, et Ctrl avec la molette agrandit ou réduit les cases."),
            ManualBlock(ManualKind.Para, "Sur une tablette ou une grande fenêtre, les cases grandissent pour remplir l’écran, jusqu’à trois fois leur taille, tant que vous ne pincez pas.", "Dans une grande fenêtre, les cases grandissent pour la remplir, jusqu’à trois fois leur taille, tant que vous ne zoomez pas."),
            ManualBlock(ManualKind.Heading, "Les réglages d’un clip"),
            ManualBlock(ManualKind.Para, "Maintenez un clip pour ses réglages : sa longueur en mesures, muet et la grille sur laquelle il s’aligne."),
            ManualBlock(ManualKind.Para, "**Copier, couper, coller et vider** sont en haut. Vous pouvez maintenir n’importe quelle case pour les avoir, même une vide, pour coller un clip dans une autre scène ou piste. Coller et vider demandent d’abord s’il y a un clip là. Couper ne demande pas, puisque le clip reste dans le presse-papiers."),
            ManualBlock(ManualKind.Para, "Une copie a les notes, l’automatisation et les réglages, longueur comprise. Elle n’a pas l’audio figé, donc un clip collé joue sa machine jusqu’à ce que vous le figiez de nouveau. Les enregistrements d’une piste audio suivent, eux."),
            ManualBlock(ManualKind.Heading, "Ce qu’une case montre"),
            ManualBlock(ManualKind.Para, "Le nombre de mesures est dans le coin, avec **1** pour un clip joué une fois et **M** pour un clip muet. Une case d’une piste audio montre sa forme d’onde et combien de ses quatre couloirs ont un enregistrement. Elle devient **ambre** si l’un d’eux a été enregistré à un autre tempo que celui de la scène."),
            ManualBlock(ManualKind.Heading, "Figer"),
            ManualBlock(ManualKind.Para, "Figer rend un clip en audio et joue cet audio au lieu de la machine, ce qui libère du processeur pour le reste. Vous pouvez figer un clip, une scène entière ou une piste entière à partir des menus."),
            ManualBlock(ManualKind.Para, "Les deux effets d’insertion de la piste sont figés aussi, donc un clip figé ne coûte presque rien à jouer. Le mixage fonctionne toujours : fader, panoramique, envois et muet."),
            ManualBlock(ManualKind.Para, "La queue (réverbération, délai, relâchement long) est rendue aussi, jusqu’à huit secondes, et elle résonne sur la boucle suivante et après l’arrêt du clip comme le ferait la machine en direct."),
            ManualBlock(ManualKind.Para, "Si une scène fait une rampe vers un nouveau tempo, ses clips figés sont étirés dans le temps le long de la rampe sans changer de hauteur."),
            ManualBlock(ManualKind.Para, "Changer la machine, un des effets ou le tempo rend un figé périmé, et le clip reçoit une marque. Défigez-le ou figez-le de nouveau."),
            ManualBlock(ManualKind.Heading, "Quand le téléphone ne suit pas", "Quand l’ordinateur ne suit pas"),
            ManualBlock(ManualKind.Para, "Si le moteur commence à prendre du retard, les pistes qui coûtent le plus s’allument en rouge, tout comme l’indicateur de charge dans l’en-tête. Rien ne s’arrête."),
            ManualBlock(ManualKind.Para, "Une piste ne s’allume que si le moteur est en retard et que cette piste pèse lourd dans la charge. La figer règle d’habitude le problème."),
        )),
        ManualSection("L’éditeur", "", listOf(
            ManualBlock(ManualKind.Para, "Un clip s’ouvre avec la grille de notes en haut, les commandes de la machine au milieu et le clavier ou les pads en bas."),
            ManualBlock(ManualKind.Heading, "La grille"),
            ManualBlock(ManualKind.Para, "Pour une machine mélodique, c’est une grille de notes, avec la hauteur à la verticale et le temps à l’horizontale."),
            ManualBlock(ManualKind.Bullet, "Touchez une case vide pour ajouter une note, et touchez une note pour la supprimer.", "Cliquez une case vide pour ajouter une note, et cliquez une note pour la supprimer."),
            ManualBlock(ManualKind.Bullet, "Glissez une note pour la déplacer, ou glissez son bord droit pour changer sa longueur."),
            ManualBlock(ManualKind.Bullet, "Glissez à **deux doigts** pour défiler et pincez pour zoomer. Un doigt dessine toujours.", "La molette fait défiler de haut en bas, et de côté avec Maj enfoncée. Ctrl avec la molette zoome sur le temps, Ctrl, Maj et la molette zooment sur les rangées, et glisser dessine toujours."),
            ManualBlock(ManualKind.Bullet, "Le coin **gam** change l’affichage de la gamme du morceau : toutes les notes, notes de la gamme en surbrillance ou seulement les notes de la gamme."),
            ManualBlock(ManualKind.Para, "Pour une boîte à rythmes, c’est une grille de pas avec une rangée par son. Touchez pour ajouter un coup.", "Pour une boîte à rythmes, c’est une grille de pas avec une rangée par son. Cliquez pour ajouter un coup."),
            ManualBlock(ManualKind.Heading, "Générer"),
            ManualBlock(ManualKind.Para, "Le bouton du dé en haut de l’éditeur écrit des notes pour vous. Le clip change à mesure que vous tournez les boutons, pour écouter pendant que le morceau joue. **OK** garde les notes et **Annuler** remet le clip comme avant, et annuler reprend le tout en une seule étape."),
            ManualBlock(ManualKind.Bullet, "**rythme** répartit un nombre de coups le plus également possible sur un nombre de pas, et **rotation** fait tourner le motif. Un motif plus court que la mesure se décale par rapport à elle."),
            ManualBlock(ManualKind.Bullet, "**ligne** écrit une ligne dans la gamme de la piste ou la tonalité du morceau, ou en pentatonique mineure s’il n’y a ni l’une ni l’autre. **sauts** règle à quelle fréquence elle saute au lieu d’aller à une note voisine."),
            ManualBlock(ManualKind.Bullet, "**muter** change une partie des notes déjà là : certaines bougent d’un degré dans la gamme, certaines partent, quelques nouvelles apparaissent et les vélocités changent. **quantité** règle combien."),
            ManualBlock(ManualKind.Para, "Sur une boîte à rythmes, rythme et **semer** travaillent sur un son et laissent les autres tranquilles, et muter déplace les coups dans le temps au lieu de la hauteur."),
            ManualBlock(ManualKind.Para, "**relancer** donne une nouvelle série de choix au hasard. Les mêmes réglages et le même tirage donnent toujours les mêmes notes."),
            ManualBlock(ManualKind.Heading, "Verrouiller un pas"),
            ManualBlock(ManualKind.Para, "Un verrou donne à un pas sa propre valeur pour un bouton, par exemple accorder la caisse claire du pas 7 plus haut que toutes les autres."),
            ManualBlock(ManualKind.Bullet, "Touchez le losange (◆) en haut de l’éditeur. Il s’allume, et la grille prend un bord rose.", "Cliquez le losange (◆) en haut de l’éditeur. Il s’allume, et la grille prend un bord rose."),
            ManualBlock(ManualKind.Bullet, "Touchez les pas à verrouiller : les coups dans la grille de batterie, les pas dans la rangée de pas de Reflux ou les notes dans la grille de notes. Touchez encore pour en libérer un.", "Cliquez les pas à verrouiller : les coups dans la grille de batterie, les pas dans la rangée de pas de Reflux ou les notes dans la grille de notes. Cliquez encore pour en libérer un."),
            ManualBlock(ManualKind.Bullet, "Tournez n’importe quel bouton du panneau en dessous, celui de la machine ou d’un effet. Les pas choisis prennent cette valeur et le bouton ne bouge pas pour le reste du clip."),
            ManualBlock(ManualKind.Bullet, "Maintenez un bouton pour retirer le verrou des pas choisis."),
            ManualBlock(ManualKind.Bullet, "Touchez encore le losange pour revenir au dessin des notes.", "Cliquez encore le losange pour revenir au dessin des notes."),
            ManualBlock(ManualKind.Para, "Un verrou dure un pas de la grille, ou la longueur de la note dans la grille de notes. Les pas verrouillés ont un losange rose dans le coin, et un bouton qui a des verrous montre ◆ sur son cadran."),
            ManualBlock(ManualKind.Para, "Si vous tournez le bouton plus tard sans pas choisi, tous les pas non verrouillés le suivent. Un bouton qui a déjà un couloir dessiné ne peut pas être verrouillé, et montre ∿ à la place."),
            ManualBlock(ManualKind.Heading, "Enregistrer"),
            ManualBlock(ManualKind.Para, "Appuyez sur enregistrer, puis jouer, et ce que vous jouez va dans le clip, sur la grille du clip. Le fonctionnement d’une prise se règle dans Réglages, **enregistrer** : un décompte, la quantification ou non, l’ajout aux notes déjà là ou leur remplacement, le départ avec jouer ou à la première note jouée, et la boucle continue ou l’arrêt après un passage."),
            ManualBlock(ManualKind.Para, "Chaque prise est une seule étape d’annulation, du moment où l’enregistrement et la lecture tournent tous les deux jusqu’à ce que l’un s’arrête."),
            ManualBlock(ManualKind.Para, "Le clavier joue plus doux en bas d’une touche et plus fort en haut. Le bouton de la barre du bas désactive ça pour que chaque note soit à pleine vélocité, et les pads de batterie ont leur propre réglage pour ça."),
            ManualBlock(ManualKind.Para, "Glissez vers le haut ou le bas la rangée de commandes juste au-dessus des touches pour agrandir ou réduire le clavier."),
            ManualBlock(ManualKind.Heading, "Quantifier"),
            ManualBlock(ManualKind.Para, "**⊞** dans l’en-tête (ou **Q**) ouvre la fenêtre de quantification. Elle agit sur les notes choisies, ou sur tout le clip si aucune ne l’est, et vous entendez les changements à mesure. **OK** les garde en une seule étape d’annulation et **Annuler** remet tout comme avant."),
            ManualBlock(ManualKind.Bullet, "**grille** - la grille du clip, ou une autre."),
            ManualBlock(ManualKind.Bullet, "**force** - jusqu’où chaque note avance vers la grille. Moins que tout le chemin resserre une partie et garde son feeling."),
            ManualBlock(ManualKind.Bullet, "**déplacer** - seulement les débuts, ou aussi les fins."),
            ManualBlock(ManualKind.Bullet, "**tel que joué** - remet les notes exactement là où elles ont été jouées. Les notes enregistrées s’en souviennent toujours, peu importe combien de fois on les quantifie."),
            ManualBlock(ManualKind.Bullet, "**groove** - quantifie sur le timing d’un autre clip au lieu d’une grille droite, comme le contretemps paresseux d’un batteur. Le swing du morceau s’ajoute à la lecture, donc quantifiez sur une grille droite pour le swing."),
            ManualBlock(ManualKind.Bullet, "**humaniser** - chaque appui ajoute de petits changements au hasard au timing, au volume et à la longueur. Appuyez encore pour un autre résultat, ou sur **aucun** pour les retirer. Le bouton règle combien."),
            ManualBlock(ManualKind.Heading, "Réglages par note"),
            ManualBlock(ManualKind.Para, "Sous la grille, il y a un couloir qu’on peut ouvrir. Choisissez ce qu’il montre, puis glissez dedans pour régler cette valeur sur chaque note."),
            ManualBlock(ManualKind.Bullet, "**volume de la note** - la vélocité de la note."),
            ManualBlock(ManualKind.Bullet, "**probabilité** - à quelle fréquence elle joue. 50 veut dire la moitié du temps."),
            ManualBlock(ManualKind.Bullet, "**condition de déclenchement** - quand elle a le droit de jouer. `1:4` joue à la première de chaque série de quatre boucles. `pre` joue seulement si la dernière note conditionnelle a joué, et `!pr` seulement si elle n’a pas joué. `fil` joue seulement pendant qu’on maintient fill, et `!fi` seulement quand on ne le maintient pas."),
            ManualBlock(ManualKind.Bullet, "**ratchet** - combien de fois la note se répète dans son pas."),
            ManualBlock(ManualKind.Bullet, "**micro-décalage** - pousse la note hors de la grille, jusqu’à une demi-double-croche dans un sens ou dans l’autre."),
            ManualBlock(ManualKind.Bullet, "**paroles** - sur une piste Diction ou Tongue, ce que chaque note chante ou dit. Touchez une note pour les taper. Voir Diction et Tongue.", "**paroles** - sur une piste Diction ou Tongue, ce que chaque note chante ou dit. Cliquez une note pour les taper. Voir Diction et Tongue."),
            ManualBlock(ManualKind.Para, "Le hasard utilise une graine fixe, donc la même variation revient chaque fois."),
            ManualBlock(ManualKind.Heading, "Les boutons"),
            ManualBlock(ManualKind.Para, "Le panneau de la machine est entre la grille et le clavier. Ses commandes sont en sections, et les onglets en haut montrent une section à la fois. Les insertions, les modificateurs et les envois ouvrent le même genre de panneau dans une fenêtre."),
            ManualBlock(ManualKind.Para, "Maintenez un bouton pour le remettre où il était à l’ouverture du panneau. Les faders et les curseurs font pareil, y compris dans le mixage."),
            ManualBlock(ManualKind.Para, "Quand l’**affectation** MIDI est active, maintenir une commande efface plutôt son affectation."),
            ManualBlock(ManualKind.Heading, "L’automatisation"),
            ManualBlock(ManualKind.Para, "La bande sous le couloir par note enregistre et dessine un paramètre dans le temps. Tournez un bouton pendant l’enregistrement et le mouvement s’y écrit, ou choisissez un paramètre et dessinez-le à la main."),
            ManualBlock(ManualKind.Para, "Un bouton qui a un couloir dans le clip ouvert a un **∿** sur son cadran, et le couloir le fait bouger pendant que le clip joue."),
            ManualBlock(ManualKind.Para, "Quand vous appuyez sur jouer, chaque bouton automatisé revient d’abord à sa valeur dans le morceau, pour que le morceau commence pareil chaque fois, et un export aussi. Dans le lanceur, ça ne se fait pas, et un clip lancé continue là où le précédent a laissé les choses."),
            ManualBlock(ManualKind.Heading, "Replier"),
            ManualBlock(ManualKind.Para, "Les couloirs, le panneau de la machine et le clavier se replient chacun avec la petite flèche sur leur bord, pour donner plus de place à la grille."),
            ManualBlock(ManualKind.Heading, "Sur un écran carré", ""),
            ManualBlock(ManualKind.Para, "Sur un téléphone à peu près aussi large que haut, la grille prend le haut de l’écran et le clavier ou le panneau de la machine prend le bas, un à la fois. **clavier** au début de la barre du bas (**pads** sur une boîte à rythmes) passe de l’un à l’autre, et **fx** et le mixage font monter le panneau.", ""),
            ManualBlock(ManualKind.Para, "Les fenêtres tiennent dans l’écran là aussi, sans défilement. Les quelques-unes qui n’y tiendraient pas sont coupées en pages. L’arpège en a trois (**temps · toucher**, **motif**, **proba · marche**), et la tonalité de la fenêtre du tempo et l’entrée de la fenêtre Son ont chacune leur propre onglet.", ""),
        )),
        ManualSection("Les machines", "", listOf(
            ManualBlock(ManualKind.Para, "Chaque piste contient une machine, et vous pouvez utiliser plusieurs fois la même machine."),
            ManualBlock(ManualKind.Heading, "Basse et lead"),
            ManualBlock(ManualKind.Bullet, "**Reflux** - basse acid. Un oscillateur et un filtre qui hurle. Jouez plus fort pour l’accent et faites chevaucher les notes pour les glisser."),
            ManualBlock(ManualKind.Bullet, "**Trinity** - le synthé polyphonique à tout faire, avec trois oscillateurs à tables d’ondes, deux filtres et une matrice de modulation."),
            ManualBlock(ManualKind.Bullet, "**Ratio** - FM à six opérateurs, avec un bouton qui passe d’un algorithme à un autre."),
            ManualBlock(ManualKind.Heading, "Claviers et nappes"),
            ManualBlock(ManualKind.Bullet, "**Cumulus** - de grandes nappes douces bâties à partir d’un spectre de partiels."),
            ManualBlock(ManualKind.Bullet, "**Manual** - un orgue à deux claviers, pédalier, quatre modèles et cabine rotative."),
            ManualBlock(ManualKind.Bullet, "**Formulate** - un synthé 8 bits avec des tables de tracker, et une forme d’onde que vous tapez comme une formule."),
            ManualBlock(ManualKind.Heading, "Instruments modélisés"),
            ManualBlock(ManualKind.Para, "Ils reproduisent le fonctionnement du vrai instrument, alors ils se jouent comme lui."),
            ManualBlock(ManualKind.Bullet, "**Filament** - des cordes pincées, frottées à l’archet ou soufflées, avec une caisse et des cordes sympathiques."),
            ManualBlock(ManualKind.Bullet, "**Brazen** - les cuivres, de la trompette au tuba."),
            ManualBlock(ManualKind.Bullet, "**Timber** - les bois, anches et flûtes."),
            ManualBlock(ManualKind.Bullet, "**Resonance** - huit objets frappés qui résonnent les uns dans les autres."),
            ManualBlock(ManualKind.Bullet, "**Hammer** - pianos à queue, droits et électriques, célesta, piano jouet, dulcimer et cymbalum."),
            ManualBlock(ManualKind.Bullet, "**Tongue** - des guimbardes, dix sortes, avec la bouche sur la molette de modulation."),
            ManualBlock(ManualKind.Bullet, "**Draw** - les anches libres : harmonicas, accordéons, melodica et plus encore."),
            ManualBlock(ManualKind.Bullet, "**Fret** - guitares et basses électriques, leurs micros, les mains du musicien et un ampli qui larsène."),
            ManualBlock(ManualKind.Bullet, "**Tine** - marimba, vibraphone, xylophone, glockenspiel, piano à pouces, boîte à musique et tambours d’acier, frappés de mailloches plus ou moins dures."),
            ManualBlock(ManualKind.Bullet, "**Sympath** - sitar, tanpura, veena et shamisen : des cordes sur un chevalet qui grésille, des cordes sympathiques accordées sur une gamme, et un tanpura qui joue tout seul en mesure."),
            ManualBlock(ManualKind.Bullet, "**Palm** - percussions à main : tabla et bayan, djembé, cajón, tambour sur cadre et tambour d’aisselle, en frappes ouverte, claquée, étouffée, basse et sur le bord."),
            ManualBlock(ManualKind.Bullet, "**Chanter** - cornemuses et vielle à roue : des bourdons qui continuent entre les notes, des notes d’agrément, et une roue dont le chien grésille en rythme."),
            ManualBlock(ManualKind.Bullet, "**Aviary** - chants d’oiseaux : sifflements, gazouillis, trilles, babils et appels en mesure, d’un oiseau ou d’une volée."),
            ManualBlock(ManualKind.Bullet, "**Fathom** - l’eau et le temps qu’il fait : bulles, gouttes, pluie, ruisseaux, ressac, vent et feu, joués au clavier."),
            ManualBlock(ManualKind.Heading, "Batterie"),
            ManualBlock(ManualKind.Bullet, "**Hexbeat** - une batterie synthétisée à la manière des petites boîtes classiques."),
            ManualBlock(ManualKind.Bullet, "**Genesis** - la grosse boîte à rythmes, avec une grosse caisse qui fait plier son propre bus."),
            ManualBlock(ManualKind.Bullet, "**Forage** - une boîte à rythmes à échantillons avec treize pads pour vos propres sons, chacun avec un filtre et une enveloppe."),
            ManualBlock(ManualKind.Bullet, "**Dice** - un découpeur de boucles avec du hasard sur chaque tranche."),
            ManualBlock(ManualKind.Heading, "Échantillons et voix"),
            ManualBlock(ManualKind.Bullet, "**Pollen** - des nuages granulaires tirés d’un fichier ou de l’entrée en direct."),
            ManualBlock(ManualKind.Bullet, "**Mosaic** - un lecteur multi-échantillons pour les SoundFont et vos propres échantillons."),
            ManualBlock(ManualKind.Bullet, "**Molt** - chantez une prise et la grille de notes l’accorde."),
            ManualBlock(ManualKind.Bullet, "**Diction** - un synthé vocal entraîné sur votre voix et poussé plus loin."),
            ManualBlock(ManualKind.Bullet, "**Cipher** - un vocodeur."),
            ManualBlock(ManualKind.Heading, "Modulaire"),
            ManualBlock(ManualKind.Bullet, "**Nexus** - un synthé modulaire dont les modules sont les autres machines."),
            ManualBlock(ManualKind.Heading, "Audio"),
            ManualBlock(ManualKind.Bullet, "**Bias** - un quatre-pistes pour les enregistrements, avec quatre couloirs par cellule. Un enregistrement fait sur le morceau est coupé aux lignes de scène. Ses sons sont des types de bande (cassette, bobine, téléphone, etc.) qui colorent le son à la sortie."),
            ManualBlock(ManualKind.Heading, "Vélocité"),
            ManualBlock(ManualKind.Para, "Chaque machine joue moins fort quand vous jouez doucement. Une note à mi-vélocité est 12 dB plus bas, au quart elle est 24 dB plus bas, et les notes les plus douces sont presque muettes. **vél.** sur chaque panneau règle l’effet de la vélocité, et à zéro chaque note joue à plein volume, comme un vrai orgue. Sur Genesis, Resonance et Dice, **accent** fait le même travail."),
            ManualBlock(ManualKind.Para, "Si un contrôleur joue trop fort ou trop doucement, corrigez-le avec **vélocité** dans la fenêtre MIDI plutôt que sur chaque machine."),
            ManualBlock(ManualKind.Heading, "Sons"),
            ManualBlock(ManualKind.Para, "Chaque machine vient avec des sons, classés par famille. Le nom du son en haut du panneau ouvre le navigateur. Ajoutez vos propres sons dans le dernier onglet."),
        ), listOf(
            ManualSection("Aviary", "Chants d’oiseaux modélisés : un syrinx à deux voix, une gorge et un bec, qui chantent sifflements, gazouillis, trilles, babils et appels en mesure.", listOf(
                ManualBlock(ManualKind.Para, "Aviary ne joue pas d’enregistrements. Un oiseau chante par son syrinx, au fond de la poitrine : deux sources, une dans chaque branche des voies respiratoires, chacune une paire de replis qui se mettent à vibrer quand la pression de l’air passe un seuil, et dont l’amplitude dépend de combien on le dépasse. Les deux peuvent chanter ensemble : un seul oiseau peut chanter deux notes. Au-dessus viennent une courte trachée, une gorge que l’oiseau accorde sur la note qu’il chante, et le bec, ouvert plus grand pour les notes aiguës."),
                ManualBlock(ManualKind.Para, "Tenez une note et un oiseau chante autour d’elle, deux octaves plus haut, en mesure. Lâchez-la et il s’arrête."),
                ManualBlock(ManualKind.Heading, "Chant"),
                ManualBlock(ManualKind.Bullet, "**motif** : **sifflement** (une note tenue, rejointe en glissant), **gazouillis** (une syllabe qui glisse, puis un silence), **trille** (des syllabes brèves et rapides), **babil** (qui erre autour de la note), **appel** (deux notes à la tierce, le reste de la volée répondant dans les silences) ou **chœur** (chaque oiseau de la volée chante son propre chant à son propre rythme)."),
                ManualBlock(ManualKind.Bullet, "**accordage** : en cents."),
                ManualBlock(ManualKind.Bullet, "**vitesse** : syllabes par temps : **1**, **2**, **4**, **8** ou **16**."),
                ManualBlock(ManualKind.Bullet, "**longueur** : la part de chaque syllabe qui est chantée."),
                ManualBlock(ManualKind.Bullet, "**balayage** : de combien chaque syllabe glisse, en demi-tons : en descendant depuis le haut, ou en montant depuis le bas quand il est négatif."),
                ManualBlock(ManualKind.Heading, "Voix"),
                ManualBlock(ManualKind.Bullet, "**râpeux** : les replis qui claquent : plus âpre, avec plus d’harmoniques."),
                ManualBlock(ManualKind.Bullet, "**deux** : l’autre côté du syrinx qui chante en même temps."),
                ManualBlock(ManualKind.Bullet, "**intervalle** : de combien plus haut (ou plus bas) chante l’autre côté."),
                ManualBlock(ManualKind.Bullet, "**souffle** : de l’air dans le son."),
                ManualBlock(ManualKind.Bullet, "**gorge** : combien sonne la gorge accordée sur la note."),
                ManualBlock(ManualKind.Bullet, "**bec** : l’ouverture du bec : plus grande, c’est plus brillant."),
                ManualBlock(ManualKind.Heading, "Volée"),
                ManualBlock(ManualKind.Bullet, "**volée** : combien d’oiseaux chantent chaque note."),
                ManualBlock(ManualKind.Bullet, "**écart** : leur écartement de gauche à droite."),
                ManualBlock(ManualKind.Bullet, "**espace** : leur éloignement : plus doux et plus sourd."),
                ManualBlock(ManualKind.Bullet, "**vélocité**, **octave**, **bend** et **volume**."),
                ManualBlock(ManualKind.Para, "La pression souffle plus fort : plus fort et plus plein. La molette de modulation élargit les glissements."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Les motifs suivent le tempo : un gazouillis à **4** par temps tombe sur les doubles croches."),
                ManualBlock(ManualKind.Bullet, "**Call and Answer** demande au moins deux oiseaux : l’un appelle, l’autre répond."),
            )),
            ManualSection("Bias", "Un quatre-pistes : des enregistrements placés le long du morceau, quatre couloirs à la fois.", listOf(
                ManualBlock(ManualKind.Para, "Bias est la piste audio. Au lieu de notes, chacune de ses cellules joue des enregistrements, quatre couloirs à la fois. Rendez deux prises muettes pour choisir la troisième, ou réactivez un deuxième couloir pour doubler une voix."),
                ManualBlock(ManualKind.Heading, "Sa place dans le morceau"),
                ManualBlock(ManualKind.Para, "Une cellule Bias est un clip normal, alors il n’y a pas de ligne de temps à part. Une prise enregistrée sur quatre scènes devient quatre cellules qui pointent toutes vers le même fichier, chacune à partir d’un endroit différent. Rien n’est copié, et ça marche pareil dans l’arrangeur et dans le lanceur de clips."),
                ManualBlock(ManualKind.Para, "Une cellule dure ses mesures fois les répétitions de la scène et joue d’un trait, alors une scène jouée deux fois joue une seule prise continue."),
                ManualBlock(ManualKind.Heading, "Enregistrer"),
                ManualBlock(ManualKind.Para, "Touchez le point rouge à côté d’un couloir, armez l’enregistrement dans le transport et appuyez sur jouer. Le morceau joue pendant l’enregistrement, et les autres couloirs continuent de jouer.", "Cliquez le point rouge à côté d’un couloir, armez l’enregistrement dans le transport et appuyez sur jouer. Le morceau joue pendant l’enregistrement, et les autres couloirs continuent de jouer."),
                ManualBlock(ManualKind.Para, "À l’arrêt, la prise est coupée aux lignes de scène, une cellule par scène, avec de nouvelles cellules dans les scènes où la piste était vide. L’enregistrement complet reste aussi dans la bibliothèque de sons, alors vous pouvez annuler le découpage et le placer à la main."),
                ManualBlock(ManualKind.Para, "Un seul couloir enregistre à la fois. Si l’enregistreur a pris du retard et laissé un trou dans la prise, elle n’est pas découpée et reste entière."),
                ManualBlock(ManualKind.Heading, "L’éditeur"),
                ManualBlock(ManualKind.Para, "Ouvrir une cellule montre les quatre couloirs :"),
                ManualBlock(ManualKind.Bullet, "glissez le **corps** d’un couloir pour déplacer son début"),
                ManualBlock(ManualKind.Bullet, "glissez l’une ou l’autre **extrémité, moitié du haut** pour le rogner"),
                ManualBlock(ManualKind.Bullet, "glissez l’une ou l’autre **extrémité, moitié du bas** pour un fondu en entrée ou en sortie. Un couloir qui s’éteint pendant qu’un autre monte fait un fondu enchaîné"),
                ManualBlock(ManualKind.Bullet, "touchez le numéro à gauche pour rendre un couloir **muet**, et le point en dessous pour l’armer", "cliquez le numéro à gauche pour rendre un couloir **muet**, et le point en dessous pour l’armer"),
                ManualBlock(ManualKind.Para, "Sur une prise plus longue que sa cellule, les deux moitiés du bord droit rognent, pour vous laisser une extrémité où faire le fondu."),
                ManualBlock(ManualKind.Heading, "Niveaux, muets et automatisation"),
                ManualBlock(ManualKind.Para, "Le niveau et le muet de chaque couloir sont des paramètres de machine normaux, alors vous pouvez les automatiser, les assigner à un contrôleur et les enregistrer."),
                ManualBlock(ManualKind.Heading, "Tempo"),
                ManualBlock(ManualKind.Para, "**tempo › prises** choisit si une prise joue à la vitesse où elle a été enregistrée ou suit le tempo du morceau. Quand elle suit, elle est étirée sans changer de hauteur. Sinon, elle commence sur la mesure et joue à sa propre vitesse, et la cellule devient ambre."),
                ManualBlock(ManualKind.Para, "Une boucle ajoutée depuis la bibliothèque avec **audio…** voit son tempo calculé comme le fait Dice, d’après sa longueur et la place de ses coups. Elle boucle pour remplir la cellule, et si son tempo n’est pas celui de la scène, **tempo › prises** passe à suivre pour qu’elle joue au tempo du morceau."),
                ManualBlock(ManualKind.Heading, "Jouer de la guitare au travers"),
                ManualBlock(ManualKind.Para, "**retour**, sous **tempo**, envoie l’entrée à la sortie de cette piste avant ses effets, alors vous entendez un ampli dans la première insertion pendant que vous jouez. L’enregistrement reste sec, alors vous pouvez changer l’ampli plus tard."),
                ManualBlock(ManualKind.Para, "Le retour est éteint par défaut. Utilisez des écouteurs ou une interface, car sur le haut-parleur du téléphone il va faire du larsen."),
                ManualBlock(ManualKind.Para, "**imprimé**, à côté, sert aux effets que vous voulez enregistrer dans la prise. Ils passent avant l’enregistreur, alors ils y restent. Ce sont les deux mêmes emplacements d’entrée que montre la fenêtre d’enregistrement."),
                ManualBlock(ManualKind.Heading, "Aplatir"),
                ManualBlock(ManualKind.Para, "**comp** mélange les quatre couloirs (avec leurs niveaux, muets et fondus) en un seul fichier dans le couloir 1. La couleur de bande du son n’est pas incluse, et les enregistrements d’origine restent dans la bibliothèque."),
                ManualBlock(ManualKind.Heading, "Sons"),
                ManualBlock(ManualKind.Para, "Les sons de Bias sont des supports d’enregistrement (cassette, bobine, téléphone, cylindre de cire, etc.). Ils colorent le son à la lecture mais ne changent jamais les enregistrements, alors essayez-les sans crainte. **Init** rejoue le fichier tel quel."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Enregistrez d’abord et décidez plus tard. Le son, le tempo, les fondus et même le découpage peuvent tous changer après coup sans toucher au fichier.", "Enregistrez d’abord et décidez plus tard. Le son, le tempo, les fondus et même le découpage peuvent tous changer après coup sans cliquer au fichier."),
                ManualBlock(ManualKind.Bullet, "Les prises peuvent être longues. Tout ce qui dépasse deux minutes est converti une fois en arrière-plan et lu depuis le stockage, alors une voix complète coûte à peu près autant qu’une courte."),
            )),
            ManualSection("Brazen", "Des cuivres modélisés, de la trompette au tuba, ou tout un pupitre.", listOf(
                ManualBlock(ManualKind.Para, "Brazen est un modèle d’instrument de cuivre : des lèvres qui vibrent contre un tube terminé par un pavillon."),
                ManualBlock(ManualKind.Heading, "Souffler"),
                ManualBlock(ManualKind.Bullet, "**pression** - la force du souffle. C’est la commande principale, et ce n’est pas un bouton de volume. Trop peu et rien ne sonne, plus et la note part, plus encore et elle devient plus brillante jusqu’à l’octaviation."),
                ManualBlock(ManualKind.Bullet, "**souffle** - le bruit d’air."),
                ManualBlock(ManualKind.Bullet, "**mordant** et **tension** - la tension des lèvres. Avec la pression, ils décident sur quelle note du tube vous tombez, comme l’embouchure d’un vrai musicien."),
                ManualBlock(ManualKind.Bullet, "**amorti**, sous **lèvres** - l’amortissement des lèvres."),
                ManualBlock(ManualKind.Heading, "Le tube"),
                ManualBlock(ManualKind.Bullet, "**tuba→trp.** - la longueur du tube, du tuba à la trompette."),
                ManualBlock(ManualKind.Bullet, "**pavillon** - l’évasement du tube, qui change sa brillance."),
                ManualBlock(ManualKind.Bullet, "**perte** - l’énergie que le tube perd."),
                ManualBlock(ManualKind.Bullet, "**cuivré** - l’éclat des cuivres joués fort."),
                ManualBlock(ManualKind.Heading, "Un pupitre"),
                ManualBlock(ManualKind.Para, "**cohésion** et **dérive** changent un musicien en plusieurs qui jouent presque ensemble. **grogne** et sa **vitesse** ajoutent un grognement dans l’embouchure."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Les gros instruments demandent plus de pression. Un tuba se joue en soufflant fort."),
                ManualBlock(ManualKind.Bullet, "Automatisez la pression sur une note pour des crescendos. Ça change le timbre autant que le niveau."),
                ManualBlock(ManualKind.Bullet, "Partez d’un son et changez **tuba→trp.** d’abord."),
            )),
            ManualSection("Chanter", "Cornemuses et vielle à roue modélisées : des bourdons qui continuent entre les notes, des notes d’agrément, et une roue dont le chevalet libre grésille en rythme.", listOf(
                ManualBlock(ManualKind.Para, "Chanter ne joue pas d’enregistrements. Une cornemuse, ici, c’est un chalumeau, un tuyau conique à anche double (le même modèle que celui de Timber), et des bourdons, des tuyaux étroits à anche simple, tous soufflés depuis une poche. La poche garde la pression : les bourdons continuent entre les notes, et encore un moment après la dernière. On ne peut pas détacher les notes au chalumeau : les sonneurs les séparent par des notes d’agrément, une note aiguë et brève avant chacune."),
                ManualBlock(ManualKind.Para, "Une vielle à roue, c’est une roue enduite de colophane qui frotte ses cordes tant qu’elle tourne : les chanterelles, arrêtées par les touches, les bourdons accordés sur la tonalité, et la trompette, dont le chevalet (le chien) est libre : quand la roue tourne assez vite, il saute et grésille contre la table. Les vielleux poussent la roue sur le temps pour le faire grésiller en rythme."),
                ManualBlock(ManualKind.Heading, "Tuyaux"),
                ManualBlock(ManualKind.Bullet, "**modèle** : cornemuse **highland** (deux bourdons ténors sur la tonalité et un bourdon basse une octave plus bas), **smallpipes** (un chalumeau doux et fermé qui s’arrête un instant entre les notes, des bourdons sur la tonalité, la quinte et l’octave), **gaita** (un bourdon basse et un chalumeau doux) ou **vielle à roue**."),
                ManualBlock(ManualKind.Bullet, "**accordage** : en cents."),
                ManualBlock(ManualKind.Bullet, "**tonique** : la tonalité sur laquelle sont accordés les bourdons."),
                ManualBlock(ManualKind.Bullet, "**bourdons** : le volume des bourdons."),
                ManualBlock(ManualKind.Bullet, "**poche** : combien de secondes les bourdons continuent après qu’on a lâché la dernière touche. Sur la vielle, combien de temps la roue tourne encore."),
                ManualBlock(ManualKind.Bullet, "**anche** : une anche de chalumeau douce ou dure : plus sombre ou plus brillante."),
                ManualBlock(ManualKind.Bullet, "**agrément** : une note aiguë et brève avant chaque note, en millisecondes. À 0, aucune."),
                ManualBlock(ManualKind.Bullet, "**dérive** : combien la pression de la poche varie quand on la serre."),
                ManualBlock(ManualKind.Bullet, "**air** : le souffle dans les anches."),
                ManualBlock(ManualKind.Heading, "Vielle à roue"),
                ManualBlock(ManualKind.Bullet, "**manivelle** : la vitesse de la roue de la vielle. Plus vite, c’est plus fort."),
                ManualBlock(ManualKind.Bullet, "**colophane** : la prise de la colophane sur les cordes : lisse ou granuleuse."),
                ManualBlock(ManualKind.Bullet, "**chien** : le volume du grésillement de la trompette."),
                ManualBlock(ManualKind.Bullet, "**seuil** : à quelle vitesse la roue doit tourner pour que le chien grésille."),
                ManualBlock(ManualKind.Bullet, "**coup** : pousse la roue **1**, **2** ou **4** fois par temps, en mesure, pour que le chien grésille en rythme. **off** pour aucun."),
                ManualBlock(ManualKind.Bullet, "**vélocité**, **octave**, **bend** et **volume**."),
                ManualBlock(ManualKind.Para, "La pression, ou la molette de modulation, serre la poche (un peu plus fort et plus haut) ou pousse la roue de la vielle : le chien grésille à la main."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Les deux jouent une note à la fois : la dernière touche tenue sonne."),
                ManualBlock(ManualKind.Bullet, "Tenez une note sur une présélection **drones** puis lâchez : les bourdons continuent."),
                ManualBlock(ManualKind.Bullet, "Sur **Hurdy-Gurdy**, appuyez sur une touche ou poussez la molette pour faire grésiller le chien."),
            )),
            ManualSection("Cipher", "Un vocodeur où vous pouvez réarranger quelle bande commande quelle autre.", listOf(
                ManualBlock(ManualKind.Para, "Cipher est un vocodeur. Il découpe un son en bandes de fréquences et met cette forme sur un autre son. Vous pouvez aussi changer quelle bande commande laquelle, et c’est de là que viennent les sons inhabituels."),
                ManualBlock(ManualKind.Heading, "Les deux côtés"),
                ManualBlock(ManualKind.Para, "La **modulante** est le son analysé, en général une voix venant de l’entrée en direct. La **porteuse** est le son façonné. Cipher a sa propre porteuse intégrée (un oscillateur avec **désaccord**, **largeur**, **sub**, **bruit** et **satur.**), alors vous n’avez pas besoin d’une deuxième piste."),
                ManualBlock(ManualKind.Heading, "Les bandes"),
                ManualBlock(ManualKind.Bullet, "**bandes** - combien. Moins sonne robotique mais clair, et plus est plus doux mais moins clair."),
                ManualBlock(ManualKind.Bullet, "**grave**, **aigu** et **pente** - la plage couverte par les bandes et leur répartition."),
                ManualBlock(ManualKind.Bullet, "**largeur**, sous **banque** - l’étroitesse de chaque bande."),
                ManualBlock(ManualKind.Heading, "La carte des bandes"),
                ManualBlock(ManualKind.Para, "Normalement, la bande 1 commande la bande 1. **réassign.** change ça : inversez l’ordre pour que les sons brillants sortent sombres, étalez-la plus large, figez la forme actuelle avec **figer** pendant que la porteuse joue, ou fondez les bandes voisines ensemble avec **flou**."),
                ManualBlock(ManualKind.Para, "**l’entrée**, **sec** et **traité** règlent quel côté est lequel et combien vous entendez de chacun. **sourdes** s’occupe des consonnes pour que les mots restent clairs."),
                ManualBlock(ManualKind.Para, "**attaque**, **relâche** et **flou** règlent la vitesse à laquelle chaque bande suit. Rapide est clair mais peut crépiter, et lent est doux mais peut bafouiller."),
                ManualBlock(ManualKind.Heading, "Modulation"),
                ManualBlock(ManualKind.Para, "Deux enveloppes et deux LFO qui peuvent se synchroniser au tempo, vers huit rangées de matrice."),
                ManualBlock(ManualKind.Para, "Trois sources viennent de la modulante elle-même : son niveau (**fort**), sa brillance (**brillant**) et sa **hauteur** (la hauteur demande **suivre** activé). Par exemple, le niveau sur **flou** resserre les mots à mesure qu’ils deviennent plus forts."),
                ManualBlock(ManualKind.Para, "Les destinations sont les commandes de la carte (**décalage**, **étirer**, **réassign.**, **figer**, **flou**, **q** et les bords des bandes), plus la hauteur et le mélange de la porteuse."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Montez **sourdes** jusqu’à ce que les mots soient clairs, puis redescendez jusqu’à ce que ça arrête de siffler."),
                ManualBlock(ManualKind.Bullet, "Figez sur une voyelle et jouez des accords dessous pour une nappe vocale."),
                ManualBlock(ManualKind.Bullet, "Utilisez moins de bandes que vous pensez. Seize bat souvent quarante pour les mots."),
            )),
            ManualSection("Cumulus", "Des nappes bâties à partir d’un spectre de partiels.", listOf(
                ManualBlock(ManualKind.Para, "Cumulus n’utilise pas d’oscillateurs normaux. Vous décrivez un spectre (quels partiels, à quel volume, de quelle largeur), il en bâtit une table d’ondes et la joue. C’est pour les nappes, les bourdons et les sons immenses."),
                ManualBlock(ManualKind.Heading, "Comment ça marche"),
                ManualBlock(ManualKind.Para, "Chaque partiel a une largeur au lieu d’être une seule fréquence, ce qui le rend riche sans avoir besoin d’un chorus."),
                ManualBlock(ManualKind.Para, "Bâtir la table prend un moment, alors ça se fait en arrière-plan chaque fois que vous changez le spectre. Tout à partir de **morph** change tout de suite."),
                ManualBlock(ManualKind.Heading, "Commandes du spectre"),
                ManualBlock(ManualKind.Bullet, "**largeur** et **vers l’aigu**, sous **bande** - la largeur de chaque partiel, et si les aigus sont plus larges que les graves. C’est la commande principale."),
                ManualBlock(ManualKind.Bullet, "**pente** - l’équilibre entre graves et aigus."),
                ManualBlock(ManualKind.Bullet, "**étirer** - éloigne les partiels des multiples entiers, comme le haut d’un piano ou une cloche. Un peu suffit."),
                ManualBlock(ManualKind.Bullet, "**prof.** et **chaque**, sous **festons** - creusent des encoches régulières dans le spectre."),
                ManualBlock(ManualKind.Bullet, "**voyelle** et son intensité - donnent au spectre la forme d’une voyelle."),
                ManualBlock(ManualKind.Bullet, "**impair/pair** - les partiels impairs contre les pairs. Tout impair sonne comme une clarinette, et tout pair sonne creux."),
                ManualBlock(ManualKind.Bullet, "**graine** - les phases aléatoires. Changez-la pour une autre version du même son."),
                ManualBlock(ManualKind.Heading, "Commandes de jeu"),
                ManualBlock(ManualKind.Para, "**combien**, **désaccord** et **écart** empilent des copies, et **dérive**, sa **vitesse** et **épars** gardent le son en mouvement. Ensuite viennent un filtre avec sa propre enveloppe, une enveloppe d’ampli et une saturation."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Utilisez de longues attaques et de longs relâchements et laissez les notes se chevaucher."),
                ManualBlock(ManualKind.Bullet, "Bougez **morph** pendant que vous jouez plutôt que les commandes du spectre, car le morph change tout de suite."),
            )),
            ManualSection("Dice", "Un découpeur de boucles avec du hasard sur chaque tranche.", listOf(
                ManualBlock(ManualKind.Para, "Dice coupe une boucle en tranches et les rejoue, avec une chance que quelque chose de différent arrive sur chacune. C’est bon pour les breaks."),
                ManualBlock(ManualKind.Heading, "Découper"),
                ManualBlock(ManualKind.Para, "**combien** règle le nombre de morceaux, et **selon** règle où ils tombent, des divisions égales jusqu’aux coups de la boucle elle-même. Chaque tranche a ses propres **niveau**, **pano**, **hauteur**, **déclin** et **jeu**."),
                ManualBlock(ManualKind.Heading, "Les dés"),
                ManualBlock(ManualKind.Para, "Cinq chances, tirées sur chaque tranche :"),
                ManualBlock(ManualKind.Bullet, "**échanger** - jouer une autre tranche."),
                ManualBlock(ManualKind.Bullet, "**inverser** - la jouer à l’envers."),
                ManualBlock(ManualKind.Bullet, "**bégaie**, avec **fois** - en répéter une partie."),
                ManualBlock(ManualKind.Bullet, "**omettre** - ne rien jouer."),
                ManualBlock(ManualKind.Bullet, "**saut**, avec **jusqu’à** - sauter ailleurs dans la boucle et continuer."),
                ManualBlock(ManualKind.Para, "**graine** décide des tirages et **dés** sur **tenir** les fige. Montez les dés jusqu’à entendre quelque chose qui vous plaît, puis figez-le."),
                ManualBlock(ManualKind.Heading, "Jouer"),
                ManualBlock(ManualKind.Para, "Les tranches sont sur la grille comme des sons de batterie, alors vous pouvez réordonner la boucle en écrivant un motif. **vitesse**, **gate**, **hauteur**, **précis** et **accent** règlent la lecture, suivis d’un filtre et d’une saturation."),
                ManualBlock(ManualKind.Heading, "Tempo"),
                ManualBlock(ManualKind.Para, "**joue au** décide si la boucle garde son propre tempo ou suit le morceau. Sur **morceau**, le réglage par défaut, chaque tranche est étirée au tempo du morceau sans changer sa hauteur, alors un break à 90 bpm entre dans un morceau à 126 bpm sans trous. **hauteur** ne change alors que la hauteur, et **vitesse** l’accélère ou la ralentit encore."),
                ManualBlock(ManualKind.Para, "**mesures** est la longueur de la boucle, d’où son tempo est calculé. Sur **auto**, il est deviné d’après la longueur de la boucle et la place de ses coups, et la ligne sous le nom de la boucle dit ce qu’il a trouvé, comme « 2 mesures à 90 bpm ». Si c’est faux, réglez-le vous-même."),
                ManualBlock(ManualKind.Para, "Une tranche jouée à l’envers n’est pas étirée. Elle est accélérée ou ralentie comme une bande, alors elle se désaccorde un peu quand le morceau est loin du tempo de la boucle."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Non figé, Dice change à chaque mesure. Figé sur un bon tirage, il devient une partie."),
                ManualBlock(ManualKind.Bullet, "Pour un break qui swingue, coupez sur les coups plutôt qu’également."),
                ManualBlock(ManualKind.Bullet, "La graine le rend répétable, alors un export sonne comme ce que vous avez arrangé."),
            )),
            ManualSection("Diction", "Un synthé vocal entraîné sur votre voix et poussé plus loin.", listOf(
                ManualBlock(ManualKind.Para, "Diction chante. C’est un seul chanteur, alors il joue une note à la fois, et il glisse d’une note à l’autre pendant que vous les tenez. Donnez des paroles à ses notes et il les chante. Une note sans paroles chante la voyelle du bouton **voyelle**. Activez **harmonie** et il chante des accords, et **chanteurs** en fait un chœur."),
                ManualBlock(ManualKind.Heading, "Paroles"),
                ManualBlock(ManualKind.Para, "Ouvrez le couloir sous la grille et choisissez **paroles**. Touchez une note pour taper les paroles à partir de cette note, une syllabe par note :", "Ouvrez le couloir sous la grille et choisissez **paroles**. Cliquez une note pour taper les paroles à partir de cette note, une syllabe par note :"),
                ManualBlock(ManualKind.Bullet, "`hel-lo world` chante *hel* sur la première note, *lo* sur la suivante et *world* sur la troisième. Un trait d’union joint les syllabes en un seul mot, alors il est dit comme un seul mot."),
                ManualBlock(ManualKind.Bullet, "`-` seul tient la dernière voyelle sur une autre note."),
                ManualBlock(ManualKind.Bullet, "`_` est une note sans paroles."),
                ManualBlock(ManualKind.Bullet, "Mettez des sons entre crochets pour dire un mot à votre façon : `[t ah m ey t ow]`."),
                ManualBlock(ManualKind.Para, "Sous les paroles, on voit ce que chaque note va chanter, en sons. Si un mot sort mal, écrivez-le entre crochets."),
                ManualBlock(ManualKind.Para, "Pour mettre des paroles sur certaines notes seulement, sélectionnez-les d’abord et touchez l’une d’elles dans le couloir : la ligne va sur les notes sélectionnées, et les autres gardent les leurs. Chaque note montre aussi sa syllabe sur la grille de notes.", "Pour mettre des paroles sur certaines notes seulement, sélectionnez-les d’abord et cliquez l’une d’elles dans le couloir : la ligne va sur les notes sélectionnées, et les autres gardent les leurs. Chaque note montre aussi sa syllabe sur la grille de notes."),
                ManualBlock(ManualKind.Para, "Les consonnes avant la voyelle viennent au début de la note, et celles d’après quand la note finit."),
                ManualBlock(ManualKind.Para, "Un accord reçoit une syllabe, sur sa note du haut. Avec **harmonie** activé, le reste de l’accord la chante aussi."),
                ManualBlock(ManualKind.Heading, "La voix"),
                ManualBlock(ManualKind.Bullet, "**voix** - **intégrée**, ou une voix enregistrée dans l’onglet **voix** de la fenêtre **Son**. Une voix enregistrée chante avec la voix qui l’a chantée, avec ses consonnes aussi longues qu’elles ont été chantées."),
                ManualBlock(ManualKind.Bullet, "**voyelle** - oo, oh, ah, eh ou ee, du fond de la bouche vers l’avant. Entre deux, elle chante la voyelle qui est entre elles, alors tourner le bouton passe d’une voyelle à l’autre."),
                ManualBlock(ManualKind.Bullet, "**formant** - la taille de la gorge, sans changer la hauteur. Vers le bas, c’est plus grand et plus sombre, vers le haut, plus petit et plus brillant. Des notes graves avec le formant baissé sonnent comme un homme, des notes aiguës avec le formant monté comme une femme ou un enfant, et entre les deux, ni l’un ni l’autre."),
                ManualBlock(ManualKind.Bullet, "**piste** - bouge la gorge avec la hauteur. Vers le haut, les notes aiguës ont une gorge plus petite, et tout en haut, c’est un tamia une octave plus haut. Sous zéro, ça va dans l’autre sens."),
                ManualBlock(ManualKind.Bullet, "**source** et **gorge** - une voix enregistrée croisée avec la voix intégrée. **source** remplace les cordes vocales du chanteur par celles de la voix intégrée : la gorge du chanteur, chantée par un bourdonnement parfaitement stable. **gorge** remplace la gorge du chanteur par celle de la voix intégrée, qui suit les paroles. Les deux au maximum donnent la voix intégrée qui chante avec le rythme de la voix enregistrée. Les consonnes comme S et T restent celles du chanteur."),
                ManualBlock(ManualKind.Bullet, "**parler** - le son d’une autre piste articule les paroles, comme une talkbox. Jouez un synthé sur cette piste : les notes de Diction disent seulement quand les paroles arrivent, et ce que vous entendez est le synthé à sa propre hauteur, façonné en paroles par la gorge (la vôtre avec une voix enregistrée, ou celle de la voix intégrée avec **gorge** montée). Les S et les T viennent encore de Diction, alors les paroles sont plus claires qu’avec une vraie talkbox. Baissez le curseur de la piste du synthé pour n’entendre que la parole, Diction l’entend encore."),
                ManualBlock(ManualKind.Bullet, "**morph** - une deuxième voix enregistrée vers laquelle se transformer, et jusqu’où. La gorge passe de celle d’une voix à celle de l’autre, chantée par la première voix. Choisir une voix cible recharge la première voix, ce qui prend un moment."),
                ManualBlock(ManualKind.Bullet, "**consonnes** - la durée des consonnes."),
                ManualBlock(ManualKind.Bullet, "**niveau** - le volume des consonnes d’une voix enregistrée par rapport à ses voyelles."),
                ManualBlock(ManualKind.Bullet, "**depuis…** - de quelle prise d’une voix enregistrée chaque consonne est tirée : celle chantée entre des **ah**, des **ee** ou des **oo**, ou **mot**, celle dont la voyelle est la plus proche de celle du mot. Ah est en général la plus claire. La fenêtre a une page pour les occlusives, une pour les sifflantes et une pour les nasales et les glissantes."),
                ManualBlock(ManualKind.Bullet, "**accent** - la façon de dire les mots. **Prairies** est l’anglais canadien tel qu’on le parle en Alberta, **centre** l’anglais canadien de l’Ontario et **américain** l’anglais américain standard."),
                ManualBlock(ManualKind.Heading, "Caractère"),
                ManualBlock(ManualKind.Bullet, "**souffle** - la quantité d’air dans la voix. Pour une voix enregistrée, la part du souffle du chanteur qui est gardée : vers le bas, c’est net, tout en haut, c’est tel que chanté."),
                ManualBlock(ManualKind.Bullet, "**net** - enlève plus de souffle aux voyelles d’une voix enregistrée que **souffle** ne le peut. Tout en haut, une voyelle tenue sonne presque comme un instrument. Ça ne fait rien à la voix intégrée ni aux consonnes."),
                ManualBlock(ManualKind.Bullet, "**chuchoter** - chuchote les paroles au lieu de les chanter."),
                ManualBlock(ManualKind.Bullet, "**effort** - de doux à poussé. Vers le haut, c’est plus brillant et plus fort, vers le bas, plus doux."),
                ManualBlock(ManualKind.Bullet, "**râpeux** - une voix rauque."),
                ManualBlock(ManualKind.Bullet, "**grogne** - une impulsion sautée une fois sur deux : un crépitement au début, un grognement une octave plus bas tout en haut."),
                ManualBlock(ManualKind.Bullet, "**chanteurs** - combien chantent : un, ou un chœur jusqu’à six."),
                ManualBlock(ManualKind.Bullet, "**écart** - à quel point les chanteurs diffèrent. Vers le haut, ils sont plus en retard, plus désaccordés, avec leur propre gorge, et plus écartés."),
                ManualBlock(ManualKind.Bullet, "**harmonie** - désactivée, ou un accord chante les paroles sur chaque note. Tenez une note pendant que vous en jouez d’autres et elles s’y joignent, lâchez-en une et elle s’arrête."),
                ManualBlock(ManualKind.Heading, "Expression"),
                ManualBlock(ManualKind.Bullet, "**vibrato** - **prof.**, **vitesse** et **délai**. Un chanteur tient une note droite un moment avant que le vibrato arrive, et **délai** est cette durée. La molette de modulation en ajoute."),
                ManualBlock(ManualKind.Bullet, "**dérive** - l’instabilité de la voix. Elle varie un peu sur une note tenue et remonte en glissant vers une nouvelle."),
                ManualBlock(ManualKind.Bullet, "**porta.** - le temps pour glisser d’une note à la suivante."),
                ManualBlock(ManualKind.Bullet, "**scoop** - à quelle distance sous sa note chaque note commence, en plus de celle de la dérive. Sous zéro, chaque note tombe en place depuis le haut."),
                ManualBlock(ManualKind.Para, "Ensuite viennent **attaque**, **relâche** et **vélocité**, l’accord et le niveau."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Tenez une note pendant que vous jouez la suivante et il y glisse sans recommencer. Lâchez d’abord et il chante la nouvelle note à neuf."),
                ManualBlock(ManualKind.Bullet, "Lâchez une note pendant que vous en tenez une autre et il revient à celle encore tenue."),
                ManualBlock(ManualKind.Bullet, "Pour une voyelle différente sur chaque note, verrouillez **voyelle** sur les pas."),
            )),
            ManualSection("Draw", "Des anches libres modélisées : harmonicas, accordéons, melodica, harmonium et les anches qui sonnent dans des tuyaux.", listOf(
                ManualBlock(ManualKind.Para, "Draw ne joue pas d’enregistrements. Chaque note est une anche, une mince languette de métal dans une fente, mise en vibration par l’air qui la pousse. Elle démarre lentement, se pose sur sa note et s’arrête quand l’air s’arrête, comme une vraie anche. Soufflez plus fort et elle devient plus brillante et plus forte, alors que la hauteur bouge à peine."),
                ManualBlock(ManualKind.Para, "L’accordéon, l’harmonium, le melodica et les harmonicas ont été ajustés sur des enregistrements de vrais instruments, et le bandonéon sur le seul enregistrement qu’il y avait."),
                ManualBlock(ManualKind.Heading, "Anches"),
                ManualBlock(ManualKind.Bullet, "**modèle** - l’instrument. Les harmonicas (**diatonique**, **chromatique**, **tremolo**, **octave**), **accordéon**, **bandonéon**, **concertina**, **melodica**, **harmonium**, les anches dans des tuyaux (**sheng**, **shō**, **khaen**) et le **diapason**."),
                ManualBlock(ManualKind.Bullet, "**accordage** - en cents."),
                ManualBlock(ManualKind.Bullet, "**assise** - la distance entre chaque anche et sa fente au repos. Plus près, elle parle plus tôt et plus brillante, et s’étouffe plus tôt quand on souffle fort."),
                ManualBlock(ManualKind.Bullet, "**chambre** - la taille de l’espace derrière chaque anche. Elle change la façon dont l’anche démarre et la couleur de la note."),
                ManualBlock(ManualKind.Bullet, "**registre** - quelles anches chaque note fait sonner, comme les registres d’un accordéon. Ils sont nommés en pieds : 8′ sonne la note, 16′ une octave plus bas et 4′ une octave plus haut, et jusqu’à trois anches de 8′ peuvent sonner ensemble. **auto** est celui de l’instrument : deux 8′ sur un accordéon, 16′ et 8′ sur un bandonéon, 8′ et 4′ sur un harmonium, un seul 8′ sur les autres."),
                ManualBlock(ManualKind.Bullet, "**désaccord** - l’écart d’accord entre les anches de 8′ d’une note, en cents. À 0, elles s’accordent (sec), de 10 à 15, elles battent doucement (tremolo), à 25 et plus, elles battent vite (un musette mouillé). Avec trois, une est sur la note et les autres de chaque côté. Sur un harmonium, deux anches de 8′ un peu écartées font sa céleste."),
                ManualBlock(ManualKind.Bullet, "**cassotto** - les anches de 16′ et la première de 8′ parlent dans une chambre de résonance, qui les rend plus douces."),
                ManualBlock(ManualKind.Bullet, "**aigu**, **grave** - où sonnent les rangs de 4′ et de 16′ du registre, en demi-tons : une octave plus haut et plus bas au départ, ou n’importe quel intervalle, comme les jeux de mutation d’un orgue. Un 4′ déplacé à +7 donne à chaque note une quinte à vide, à +16 une dixième. Ils déplacent aussi les tuyaux supplémentaires du sheng et du khaen."),
                ManualBlock(ManualKind.Para, "Les anches ne s’accordent jamais tout à fait, alors une note sur deux ou trois anches bat, chaque harmonique à sa propre vitesse. C’est surtout ça qui fait qu’un accordéon sonne comme un accordéon."),
                ManualBlock(ManualKind.Heading, "Harmonicas"),
                ManualBlock(ManualKind.Para, "Un trou d’harmonica a deux anches, une pour souffler et une pour aspirer, avec votre bouche derrière. Draw modélise aussi la bouche : la position de la langue change la note, et c’est comme ça qu’un joueur fait un bend."),
                ManualBlock(ManualKind.Bullet, "**tonalité** - la tonalité de l’harmonica, de G à F♯. Un harmonica diatonique a toutes les notes de sa tonalité et peut atteindre la plupart des autres en bend."),
                ManualBlock(ManualKind.Bullet, "**jeu** - **joueur** place chaque note là où un joueur la trouverait sur l’harmonica : sur un trou tel quel, ou en bend vers le bas depuis le trou au-dessus. Les notes qu’un joueur ne peut pas atteindre en bend, dont les overblows, sonnent sur une anche à elles. **droite** joue chaque note sur une anche à elle, alors aucune n’est en bend."),
                ManualBlock(ManualKind.Para, "Sur l’harmonica chromatique, chaque anche est derrière une valve, alors chaque note a son anche à elle. Un harmonica tremolo fait sonner deux anches par note, écartées par **désaccord**, et un harmonica à octaves fait sonner la note et l’octave au-dessus."),
                ManualBlock(ManualKind.Para, "Un pitch-bend vers le bas sur un harmonica diatonique joué en **joueur** fait plier la note avec la langue, aussi loin que son trou le permet : beaucoup sur les trous 2 et 3, un peu sur les autres. Un bend vers le haut, ou sur les notes qui ne plient pas, déplace plutôt la note."),
                ManualBlock(ManualKind.Heading, "Tuyaux"),
                ManualBlock(ManualKind.Para, "Le sheng, le shō et le khaen font sonner chaque anche dans un tuyau de bambou, qui résonne avec elle et lui enlève la plus grande partie de son mordant : ils sont presque purs. Les anches du khaen s’entendent aussi dans sa chambre à vent, alors il bourdonne plus."),
                ManualBlock(ManualKind.Para, "Sur le shō, **jeu** réglé à **joueur** donne à chaque touche son accord (aitake) là où le shō en a un, à la hauteur propre au shō, accordé en quintes à partir de A : A, B, C, C♯, D, E, F♯, G, G♯ et le A aigu en ont chacun un. Les autres touches, et **droite**, jouent des tuyaux seuls. Ses tuyaux ne sont jamais limés tout à fait pareil, alors ses accords chatoient."),
                ManualBlock(ManualKind.Para, "Le registre marche aussi sur le sheng et le khaen : 4′ ajoute l’octave au-dessus."),
                ManualBlock(ManualKind.Heading, "Souffle"),
                ManualBlock(ManualKind.Bullet, "**pression** - la force du souffle dans les anches, de doux à fort. La vélocité et la pression de votre clavier soufflent encore plus fort."),
                ManualBlock(ManualKind.Bullet, "**attaque** - le temps que prend le souffle ou le soufflet pour monter, en ms."),
                ManualBlock(ManualKind.Bullet, "**relâche** - le temps qu’il prend pour s’arrêter, en ms."),
                ManualBlock(ManualKind.Bullet, "**air** - l’air que vous entendez : le souffle, et la turbulence de l’air dans chaque anche. Aucun souffle ni soufflet n’est tout à fait égal, et les anches varient un peu avec lui."),
                ManualBlock(ManualKind.Bullet, "**secousse** - le soufflet tiré et poussé, en tours par seconde, comme un accordéoniste qui le secoue. À chaque tour, le son baisse et l’autre jeu d’anches parle. Seulement sur l’accordéon, le bandonéon et le concertina."),
                ManualBlock(ManualKind.Bullet, "**sync** - fait plutôt tourner le soufflet sur la grille du morceau : noires, croches, triolets, doubles croches, etc., en mesure avec le morceau."),
                ManualBlock(ManualKind.Bullet, "**de la piste** - le son d’une autre piste souffle dans les anches : elles parlent aussi fort qu’elle joue et se taisent quand elle s’arrête. Tenez les notes et laissez l’autre piste les faire entrer."),
                ManualBlock(ManualKind.Para, "L’accordéon, le bandonéon, le concertina et l’harmonium partagent un seul soufflet, alors un gros accord baisse un peu sa pression."),
                ManualBlock(ManualKind.Para, "La pression ajoutée pendant qu’une note est tenue, par l’aftertouch ou une touche qui envoie la sienne, rend cette note plus forte et plus brillante."),
                ManualBlock(ManualKind.Heading, "Mains"),
                ManualBlock(ManualKind.Bullet, "**creux** - vos mains autour de l’harmonica, d’ouvertes à fermées. Fermées, c’est sombre et creux. La molette de modulation les ferme davantage, pour un wah."),
                ManualBlock(ManualKind.Bullet, "**vibrato** - un vibrato de gorge. Comme celui d’un joueur, il est surtout dans le niveau et aucun cycle n’est tout à fait pareil."),
                ManualBlock(ManualKind.Bullet, "**vitesse** - sa vitesse, en Hz."),
                ManualBlock(ManualKind.Bullet, "**paroles** - à quel point les paroles d’un clip façonnent un harmonica, comme le fait un joueur d’harmonica parlant. Tapez des paroles dans les notes comme pour Diction : les voyelles colorent le son et bougent la langue du joueur, alors une note qui peut plier plie avec elles, et m, b, p et w ferment les mains."),
                ManualBlock(ManualKind.Heading, "Sortie"),
                ManualBlock(ManualKind.Bullet, "**voix** - combien de notes à la fois, jusqu’à huit."),
                ManualBlock(ManualKind.Bullet, "**vélocité** - à quel point jouer plus fort souffle plus fort."),
                ManualBlock(ManualKind.Bullet, "**octave**, **bend** - l’octave, et l’amplitude du pitch-bend en demi-tons."),
                ManualBlock(ManualKind.Bullet, "**volume**."),
            )),
            ManualSection("Fathom", "L’eau et le temps qu’il fait, modélisés : bulles, gouttes, pluie, ruisseaux, ressac, vent et feu, joués au clavier.", listOf(
                ManualBlock(ManualKind.Para, "Fathom ne joue pas d’enregistrements. L’essentiel du son de l’eau, ce sont des bulles : une poche d’air prise sous la surface vibre comme un ressort, à une hauteur fixée par sa taille (plus elle est petite, plus elle est aiguë), et monte quand elle approche de la surface. Une goutte, c’est une bulle et le choc de la goutte ; la pluie, beaucoup de gouttes, et le son de ce sur quoi elles tombent ; un ruisseau, un nuage dense de petites bulles et quelques grosses. Le ressac, c’est le grondement d’une vague qui monte et retombe. Le vent, c’est de l’air qui file en rafales et siffle là où il se prend dans une fente ; le feu, des crépitements, un sifflement et un grondement."),
                ManualBlock(ManualKind.Para, "Tenez une note pour que ça continue. La note fixe la taille des bulles, ou la note que siffle le vent ; la vélocité, la quantité."),
                ManualBlock(ManualKind.Heading, "Eau"),
                ManualBlock(ManualKind.Bullet, "**modèle** : **bulles**, **gouttes**, **pluie**, **ruisseau**, **ressac**, **vent** ou **feu**."),
                ManualBlock(ManualKind.Bullet, "**accordage** : en cents."),
                ManualBlock(ManualKind.Bullet, "**densité** : combien de bulles, de gouttes ou de crépitements. À 0, il en vient une à chaque note : on peut jouer un air avec."),
                ManualBlock(ManualKind.Bullet, "**taille** : de combien la taille des bulles, et donc leur hauteur, s’écarte de la note, en demi-tons."),
                ManualBlock(ManualKind.Bullet, "**montée** : de combien monte une bulle en approchant de la surface."),
                ManualBlock(ManualKind.Bullet, "**déclin** : combien de temps sonne chaque bulle."),
                ManualBlock(ManualKind.Bullet, "**surface** : ce sur quoi tombe la pluie : **eau**, **feuilles**, **tôle** ou **vitre**."),
                ManualBlock(ManualKind.Heading, "Temps"),
                ManualBlock(ManualKind.Bullet, "**rafale** : combien le vent, le feu et les vagues vont et viennent."),
                ManualBlock(ManualKind.Bullet, "**sifflement** : le vent pris dans une fente, qui siffle sur la note."),
                ManualBlock(ManualKind.Bullet, "**ton** : plus sombre ou plus brillant."),
                ManualBlock(ManualKind.Bullet, "**houle** : combien de temps d’une vague à la suivante. Elle suit le tempo."),
                ManualBlock(ManualKind.Bullet, "**écart** : l’écartement des bulles et des gouttes, de gauche à droite."),
                ManualBlock(ManualKind.Bullet, "**fondu** : le temps qu’il faut pour arriver quand une note est tenue, et pour s’éteindre quand on la lâche."),
                ManualBlock(ManualKind.Bullet, "**vélocité**, **octave**, **bend** et **volume**."),
                ManualBlock(ManualKind.Para, "La pression, ou la molette de modulation, épaissit le tout."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "**Bubble Notes** et **Drip Notes** n’ont pas de densité : chaque note est une bulle ou une goutte accordée, pour jouer des mélodies."),
                ManualBlock(ManualKind.Bullet, "**Whistling Wind** joue la note tenue : essayez des accords lents."),
            )),
            ManualSection("Filament", "Des cordes modélisées : pincées, au médiator, frappées, frottées ou soufflées.", listOf(
                ManualBlock(ManualKind.Para, "Filament ne joue pas d’enregistrement. Il simule une corde qui vibre, alors il réagit comme une vraie."),
                ManualBlock(ManualKind.Heading, "L’excitateur"),
                ManualBlock(ManualKind.Para, "**excitateur** est ce qui met la corde en mouvement : pincer, médiator, marteau, archet, souffle ou **entrée**, l’entrée en direct, alors vous pouvez jouer une corde avec un micro."),
                ManualBlock(ManualKind.Bullet, "**où** - l’endroit de la corde où elle est excitée. C’est ce qui change le plus le timbre : près du bout, c’est mince et nasal, près du milieu, c’est rond."),
                ManualBlock(ManualKind.Bullet, "**dureté** - la dureté du marteau."),
                ManualBlock(ManualKind.Bullet, "**rugueux** et **longueur** - le bruit de l’excitation et sa durée."),
                ManualBlock(ManualKind.Heading, "La corde"),
                ManualBlock(ManualKind.Bullet, "**couplage**, **désaccord** et **écart** - deux cordes par note, un peu écartées, comme une douze-cordes ou le registre du milieu d’un piano."),
                ManualBlock(ManualKind.Bullet, "**étouffoir** - un feutre posé sur la corde à l’endroit de votre choix, bon pour les sons de guitare étouffés."),
                ManualBlock(ManualKind.Heading, "La caisse"),
                ManualBlock(ManualKind.Para, "Quatre résonances tiennent lieu de caisse de l’instrument. **taille** les déplace, **amortir** les élargit et **mélange** règle combien vous les entendez. Il y a aussi des **cordes** sympathiques, sous **sympathie**, qui résonnent avec ce que vous jouez."),
                ManualBlock(ManualKind.Heading, "Modulation"),
                ManualBlock(ManualKind.Para, "Deux enveloppes et deux LFO qui peuvent se synchroniser au tempo, vers huit rangées de matrice (source, destination, intensité)."),
                ManualBlock(ManualKind.Para, "Les enveloppes ne font rien tant que vous ne les routez pas. Une des sources est **anneau**, le niveau auquel la corde résonne en ce moment, alors la corde peut réagir à elle-même."),
                ManualBlock(ManualKind.Para, "Les destinations comprennent **maintien**, **ton**, **position**, **pression**, **étouffoir**, **tension** et **désaccord**. **brillant** change l’excitateur (le grain, ou la dureté d’un marteau), et **grésil** et **volume** agissent par note. **corps**, **satur.** et **sympathie** s’appliquent à tout l’instrument et suivent la dernière note."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Changez **où** en premier, avant le filtre ou la caisse."),
                ManualBlock(ManualKind.Bullet, "Un LFO lent sur **position** donne vie à un pincement statique."),
                ManualBlock(ManualKind.Bullet, "Si une note résonne trop longtemps, raccourcissez le déclin plutôt que de baisser les choses."),
            )),
            ManualSection("Forage", "Une boîte à rythmes à échantillons : treize pads pour vos propres sons.", listOf(
                ManualBlock(ManualKind.Para, "Forage joue vos propres échantillons sur treize pads, chacun avec un peu de traitement pour l’aider à trouver sa place."),
                ManualBlock(ManualKind.Heading, "Un pad"),
                ManualBlock(ManualKind.Bullet, "**niveau**, **pano**, **hauteur** et **déclin**."),
                ManualBlock(ManualKind.Bullet, "**début** et **fin** - la partie du fichier qui joue, alors un long enregistrement peut alimenter plusieurs pads."),
                ManualBlock(ManualKind.Bullet, "**jeu** - une fois, en boucle ou tenu."),
                ManualBlock(ManualKind.Bullet, "**inverser** - vers l’avant ou à l’envers."),
                ManualBlock(ManualKind.Bullet, "**coupure**, **rés.** et **mode** (passe-bas ou passe-bande), et **écraser** pour réduire les bits."),
                ManualBlock(ManualKind.Bullet, "**env hauteur** et son **déclin**, sous **punch** - une chute de hauteur, pour qu’un échantillon tombe comme le fait un tambour."),
                ManualBlock(ManualKind.Bullet, "**étouffe** - les pads d’un même groupe d’étouffement se coupent entre eux, comme un charleston ouvert qui s’arrête quand le fermé joue."),
                ManualBlock(ManualKind.Heading, "Découper un seul fichier"),
                ManualBlock(ManualKind.Para, "Il y a un quatorzième emplacement au-dessus des pads pour un fichier partagé par toute la machine. Chargez-y un break, demandez treize tranches et chaque pad en joue un morceau."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Mettez vos charlestons dans un groupe d’étouffement."),
                ManualBlock(ManualKind.Bullet, "Coupez le silence au début d’un échantillon, sinon il jouera en retard."),
                ManualBlock(ManualKind.Bullet, "Automatisez **début** sur une mesure pour changer un coup en bégaiement."),
                ManualBlock(ManualKind.Bullet, "La bibliothèque de sons vous avertit avant de supprimer un fichier qu’une piste utilise encore."),
            )),
            ManualSection("Formulate", "Un synthé 8 bits, et une forme d’onde que vous tapez comme une formule.", listOf(
                ManualBlock(ManualKind.Para, "Formulate est un synthé de puce sonore avec impulsion, triangle et bruit, comme les vieilles consoles de jeu. Il peut aussi jouer une forme d’onde que vous écrivez comme une formule."),
                ManualBlock(ManualKind.Heading, "La puce"),
                ManualBlock(ManualKind.Bullet, "**onde** - impulsion, triangle, bruit ou la formule."),
                ManualBlock(ManualKind.Bullet, "**rapport** - la largeur d’impulsion. **pwm** et sa **vitesse** la balaient."),
                ManualBlock(ManualKind.Bullet, "**sous-oct.** - ajoute une octave en dessous."),
                ManualBlock(ManualKind.Bullet, "**bruit** - fait passer le bruit d’un souffle à un bourdonnement métallique."),
                ManualBlock(ManualKind.Bullet, "**bits**, **fréq. éch.** et **lisse** - la résolution, la fréquence d’échantillonnage et à quel point les marches sont adoucies."),
                ManualBlock(ManualKind.Heading, "Tables de tracker"),
                ManualBlock(ManualKind.Para, "Il y en a trois, **arpège**, **rapport cyclique** et **volume**, tapées en texte et parcourues à chaque tick comme un instrument de tracker. Une table d’arpège `0 4 7` jouée vite fait un accord avec une seule voix."),
                ManualBlock(ManualKind.Heading, "La formule"),
                ManualBlock(ManualKind.Para, "**formule** est une expression où **x** va de 0 à 1 sur un cycle de l’onde. `sin(x*2*pi)` est un sinus, `x*2-1` est une dent de scie et `(x<0.3)?1:-1` est une impulsion à 30 % de rapport cyclique."),
                ManualBlock(ManualKind.Para, "**contre x** choisit si la formule est calculée une fois par cycle ou à chaque échantillon. Les trois boutons macro **a**, **b** et **c** peuvent être utilisés par leur nom dans la formule, alors vous pouvez lui donner des commandes. Si une formule a une erreur, le panneau vous le dit."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Utilisez une macro dans la formule et automatisez-la. `sin(x*2*pi*a)` avec **a** sur un couloir balaie le timbre."),
                ManualBlock(ManualKind.Bullet, "Les tables de tracker changent beaucoup de choses. Un son simple avec une bonne table de volume bat souvent une formule astucieuse sans table."),
            )),
            ManualSection("Fret", "Guitares et basses électriques modélisées : des cordes, des micros, les mains du musicien et un ampli assez fort pour larsener.", listOf(
                ManualBlock(ManualKind.Para, "Fret ne joue pas d’enregistrements. Chaque note est une corde, pincée au médiator, au doigt ou claquée du pouce, et entendue comme une guitare électrique l’entend : pas dans l’air, mais par un aimant posé sous la corde. Un micro entend la corde là où il se trouve. Près du manche, il entend une note ronde et pleine ; près du chevalet, une note fine et brillante ; et au quart de la longueur, il n’entend plus du tout le 4e harmonique."),
                ManualBlock(ManualKind.Heading, "Guitare"),
                ManualBlock(ManualKind.Bullet, "**modèle** : **guitare**, **12 cordes** (les quatre chœurs graves avec une corde à l’octave, les deux aigus doublés), **baryton** (un manche plus long, accordé plus bas), **basse** et basse **5 cordes**."),
                ManualBlock(ManualKind.Bullet, "**accordage** : en cents."),
                ManualBlock(ManualKind.Bullet, "**capteur** : **manche**, **les deux** ou **chevalet**."),
                ManualBlock(ManualKind.Bullet, "**bobine** : **simple** (brillante et claire) ou **double bobinage** (deux bobines côte à côte : plus épais et plus sombre)."),
                ManualBlock(ManualKind.Bullet, "**ton** : le bouton de tonalité de la guitare : la résonance de la bobine baisse quand vous le tournez vers le bas."),
                ManualBlock(ManualKind.Bullet, "**maintien** : combien de temps les cordes résonnent."),
                ManualBlock(ManualKind.Bullet, "**brillant** : combien de temps elles gardent leurs aigus."),
                ManualBlock(ManualKind.Heading, "Mains"),
                ManualBlock(ManualKind.Bullet, "**attaque** : **médiator**, **doigt** ou **slap** (le pouce qui fait claquer la corde contre les frettes)."),
                ManualBlock(ManualKind.Bullet, "**dureté** : un médiator ou un doigt doux ou dur."),
                ManualBlock(ManualKind.Bullet, "**position** : où la corde est attaquée : près du chevalet c’est fin, plus loin c’est plus chaud."),
                ManualBlock(ManualKind.Bullet, "**sourdine** : la paume posée sur les cordes près du chevalet. La molette de modulation fait de même, pour étouffer en jouant."),
                ManualBlock(ManualKind.Bullet, "**harmonique** : un doigt qui effleure la **12**e, la **7**e ou la **5**e frette, pour une harmonique cristalline à l’octave, à la douzième ou à deux octaves."),
                ManualBlock(ManualKind.Bullet, "**buzz** : laisse les cordes frapper les frettes quand on joue fort."),
                ManualBlock(ManualKind.Bullet, "**glissé** : avec une seule voix, une nouvelle note glisse depuis la précédente au lieu d’être attaquée de nouveau."),
                ManualBlock(ManualKind.Bullet, "**vibrato** : un doigt qui balance sur la corde. La pression en ajoute."),
                ManualBlock(ManualKind.Bullet, "**gratter** : joue un accord à travers les cordes, avec ce nombre de millisecondes entre chaque corde, au lieu de tout à la fois."),
                ManualBlock(ManualKind.Bullet, "**sens** : gratter vers le **bas** (corde grave d’abord), vers le **haut**, ou **les deux** à tour de rôle."),
                ManualBlock(ManualKind.Heading, "Ampli"),
                ManualBlock(ManualKind.Bullet, "**satur.** : l’ampli, du son clair au son poussé à fond, avec un haut-parleur qui entre en jeu à mesure."),
                ManualBlock(ManualKind.Bullet, "**réinjection** : combien le son de l’ampli fait vibrer les cordes en retour. Avec de la saturation, une note tenue se maintient et peut sauter à une harmonique."),
                ManualBlock(ManualKind.Bullet, "**voix**, **vélocité**, **octave**, **bend** et **volume**."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "**Chug** et **Funk** utilisent la **sourdine** ; bougez la molette de modulation en jouant pour ouvrir les notes."),
                ManualBlock(ManualKind.Bullet, "**Singing Lead** et **Feedback Swell** demandent des notes tenues : laissez-les sonner et l’ampli prend le relais."),
                ManualBlock(ManualKind.Bullet, "Pour des accords grattés, jouez toutes les notes ensemble et laissez **gratter** les étaler."),
                ManualBlock(ManualKind.Bullet, "Passez Fret dans l’effet **Amp** pour un ampli et un baffle plus gros que le sien."),
            )),
            ManualSection("Genesis", "La grosse boîte à rythmes, avec un compresseur de bus que la grosse caisse fait plier.", listOf(
                ManualBlock(ManualKind.Para, "Genesis est la grosse boîte à rythmes, dans le style des boîtes qui ont servi à faire la house et la techno. Elle a douze voix, plus de poids que Hexbeat et deux extras."),
                ManualBlock(ManualKind.Heading, "La dérive"),
                ManualBlock(ManualKind.Para, "Les vraies boîtes à rythmes analogiques ne sonnent jamais deux fois pareil, et **dérive** ajoute un peu de cette variation d’un coup à l’autre."),
                ManualBlock(ManualKind.Heading, "Le compresseur de bus"),
                ManualBlock(ManualKind.Para, "Tout le kit passe dans un compresseur (**compr.**, **attaque**, **relâche**), et **g. c. atténue** laisse la grosse caisse baisser le reste du kit, qui pompe alors avec elle."),
                ManualBlock(ManualKind.Heading, "Le kit"),
                ManualBlock(ManualKind.Bullet, "**g. caisse** - accord, déclin, niveau, **balayage** (la longue chute de hauteur), **punch**, **clic** (l’attaque) et **satur.**"),
                ManualBlock(ManualKind.Bullet, "**c. claire**, **clap** (avec écart et ton) et **cercle**."),
                ManualBlock(ManualKind.Bullet, "**toms**, et **charl.** avec ton et accord partagés et des déclins séparés pour ouvert et fermé."),
                ManualBlock(ManualKind.Bullet, "**crash** et **ride**, avec une **cloche** sur la ride."),
                ManualBlock(ManualKind.Bullet, "**cloche** (la cloche à vache)."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Réglez **g. c. atténue** avant les niveaux, puisqu’il change le volume apparent de tout le reste."),
                ManualBlock(ManualKind.Bullet, "Si la grosse caisse disparaît sur un haut-parleur de téléphone, ajoutez de la **satur.** à la grosse caisse plutôt que du niveau."),
                ManualBlock(ManualKind.Bullet, "Gardez la dérive basse : assez pour que les mesures diffèrent, sans que les charleys sonnent brisés."),
            )),
            ManualSection("Hammer", "Des pianos modélisés et leurs cousins : des marteaux qui frappent des cordes et des barres, entendus par une table d’harmonie ou des capteurs.", listOf(
                ManualBlock(ManualKind.Para, "Hammer ne joue pas d’enregistrements. Un marteau de feutre est lancé sur de vraies cordes qui résonnent par une table d’harmonie, et il se joue donc comme un piano : plus fort, c’est plus brillant en plus d’être plus fort, les notes graves résonnent longtemps, et les cordes d’une même touche battent entre elles en s’éteignant."),
                ManualBlock(ManualKind.Para, "Chaque touche a été mesurée sur un enregistrement de piano de concert, et **Init** est ce piano."),
                ManualBlock(ManualKind.Heading, "L’instrument"),
                ManualBlock(ManualKind.Para, "**modèle** choisit l’instrument :"),
                ManualBlock(ManualKind.Bullet, "**à queue** - un piano de concert, tel que mesuré."),
                ManualBlock(ManualKind.Bullet, "**droit** - des cordes plus courtes et une table plus petite : moins de basses, plus de médium, et des notes qui meurent plus tôt."),
                ManualBlock(ManualKind.Bullet, "**honky-tonk** - un vieux piano droit avec les cordes de chaque touche désaccordées entre elles."),
                ManualBlock(ManualKind.Bullet, "**fortepiano** - un piano des environs de 1800 : de légers marteaux de cuir, des cordes fines, un son vif et clair avec un petit choc dedans."),
                ManualBlock(ManualKind.Bullet, "**à queue élec.** - des cordes courtes entendues par des capteurs plutôt que par une table."),
                ManualBlock(ManualKind.Bullet, "**tige** - un marteau frappe une fine tige de métal à côté d’une barre accordée, et un capteur l’entend : une cloche par-dessus, une longue note chaude, un grognement quand vous appuyez fort."),
                ManualBlock(ManualKind.Bullet, "**anche** - une anche d’acier et un capteur qui l’entend plus d’un côté que de l’autre : plus nasillard, plus vite éteint, un grondement joué fort."),
                ManualBlock(ManualKind.Bullet, "**tangente** - une tangente de métal frappe une corde et y reste tant que la touche est enfoncée. Relâchez et la note s’arrête net. Deux capteurs sous les cordes."),
                ManualBlock(ManualKind.Bullet, "**célesta** - des marteaux de feutre sur des barres d’acier, chacune au-dessus d’une petite boîte de bois : une cloche douce, avec des étouffoirs et une pédale."),
                ManualBlock(ManualKind.Bullet, "**jouet** - de petits marteaux durs sur des tiges de métal dans une boîte de plastique : métallique, court, jamais tout à fait juste (la graine choisit comment), sans étouffoirs."),
                ManualBlock(ManualKind.Bullet, "**tympanon** - de légers marteaux de bois sur des chœurs de cordes fines, sans aucun étouffoir, et tout résonne dans tout."),
                ManualBlock(ManualKind.Bullet, "**cymbalum** - un gros tympanon : des cordes plus lourdes, des marteaux doux, et une pédale d’étouffoirs."),
                ManualBlock(ManualKind.Para, "**taille** va du petit piano à queue au piano de concert : un plus petit a des basses plus minces et plus raides. **âge** use le piano. Les marteaux durcissent, les cordes résonnent moins longtemps et plus sombre, et les touches se désaccordent. **graine** choisit dans quel sens dérive chaque touche."),
                ManualBlock(ManualKind.Heading, "Le marteau"),
                ManualBlock(ManualKind.Bullet, "**dureté** - un feutre plus doux est plus sombre et plus rond, un plus dur est plus brillant. **par touche** rend le haut plus dur et le bas plus doux, ou l’inverse."),
                ManualBlock(ManualKind.Bullet, "**poids** - un marteau plus lourd reste plus longtemps sur les cordes, ce qui est plus sombre."),
                ManualBlock(ManualKind.Bullet, "**frappe à** - l’endroit de la corde où tombe le marteau. Monté, il tombe plus loin du bout, ce qui est plus rond. Baissé, c’est plus mince et plus brillant."),
                ManualBlock(ManualKind.Bullet, "**vélocité** - à quel point la force de votre jeu change le volume d’une note. Le coup suit toujours votre jeu : une note douce reste plus sombre."),
                ManualBlock(ManualKind.Bullet, "**punaises** - des punaises de métal enfoncées dans le feutre : chaque note dure et brillante, si doucement que vous jouiez. Un piano à punaises."),
                ManualBlock(ManualKind.Bullet, "**modérateur** - une bande de feutre entre les marteaux et les cordes : doux et étouffé."),
                ManualBlock(ManualKind.Heading, "Les cordes"),
                ManualBlock(ManualKind.Bullet, "**maintien** - combien de temps les cordes résonnent. **par touche** fait résonner le haut plus longtemps et le bas moins, ou l’inverse."),
                ManualBlock(ManualKind.Bullet, "**ton** - à quelle vitesse le haut du son meurt par rapport au reste. Baissé, c’est un piano qui s’assombrit en résonnant, monté le garde brillant. **par touche** l’incline sur le clavier, comme pour le maintien."),
                ManualBlock(ManualKind.Bullet, "**raideur** - la raideur des cordes. Des cordes raides placent leurs partiels aigus un peu trop haut, et c’est surtout ce qui fait qu’un piano sonne comme un piano. **étirer** est à quel point l’accordage suit cela, comme un accordeur étire les octaves."),
                ManualBlock(ManualKind.Bullet, "**cordes** - combien de cordes a chaque touche. **auto** est celui d’un piano à queue : une dans les notes les plus graves, puis deux, puis trois."),
                ManualBlock(ManualKind.Bullet, "**unisson** - à quel point les cordes d’une touche sont désaccordées entre elles. Un peu donne la longue résonance lente, plus donne un honky-tonk."),
                ManualBlock(ManualKind.Bullet, "**couplage** - à quel point les cordes se parlent par le chevalet."),
                ManualBlock(ManualKind.Bullet, "**travers** - à quel point les cordes bougent en travers de la table en plus de vers elle, ce qui garde une note sonnante après la première chute rapide."),
                ManualBlock(ManualKind.Heading, "Les pédales"),
                ManualBlock(ManualKind.Para, "**étouffoirs** est la fermeté avec laquelle le feutre arrête une note quand vous lâchez la touche, et **temps** la durée que ça prend. Les touches du haut n’ont pas d’étouffoirs, comme sur un piano, et continuent de sonner."),
                ManualBlock(ManualKind.Para, "La pédale de maintien lève les étouffoirs, et Hammer la suit en partie : une demi-pédale les laisse toucher les cordes, ce qui enlève le haut d’une note et laisse sonner le reste. **lève à** est la profondeur où les étouffoirs commencent à quitter les cordes, et **étendue** combien plus loin ils en sont dégagés.", "La pédale de maintien lève les étouffoirs, et Hammer la suit en partie : une demi-pédale les laisse cliquer les cordes, ce qui enlève le haut d’une note et laisse sonner le reste. **lève à** est la profondeur où les étouffoirs commencent à quitter les cordes, et **étendue** combien plus loin ils en sont dégagés."),
                ManualBlock(ManualKind.Para, "Pédale enfoncée, les cordes que vous n’avez pas jouées résonnent avec celles que vous avez jouées, à une octave ou une quinte. **sympathie** en règle la quantité. **bruits** est le choc des étouffoirs qui quittent les cordes et y retombent."),
                ManualBlock(ManualKind.Para, "La pédale douce est **una corda** : le marteau glisse pour manquer une corde et frappe les autres avec un feutre plus doux, et la note est plus faible et plus sombre. Le bouton règle de combien. Sur un piano droit, les marteaux se rapprochent plutôt des cordes, et frappent plus doucement."),
                ManualBlock(ManualKind.Heading, "Le son"),
                ManualBlock(ManualKind.Para, "**table** est le volume du choc de la table d’harmonie sous chaque note. **capot** ouvert est brillant, fermé enlève le haut. **salle** est la part de la pièce que vous entendez."),
                ManualBlock(ManualKind.Para, "**mic** est l’endroit d’où vous écoutez :"),
                ManualBlock(ManualKind.Bullet, "**joueur** - au clavier, les basses à gauche."),
                ManualBlock(ManualKind.Bullet, "**public** - devant le piano, à l’inverse et plus étroit."),
                ManualBlock(ManualKind.Bullet, "**proche** - dans le piano, large et brillant."),
                ManualBlock(ManualKind.Bullet, "**salle** - de l’autre bout de la pièce."),
                ManualBlock(ManualKind.Para, "**largeur** est la largeur de l’étalement du clavier."),
                ManualBlock(ManualKind.Heading, "Préparer"),
                ManualBlock(ManualKind.Para, "Des objets posés sur les cordes, comme sur un piano préparé."),
                ManualBlock(ManualKind.Bullet, "**quoi** - du **caoutchouc** coincé entre les cordes étouffe presque toute la note et laisse une résonance terne. Une **vis** désaccorde les partiels, comme une cloche. Un **boulon** cliquette. Le **papier** grésille. **mélangé** met un objet différent sur chaque touche."),
                ManualBlock(ManualKind.Bullet, "**touches** - quelles touches : toutes, les blanches ou les noires, la moitié grave ou aiguë, ou certaines de chaque au hasard (la graine choisit)."),
                ManualBlock(ManualKind.Bullet, "**où** - à quelle distance le long de la corde. Près du bout, ça change moins."),
                ManualBlock(ManualKind.Bullet, "**intensité** - à quel point c’est lourd, lâche, présent."),
                ManualBlock(ManualKind.Heading, "L’électrique"),
                ManualBlock(ManualKind.Para, "Pour les modèles tige, anche et tangente."),
                ManualBlock(ManualKind.Bullet, "**proche** - la distance du capteur. Plus près, ça grogne plus tôt."),
                ManualBlock(ManualKind.Bullet, "**décalage** - à quel point la tige est décentrée par rapport au capteur. Près du centre, elle sonne une octave plus haut et creux. Plus loin, c’est la note, plus pure."),
                ManualBlock(ManualKind.Bullet, "**barre ton.** - la part de la note d’une tige que retient sa barre de ton : plus, c’est plus long et plus doux, moins, c’est plus de cloche."),
                ManualBlock(ManualKind.Bullet, "**capteurs** - quels capteurs de la tangente vous entendez : celui du **chevalet** (brillant), celui du **manche** (plus plein), **les deux**, ou les deux **opposés** l’un à l’autre (mince et creux). **sourdine** est une bande de feutre sur les cordes : court et pincé."),
                ManualBlock(ManualKind.Bullet, "**satur.** - l’ampli, du net au rugueux."),
                ManualBlock(ManualKind.Bullet, "**prof.**, **vitesse** et **pano** forment le trémolo. **sync** le cale sur le tempo. Avec **pano** au maximum, il balance d’un côté à l’autre plutôt que de haut en bas. La molette de modulation fait entrer le trémolo."),
                ManualBlock(ManualKind.Heading, "La sortie"),
                ManualBlock(ManualKind.Para, "**volume** et **pano**, et l’accordage : **bend**, **octave**, **transposer** et **précis**."),
                ManualBlock(ManualKind.Para, "**voix** est le nombre maximal de notes qui sonnent à la fois. **détail** sur **auto** suit le réglage de qualité, et un téléphone plus lent joue un piano plus léger. **complet** joue toujours le modèle entier."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "La couleur d’un piano vient surtout du marteau. Essayez **dureté** avant tout le reste."),
                ManualBlock(ManualKind.Bullet, "Pour un piano plus vieux, montez **âge**, ou baissez **ton** et montez un peu **unisson**."),
                ManualBlock(ManualKind.Bullet, "Tenez la pédale de maintien et jouez dans le grave : les cordes résonnent les unes dans les autres."),
                ManualBlock(ManualKind.Bullet, "Pour un piano à tiges qui grogne, montez **proche** et jouez fort."),
            )),
            ManualSection("Hexbeat", "Des percussions synthétisées dans le style des petites boîtes classiques, avec un plus grand kit.", listOf(
                ManualBlock(ManualKind.Para, "Hexbeat fait ses percussions par synthèse plutôt qu’avec des échantillons. Il a treize voix dans le style des petites boîtes à rythmes classiques, percutantes, sèches et faciles à placer dans un mixage."),
                ManualBlock(ManualKind.Heading, "Le kit"),
                ManualBlock(ManualKind.Para, "Grosse caisse, cercle, caisse claire, clap, trois toms, charley fermé et ouvert, crash, ride, cloche et claves."),
                ManualBlock(ManualKind.Heading, "Les commandes"),
                ManualBlock(ManualKind.Para, "Chaque voix a un **niveau**, et la plupart ont **accordage** et **déclin**, plus quelques commandes à elles :"),
                ManualBlock(ManualKind.Bullet, "**g. caisse** - accord, déclin et **punch** (la chute de hauteur au début)."),
                ManualBlock(ManualKind.Bullet, "**c. claire** - accord, déclin, ton et **timbre** (le fût contre le bruit)."),
                ManualBlock(ManualKind.Bullet, "**charl.** - ton et accord partagés, et des déclins séparés pour fermé et ouvert."),
                ManualBlock(ManualKind.Bullet, "**clap** - déclin, ton et l’écart des petites répétitions qui en font un clap."),
                ManualBlock(ManualKind.Bullet, "**cymbales** - déclin et ton pour le crash et la ride."),
                ManualBlock(ManualKind.Bullet, "**cloche** et **claves** - accord et niveau."),
                ManualBlock(ManualKind.Para, "**accent** est ce qu’un coup fort ajoute à tout le kit, et **vél.** est la part de la vélocité dans le niveau de chaque coup."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Il s’ouvre sur la grille de percussions, la meilleure façon de l’éditer."),
                ManualBlock(ManualKind.Bullet, "Changer les déclins rend vite un motif plus serré ou plus ample."),
                ManualBlock(ManualKind.Bullet, "Essayez une probabilité sur les charleys et un ratchet sur la caisse claire pour que la boucle ne se répète pas à l’identique."),
                ManualBlock(ManualKind.Bullet, "Pour des percussions faites de vos propres échantillons, voyez Forage, et pour un kit plus gros et plus lourd, voyez Genesis."),
            )),
            ManualSection("Manual", "L’orgue : deux claviers et un pédalier, quatre modèles et un baffle rotatif.", listOf(
                ManualBlock(ManualKind.Para, "Manual est un orgue à deux claviers et un pédalier. Ils partagent tous un même jeu de 91 roues phoniques, comme le vrai : la même roue joue la quinte d’une note et l’octave d’une autre, et c’est pourquoi les accords d’orgue scintillent et battent un peu."),
                ManualBlock(ManualKind.Heading, "Les tirettes"),
                ManualBlock(ManualKind.Para, "Neuf par clavier, et elles font l’essentiel du son. Chacune ajoute une harmonique de la note, aussi fort que vous la tirez."),
                ManualBlock(ManualKind.Heading, "Les quatre modèles"),
                ManualBlock(ManualKind.Para, "**modèle** choisit le genre d’orgue :"),
                ManualBlock(ManualKind.Bullet, "**combo** - un orgue à transistors, bourdonnant, avec sa propre attaque."),
                ManualBlock(ManualKind.Bullet, "**molette** - l’orgue à roues phoniques classique, avec **fuite** (les roues qui débordent l’une sur l’autre), **ronfl.** et **âge**."),
                ManualBlock(ManualKind.Bullet, "**anche** - un harmonium, avec **pression**, **buzz** et un trémolo."),
                ManualBlock(ManualKind.Bullet, "**tuyau** - un orgue à tuyaux avec les jeux **principal**, **flûte**, **corde**, **anche** et **fourniture**, du **chiff** sur l’attaque et le bruit de la **mécanique**."),
                ManualBlock(ManualKind.Para, "La fuite, le ronflement et le bruit de soufflerie entrent en fondu quand l’orgue commence à jouer et sortent environ une demi-seconde après qu’il s’arrête : une piste qui ne joue pas dans une scène y reste muette."),
                ManualBlock(ManualKind.Heading, "Le clic des touches"),
                ManualBlock(ManualKind.Para, "Sur un vrai orgue à roues phoniques, les contacts des touches se ferment l’un après l’autre, et chaque note commence par une petite rafale de clics. Dans le groupe **clic**, **oui** règle son volume, **non** est le clic quand vous relâchez et **écart** étale les contacts. Sans le clic, ça sonne beaucoup moins comme un orgue."),
                ManualBlock(ManualKind.Heading, "Le baffle"),
                ManualBlock(ManualKind.Para, "Le haut-parleur rotatif est intégré : un pavillon qui tourne au-dessus d’un tambour qui tourne dans l’autre sens, chacun avec sa vitesse et sa rampe de montée et de descente, et deux micros que vous pouvez déplacer. La position des rotors peut aussi servir de source de modulation."),
                ManualBlock(ManualKind.Heading, "La modulation"),
                ManualBlock(ManualKind.Para, "Deux enveloppes et deux LFO qui peuvent se synchroniser au tempo, vers huit rangées de matrice (source, destination, profondeur)."),
                ManualBlock(ManualKind.Para, "Quatre des sources viennent de l’orgue lui-même : **pavillon** et **tambour** (là où pointent les rotors), le **balayage** du scanner de vibrato, et **vent** (la pression d’air). Le pavillon et le tambour ne bougent pas quand le rotatif est arrêté."),
                ManualBlock(ManualKind.Para, "Les destinations comprennent chaque tirette, et toutes les tirettes d’un clavier à la fois."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Changez la vitesse du rotatif en jouant. L’accélération et le ralentissement sont le meilleur moment."),
                ManualBlock(ManualKind.Bullet, "La percussion prend la dernière tirette quand elle est active, comme sur les originaux. C’est d’habitude mieux de la laisser ainsi."),
            )),
            ManualSection("Molt", "Chantez une prise, et la grille de notes l’accorde.", listOf(
                ManualBlock(ManualKind.Para, "Molt fait d’un enregistrement chanté un instrument. Il trouve les impulsions séparées de la voix et les espace autrement pour changer la hauteur, ce qui garde le caractère de la voix au lieu de la rendre nasillarde comme un écureuil."),
                ManualBlock(ManualKind.Heading, "La grille accorde"),
                ManualBlock(ManualKind.Para, "Dessinez les notes voulues dans la grille de notes, chantez n’importe quoi, et la prise est tirée vers ces notes."),
                ManualBlock(ManualKind.Bullet, "**intensité** - la force de la traction. Au maximum, c’est l’accord dur, et moins donne une correction douce."),
                ManualBlock(ManualKind.Bullet, "**vitesse** - à quelle vitesse la note est atteinte. Lent sonne comme un glissé naturel, rapide sonne par paliers."),
                ManualBlock(ManualKind.Bullet, "**robot** - aplatit complètement la hauteur sur la note."),
                ManualBlock(ManualKind.Heading, "La voix"),
                ManualBlock(ManualKind.Bullet, "**formant** - déplace les formants sans changer la hauteur, pour que la voix semble plus grosse ou plus petite."),
                ManualBlock(ManualKind.Bullet, "**mega** - un mégaphone."),
                ManualBlock(ManualKind.Bullet, "**début** et **boucle** - quelle partie de la prise joue, et si elle boucle."),
                ManualBlock(ManualKind.Para, "Puis un filtre, une enveloppe d’amplitude et une saturation."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Gardez le grondement grave hors de l’enregistrement. Le bruit du téléphone tenu dans la main peut tromper la détection de hauteur. Le **coupe-bas** de l’enregistreur aide, et il est activé par défaut pour Molt."),
                ManualBlock(ManualKind.Bullet, "Les consonnes sont copiées plutôt que transposées, et restent nettes."),
                ManualBlock(ManualKind.Bullet, "Chanter approximativement et laisser la grille corriger marche très bien."),
            )),
            ManualSection("Mosaic", "Un lecteur multi-échantillons : des zones sur le clavier et la vélocité, plus des nuages de grains.", listOf(
                ManualBlock(ManualKind.Para, "Mosaic joue des cartes d’échantillons. Chaque échantillon (une zone) couvre une plage de touches et de vélocités, et ensemble ils forment un instrument jouable."),
                ManualBlock(ManualKind.Heading, "La carte"),
                ManualBlock(ManualKind.Para, "Une **zone** est un fichier, une plage de touches, une plage de vélocités, une note de base et un accordage. Construisez les zones à la main avec vos propres enregistrements, ou chargez une **soundfont…** pour obtenir toute une carte d’un coup."),
                ManualBlock(ManualKind.Bullet, "**fondu clav.** et **fondu vél.** - des fondus enchaînés entre zones voisines, pour ne pas entendre les raccords."),
                ManualBlock(ManualKind.Bullet, "**balayage** et **intensité** - parcourent les couches de vélocité avec un bouton plutôt qu’avec la vélocité. Mettez le balayage sur la molette de modulation pour mêler un échantillon doux et un fort."),
                ManualBlock(ManualKind.Heading, "Le jeu"),
                ManualBlock(ManualKind.Para, "**début**, **boucle**, **sens**, **env de** et **mod fichier** décident de la façon dont chaque fichier est joué. Ensuite viennent un filtre avec sa propre enveloppe et son suivi de clavier, deux enveloppes, deux LFO, le portamento et les modes de voix."),
                ManualBlock(ManualKind.Heading, "Les grains"),
                ManualBlock(ManualKind.Para, "**nuage** joue plutôt la carte comme un nuage de grains, avec **taille**, **densité**, **position**, **dispers.**, **hauteur** et **vitesse**."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Réglez les fondus avant de juger le son d’une carte."),
                ManualBlock(ManualKind.Bullet, "Vérifiez les notes de base. Une mauvaise base désaccorde tout."),
                ManualBlock(ManualKind.Bullet, "Les grosses cartes prennent beaucoup de mémoire. La bibliothèque de sons montre ce qu’un morceau utilise avant que vous supprimiez quoi que ce soit."),
            )),
            ManualSection("Nexus", "Un synthé modulaire dont les modules sont les autres machines.", listOf(
                ManualBlock(ManualKind.Para, "Nexus vous laisse construire votre propre machine. Ses modules sont les instruments de l’application, et vous pouvez relier un filtre de Reflux, un oscillateur de Trinity et une banque de modes de Resonance."),
                ManualBlock(ManualKind.Heading, "Le patch est du texte"),
                ManualBlock(ManualKind.Para, "Un patch Nexus est une liste de modules et de connexions écrite en texte, que vous pouvez lire, copier et envoyer à quelqu’un. Il a son propre écran, car un patch demande de la place."),
                ManualBlock(ManualKind.Para, "Ses boutons sont des paramètres normaux, et tout ce qui est dans un patch peut être automatisé, assigné à un contrôleur et enregistré."),
                ManualBlock(ManualKind.Para, "**cadrer** ajuste le patch à l’écran. Il place les modules dans l’ordre où le son les traverse, de gauche à droite, sur autant de rangées qu’il convient à l’écran, puis zoome pour tout montrer. Tournez le téléphone et touchez-le de nouveau pour une disposition adaptée à ce sens. C’est une seule étape d’annulation, et les modules peuvent revenir où ils étaient.", "**cadrer** ajuste le patch à l’écran. Il place les modules dans l’ordre où le son les traverse, de gauche à droite, sur autant de rangées qu’il convient à l’écran, puis zoome pour tout montrer. Élargissez ou allongez la fenêtre et cliquez de nouveau dessus pour une disposition adaptée à cette forme. C’est une seule étape d’annulation, et les modules peuvent revenir où ils étaient."),
                ManualBlock(ManualKind.Heading, "Les modules sur le canevas"),
                ManualBlock(ManualKind.Para, "Chaque module est un panneau sur des rails, aussi large que ses boutons et ses prises le demandent. Les entrées sont les prises turquoise et les sorties les prises ambre, dans la boîte sombre du bas. La couleur en haut dit de quel genre de module il s’agit, et le voyant à côté du nom montre à quel point il travaille. Les câbles prennent la couleur du module d’où ils viennent."),
                ManualBlock(ManualKind.Para, "Tournez un bouton sur un panneau en glissant vers le haut ou le bas. Zoomez pour des réglages plus fins, et touchez-le deux fois pour le remettre. Les mêmes boutons sont sous le canevas quand le module est sélectionné. En mode d’assignation, touchez un bouton sur un panneau pour l’assigner et maintenez-le pour effacer l’assignation.", "Tournez un bouton sur un panneau en glissant vers le haut ou le bas. Zoomez pour des réglages plus fins, et cliquez-le deux fois pour le remettre. Les mêmes boutons sont sous le canevas quand le module est sélectionné. En mode d’assignation, cliquez un bouton sur un panneau pour l’assigner et maintenez-le pour effacer l’assignation."),
                ManualBlock(ManualKind.Heading, "Les effets en modules"),
                ManualBlock(ManualKind.Para, "Les effets d’insertion sont aussi des modules, et un effet peut aller n’importe où dans un patch et être bougé par un câble : **reverb**, **chorus**, **phaser**, **crush**, **shift**, **drive** et **swell**. Chacun sonne exactement comme sur une piste. Leur deuxième entrée bouge le bouton dont elle porte le nom, comme **size** sur la réverbération ou **amount** sur swell. Chacun a une fraction de milliseconde de retard, qu’on n’entend pas."),
                ManualBlock(ManualKind.Heading, "Les instruments des autres machines"),
                ManualBlock(ManualKind.Para, "D’autres machines sont des modules, chacun avec la partie qui fait son son :"),
                ManualBlock(ManualKind.Bullet, "**bore** : le cuivre de Brazen, des lèvres sur un tube avec un pavillon."),
                ManualBlock(ManualKind.Bullet, "**pipe** : le tuyau de Timber, avec une anche, une anche double ou le jet d’air d’une flûte."),
                ManualBlock(ManualKind.Bullet, "**reed** : l’anche libre de Draw : harmonica, accordéon, mélodica, harmonium ou concertina."),
                ManualBlock(ManualKind.Bullet, "**jaw** : l’anche de la guimbarde de Tongue, pincée par son entrée **trig**. Passez-la dans un **throat** et bougez la voyelle pour le son de guimbarde."),
                ManualBlock(ManualKind.Bullet, "**piano** : tout Hammer, joué par une **pitch** et un **gate**."),
                ManualBlock(ManualKind.Bullet, "**throat** : le conduit vocal de Diction en filtre : tout ce qui le traverse devient une voyelle, de ou à i."),
                ManualBlock(ManualKind.Bullet, "**formula** : les expressions de Formulate, en oscillateur ou pour façonner ce qui arrive dans **x**. Sélectionnez-le et touchez **modifier…** pour taper la formule.", "**formula** : les expressions de Formulate, en oscillateur ou pour façonner ce qui arrive dans **x**. Sélectionnez-le et cliquez **modifier…** pour taper la formule."),
                ManualBlock(ManualKind.Bullet, "**follow** : l’oreille de Molt : la hauteur de ce qui entre, un gate tant qu’il en est sûr, et son niveau. Chantez dedans pour jouer le patch."),
                ManualBlock(ManualKind.Para, "Les instruments à vent (**bore**, **pipe** et **reed**) prennent leur air à l’entrée **breath**, depuis une enveloppe ou une source de pression. Sans rien dedans, ce sont les touches qui soufflent."),
                ManualBlock(ManualKind.Heading, "Les macros"),
                ManualBlock(ManualKind.Para, "Huit macros, **1** à **8** sous **macros**, plus **morph**. Le patch décide de ce qu’elles contrôlent, et un gros patch peut se jouer avec quelques boutons."),
                ManualBlock(ManualKind.Heading, "MPE"),
                ManualBlock(ManualKind.Para, "Le module **touch** donne à chaque voix la pression et le glissé du doigt qui la joue, depuis un contrôleur MPE ou un clavier à aftertouch polyphonique. Reliez ses sorties **prs** et **slide** à n’importe quoi, comme la coupure d’un filtre ou un VCA."),
                ManualBlock(ManualKind.Heading, "L’entrée audio"),
                ManualBlock(ManualKind.Para, "Il y a un module d’entrée audio, et tout ce qui entre dans le téléphone peut passer par un patch.", "Il y a un module d’entrée audio, et tout ce qui entre dans l’ordinateur peut passer par un patch."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Gardez les patchs petits et nommez vos macros."),
                ManualBlock(ManualKind.Bullet, "Reliez **morph** aux deux ou trois choses qui changent le plus le patch."),
                ManualBlock(ManualKind.Bullet, "Nexus n’est pas l’endroit le plus facile pour commencer. Les autres machines font la plupart des choses plus directement, et Nexus sert aux combinaisons qu’elles ne couvrent pas."),
            )),
            ManualSection("Palm", "Percussions à main modélisées : tabla et bayan, djembé, cajón, tambour sur cadre et tambour d’aisselle, joués en frappes ouverte, claquée, étouffée, basse et sur le bord.", listOf(
                ManualBlock(ManualKind.Para, "Palm ne joue pas d’enregistrements. Chaque note est une peau accordée sur la note. Une peau ordinaire vibre selon les rapports inégaux d’un cercle tendu, d’où l’absence de hauteur nette de la plupart des tambours ; celle d’un tabla est chargée en son centre d’une pâte qui ramène ses harmoniques vers une série harmonique, et il chante une note."),
                ManualBlock(ManualKind.Para, "La main fait le reste : où elle tombe (le centre fait sonner les modes graves, le bord les aigus), combien de temps elle reste sur la peau, et si elle y reste pour l’étouffer."),
                ManualBlock(ManualKind.Heading, "Tambour"),
                ManualBlock(ManualKind.Bullet, "**modèle** : **tabla** (le petit tambour accordé), **bayan** (son grand compagnon grave), **djembé**, **cajón**, tambour sur **cadre** ou tambour d’**aisselle**."),
                ManualBlock(ManualKind.Bullet, "**accordage** : en cents."),
                ManualBlock(ManualKind.Bullet, "**attaque** : **ouvert** (les doigts à plat près du bord, aussitôt relevés), **slap** (le bout des doigts qui claque, la main restée au centre), **étouffé** (appuyé et tenu), **basse** (la paume au centre), **cercle** (les doigts sur le bord), ou **vélocité**, qui choisit étouffé pour les notes douces, ouvert au milieu et slap pour les plus fortes."),
                ManualBlock(ManualKind.Bullet, "**position** : déplace la frappe vers le centre ou le bord."),
                ManualBlock(ManualKind.Bullet, "**main** : du bout des doigts et de la paume, doux, aux doigts durs et rapides."),
                ManualBlock(ManualKind.Bullet, "**déclin** : combien de temps la peau sonne."),
                ManualBlock(ManualKind.Bullet, "**amortir** : l’autre main posée sur la peau."),
                ManualBlock(ManualKind.Heading, "Corps"),
                ManualBlock(ManualKind.Bullet, "**chute** : de combien une frappe forte fait monter la peau avant qu’elle ne se pose."),
                ManualBlock(ManualKind.Bullet, "**serrer** : de combien de demi-tons la pression, ou la molette de modulation, fait monter la peau : le poignet qui appuie sur un bayan, le bras qui serre un tambour d’aisselle."),
                ManualBlock(ManualKind.Bullet, "**grésil** : le timbre d’un cajón, les sonnailles d’un djembé ou les cymbalettes d’un tambour sur cadre."),
                ManualBlock(ManualKind.Bullet, "**corps** : l’air d’un djembé ou d’un cajón, qui gronde sous une frappe basse."),
                ManualBlock(ManualKind.Heading, "Jeu"),
                ManualBlock(ManualKind.Bullet, "**roulés** : les notes tenues frappées encore et encore, tant de fois par seconde."),
                ManualBlock(ManualKind.Bullet, "**écart** : les tambours graves à gauche, les aigus à droite."),
                ManualBlock(ManualKind.Bullet, "**voix**, **vélocité**, **octave**, **bend** et **volume**."),
                ManualBlock(ManualKind.Para, "Avec le MPE, glisser un doigt vers le haut le pose sur la peau et l’étouffe pendant qu’elle sonne."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Les présélections **By Touch** jouent toutes les frappes depuis une seule touche : jouez doucement pour étouffé, plus fort pour ouvert, très fort pour slap."),
                ManualBlock(ManualKind.Bullet, "**Bayan Swoop** et **Talking Squeeze** se jouent en appuyant : jouez une note, puis pesez sur la touche ou poussez la molette."),
            )),
            ManualSection("Pollen", "Des nuages granulaires tirés d’un fichier ou de l’entrée en direct, dont les grains peuvent en faire naître d’autres.", listOf(
                ManualBlock(ManualKind.Para, "Pollen joue un son comme un nuage de grains courts. La source est un fichier que vous chargez ou l’entrée en direct, enregistrée dans une boucle pendant que vous jouez."),
                ManualBlock(ManualKind.Heading, "Le nuage"),
                ManualBlock(ManualKind.Bullet, "**taille** et **· écart** - la durée de chaque grain, et combien elle varie."),
                ManualBlock(ManualKind.Bullet, "**densité** et **· gigue** - combien de grains par seconde, et à quel point ils sont irréguliers."),
                ManualBlock(ManualKind.Bullet, "**fenêtre** et **biais** - la forme de l’entrée et de la sortie en fondu de chaque grain."),
                ManualBlock(ManualKind.Bullet, "**position**, **balayage** et **dispers.** - d’où viennent les grains dans le tampon, si ce point bouge et jusqu’où ils s’éparpillent autour."),
                ManualBlock(ManualKind.Bullet, "**aimant attaques** - aligne les grains sur les attaques de la source, pour qu’un matériau rythmique le reste."),
                ManualBlock(ManualKind.Bullet, "**écart** et **largeur**."),
                ManualBlock(ManualKind.Heading, "L’entrée en direct"),
                ManualBlock(ManualKind.Para, "**lit depuis** passe à l’entrée. **longueur** règle ce qui est gardé, **direct** le fige et **capture** saisit ce qu’il contient. Un tampon en direct n’est pas sauvegardé avec le morceau et reste muet dans un export, et le panneau vous le rappelle."),
                ManualBlock(ManualKind.Heading, "La pollinisation"),
                ManualBlock(ManualKind.Para, "**éclosion** et **prof.** laissent les grains en faire naître d’autres à une position et une hauteur voisines, jusqu’à la profondeur choisie. Un peu épaissit le son, et beaucoup fait d’une note une texture changeante. **dérive** et **muter** règlent jusqu’où les nouveaux grains s’éloignent."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "La densité et la taille s’opposent. De longs grains à forte densité font un mur, et des courts font une texture."),
                ManualBlock(ManualKind.Bullet, "Utilisez **aimant attaques** sur tout ce qui a un rythme."),
                ManualBlock(ManualKind.Bullet, "La dispersion de hauteur peut être verrouillée sur une gamme pour que le nuage reste dans la tonalité."),
                ManualBlock(ManualKind.Bullet, "En qualité **légère** (**Réglages**), le nuage utilise deux fois moins de grains."),
            )),
            ManualSection("Ratio", "La FM à six opérateurs, avec un bouton qui passe d’un algorithme à un autre.", listOf(
                ManualBlock(ManualKind.Para, "Ratio est le synthé FM. Il a six opérateurs, chacun une onde sinus qui est soit une porteuse (vous l’entendez), soit un modulateur (il change le son d’un autre). La façon dont ils sont reliés est l’algorithme."),
                ManualBlock(ManualKind.Heading, "Les algorithmes qui se transforment"),
                ManualBlock(ManualKind.Para, "Vous choisissez deux algorithmes, `algoa` et `algob`, et **morph** passe de l’un à l’autre. Les réglages intermédiaires ne sont dans aucune liste d’algorithmes standard, et vous pouvez automatiser le morph : une nappe peut ainsi s’ouvrir de deux opérateurs à six en quelques mesures."),
                ManualBlock(ManualKind.Heading, "Les opérateurs"),
                ManualBlock(ManualKind.Para, "Chacun des six a :"),
                ManualBlock(ManualKind.Bullet, "**ratio** - sa fréquence en multiple de la note. **hauteur** sur **Hz** la garde plutôt sur une seule fréquence, ce qui est bien pour les formants."),
                ManualBlock(ManualKind.Bullet, "**niveau** - combien de FM il ajoute comme modulateur, ou son volume comme porteuse."),
                ManualBlock(ManualKind.Bullet, "**réinj.** - une réinjection sur lui-même, d’un sinus vers une dent de scie."),
                ManualBlock(ManualKind.Bullet, "**A D S R** - sa propre enveloppe. Sur un modulateur, elle façonne le timbre plutôt que le volume."),
                ManualBlock(ManualKind.Bullet, "le suivi de **clavier**, l’accord **précis**, le **pano** et le **mode**."),
                ManualBlock(ManualKind.Heading, "Tout le reste"),
                ManualBlock(ManualKind.Para, "Un filtre avec sa propre enveloppe, trois enveloppes de plus pour la modulation, trois LFO qui peuvent se synchroniser au tempo et dix rangées de matrice (source, deuxième source, destination, profondeur) qui marchent comme celles de Trinity."),
                ManualBlock(ManualKind.Para, "**aimant** garde les ratios sur des valeurs utiles (nombres entiers, nombres impairs, demi-tons, partiels de cloche), et **biais** les éloigne tous ensemble de ces valeurs."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Les ratios entiers (1, 2, 3) sonnent harmoniques, et les autres (1.41, 3.14) sonnent comme des cloches et du métal. Les bons sons mêlent souvent les deux."),
                ManualBlock(ManualKind.Bullet, "Donnez aux modulateurs des enveloppes plus courtes qu’aux porteuses. Une attaque brillante qui s’éteint dans un corps doux, c’est le piano électrique classique."),
                ManualBlock(ManualKind.Bullet, "La réinjection sur l’opérateur du haut d’une pile est la façon la moins coûteuse d’ajouter de la brillance."),
            )),
            ManualSection("Reflux", "La basse acid : un oscillateur, un filtre qui hurle, et des lignes que vous jouez.", listOf(
                ManualBlock(ManualKind.Para, "Reflux, c’est un oscillateur, un filtre et une enveloppe, réglés pour que vous puissiez jouer une ligne de basse au lieu de la construire pas à pas."),
                ManualBlock(ManualKind.Heading, "L’accent et le glissé"),
                ManualBlock(ManualKind.Para, "Les lignes de basse acid viennent de l’accent et du glissé, et Reflux les tire de votre jeu :"),
                ManualBlock(ManualKind.Bullet, "L’accent, c’est la vélocité. Jouez une note plus fort et elle est plus forte, plus brillante et a plus d’enveloppe de filtre."),
                ManualBlock(ManualKind.Bullet, "Le glissé, c’est le legato. Faites chevaucher deux notes et la deuxième glisse depuis la première au lieu de repartir. Laissez un espace et elle est pincée."),
                ManualBlock(ManualKind.Para, "Jouez donc une ligne au clavier, ou dessinez-la dans la grille avec des notes qui se chevauchent pour les glissés."),
                ManualBlock(ManualKind.Heading, "Les commandes"),
                ManualBlock(ManualKind.Bullet, "**osc** - l’**onde**, scie ou impulsion, avec **pw** pour la largeur d’impulsion, un oscillateur **sub** une octave plus bas et **accordage**."),
                ManualBlock(ManualKind.Bullet, "**filtre** - **coupure** et **rés.**, **mod env** pour l’ouverture du filtre par l’enveloppe et **déclin** pour sa durée. Les déclins courts sont pincés et les longs sont élastiques. **mode** est passe-bas ou passe-bande. L’essentiel du son est ici."),
                ManualBlock(ManualKind.Bullet, "**jeu** - **accent** est ce qu’une note accentuée ajoute au niveau et au filtre, **glissé** est la durée d’un glissé, et **vél.** est la part de la vélocité dans le niveau. Une note qui glisse garde le niveau de la note d’où elle vient."),
                ManualBlock(ManualKind.Bullet, "**sortie** - **satur.**, d’où vient le hurlement, et **volume**."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "La résonance et la saturation ensemble font le son classique. La plupart des sons acid ont les deux montées et la coupure qui bouge."),
                ManualBlock(ManualKind.Bullet, "Enregistrez le bouton de coupure en automatisation pendant que le morceau joue, plutôt que de la dessiner."),
                ManualBlock(ManualKind.Bullet, "Deux Reflux qui jouent le même clip, l’un pincé et l’autre glissé, séparés dans le panoramique avec des coupures un peu différentes, ça marche encore très bien."),
                ManualBlock(ManualKind.Para, "*Reflux s’appelait Subvert dans les versions antérieures, et les morceaux et sons de cette époque s’ouvrent en Reflux.*"),
            )),
            ManualSection("Resonance", "Huit objets frappés qui résonnent les uns dans les autres.", listOf(
                ManualBlock(ManualKind.Para, "Resonance fait des percussions modales. Chacun de ses huit pads est un objet (un tambour, une barre, une cloche, etc.) qui résonne sur un ensemble de fréquences, et jouer un pad le frappe. Rien n’est échantillonné."),
                ManualBlock(ManualKind.Heading, "Un pad"),
                ManualBlock(ManualKind.Bullet, "**modes** - combien de partiels il a. Peu sonne comme un wood-block, beaucoup comme une cloche."),
                ManualBlock(ManualKind.Bullet, "**forme** - membrane, barre, plaque, tube, bol ou métal. Elle règle l’espacement des partiels, et c’est surtout ce qui distingue le son d’un tambour de celui d’une barre."),
                ManualBlock(ManualKind.Bullet, "**raideur** - étire l’espacement."),
                ManualBlock(ManualKind.Bullet, "**déclin** et **amorti** - combien de temps il résonne, et si les aigus meurent en premier."),
                ManualBlock(ManualKind.Bullet, "**dureté** - la dureté de la mailloche (combien d’aigus)."),
                ManualBlock(ManualKind.Bullet, "**où** - l’endroit où vous le frappez. Chaque endroit fait ressortir certains partiels et en cache d’autres, et change donc beaucoup le son."),
                ManualBlock(ManualKind.Bullet, "**intensité** et **temps** de **bend** - une chute de hauteur après le coup, comme un tom."),
                ManualBlock(ManualKind.Bullet, "**satur.**, **pano**, **niveau** et **écoute**."),
                ManualBlock(ManualKind.Heading, "Le couplage"),
                ManualBlock(ManualKind.Para, "**couplage** règle à quel point les pads résonnent les uns dans les autres. Frappez-en un et les autres répondent doucement à leur propre hauteur, et un kit sonne comme des objets dans une même pièce. **humaniser** varie un peu chaque coup."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Réglez **où** et **forme** avant d’accorder."),
                ManualBlock(ManualKind.Bullet, "Allez-y doucement avec le couplage. Un peu sonne comme une pièce, et beaucoup fait de la réinjection."),
                ManualBlock(ManualKind.Bullet, "Avec de longs déclins, vous pouvez jouer des mélodies sur les pads."),
            )),
            ManualSection("Sympath", "Sitar, tanpura, veena et shamisen modélisés : des cordes pincées sur un chevalet qui grésille, et des cordes qui vibrent par sympathie.", listOf(
                ManualBlock(ManualKind.Para, "Sympath ne joue pas d’enregistrements. Chaque note est une corde posée sur un chevalet large et bombé. Quand la corde oscille assez loin vers le chevalet, elle le frappe, d’autant plus fort qu’elle va loin, et chaque choc fait sonner le chevalet : ce grésillement brillant, à chaque oscillation, qui dure tant que la corde va assez loin pour l’atteindre et s’éteint avec la note."),
                ManualBlock(ManualKind.Para, "Sous les cordes jouées se trouvent des cordes sympathiques qu’on ne touche jamais. Elles sont accordées sur la gamme du morceau : toute note qui tombe sur l’une d’elles la fait sonner, et elle sonne encore après la note."),
                ManualBlock(ManualKind.Heading, "Cordes"),
                ManualBlock(ManualKind.Bullet, "**modèle** : **sitar** (onze cordes sympathiques et deux cordes de bourdon), **tanpura** (quatre cordes qu’il pince tout seul), **veena** (un chevalet plus plat et trois cordes de bourdon sur le côté) ou **shamisen** (un grand plectre qui frappe aussi la peau, et sa corde grave qui grésille contre le manche)."),
                ManualBlock(ManualKind.Bullet, "**accordage** : en cents."),
                ManualBlock(ManualKind.Bullet, "**sa** : la tonique sur laquelle sont accordées les cordes sympathiques et de bourdon."),
                ManualBlock(ManualKind.Bullet, "**gamme** : la gamme des cordes sympathiques : **bilawal** (majeur), **khamaj**, **kafi**, **asavari**, **bhairavi**, **bhairav**, **kalyan**, **marwa**, **purvi** ou **todi**."),
                ManualBlock(ManualKind.Bullet, "**chevalet** : combien le chevalet grésille. À 0, c’est une arête nette."),
                ManualBlock(ManualKind.Bullet, "**courbe** : jusqu’où la corde doit osciller avant de se coucher sur le chevalet. Basse, même les notes douces grésillent ; haute, seules les fortes."),
                ManualBlock(ManualKind.Bullet, "**pincer** : un pincement doux ou dur."),
                ManualBlock(ManualKind.Bullet, "**position** : où la corde est pincée."),
                ManualBlock(ManualKind.Bullet, "**maintien** : combien de temps les cordes résonnent."),
                ManualBlock(ManualKind.Bullet, "**brillant** : combien de temps elles gardent leurs aigus."),
                ManualBlock(ManualKind.Heading, "Bourdons"),
                ManualBlock(ManualKind.Bullet, "**tarabs** : le volume des cordes sympathiques."),
                ManualBlock(ManualKind.Bullet, "**chikari** : frappe les cordes de bourdon à chaque nouvelle note."),
                ManualBlock(ManualKind.Bullet, "**première** : la première corde du tanpura : **pa**, **ma**, **ni** ou **sa** une octave plus bas. Les trois autres sont Sa, Sa et Sa une octave plus bas."),
                ManualBlock(ManualKind.Bullet, "**cycle** : en combien de temps le tanpura pince ses quatre cordes avant de recommencer : **2**, **4**, **6** ou **8** temps. Il suit le tempo."),
                ManualBlock(ManualKind.Heading, "Mains"),
                ManualBlock(ManualKind.Bullet, "**meend** : avec une seule voix, une nouvelle note glisse depuis la précédente sur la même corde au lieu d’être pincée à nouveau."),
                ManualBlock(ManualKind.Bullet, "**gamak** : secoue la note rapidement. La molette de modulation fait de même."),
                ManualBlock(ManualKind.Bullet, "**voix**, **vélocité**, **octave**, **bend** et **volume**."),
                ManualBlock(ManualKind.Para, "La pression (du clavier, ou de chaque note avec le MPE) tire la corde de côté et monte la note jusqu’à un ton entier."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Réglez **sa** sur la tonalité du morceau et **gamme** sur sa gamme : les cordes sympathiques sonnent avec la mélodie."),
                ManualBlock(ManualKind.Bullet, "Le tanpura ne pince que tant qu’une note est tenue : tenez Sa aussi longtemps que le bourdon doit durer."),
                ManualBlock(ManualKind.Bullet, "**Sitar** n’a qu’une voix : jouez lié pour le meend, et appuyez plus fort pour tirer une note vers le haut."),
            )),
            ManualSection("Timber", "Des bois modélisés : anches et flûtes.", listOf(
                ManualBlock(ManualKind.Para, "Timber est la version bois de Brazen : une anche qui vibre contre un bec, ou un jet d’air soufflé sur un biseau, qui alimente un tube percé de trous."),
                ManualBlock(ManualKind.Heading, "La famille"),
                ManualBlock(ManualKind.Para, "**excité par** choisit le genre d’instrument :"),
                ManualBlock(ManualKind.Bullet, "**anche** - la clarinette et le saxophone."),
                ManualBlock(ManualKind.Bullet, "**double** - une anche double, le hautbois et le basson."),
                ManualBlock(ManualKind.Bullet, "**air** - un jet d’air, la flûte. **visée** règle la façon dont l’air frappe le biseau, comme les lèvres d’un flûtiste."),
                ManualBlock(ManualKind.Heading, "Le tube"),
                ManualBlock(ManualKind.Bullet, "**forme** - la perce, un cylindre ou un cône. Un cylindre donne le son creux de la clarinette et un cône sonne plutôt comme un sax."),
                ManualBlock(ManualKind.Bullet, "**plus grave** et **cloche** - la forme du bout."),
                ManualBlock(ManualKind.Bullet, "**perte** - combien d’énergie le tube perd."),
                ManualBlock(ManualKind.Bullet, "**longueur** et **réponses**, sous **dessous** - les trous, y compris la partie du tube au-delà de la note jouée."),
                ManualBlock(ManualKind.Bullet, "**fourche** - les doigtés de fourche, qui sonnent un peu autrement que les doigtés normaux, comme sur un vrai instrument."),
                ManualBlock(ManualKind.Heading, "Le souffle"),
                ManualBlock(ManualKind.Para, "**pression** et **souffle** marchent comme dans Brazen. Les flûtes ajoutent **jet** et **visée**, et **langue** ajoute l’articulation."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "La pression décide du registre. Surchargez une clarinette et elle saute d’une douzième plutôt que d’une octave, comme la vraie."),
                ManualBlock(ManualKind.Bullet, "Le bruit de souffle compte beaucoup dans le réalisme."),
                ManualBlock(ManualKind.Bullet, "Utilisez **langue** entre les notes pour qu’une phrase ne sonne pas comme une seule longue note."),
            )),
            ManualSection("Tine", "Lames, languettes et tambours d’acier modélisés : marimba, vibraphone, xylophone, glockenspiel, piano à pouces, boîte à musique, steelpan, handpan et tambour à languettes.", listOf(
                ManualBlock(ManualKind.Para, "Tine ne joue pas d’enregistrements. Chaque note est une poignée de résonances accordées comme l’objet frappé. Une lame de marimba est creusée en dessous pour que sa première harmonique sonne deux octaves plus haut et la suivante deux octaves et une tierce ; celle d’un xylophone est creusée à la douzième ; la lame d’acier d’un glockenspiel est laissée telle quelle, ses harmoniques loin de tout accord. La languette d’un piano à pouces est tenue par un bout, ce qui place ses harmoniques plus haut encore, et la note d’un steelpan est martelée jusqu’à sonner son octave et sa douzième."),
                ManualBlock(ManualKind.Para, "Ce qui frappe compte tout autant. Une mailloche douce reste quelques millisecondes sur la lame et ne peut que lancer la note ; une dure est repartie avant que les harmoniques démarrent, et elles sonnent."),
                ManualBlock(ManualKind.Heading, "Barre"),
                ManualBlock(ManualKind.Bullet, "**modèle** : **marimba**, **vibra**, **xylophone**, **glock**, **pouce** (piano à pouces), **boîte à musique**, **steelpan**, **handpan** ou **tambour à lang.** (tambour à languettes)."),
                ManualBlock(ManualKind.Bullet, "**accordage** : en cents."),
                ManualBlock(ManualKind.Bullet, "**mailloche** : la dureté de la mailloche, du doigt ou de la goupille : de la laine douce au métal nu. Jouer plus fort la durcit un peu aussi."),
                ManualBlock(ManualKind.Bullet, "**position** : où elle est frappée. Au milieu, la deuxième harmonique d’une lame reste discrète ; vers le bout, la note s’amincit et les harmoniques ressortent."),
                ManualBlock(ManualKind.Bullet, "**déclin** : combien de temps les notes sonnent. Les graves sonnent toujours plus longtemps."),
                ManualBlock(ManualKind.Bullet, "**brillant** : la part des harmoniques, et leur durée."),
                ManualBlock(ManualKind.Bullet, "**amortir** : la barre d’étouffoirs : combien une note s’arrête quand vous la lâchez. La pédale de sustain la lève."),
                ManualBlock(ManualKind.Heading, "Corps"),
                ManualBlock(ManualKind.Bullet, "**tube** : le tube sous chaque lame, qui sonne avec la note (et ses harmoniques impaires). Sur les steelpans et le tambour à languettes, c’est la coque."),
                ManualBlock(ManualKind.Bullet, "**moteur** : les disques qui tournent dans les tubes d’un vibraphone, en tours par seconde. À 0, ils sont à l’arrêt."),
                ManualBlock(ManualKind.Bullet, "**prof.** : combien les disques font pulser la note. La molette de modulation s’y ajoute."),
                ManualBlock(ManualKind.Bullet, "**éclosion** : sur les steelpans, combien l’octave naît de la note après la frappe."),
                ManualBlock(ManualKind.Bullet, "**buzz** : une ferraille qui touche la languette quand elle bat large."),
                ManualBlock(ManualKind.Heading, "Jeu"),
                ManualBlock(ManualKind.Bullet, "**roulés** : les notes tenues frappées encore et encore, tant de fois par seconde, jamais tout à fait régulièrement. À 0, une note est frappée une fois."),
                ManualBlock(ManualKind.Bullet, "**écart** : les graves à gauche, les aigus à droite."),
                ManualBlock(ManualKind.Bullet, "**voix**, **vélocité**, **octave**, **bend** et **volume**."),
                ManualBlock(ManualKind.Para, "La pression (du clavier, ou de chaque note avec le MPE) passe un archet sur une lame tenue : la note enfle et tient tant que vous appuyez."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "**Vibraphone** arrête chaque note quand vous la lâchez ; tenez la pédale de sustain pour les laisser sonner, comme un vibraphoniste."),
                ManualBlock(ManualKind.Bullet, "**Vibes Motor** et **Slow Motor** font tourner les disques ; la molette creuse la pulsation."),
                ManualBlock(ManualKind.Bullet, "**Marimba Roll**, **Vibes Roll** et **Pan Roll** demandent des notes tenues."),
            )),
            ManualSection("Tongue", "Une guimbarde modélisée : une lame qui vibre dans une fente, et une bouche qui en fait ressortir les harmoniques.", listOf(
                ManualBlock(ManualKind.Para, "Tongue ne joue pas d’enregistrements. Une lame d’acier est pincée et passe et repasse dans une fente de son cadre, et chaque passage pousse une bouffée d’air. C’est le bourdonnement, avec toutes ses harmoniques à peu près au même niveau. Votre bouche est devant, et en changeant de forme elle fait ressortir une harmonique puis une autre : c’est la mélodie, par-dessus un bourdon qui reste sur la note jouée."),
                ManualBlock(ManualKind.Para, "Il y a dix genres de guimbarde, et celles en métal ont été ajustées sur des enregistrements de vraies guimbardes. Une guimbarde peut avoir jusqu’à cinq lames, accordées en accord."),
                ManualBlock(ManualKind.Para, "La molette de modulation bouge la bouche : vous pouvez jouer le bourdon d’une main et la mélodie de l’autre. Ou mettez **jeu** sur **bouche**, et les touches jouent la mélodie comme le fait un joueur, par-dessus un bourdon qui ne bouge pas. La pression, c’est le souffle."),
                ManualBlock(ManualKind.Heading, "La guimbarde"),
                ManualBlock(ManualKind.Bullet, "**modèle** - le genre de guimbarde : - **acier** - la guimbarde d’acier courante, qui résonne longtemps. - **munnharpe** - une guimbarde norvégienne grave, douce et ronde. - **khomus** - une guimbarde iakoute, plus sombre dans l’aigu que l’acier, où l’on souffle souvent en jouant. - **morsing** - une grosse guimbarde du sud de l’Inde : grave, sombre et courte, pour le rythme. - **temir komuz** - une guimbarde kirghize : ajustée serré, brillante et sonnante. - **laiton** - une fine guimbarde de laiton découpée dans son propre cadre : aiguë, bourdonnante et discrète, avec le cadre qui résonne aussi. - **bambou** - une lame taillée dans une lamelle de bambou : douce, aérée et courte, avec un toc boisé. - **mukkuri** - une guimbarde de bambou qu’on joue en tirant une ficelle attachée à son cadre. - **genggong** - une guimbarde de palmier, elle aussi à ficelle : un coup sec et un bourdonnement. - **kouxian** - une guimbarde à plusieurs lames, trois accordées sur un accord pentatonique, à moins que vous régliez vous-même **anches** et **accord**."),
                ManualBlock(ManualKind.Bullet, "**accordage** - en cents."),
                ManualBlock(ManualKind.Bullet, "**assise** - où la lame repose dans la fente. Au milieu, les bouffées sont régulières et les harmoniques impaires plus fortes. Décalée d’un côté, les paires montent avec elles."),
                ManualBlock(ManualKind.Bullet, "**ajust.** - à quel point la lame est ajustée à la fente. Serré donne des bouffées plus nettes et plus d’harmoniques aiguës. Lâche est plus doux et plus creux."),
                ManualBlock(ManualKind.Bullet, "**anneau** - combien de temps résonne une guimbarde d’acier, en secondes. Les autres genres résonnent plus ou moins longtemps."),
                ManualBlock(ManualKind.Para, "**assise**, **ajust.** et **pincer** partent du réglage propre à chaque genre : un morsing avec ces boutons à leur valeur par défaut est déjà un morsing."),
                ManualBlock(ManualKind.Heading, "Le pincement"),
                ManualBlock(ManualKind.Bullet, "**pincer** - la netteté de la chiquenaude. Monté, c’est une chiquenaude vive avec un clic, baissé, une poussée douce du bout du doigt."),
                ManualBlock(ManualKind.Bullet, "**harmoniques** - la part du pincement qui va dans les harmoniques propres à la lame, le tintement métallique du début."),
                ManualBlock(ManualKind.Bullet, "**vélocité** - à quel point jouer plus fort change le niveau."),
                ManualBlock(ManualKind.Para, "Pincez une touche qui résonne encore et le doigt attrape d’abord la lame, qui ne devient donc pas de plus en plus forte. Les genres à ficelle sont plutôt tirés puis relâchés, et **pincer** règle à quelle vitesse."),
                ManualBlock(ManualKind.Heading, "Les lames"),
                ManualBlock(ManualKind.Bullet, "**anches** - combien de lames a la guimbarde, ou **auto** pour le nombre propre au genre."),
                ManualBlock(ManualKind.Bullet, "**accord** - leur accord par rapport à la note jouée : **unisson** (quelques cents d’écart), **octaves**, **quintes**, **majeur**, **mineur** ou **pentatonique**, ou **auto** pour celui du genre."),
                ManualBlock(ManualKind.Bullet, "**gratter** - le temps entre une lame et la suivante, en ms. À 0, elles sont pincées ensemble."),
                ManualBlock(ManualKind.Bullet, "**ordre** - vers le **haut** ou le **bas** de l’accord, **épars** dans un ordre différent à chaque fois, ou **tour à tour** : chaque note ne pince que la lame suivante, et les autres continuent de résonner, et jouer un rythme sur une touche joue l’accord."),
                ManualBlock(ManualKind.Heading, "La bouche"),
                ManualBlock(ManualKind.Bullet, "**voyelle** - la forme de la bouche : oo, oh, ah, eh, ee. La molette de modulation s’y ajoute."),
                ManualBlock(ManualKind.Bullet, "**focus** - l’étroitesse des résonances de la bouche. Monté, chacune fait ressortir une seule harmonique et la mélodie devient plus claire."),
                ManualBlock(ManualKind.Bullet, "**prof.** - la part du son qui passe par la bouche."),
                ManualBlock(ManualKind.Bullet, "**porta.** - le temps que prend la bouche pour passer à une nouvelle voyelle, en ms."),
                ManualBlock(ManualKind.Bullet, "**paroles** - à quel point les paroles d’un clip bougent la bouche. Voyez plus bas."),
                ManualBlock(ManualKind.Para, "La bouche garde le niveau stable : la bouger change la couleur, pas le volume."),
                ManualBlock(ManualKind.Heading, "Les paroles et le suivi"),
                ManualBlock(ManualKind.Para, "Tongue peut parler. Donnez des paroles à ses notes dans le couloir **paroles** de l’éditeur, comme pour Diction, et la bouche façonne le mot de chaque note : la voyelle tenue tant que la note est enfoncée, les sons d’avant à l’entrée et ceux d’après au relâchement. Un S ou un T siffle. Une guimbarde ne parle pas très clairement, et les mots courts et ouverts, riches en voyelles, passent le mieux."),
                ManualBlock(ManualKind.Para, "La bouche peut aussi suivre une autre piste. Réglez **suivre** sur cette piste, et sa mélodie amène la bouche sur l’harmonique la plus proche du bourdon, comme le font les touches en mode bouche. Son octave n’a pas d’importance : chaque note est ramenée dans les harmoniques que la bouche fait le mieux ressortir, de la 3e à la 12e. Quand cette piste se tait, la bouche revient aux touches. Tenez un bourdon avec un motif actif et la guimbarde joue la mélodie de l’autre piste."),
                ManualBlock(ManualKind.Heading, "Le souffle"),
                ManualBlock(ManualKind.Bullet, "**souffle** - de l’air soufflé dans la guimbarde pendant que vous jouez. La pression s’y ajoute."),
                ManualBlock(ManualKind.Bullet, "**air** - la part de cet air que vous entendez comme un souffle sifflant."),
                ManualBlock(ManualKind.Bullet, "**maintien** - un souffle assez fort pour garder la lame en mouvement tant que la touche est enfoncée. Avec **souffle** et **maintien** tous deux montés, une note tenue ne meurt pas."),
                ManualBlock(ManualKind.Heading, "Les touches"),
                ManualBlock(ManualKind.Bullet, "**jeu** - ce que font les touches. - **bourdon** - chaque touche pince une guimbarde à sa propre hauteur. - **bouche** - une guimbarde reste sur la note de **bourdon**, et chaque touche amène la bouche sur l’harmonique du bourdon la plus proche : la mélodie est dans les harmoniques, comme sur une vraie guimbarde. Les touches s’alignent sur l’harmonique la plus proche, à partir de la 2e. Lâcher une touche revient à celle encore enfoncée."),
                ManualBlock(ManualKind.Bullet, "**bourdon** - la note du bourdon en mode bouche."),
                ManualBlock(ManualKind.Bullet, "**repincer** - en mode bouche, quand une touche pince de nouveau la guimbarde : à **chaque** touche, seulement la **première** une fois les autres relâchées, ou les touches jouées **fort** (vélocité 100 et plus)."),
                ManualBlock(ManualKind.Heading, "Le rythme"),
                ManualBlock(ManualKind.Para, "Tant qu’une touche est enfoncée, la guimbarde est pincée de nouveau en rythme, au tempo du morceau, même quand il est arrêté."),
                ManualBlock(ManualKind.Bullet, "**motif** - **non**, **croches**, **doubles croches**, **galop** (long, court, court), **triolets**, **traits** (des traits rapides de quatre et un silence, comme on tire un genggong) ou **groupes** (des doubles croches en groupes de quatre et de trois, comme sur un morsing)."),
                ManualBlock(ManualKind.Bullet, "**accent** - à quel point les pas faibles sont plus doux."),
                ManualBlock(ManualKind.Bullet, "**répétition** - à quelle fréquence un pas devient deux ou trois pincements rapides."),
                ManualBlock(ManualKind.Para, "En mode bouche, le motif pince le bourdon pendant que les touches jouent la mélodie."),
                ManualBlock(ManualKind.Heading, "La sortie"),
                ManualBlock(ManualKind.Bullet, "**arrêt** - lâcher une touche pose un doigt sur la lame. Baissé, elle continue de résonner. Monté, elle s’arrête vite."),
                ManualBlock(ManualKind.Bullet, "**voix** - une guimbarde, ou jusqu’à quatre. Avec une seule, une nouvelle note repince la même guimbarde à la nouvelle hauteur."),
                ManualBlock(ManualKind.Bullet, "**octave**, **bend** - l’octave, et l’étendue du pitch-bend en demi-tons."),
                ManualBlock(ManualKind.Bullet, "**volume**."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Commencez par le **modèle**. Les genres diffèrent plus que n’importe quel bouton ne les change."),
                ManualBlock(ManualKind.Bullet, "La mélodie est dans la bouche. Laissez **jeu** sur **bourdon**, tenez une note et bougez la molette de modulation, ou mettez **jeu** sur **bouche** et jouez la mélodie au clavier."),
                ManualBlock(ManualKind.Bullet, "Un **motif** sur une note tenue, c’est l’essentiel du jeu de guimbarde. Essayez **galop**."),
                ManualBlock(ManualKind.Bullet, "Les bourdons graves parlent le mieux : vers D3 et plus bas, les harmoniques que choisit la bouche sont proches et la mélodie passe clairement."),
                ManualBlock(ManualKind.Bullet, "Pour un son qui ne s’arrête jamais, montez **souffle** et **maintien**."),
            )),
            ManualSection("Trinity", "Trois oscillateurs, des tables d’ondes, deux filtres et une matrice de modulation : le polyvalent.", listOf(
                ManualBlock(ManualKind.Para, "Trinity est le synthé polyphonique à tout faire, trois oscillateurs dans deux filtres avec une matrice de modulation par-dessus."),
                ManualBlock(ManualKind.Heading, "Les oscillateurs"),
                ManualBlock(ManualKind.Para, "Chaque oscillateur joue une table d’ondes, une rangée de formes d’onde que **pos** parcourt. Automatisez **pos** pour balayer le timbre."),
                ManualBlock(ManualKind.Bullet, "**densité** empile des copies de l’oscillateur, **désaccord** les écarte et **dérive** fait errer un peu chaque copie. C’est ainsi qu’on obtient un gros son de supersaw."),
                ManualBlock(ManualKind.Bullet, "**dur** est la synchro d’oscillateur et **pw** la largeur d’impulsion."),
                ManualBlock(ManualKind.Bullet, "**fm21** et **fm32** sont de la FM entre les oscillateurs (2 dans 1, 3 dans 2), pour des sons métalliques et de cloche."),
                ManualBlock(ManualKind.Bullet, "**bruit** et sa **couleur** servent au souffle, aux queues de caisse claire, etc."),
                ManualBlock(ManualKind.Heading, "Les filtres"),
                ManualBlock(ManualKind.Para, "Il y en a deux. **routage** les met en série, en parallèle ou partagés avec une **balance** entre eux, et chacun a son propre type, sa saturation, son suivi de clavier et sa quantité d’enveloppe."),
                ManualBlock(ManualKind.Heading, "La modulation"),
                ManualBlock(ManualKind.Para, "Six enveloppes et trois LFO alimentent douze rangées de matrice."),
                ManualBlock(ManualKind.Para, "L’enveloppe **env ampli** est l’amplitude et **env filtre** est le filtre, et les quatre autres ne font rien tant que vous ne les routez pas. Chaque LFO a une onde, une vitesse qui peut se synchroniser au tempo, un délai, une phase, une synchro au clavier, un mode coup unique et un lissage."),
                ManualBlock(ManualKind.Para, "Une rangée de matrice a une source, une deuxième source, une destination et une profondeur. La deuxième source multiplie la première : une enveloppe avec la molette de modulation comme deuxième source est une enveloppe que vous pouvez faire entrer avec la molette."),
                ManualBlock(ManualKind.Para, "La molette de modulation ouvre aussi les deux filtres, quoi que dise la matrice, et **molette** dans la section voix règle de combien. À zéro, la molette ne fait que ce que la matrice lui dit."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Commencez par les oscillateurs (position dans la table et densité) plutôt que par le filtre. C’est là qu’est le caractère de Trinity."),
                ManualBlock(ManualKind.Bullet, "Une forte densité coûte le plus de CPU. Si un morceau peine, figez le clip de Trinity qui a la plus grosse pile."),
            )),
        )),
        ManualSection("Effets et mixage", "", listOf(
            ManualBlock(ManualKind.Heading, "Insertions"),
            ManualBlock(ManualKind.Para, "Chaque piste a deux emplacements d’effet en insertion. **fx** dans la barre du bas de l’éditeur les affiche à la place du panneau de la machine."),
            ManualBlock(ManualKind.Para, "Il y a vingt-neuf effets. Chacun a les réglages habituels plus un extra, affiché dans la couleur d’accent. Chaque effet finit par **gain**, un réglage du niveau de sortie, puisque monter le mélange peut changer le niveau."),
            ManualBlock(ManualKind.Para, "Chaque effet a sa propre page ci-dessous."),
            ManualBlock(ManualKind.Heading, "Temps"),
            ManualBlock(ManualKind.Bullet, "**Delay** : des échos sur une valeur de note, qui peuvent s’atténuer pendant que vous jouez."),
            ManualBlock(ManualKind.Bullet, "**Reverb** : une salle qui peut aussi se figer, se couper, miroiter ou s’écraser jusqu’à 8 bits."),
            ManualBlock(ManualKind.Bullet, "**Grain** : un nuage de courtes tranches de ce que la piste vient de jouer, qui peut se figer."),
            ManualBlock(ManualKind.Bullet, "**Tape** : un magnétophone usé, avec pleurage, scintillement, saturation et souffle, et un interrupteur qui le ralentit jusqu’à l’arrêt."),
            ManualBlock(ManualKind.Bullet, "**Slicer** : découpe la piste en tranches sur le temps et en répète, inverse ou omet certaines."),
            ManualBlock(ManualKind.Heading, "Timbre"),
            ManualBlock(ManualKind.Bullet, "**Eq** : trois bandes et une pente."),
            ManualBlock(ManualKind.Bullet, "**Filter** : passe-bas, passe-bande ou passe-haut, déplacé par un LFO, le niveau du signal ou une autre piste."),
            ManualBlock(ManualKind.Bullet, "**Width** : plus large, plus étroit, mono sous une fréquence ou tourné."),
            ManualBlock(ManualKind.Bullet, "**Acid** : le filtre de la basse acid sur n’importe quelle piste, ouvert par chaque note ou par un motif sur le temps."),
            ManualBlock(ManualKind.Bullet, "**Mouth** : des voyelles, déplacées par un LFO, le niveau de la piste ou une autre piste."),
            ManualBlock(ManualKind.Bullet, "**Spectral** : fige, étire, brouille ou robotise les fréquences de la piste."),
            ManualBlock(ManualKind.Heading, "Saturation"),
            ManualBlock(ManualKind.Bullet, "**Distortion** : quatre sortes d’écrêtage et un réglage de polarisation."),
            ManualBlock(ManualKind.Bullet, "**Amp** : un ampli de guitare avec un baffle dont on peut changer la taille."),
            ManualBlock(ManualKind.Bullet, "**Bitcrusher** : moins de bits et une fréquence d’échantillonnage plus basse, avec une horloge instable si vous voulez."),
            ManualBlock(ManualKind.Bullet, "**Magneto** : le son des formats d’un petit disque enregistrable, de l’original propre au tourbillon de la longue durée, recopié jusqu’à quatre fois."),
            ManualBlock(ManualKind.Bullet, "**Formula** : tapez une formule et elle façonne la piste, échantillon par échantillon."),
            ManualBlock(ManualKind.Heading, "Niveau"),
            ManualBlock(ManualKind.Bullet, "**Compressor** : les réglages habituels, une entrée latérale de n’importe quelle piste et un pompage calé sur le tempo."),
            ManualBlock(ManualKind.Bullet, "**Gate** : une porte de bruit qu’une autre piste peut ouvrir."),
            ManualBlock(ManualKind.Bullet, "**Swell** : une compression vers le haut, sur une bande ou trois. Les passages doux montent rejoindre les forts."),
            ManualBlock(ManualKind.Bullet, "**Smash** : trois bandes écrasées des deux côtés. Les passages forts descendent, les doux montent."),
            ManualBlock(ManualKind.Heading, "Mouvement"),
            ManualBlock(ManualKind.Bullet, "**Chorus** : deux à quatre voix désaccordées qui dérivent."),
            ManualBlock(ManualKind.Bullet, "**Flanger** : un court délai qui balaie, avec une réinjection négative pour le son creux."),
            ManualBlock(ManualKind.Bullet, "**Phaser** : deux à huit étages."),
            ManualBlock(ManualKind.Bullet, "**Tremolo** : le volume sur un LFO, ou un panoramique automatique."),
            ManualBlock(ManualKind.Bullet, "**Rotary** : la cabine à haut-parleur tournant de l’orgue, lente, rapide ou sur le temps."),
            ManualBlock(ManualKind.Heading, "Hauteur"),
            ManualBlock(ManualKind.Bullet, "**Shifter** : un décalage de fréquence, pour des sons métalliques et désaccordés."),
            ManualBlock(ManualKind.Bullet, "**Harmonizer** : ajoute deux voix à des degrés de la gamme, pour qu’elles restent dans la tonalité."),
            ManualBlock(ManualKind.Bullet, "**Resonator** : des cordes accordées dans une tonalité, qui résonnent avec la piste."),
            ManualBlock(ManualKind.Bullet, "**Horn** : la piste joue d’un cuivre, d’une clarinette, d’un hautbois ou d’une flûte, en suivant sa hauteur et son niveau."),
            ManualBlock(ManualKind.Heading, "Effets d’entrée"),
            ManualBlock(ManualKind.Para, "Il y a deux autres emplacements d’effet sur l’**entrée**. Ils sont en haut de la page **enregistrer** de la fenêtre d’enregistrement (sous **gravé dans la prise**), et sur le panneau de Bias sous **imprimé**."),
            ManualBlock(ManualKind.Bullet, "Un effet **sur l’entrée** passe avant que quoi que ce soit d’autre entende l’audio, donc il est **gravé dans la prise**."),
            ManualBlock(ManualKind.Bullet, "Un effet **sur une piste** passe à la lecture, donc vous pouvez le changer plus tard."),
            ManualBlock(ManualKind.Para, "Mettez donc un ampli sur l’entrée si vous avez choisi votre son, ou sur la piste pour garder vos options. Les effets d’entrée gardent leur réglage **mélange**."),
            ManualBlock(ManualKind.Heading, "Le mixage"),
            ManualBlock(ManualKind.Para, "Le bouton de mixage ouvre une tranche par piste, plus la sortie principale. Les onglets le long du bord gauche passent du mixage aux trois pages de jeu."),
            ManualBlock(ManualKind.Bullet, "**Fader et vumètre** pour chaque piste, avec muet et solo."),
            ManualBlock(ManualKind.Bullet, "**Deux niveaux d’envoi** par piste, vers deux effets partagés par tout le morceau."),
            ManualBlock(ManualKind.Bullet, "**pano**, et une rangée MIDI pour ce que la piste envoie."),
            ManualBlock(ManualKind.Bullet, "Un **∿ à côté du nom d’une piste** veut dire que quelque chose sur ce canal est automatisé. Touchez-le pour voir quels couloirs, et pour les vider de tous les clips de la piste. Les notes ne sont pas touchées.", "Un **∿ à côté du nom d’une piste** veut dire que quelque chose sur ce canal est automatisé. Cliquez-le pour voir quels couloirs, et pour les vider de tous les clips de la piste. Les notes ne sont pas touchées."),
            ManualBlock(ManualKind.Para, "Après les pistes viennent les **groupes**, si le morceau en a, et un bouton **+ groupe**. En dernier vient la tranche principale, avec le fader général, la **sat. limiteur** et la mesure de sonie. Dessous, une grille de boutons : les deux envois en haut, les deux insertions générales (**fx1**, **fx2**) au milieu, et le limiteur (**lim**) et le clic (**♩**) en bas. Touchez-en un pour l’activer ou le désactiver, et maintenez un envoi ou une insertion pour choisir son effet et le régler.", "Après les pistes viennent les **groupes**, si le morceau en a, et un bouton **+ groupe**. En dernier vient la tranche principale, avec le fader général, la **sat. limiteur** et la mesure de sonie. Dessous, une grille de boutons : les deux envois en haut, les deux insertions générales (**fx1**, **fx2**) au milieu, et le limiteur (**lim**) et le clic (**♩**) en bas. Cliquez-en un pour l’activer ou le désactiver, et maintenez un envoi ou une insertion pour choisir son effet et le régler."),
            ManualBlock(ManualKind.Heading, "Jeu"),
            ManualBlock(ManualKind.Para, "Les onglets le long du bord gauche du mixage sont **mix**, **tenir**, **pad** et **direct**. Les trois derniers servent à jouer le morceau en direct."),
            ManualBlock(ManualKind.Para, "Les effets de **tenir** et de **pad** agissent sur tout le mixage, après les insertions générales, et ne sont actifs que pendant que vous les maintenez, sauf si **verrou** est actif. Avec le verrou, un toucher active quelque chose et un autre le désactive, et le pad reste où vous le laissez. Désactiver le verrou relâche tout sur cette page.", "Les effets de **tenir** et de **pad** agissent sur tout le mixage, après les insertions générales, et ne sont actifs que pendant que vous les maintenez, sauf si **verrou** est actif. Avec le verrou, un cliquer active quelque chose et un autre le désactive, et le pad reste où vous le laissez. Désactiver le verrou relâche tout sur cette page."),
            ManualBlock(ManualKind.Para, "Si le morceau a des groupes, **sur tout** choisit sur quoi les effets agissent : tout le mixage ou un seul groupe, par exemple pour ne répéter que la batterie. Touchez-le pour passer d’un groupe à l’autre.", "Si le morceau a des groupes, **sur tout** choisit sur quoi les effets agissent : tout le mixage ou un seul groupe, par exemple pour ne répéter que la batterie. Cliquez-le pour passer d’un groupe à l’autre."),
            ManualBlock(ManualKind.Para, "Si vous enregistrez, tout ce que vous faites sur **tenir** et **pad** est enregistré comme automatisation dans le clip de la dernière piste ouverte. Arrêter le morceau relâche tout ce qui est maintenu."),
            ManualBlock(ManualKind.Subheading, "Tenir"),
            ManualBlock(ManualKind.Bullet, "**répéter** boucle la dernière tranche du morceau. Les cinq boutons sont la longueur de la tranche, d’un temps jusqu’à une double croche, et vous pouvez glisser de l’un à l’autre sans lever le doigt. Pendant la lecture, la tranche commence sur le temps, donc elle reste en mesure."),
            ManualBlock(ManualKind.Bullet, "**gate** hache le son en mesure. Les cinq boutons sont la vitesse : croches, doubles croches, triples croches, ou triolets de croches et de doubles croches."),
            ManualBlock(ManualKind.Bullet, "**inverse** joue le dernier temps à l’envers, en boucle, en mesure avec le morceau. Maintenez-le avec une répétition et la répétition joue à l’envers."),
            ManualBlock(ManualKind.Bullet, "**arrêt** ralentit le morceau jusqu’à l’arrêt comme un magnétophone qui perd son courant, et repart quand vous relâchez. **arrêt** en dessous règle combien de temps ça prend."),
            ManualBlock(ManualKind.Bullet, "**montée** prépare un drop. Un passe-haut monte et du bruit monte dessous sur 1, 2 ou 4 mesures (**montée** en dessous), puis tout revient d’un coup quand vous relâchez."),
            ManualBlock(ManualKind.Subheading, "Pad"),
            ManualBlock(ManualKind.Para, "De gauche à droite, c’est un filtre : passe-bas à gauche du milieu et passe-haut à droite. Vers le haut, c’est la part du mixage envoyée dans un écho. Relâchez et l’écho continue de se répéter en s’éteignant. **écho** règle son temps et **retour** sa durée."),
            ManualBlock(ManualKind.Para, "**x** et **y** changent ce que fait le pad :"),
            ManualBlock(ManualKind.Bullet, "**x : crush** fait de la gauche et de la droite un bitcrusher au lieu d’un filtre, avec moins d’échantillons à gauche du milieu et moins de bits à droite. Il écrase un mixage doux autant qu’un mixage fort."),
            ManualBlock(ManualKind.Bullet, "**y : nappe** envoie dans un court écho étalé qui ressemble plus à une grosse réverbération qu’à des répétitions. Il n’a pas de réglage de temps, et **retour** règle encore sa durée."),
            ManualBlock(ManualKind.Para, "Sous le pad, **coupe grave**, **coupe médium** et **coupe aigu** retirent cette partie du son pendant que vous les maintenez : sous 250 Hz, de 250 Hz à 2,5 kHz, et au-dessus de 2,5 kHz."),
            ManualBlock(ManualKind.Subheading, "Direct"),
            ManualBlock(ManualKind.Para, "Un bouton muet pour chaque piste (le même muet que celui du mixage), et **fill**."),
            ManualBlock(ManualKind.Para, "Pendant la lecture, un muet attend la mesure suivante et tombe dessus, donc les pistes entrent et sortent en mesure. Le bouton est en contour jusque-là. **muet** règle ce qu’il attend : une mesure, un temps ou rien (**direct**). Quand le morceau est arrêté, les muets agissent tout de suite. Si vous enregistrez, les muets sont enregistrés dans le clip de chaque piste."),
            ManualBlock(ManualKind.Para, "Les notes réglées pour jouer sur fill ne jouent que pendant que **fill** est maintenu. Le fill n’est pas enregistré."),
            ManualBlock(ManualKind.Heading, "Insertions générales"),
            ManualBlock(ManualKind.Para, "**fx1** et **fx2** traitent tout le mixage, envois compris, avant le fader général et le limiteur. Servez-vous-en pour ce qui s’applique à tout le morceau, comme un EQ léger, un peu de compression de liaison, une saturation de bande ou un grave plus étroit."),
            ManualBlock(ManualKind.Para, "Un envoi s’ajoute à côté du mixage, et chaque piste choisit combien elle envoie. Une insertion générale traite tout pareil. La reverb et le delay vont donc d’habitude sur les envois, et l’EQ et la compression de tout le morceau sur les insertions générales."),
            ManualBlock(ManualKind.Heading, "Groupes"),
            ManualBlock(ManualKind.Para, "Un groupe est une tranche du mixage par laquelle des pistes peuvent passer. Il n’a ni machine ni clips, et il n’est pas dans la grille du morceau."),
            ManualBlock(ManualKind.Para, "Touchez **+ groupe** dans le mixage pour en ajouter un (jusqu’à quatre). Touchez le nom d’un groupe pour le renommer, et le **✕** à côté ou un maintien sur le nom le supprime. Dès que le morceau a un groupe, chaque tranche de piste a une rangée de plus en bas. Touchez-la pour envoyer la piste à la sortie principale ou à un des groupes.", "Cliquez **+ groupe** dans le mixage pour en ajouter un (jusqu’à quatre). Cliquez le nom d’un groupe pour le renommer, et le **✕** à côté ou un maintien sur le nom le supprime. Dès que le morceau a un groupe, chaque tranche de piste a une rangée de plus en bas. Cliquez-la pour envoyer la piste à la sortie principale ou à un des groupes."),
            ManualBlock(ManualKind.Para, "Une tranche de groupe a un fader, le pano, muet et solo, et liste les pistes qui y entrent."),
            ManualBlock(ManualKind.Para, "Tout ce qui passe par un groupe traverse ses deux effets (**fx1**, **fx2**) et son fader avant la sortie principale, donc vous pouvez mettre un seul compresseur sur toute la batterie ou baisser toute une section d’un seul fader."),
            ManualBlock(ManualKind.Bullet, "Les **envois** d’une piste vont encore directement aux effets d’envoi, sans passer par le groupe."),
            ManualBlock(ManualKind.Bullet, "Mettez un groupe en **solo** pour l’entendre au complet. Mettez en solo une piste dans un groupe pour n’entendre qu’elle, toujours à travers les effets du groupe."),
            ManualBlock(ManualKind.Bullet, "Supprimer un groupe renvoie ses pistes à la sortie principale."),
            ManualBlock(ManualKind.Bullet, "Quand vous exportez **par piste**, chaque groupe est un fichier avec ses pistes dedans, et ces pistes n’ont pas leur propre fichier."),
            ManualBlock(ManualKind.Heading, "Entrée latérale"),
            ManualBlock(ManualKind.Para, "Le compresseur, la porte et le filtre peuvent suivre une autre piste au lieu de leur propre entrée. Réglez **entrée lat.** dans l’effet sur la piste voulue. L’usage classique est un compresseur sur la basse déclenché par la grosse caisse, pour que la basse baisse à chaque coup de grosse caisse."),
            ManualBlock(ManualKind.Para, "L’entrée latérale entend l’autre piste avant son fader et son muet, donc baisser la grosse caisse n’affaiblit pas l’effet, et une grosse caisse en muet sert encore de déclencheur."),
            ManualBlock(ManualKind.Heading, "Les deux envois"),
            ManualBlock(ManualKind.Para, "Ils commencent avec une reverb et un delay, mais chacun peut tenir n’importe quel effet. Les boutons d’envoi sur la tranche principale montrent ce qu’ils contiennent. Touchez pour en activer ou désactiver un, et maintenez pour choisir et régler l’effet. Les curseurs d’envoi de chaque piste portent le nom de ce qui est sur les envois.", "Ils commencent avec une reverb et un delay, mais chacun peut tenir n’importe quel effet. Les boutons d’envoi sur la tranche principale montrent ce qu’ils contiennent. Cliquez pour en activer ou désactiver un, et maintenez pour choisir et régler l’effet. Les curseurs d’envoi de chaque piste portent le nom de ce qui est sur les envois."),
            ManualBlock(ManualKind.Para, "Un envoi est toujours 100 % traité, puisque le son direct est déjà dans le mixage, donc l’éditeur d’un envoi n’a pas de réglage de mélange."),
            ManualBlock(ManualKind.Para, "Certains effets sont amusants sur un envoi, comme un décaleur de hauteur nourri d’un peu de plusieurs pistes, ou un bitcrusher pour une copie massacrée du mixage placée derrière."),
            ManualBlock(ManualKind.Heading, "Tempo et réglages du morceau"),
            ManualBlock(ManualKind.Para, "Touchez le tempo dans l’en-tête du morceau pour ouvrir les réglages du morceau.", "Cliquez le tempo dans l’en-tête du morceau pour ouvrir les réglages du morceau."),
            ManualBlock(ManualKind.Bullet, "**bpm** : tapez un nombre ou utilisez les boutons de chaque côté. **taper** le règle à partir de quatre touchers."),
            ManualBlock(ManualKind.Bullet, "**mesure** : le chiffrage, de 4/4 à 7/8. Une scène peut avoir le sien."),
            ManualBlock(ManualKind.Bullet, "**swing** : le retard des contretemps. **triolet** est le shuffle classique. **swing sur** choisit s’il fait swinguer les doubles croches ou les croches."),
            ManualBlock(ManualKind.Bullet, "**tonalité** : la tonalité et la gamme du morceau. La grille de notes ombre les notes en dehors, et une nouvelle piste reçoit une gamme assortie. Ça ne change aucune note, ni une piste qui a sa propre gamme."),
            ManualBlock(ManualKind.Bullet, "**accordage** : comment les notes sont accordées. Maintenez-le pour la liste."),
            ManualBlock(ManualKind.Para, "Les pages **clic** et **link** sont dans la même fenêtre."),
            ManualBlock(ManualKind.Heading, "Accordages"),
            ManualBlock(ManualKind.Para, "Le tempérament égal est l’accordage habituel, avec des demi-tons tous de la même taille. Les autres rendent certains intervalles plus purs et d’autres plus rudes."),
            ManualBlock(ManualKind.Bullet, "**just** : des quintes et des tierces aussi pures que possible. Superbe dans la tonalité où il est accordé, et rude dans les tonalités éloignées."),
            ManualBlock(ManualKind.Bullet, "**pythagorean** : des quintes pures, des tierces brillantes."),
            ManualBlock(ManualKind.Bullet, "**meantone** : des tierces pures, des quintes un peu étroites."),
            ManualBlock(ManualKind.Bullet, "**werckmeister** : un tempérament inégal où chaque tonalité marche et a sa propre couleur."),
            ManualBlock(ManualKind.Bullet, "**19 equal** et **24 equal** : plus de douze notes par octave. L’octave est 19 ou 24 touches plus haut, donc le clavier joue de petits pas. 24 donne des quarts de ton."),
            ManualBlock(ManualKind.Para, "Un accordage se compte à partir de la **tonique** du morceau. La note de la tonique au milieu du clavier garde sa hauteur habituelle, donc un accordage en la laisse le la à 440 et le reste bouge autour. Changez la tonique et l’accordage suit."),
            ManualBlock(ManualKind.Para, "Une piste peut avoir son propre accordage dans ses réglages (maintenez le nom de la piste), où **morceau** veut dire qu’elle utilise celui du morceau. Les boîtes à rythmes jouent toujours en tempérament égal."),
            ManualBlock(ManualKind.Para, "Ajoutez vos propres accordages en fichiers Scala (.scl) avec **Importer…** dans le menu fichier et ils rejoignent la liste. L’accordage est enregistré dans le morceau, donc il joue pareil sur un téléphone qui n’a jamais vu le fichier."),
            ManualBlock(ManualKind.Heading, "Comment marche le swing"),
            ManualBlock(ManualKind.Para, "Le swing retarde les contretemps sans changer l’ordre des notes, donc une partie jouée librement swingue avec tout le reste."),
            ManualBlock(ManualKind.Para, "Une piste peut avoir son propre swing, comme une batterie swinguée sur une basse droite. Réglez-le dans les réglages de la piste en maintenant son nom."),
            ManualBlock(ManualKind.Para, "Ce que vous enregistrez est gardé droit. Quand vous jouez sur un morceau swingué, le swing est retiré avant que les notes soient écrites, donc la grille montre où vous vouliez mettre les notes, et baisser le swing plus tard laisse la partie droite."),
            ManualBlock(ManualKind.Para, "Le clic ne swingue jamais."),
        ), listOf(
            ManualSection("Acid", "Le filtre de Reflux sur n’importe quelle piste, balayé par ses coups ou par un motif.", listOf(
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**coupure** : où le filtre se pose, de 40 Hz à 12 kHz."),
                ManualBlock(ManualKind.Bullet, "**résonance** : combien il sonne. Vers le haut, il hurle."),
                ManualBlock(ManualKind.Bullet, "**env** : jusqu’où chaque balayage l’ouvre, jusqu’à quatre octaves."),
                ManualBlock(ManualKind.Bullet, "**déclin** : la vitesse à laquelle il retombe, de 30 ms à 3 s."),
                ManualBlock(ManualKind.Bullet, "**accent** *(extra)* : de combien un balayage accentué va plus loin, et combien il est plus fort."),
                ManualBlock(ManualKind.Bullet, "**motif** *(extra)* : ce qui lance le balayage. **piste**, c’est la piste elle-même : chaque coup l’ouvre, et un coup fort est un accent. Les huit autres sont des motifs de seize pas sur le tempo, avec des accents."),
                ManualBlock(ManualKind.Bullet, "**satur.** : de la saturation après le filtre."),
                ManualBlock(ManualKind.Bullet, "**mode** : passe-bas ou passe-bande."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son sec face au son filtré."),
                ManualBlock(ManualKind.Bullet, "**gain** : le niveau de sortie."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Sur un accord tenu avec **motif** à **16ths**, une nappe devient une ligne acide."),
                ManualBlock(ManualKind.Bullet, "Sur une boucle de batterie avec **motif** à **piste**, chaque coup aboie."),
                ManualBlock(ManualKind.Bullet, "En passe-bande avec la piste comme motif, c’est une wah qui suit le jeu."),
            )),
            ManualSection("Amp", "Un ampli de guitare avec un baffle dont on peut changer la taille.", listOf(
                ManualBlock(ManualKind.Para, "Un ampli de guitare avec toute la chaîne : un préampli, un correcteur de timbre, un étage de puissance et un baffle. Le correcteur se trouve entre le préampli et l’étage de puissance, comme sur un vrai ampli."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**satur.** et **polar.** : le préampli. La polarisation rend l’écrêtage asymétrique, pour un son plus ancien et plus feutré."),
                ManualBlock(ManualKind.Bullet, "**basse**, **médium**, **aigus** et **étage** : ils agissent les uns sur les autres comme les réglages de timbre d’un vrai ampli, donc monter les basses et les aigus creuse les médiums. **étage** (É.-U., R.-U. ou moderne) change tout le caractère de l’ampli."),
                ManualBlock(ManualKind.Bullet, "**présence** : pousse plus fort l’étage de puissance dans le haut-médium."),
                ManualBlock(ManualKind.Bullet, "**général** : à quel point l’étage de puissance est poussé. Peu de saturation avec beaucoup de général ne sonne pas comme l’inverse au même volume."),
                ManualBlock(ManualKind.Bullet, "**affaiss.** : à quel point l’alimentation fléchit quand vous jouez fort, ce qui rend l’ampli élastique."),
                ManualBlock(ManualKind.Bullet, "**baffle** : le baffle, ou rien."),
                ManualBlock(ManualKind.Bullet, "**taille** et **cône** *(extra)* : changent la taille du baffle en douceur, d’un petit combo à un 4x12 jusqu’à un gros baffle de basse, et tout ce qu’il y a entre."),
                ManualBlock(ManualKind.Bullet, "**mic**, **biseau** et **salle** : la place du micro, soit l’angle, le centre ou le bord du cône, et la distance."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son traité contre le son direct."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Réglez **satur.** et **général** avant les réglages de timbre."),
                ManualBlock(ManualKind.Bullet, "Si le son est dur, déplacez le micro avec **biseau** avant de baisser les aigus."),
                ManualBlock(ManualKind.Bullet, "Gardez **mélange** bas sur une basse ou un synthé pour un peu de grain sans perdre le grave."),
                ManualBlock(ManualKind.Bullet, "Amp est l’effet qui prend le plus de CPU. Un, ça va, une douzaine, c’est beaucoup."),
            )),
            ManualSection("Bitcrusher", "Moins de bits et une fréquence d’échantillonnage plus basse, avec une horloge instable si vous voulez.", listOf(
                ManualBlock(ManualKind.Para, "**bits** baisse la résolution et **vitesse** baisse la fréquence d’échantillonnage. Ils sonnent assez différemment, donc ils ont chacun leur réglage."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**bits** : de 16 à 1. Ajoute un bruit qui suit le signal."),
                ManualBlock(ManualKind.Bullet, "**vitesse** : de 48 kHz à 500 Hz, pour le son lo-fi métallique."),
                ManualBlock(ManualKind.Bullet, "**gigue** *(extra)* : rend l’horloge d’échantillonnage instable, comme les vieux échantillonneurs."),
                ManualBlock(ManualKind.Bullet, "**ton** *(extra)* : un passe-bas après l’écrasement pour enlever un peu de grésillement."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son traité contre le son direct."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "L’essentiel du son lo-fi vient de **vitesse**. **bits** seul ajoute surtout du souffle."),
                ManualBlock(ManualKind.Bullet, "Un peu de **gigue** fait plus penser à une vieille machine."),
                ManualBlock(ManualKind.Bullet, "Sur un envoi avec **ton** vers 4 kHz, vous obtenez une copie massacrée du morceau derrière la version propre."),
            )),
            ManualSection("Chorus", "Deux à quatre voix désaccordées qui dérivent.", listOf(
                ManualBlock(ManualKind.Para, "Un chorus fait de plusieurs voix à des délais différents, chacune balayée par sa propre partie du LFO, donc il sonne comme un groupe plutôt qu’une seule copie doublée."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**vitesse** : la vitesse du balayage des voix, en valeur de note."),
                ManualBlock(ManualKind.Bullet, "**prof.** : jusqu’où chaque voix bouge. Peu épaissit, beaucoup donne le mal de mer."),
                ManualBlock(ManualKind.Bullet, "**voix** : deux, trois ou quatre. Deux sonne comme un doublage et quatre comme un ensemble."),
                ManualBlock(ManualKind.Bullet, "**écart** : la largeur stéréo des voix."),
                ManualBlock(ManualKind.Bullet, "**dérive** *(extra)* : chaque voix erre au hasard, comme un vieux chorus analogique avec une horloge instable."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son traité contre le son direct."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Si ça sonne faux, prenez plus de voix et moins de profondeur."),
                ManualBlock(ManualKind.Bullet, "Un peu de **dérive** le rend analogique."),
                ManualBlock(ManualKind.Bullet, "Il est large au départ, donc baissez **écart** sur un lead ou une basse."),
            )),
            ManualSection("Compressor", "Les réglages habituels, une entrée latérale de n’importe quelle piste et un pompage calé sur le tempo.", listOf(
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**seuil** : le niveau à partir duquel il agit, de -60 à 0 dB."),
                ManualBlock(ManualKind.Bullet, "**ratio** : la force de la compression, de 1:1 à 20:1. Au-delà d’environ 10:1, il agit comme un limiteur."),
                ManualBlock(ManualKind.Bullet, "**attaque** : la vitesse de réaction, de 0,1 à 100 ms. Plus lent laisse passer le début de chaque coup, ce qui rend la batterie plus percutante."),
                ManualBlock(ManualKind.Bullet, "**relâche** : la vitesse à laquelle il lâche, de 10 à 1000 ms."),
                ManualBlock(ManualKind.Bullet, "**compens.** : rajoute du niveau, jusqu’à 24 dB."),
                ManualBlock(ManualKind.Bullet, "**pompage** *(extra)* : baisse le son en mesure avec le morceau, comme une entrée latérale d’une grosse caisse qui n’est pas là."),
                ManualBlock(ManualKind.Bullet, "**vit. pompe** *(extra)* : à quelle fréquence il pompe, 1/16, 1/8, 1/4 ou 1/2."),
                ManualBlock(ManualKind.Bullet, "**entrée lat.** : ce que le compresseur écoute, soit **propre** (cette piste), soit une autre piste, qui baisse celle-ci chaque fois que l’autre est forte. Il entend l’autre piste avant son fader et son muet, donc une grosse caisse en muet sert encore de déclencheur."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Sur la batterie, **attaque** change le timbre. Vers 20 ms, c’est plus percutant, et à 1 ms, plus plat."),
                ManualBlock(ManualKind.Bullet, "Pour baisser la basse sous la grosse caisse, réglez **entrée lat.** du compresseur de la basse sur la batterie, un ratio de 8:1 ou plus, l’attaque la plus rapide et une relâche de 80-150 ms, puis baissez le seuil jusqu’à ce qu’il baisse de 6-10 dB à chaque coup."),
                ManualBlock(ManualKind.Bullet, "Une vraie entrée latérale suit la vraie batterie, fills compris. **pompage** n’a besoin d’aucun routage et ne rate jamais un temps, ce qui est pratique avant que la batterie soit écrite."),
                ManualBlock(ManualKind.Bullet, "Sur la sortie principale, allez-y doucement : 2:1, avec 2-3 dB de réduction sur les passages forts."),
            )),
            ManualSection("Delay", "Des échos sur une valeur de note, qui peuvent s’atténuer pendant que vous jouez.", listOf(
                ManualBlock(ManualKind.Para, "Un delay calé sur le morceau. **temps** est une valeur de note, donc un delay à la croche pointée reste à la croche pointée quand le tempo change."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**temps** : l’écart entre les échos, de 1/32 à une mesure entière, avec les valeurs pointées et en triolet."),
                ManualBlock(ManualKind.Bullet, "**réinjection** : la part de chaque écho renvoyée dedans, jusqu’à 0,95."),
                ManualBlock(ManualKind.Bullet, "**ton** : un passe-bas sur les échos, donc chaque répétition est plus sourde que la précédente."),
                ManualBlock(ManualKind.Bullet, "**ping-pong** : à quel point les échos rebondissent entre la gauche et la droite."),
                ManualBlock(ManualKind.Bullet, "**mélange** : la part d’écho que vous entendez."),
                ManualBlock(ManualKind.Bullet, "**atténuer** *(extra)* : baisse les échos pendant que le son direct joue et les ramène dans les silences."),
                ManualBlock(ManualKind.Bullet, "**oscillation** *(extra)* : fait dériver lentement le temps du delay comme un magnétophone. Un peu le réchauffe, et plus désaccorde les échos."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Descendez **ton** à quelques kHz pour qu’une longue réinjection se fonde dans le fond au lieu de s’empiler."),
                ManualBlock(ManualKind.Bullet, "Utilisez **atténuer** au lieu de baisser le mélange pour que le delay n’écrase pas une partie."),
                ManualBlock(ManualKind.Bullet, "Sur un envoi, le delay est toujours 100 % traité, et le curseur d’envoi de chaque piste règle combien lui arrive."),
            )),
            ManualSection("Distortion", "Quatre sortes d’écrêtage et un réglage de polarisation.", listOf(
                ManualBlock(ManualKind.Para, "Une saturation jusqu’à l’écrêtage, avec un réglage de ton après."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**satur.** : à quel point le signal est poussé, de 1 à 40."),
                ManualBlock(ManualKind.Bullet, "**ton** : un passe-bas après l’écrêtage, pour calmer le grésillement."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son traité contre le son direct. Un peu de distorsion mélangée sous le son propre l’épaissit sans le salir."),
                ManualBlock(ManualKind.Bullet, "**mode** *(extra)* : doux, dur, repli ou diode. Doux arrondit les crêtes, dur les coupe net, repli change de caractère en devenant plus fort et diode est asymétrique."),
                ManualBlock(ManualKind.Bullet, "**polar.** *(extra)* : fait écrêter le haut et le bas de l’onde différemment, pour des harmoniques plus chaudes, comme un tube."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Un peu de polarisation, c’est ce qui rend une distorsion chaude."),
                ManualBlock(ManualKind.Bullet, "Repli change le timbre quand vous jouez plus fort, au lieu de juste monter le volume."),
                ManualBlock(ManualKind.Bullet, "Celle-ci n’est pas suréchantillonnée comme Amp, donc elle a quelques aspérités, exprès."),
            )),
            ManualSection("Eq", "Trois bandes et une pente.", listOf(
                ManualBlock(ManualKind.Para, "Un plateau grave, une bande médium réglable et un plateau aigu."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**gain grave** et **fréq. grave** : un plateau jusqu’à 15 dB dans un sens ou dans l’autre, de 40 à 500 Hz."),
                ManualBlock(ManualKind.Bullet, "**gain méd.**, **fréq. méd.** et **Q méd.** : la bande médium. **Q méd.** va de large (0,3) à très étroit (6)."),
                ManualBlock(ManualKind.Bullet, "**gain aigu** et **fréq. aigu** : le plateau aigu, de 1,5 à 16 kHz."),
                ManualBlock(ManualKind.Bullet, "**pente** *(extra)* : un seul bouton qui monte le haut et baisse le bas, ou l’inverse."),
                ManualBlock(ManualKind.Bullet, "**gain** : le niveau de sortie."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Couper aide en général plus qu’accentuer."),
                ManualBlock(ManualKind.Bullet, "Pour enlever une fréquence qui résonne, accentuez avec un Q étroit, balayez jusqu’à ce que ce soit pire, puis coupez. Pour changer le timbre, prenez un Q large et de petits mouvements."),
                ManualBlock(ManualKind.Bullet, "Essayez **pente** en premier quand quelque chose sonne trop sombre ou trop mince."),
            )),
            ManualSection("Filter", "Passe-bas, passe-bande ou passe-haut, déplacé par un LFO, le niveau du signal ou une autre piste.", listOf(
                ManualBlock(ManualKind.Para, "Un filtre résonant qui peut bouger tout seul, en mesure avec le morceau ou avec le son qui le traverse."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**coupure** : de 20 Hz à 20 kHz."),
                ManualBlock(ManualKind.Bullet, "**rés.** : la résonance, jusqu’au bord de l’auto-oscillation."),
                ManualBlock(ManualKind.Bullet, "**mode** : passe-bas, passe-bande ou passe-haut."),
                ManualBlock(ManualKind.Bullet, "**vit. lfo** *(extra)* : la vitesse du LFO en valeur de note, pour qu’il reste en mesure, de 1/32 à 8 mesures, avec les triolets (**T**) et les pointées (**.**) entre les deux."),
                ManualBlock(ManualKind.Bullet, "**prof. lfo** *(extra)* : jusqu’où le LFO déplace la coupure. Négatif balaie vers le bas au lieu du haut."),
                ManualBlock(ManualKind.Bullet, "**prof. env** *(extra)* : à quel point le niveau du signal déplace la coupure. Positif l’ouvre quand vous jouez plus fort (auto-wah), et négatif la ferme."),
                ManualBlock(ManualKind.Bullet, "**entrée lat.** : quel niveau le déplace, **propre** ou une autre piste. Avec une **prof. env** négative et la grosse caisse comme source, le filtre se ferme à chaque coup de grosse caisse et se rouvre après."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Une profondeur négative laisse le filtre ouvert et le fait plonger, ce qui sonne tout autrement qu’un balayage vers le haut."),
                ManualBlock(ManualKind.Bullet, "Combinez un LFO lent avec un peu d’enveloppe pour qu’il bouge avec le morceau et avec ce qui est joué."),
                ManualBlock(ManualKind.Bullet, "La résonance et le passe-bande font perdre du niveau, donc rattrapez-le avec **gain**."),
                ManualBlock(ManualKind.Bullet, "Pour un wobble dubstep, mettez-le après une basse épaisse et partez d’un son **wobble**. Un wobble parle en changeant de vitesse : verrouillez **vit. lfo** sur les pas (1/4, 1/8, 1/8T, 1/16), ou assignez-le à un bouton ou à la molette de modulation et jouez-le. Une distorsion après le rend plus méchant. Les sons de basse **Wobble** et **Wub** de Trinity ont la même chose intégrée, sur le **sync** du LFO 1."),
            )),
            ManualSection("Flanger", "Un court délai qui balaie, avec une réinjection négative pour le son creux.", listOf(
                ManualBlock(ManualKind.Para, "Un seul délai très court, balayé et mélangé au son direct."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**vitesse** : la vitesse du balayage, en valeur de note."),
                ManualBlock(ManualKind.Bullet, "**prof.** : jusqu’où va le balayage."),
                ManualBlock(ManualKind.Bullet, "**réinjection** : jusqu’à 0,95. Bas, c’est un souffle doux, et haut, c’est l’avion à réaction."),
                ManualBlock(ManualKind.Bullet, "**négatif** *(extra)* : inverse la réinjection pour un son creux plutôt que résonnant."),
                ManualBlock(ManualKind.Bullet, "**écart** : le décalage entre les balayages des deux canaux."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son traité contre le son direct. La moitié donne l’effet le plus fort."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Gardez le mélange vers la moitié, puisque 100 % traité perd l’essentiel de l’effet."),
                ManualBlock(ManualKind.Bullet, "Essayez **négatif** sur des accords tenus."),
                ManualBlock(ManualKind.Bullet, "Une vitesse lente et une petite profondeur sur un envoi donnent un peu de mouvement à un mixage."),
            )),
            ManualSection("Formula", "Tapez une formule et elle façonne la piste, échantillon par échantillon.", listOf(
                ManualBlock(ManualKind.Para, "Formula emploie le même petit langage que la machine Formulate : des nombres entiers et les opérateurs du C (`+ - * / % & | ^ << >>`, comparaisons, `? :`) et `sin`, `abs`, `min` et `max`. La piste entre comme `x`, de 0 à 255, le silence à 128. Ce que la formule donne, pris de 0 à 255, ressort. Ainsi `x` seul, c’est la piste réduite à huit bits, et tout le reste la tord à partir de là."),
                ManualBlock(ManualKind.Para, "Touchez **modifier…** au-dessus des boutons pour en écrire une, ou choisissez un exemple pour commencer. La formule n’est appliquée que quand vous appuyez sur OK, et si elle ne peut pas être lue, la raison s’affiche en rouge. Sans formule, la piste passe intacte.", "Cliquez **modifier…** au-dessus des boutons pour en écrire une, ou choisissez un exemple pour commencer. La formule n’est appliquée que quand vous appuyez sur OK, et si elle ne peut pas être lue, la raison s’affiche en rouge. Sans formule, la piste passe intacte."),
                ManualBlock(ManualKind.Heading, "Ce qu’une formule peut lire"),
                ManualBlock(ManualKind.Bullet, "**x** : la piste, de 0 à 255."),
                ManualBlock(ManualKind.Bullet, "**t** : un compteur qui monte à la **vitesse**."),
                ManualBlock(ManualKind.Bullet, "**a**, **b**, **c** : les trois boutons, de 0 à 255."),
                ManualBlock(ManualKind.Bullet, "**r** : un nombre aléatoire neuf, de 0 à 255, à chaque échantillon."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**a**, **b**, **c** : lus par la formule, ou ignorés si elle ne s’en sert pas."),
                ManualBlock(ManualKind.Bullet, "**vitesse** *(extra)* : à quelle vitesse `t` compte, de 1 à 48 kHz. À 8 kHz, la plupart des formules écrites pour ce genre de chose sonnent comme prévu."),
                ManualBlock(ManualKind.Bullet, "**satur.** : pousse la piste plus fort dans la formule, jusqu’à 24 dB."),
                ManualBlock(ManualKind.Bullet, "**lisse** *(extra)* : adoucit les marches que laisse la formule. Au maximum, il est coupé."),
                ManualBlock(ManualKind.Bullet, "**mélange** : la piste sèche face à celle de la formule."),
                ManualBlock(ManualKind.Bullet, "**gain** : le niveau de sortie."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "`x & (255 << (a >> 5))` jette des bits à mesure que **a** monte."),
                ManualBlock(ManualKind.Bullet, "`t >> 11 & 1 ? x : 128` coupe la piste au rythme du compteur."),
                ManualBlock(ManualKind.Bullet, "La sortie reste toujours sous le plein niveau, mais elle peut être dure : commencez avec **mélange** bas ou **lisse** baissé."),
            )),
            ManualSection("Gate", "Une porte de bruit, avec un filtre sur ce qu’elle écoute et une entrée latérale.", listOf(
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**seuil** : le niveau où elle s’ouvre, de -80 à 0 dB."),
                ManualBlock(ManualKind.Bullet, "**hyst.** : de combien le signal doit descendre sous le seuil avant qu’elle se ferme, jusqu’à 24 dB, pour qu’elle ne clignote pas sur une note proche du seuil."),
                ManualBlock(ManualKind.Bullet, "**attaque** : la vitesse d’ouverture, de 0,05 à 50 ms."),
                ManualBlock(ManualKind.Bullet, "**tenir** : combien de temps elle reste ouverte après la baisse du signal, jusqu’à 500 ms."),
                ManualBlock(ManualKind.Bullet, "**relâche** : la vitesse de fermeture une fois le maintien fini."),
                ManualBlock(ManualKind.Bullet, "**atténuer** *(extra)* : jusqu’où descend la porte fermée. À fond, c’est une porte complète, et vers -12 dB, ça convient à la batterie."),
                ManualBlock(ManualKind.Bullet, "**clavier** *(extra)* : un filtre passe-haut sur ce que la porte écoute, pas sur le son. Montez-le pour que la porte ignore le ronflement et le grondement mais s’ouvre encore pour les notes."),
                ManualBlock(ManualKind.Bullet, "**entrée lat.** : ce qui l’ouvre, **propre** ou une autre piste. Le filtre **clavier** s’applique quand même."),
                ManualBlock(ManualKind.Para, "Il n’y a pas de réglage de mélange, puisqu’une porte à moitié ouverte ne serait que le bruit à moitié du niveau."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Si elle claque, allongez **tenir** avant de toucher à la relâche.", "Si elle claque, allongez **tenir** avant de cliquer à la relâche."),
                ManualBlock(ManualKind.Bullet, "Pour une guitare avec un ronflement du secteur, réglez **clavier** vers 120 Hz."),
                ManualBlock(ManualKind.Bullet, "Déclenchez la porte d’une nappe tenue par la piste de charleston pour la hacher en rythme, avec **atténuer** vers -12 dB pour que les trous ne soient pas silencieux."),
                ManualBlock(ManualKind.Bullet, "Avant un ampli, elle enlève le souffle du micro de guitare, et après, celui de l’ampli. Sur un emplacement d’entrée, elle nettoie l’enregistrement lui-même."),
            )),
            ManualSection("Grain", "Un nuage de courtes tranches de ce que la piste vient de jouer.", listOf(
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**taille** : la longueur de chaque grain, de 5 à 500 ms."),
                ManualBlock(ManualKind.Bullet, "**densité** : combien de grains commencent par seconde, de 1 à 100."),
                ManualBlock(ManualKind.Bullet, "**dispers.** : jusqu’où ils peuvent remonter dans les quatre dernières secondes. À 0 ils suivent la partie de près, à 1 ils viennent de partout."),
                ManualBlock(ManualKind.Bullet, "**hauteur** : la hauteur où ils jouent, deux octaves dans chaque sens."),
                ManualBlock(ManualKind.Bullet, "**épars** : la probabilité qu’un grain saute d’une octave en haut ou en bas."),
                ManualBlock(ManualKind.Bullet, "**inverser** : la probabilité qu’un grain joue à l’envers."),
                ManualBlock(ManualKind.Bullet, "**figer** *(extra)* : arrête d’écouter, et le nuage continue de jouer ce qu’il a. Un interrupteur pour jouer en direct."),
                ManualBlock(ManualKind.Bullet, "**réinjection** *(extra)* : renvoie le nuage dans ce qu’il écoute, et il se nourrit de lui-même."),
                ManualBlock(ManualKind.Bullet, "**largeur** : l’étalement des grains dans la stéréo."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son sec face au nuage."),
                ManualBlock(ManualKind.Bullet, "**gain** : le niveau de sortie."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Assignez **figer** à un bouton et attrapez la fin d’une phrase pour la tenir sous la suivante."),
                ManualBlock(ManualKind.Bullet, "Des grains longs avec un peu de **dispers.** floutent une partie. Des courts avec beaucoup font un essaim."),
                ManualBlock(ManualKind.Bullet, "**réinjection** avec **hauteur** à +7 donne un nuage qui monte par quintes."),
            )),
            ManualSection("Harmonizer", "Ajoute deux voix à des degrés de la gamme, pour qu’elles restent dans la tonalité.", listOf(
                ManualBlock(ManualKind.Para, "Un décaleur de hauteur qui connaît la tonalité. Vous réglez les intervalles en degrés de la gamme plutôt qu’en demi-tons, donc une tierce sort majeure ou mineure selon la note, comme une vraie partie d’harmonie."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**intervalle** et **intervalle2** : les deux voix ajoutées, de -7 à +7 degrés."),
                ManualBlock(ManualKind.Bullet, "**gamme** *(extra)* : la gamme où les degrés sont comptés, dans la même liste que le modificateur Scale."),
                ManualBlock(ManualKind.Bullet, "**tonalité** *(extra)* : la tonalité."),
                ManualBlock(ManualKind.Bullet, "**fenêtre** : de 10 à 120 ms. Court suit les parties rapides mais sonne plus granuleux, et long est plus doux mais brouille les attaques."),
                ManualBlock(ManualKind.Bullet, "**réinjection** : renvoie la sortie dedans, en empilant l’intervalle sur lui-même."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son traité contre le son direct."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Réglez la tonalité, sinon ce n’est qu’un décaleur de hauteur et certaines tierces seront fausses."),
                ManualBlock(ManualKind.Bullet, "Sur la batterie ou tout ce qui est percussif, prenez une fenêtre courte (vers 20 ms)."),
                ManualBlock(ManualKind.Bullet, "Une quinte ou une octave en dessous est souvent plus utile qu’une tierce au dessus, et trahit moins les défauts de justesse."),
                ManualBlock(ManualKind.Bullet, "Deux degrés avec de la réinjection empilent un accord."),
            )),
            ManualSection("Horn", "La piste joue d’un instrument à vent.", listOf(
                ManualBlock(ManualKind.Para, "Horn écoute la hauteur de la piste et son volume, et joue la même ligne sur un cuivre, une clarinette, un hautbois ou une flûte : le niveau devient le souffle. Il suit une note à la fois : donnez-lui une mélodie, une ligne de basse ou une voix plutôt que des accords. Chantez dans une piste d’entrée et vous jouez de la trompette."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**type** : **laiton** (un cuivre), **clarinette** (une anche simple), **hautbois** (une anche double) ou **flûte** (un biseau)."),
                ManualBlock(ManualKind.Bullet, "**octave** : joue jusqu’à deux octaves de la piste."),
                ManualBlock(ManualKind.Bullet, "**ton** : le mordant des lèvres sur le cuivre, ou la raideur de l’anche."),
                ManualBlock(ManualKind.Bullet, "**Cloche** : à quel point le pavillon laisse sortir un son brillant."),
                ManualBlock(ManualKind.Bullet, "**air** : le bruit du souffle."),
                ManualBlock(ManualKind.Bullet, "**porta.** : à quelle vitesse il passe à une nouvelle note, de 1 à 500 ms."),
                ManualBlock(ManualKind.Bullet, "**souffle** *(extra)* : à quel point un niveau donné le fait sonner fort. Montez-le pour une piste discrète."),
                ManualBlock(ManualKind.Bullet, "**aimant** *(extra)* : **libre** suit la hauteur telle quelle, glissés compris ; **demi-ton** pose chaque note sur un demi-ton."),
                ManualBlock(ManualKind.Bullet, "**mélange** : la piste sèche face à l’instrument."),
                ManualBlock(ManualKind.Bullet, "**gain** : le niveau de sortie."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "**Low Brass** sous une ligne de basse la double d’un cuivre grave."),
                ManualBlock(ManualKind.Bullet, "**Sung Brass** sur une partie chantée ajoute un cuivre qui suit la voix."),
                ManualBlock(ManualKind.Bullet, "S’il hésite entre deux notes, montez **porta.** ou passez **aimant** sur **demi-ton**."),
            )),
            ManualSection("Magneto", "Le son d’un petit disque enregistrable, dans chacun de ses formats.", listOf(
                ManualBlock(ManualKind.Para, "Ces disques contenaient plus qu’ils n’avaient de place en jetant ce que l’oreille risquait le moins de regretter. Chaque format en jetait plus que le précédent, et ce qu’il jetait, c’est le son. Magneto fait de même : la piste est coupée en trames courtes, chacune divisée en bandes, et chaque trame n’a que tant de bits à dépenser."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**mode** : le format : - **SP** : l’original. Le haut reste presque entier, avec un grain fin dans les médiums et les aigus. - **LP2** : moitié moins de bits. Le haut est coupé un peu sous 16 kHz, il devient granuleux et les coups bavent un peu. - **LP4** : encore moitié moins, la gauche et la droite partageant leurs bits. Les aigus vont et viennent sous la coupure à 14 kHz, les détails aigus discrets disparaissent et le haut-médium se resserre presque en mono. - **HQ** : le format plus récent à haut débit. Le plus propre, presque transparent. - **XLP** : le format plus récent à son débit le plus bas, entre LP2 et LP4."),
                ManualBlock(ManualKind.Bullet, "**copies** *(extra)* : recopie encore, de une à quatre générations, chacune perdant un peu plus, comme quand un disque était enregistré depuis un autre."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son sec face à la copie."),
                ManualBlock(ManualKind.Bullet, "**gain** : le niveau de sortie."),
                ManualBlock(ManualKind.Para, "La copie suit la piste avec un peu de retard : environ 20 ms par génération. Le son sec de **mélange** est retardé d’autant, pour que les deux restent ensemble."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "**LP4** sur tout un mix, c’est tout de suite le baladeur de la fin des années quatre-vingt-dix."),
                ManualBlock(ManualKind.Bullet, "**Fourth Generation** sur des nappes et des claviers les rend aqueux et tourbillonnants."),
                ManualBlock(ManualKind.Bullet, "Baissez **mélange** pour garder le grain sans perdre le haut."),
            )),
            ManualSection("Mouth", "La gorge de Diction sur n’importe quelle piste : ce qui la traverse devient une voyelle.", listOf(
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**voyelle** : ou, o, a, è, i du bas vers le haut."),
                ManualBlock(ManualKind.Bullet, "**taille** : la taille de la gorge, grande et sombre à petite et brillante."),
                ManualBlock(ManualKind.Bullet, "**nasal** : ouvre le nez."),
                ManualBlock(ManualKind.Bullet, "**bouger** *(extra)* : ce qui bouge la voyelle : un **lfo** sur le tempo, le **niveau** de la piste (plus fort ouvre la bouche), ou une autre piste par l’**entrée lat.** (**key**)."),
                ManualBlock(ManualKind.Bullet, "**vitesse** : la valeur de note du LFO."),
                ManualBlock(ManualKind.Bullet, "**prof.** : jusqu’où la voyelle bouge depuis son réglage."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son sec face à la voyelle."),
                ManualBlock(ManualKind.Bullet, "**gain** : le niveau de sortie."),
                ManualBlock(ManualKind.Bullet, "**entrée lat.** : la piste qui la fait bouger quand **bouger** est sur **key**."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Sur un lead avec **bouger** sur le niveau, les notes plus fortes disent « a »."),
                ManualBlock(ManualKind.Bullet, "Pointez l’entrée latérale sur une boucle de batterie et une nappe parle à son rythme."),
                ManualBlock(ManualKind.Bullet, "Un balayage lent de ou à a sonne comme une wah jouée par une voix."),
            )),
            ManualSection("Phaser", "Deux à huit étages.", listOf(
                ManualBlock(ManualKind.Para, "Des creux qui balaient, faits d’une chaîne de filtres passe-tout. Les creux ne sont pas espacés régulièrement comme ceux d’un flanger, ce qui donne au phaser son propre son."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**vitesse** : la vitesse du balayage, en valeur de note."),
                ManualBlock(ManualKind.Bullet, "**prof.** : jusqu’où vont les creux."),
                ManualBlock(ManualKind.Bullet, "**réinjection** : jusqu’à 0,9. Fait résonner les creux."),
                ManualBlock(ManualKind.Bullet, "**étages** : deux, quatre, six ou huit. Plus d’étages donne plus de creux et un effet plus fort."),
                ManualBlock(ManualKind.Bullet, "**écart** *(extra)* : décale les balayages des deux canaux pour que ce soit large. Superbe sur les nappes."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son traité contre le son direct."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Changez **étages** en premier pour régler le caractère. Quatre, c’est la pédale classique."),
                ManualBlock(ManualKind.Bullet, "Plus de réinjection rend le balayage plus évident."),
                ManualBlock(ManualKind.Bullet, "Un phaser lent sur un envoi ajoute du mouvement sans se faire remarquer."),
            )),
            ManualSection("Resonator", "Des cordes accordées dans une tonalité, qui résonnent avec la piste.", listOf(
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**tonalité** et **gamme** : la tonalité des cordes. Réglez-les sur celles du morceau."),
                ManualBlock(ManualKind.Bullet, "**grave** : la corde la plus grave, en note. Les cordes montent la gamme à partir de la première note de la tonalité à ce niveau ou au-dessus."),
                ManualBlock(ManualKind.Bullet, "**cordes** : combien, de 4 à 16."),
                ManualBlock(ManualKind.Bullet, "**déclin** : combien de temps elles résonnent, de 0,2 à 12 s."),
                ManualBlock(ManualKind.Bullet, "**ton** : leur brillance."),
                ManualBlock(ManualKind.Bullet, "**métal** *(extra)* : de la raideur dans les cordes, qui fait monter leurs harmoniques, d’une corde vers une cloche."),
                ManualBlock(ManualKind.Bullet, "**largeur** : l’écart entre cordes graves et aiguës dans la stéréo."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son sec face aux cordes."),
                ManualBlock(ManualKind.Bullet, "**gain** : le niveau de sortie."),
                ManualBlock(ManualKind.Para, "Une note de la tonalité fait résonner ses cordes. Une note hors de la tonalité presque pas, et une partie dans le ton s’épanouit comme les cordes libres d’un sitar ou d’un piano pédale enfoncée."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Sur la batterie, chaque coup prend une hauteur dans la tonalité."),
                ManualBlock(ManualKind.Bullet, "Un **déclin** long avec un **grave** bas fait de la partie un bourdon."),
                ManualBlock(ManualKind.Bullet, "Mettez-le sur un envoi : plusieurs pistes font résonner les mêmes cordes."),
            )),
            ManualSection("Reverb", "Une salle qui peut aussi se figer, se couper, miroiter ou s’écraser.", listOf(
                ManualBlock(ManualKind.Para, "Une réverbération avec la taille, l’amortissement et le prédélai habituels, plus quelques extras."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**taille** : la grandeur de l’espace."),
                ManualBlock(ManualKind.Bullet, "**amortir** : à quel point la salle absorbe. Amortie, elle sonne comme du tapis, et sans amortissement, comme de la céramique."),
                ManualBlock(ManualKind.Bullet, "**ton** : un passe-bas sur la queue de réverbération."),
                ManualBlock(ManualKind.Bullet, "**prédélai** : un écart avant que la réverbération commence, jusqu’à 200 ms."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son traité contre le son direct."),
                ManualBlock(ManualKind.Bullet, "**figer** *(extra)* : tient la queue pour toujours."),
                ManualBlock(ManualKind.Bullet, "**gate** *(extra)* : coupe la queue net, pour la caisse claire à porte classique des années 80."),
                ManualBlock(ManualKind.Bullet, "**miroitement** *(extra)* : renvoie la queue une octave plus haut, donc un accord tenu continue de monter."),
                ManualBlock(ManualKind.Bullet, "**bits** et **écraser** *(extra)* : réduction de bits et de fréquence d’échantillonnage sur la queue seulement."),
                ManualBlock(ManualKind.Bullet, "**oscillation** *(extra)* : fait dériver un peu la queue pour qu’elle ne soit jamais tout à fait immobile."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Si la réverbération rend le son brouillé, essayez 30-60 ms de **prédélai** avant de la rapetisser."),
                ManualBlock(ManualKind.Bullet, "Le miroitement marche mieux avec un mélange bas et une longue queue."),
                ManualBlock(ManualKind.Bullet, "Mettez **bits** et **écraser** sur un envoi pour une copie lo-fi du mixage derrière la version propre."),
            )),
            ManualSection("Rotary", "La cabine à haut-parleur tournant de l’orgue, pour n’importe quelle piste.", listOf(
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**vitesse** : frein, lent ou rapide."),
                ManualBlock(ManualKind.Bullet, "**lent** : la vitesse du pavillon en lent, de 0,1 à 2 Hz."),
                ManualBlock(ManualKind.Bullet, "**rapide** : sa vitesse en rapide, de 2 à 10 Hz. Le tambour tourne un peu moins vite que le pavillon dans les deux cas."),
                ManualBlock(ManualKind.Bullet, "**rampe** : le temps que mettent les rotors pour atteindre une nouvelle vitesse. Ralentir prend presque deux fois plus longtemps, comme avec les vrais moteurs."),
                ManualBlock(ManualKind.Bullet, "**distance** : l’éloignement des micros. Près, l’effet balance fort ; loin, doucement."),
                ManualBlock(ManualKind.Bullet, "**angle** : l’écart entre les deux micros."),
                ManualBlock(ManualKind.Bullet, "**largeur** : la part de stéréo que donnent les micros."),
                ManualBlock(ManualKind.Bullet, "**tempo** *(extra)* : le pavillon fait un tour par valeur de note (de 1/1 à 1/8 de triolet) au lieu de sa propre vitesse, et le tourbillon tombe sur le temps."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son sec face à la cabine."),
                ManualBlock(ManualKind.Bullet, "**gain** : le niveau de sortie."),
                ManualBlock(ManualKind.Para, "La cabine n’a qu’une entrée : une piste stéréo est additionnée avant, comme pour un orgue."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Automatisez **vitesse** entre lent et rapide et laissez **rampe** faire le reste. L’accélération et le ralentissement font le son."),
                ManualBlock(ManualKind.Bullet, "Sur une guitare ou un piano électrique, **mélange** vers 0,6 garde l’attaque nette."),
                ManualBlock(ManualKind.Bullet, "Avec **tempo**, une nappe pulse en rythme sans LFO à régler."),
            )),
            ManualSection("Shifter", "Un décalage de fréquence, pour des sons métalliques et désaccordés.", listOf(
                ManualBlock(ManualKind.Para, "Un décaleur de fréquence monte ou descend chaque harmonique d’un son du même nombre de hertz, donc le son n’est plus juste avec lui-même. Un décaleur de hauteur, lui, garde leurs proportions."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**décalage** : de -500 à +500 Hz. Les petites valeurs sont les plus utiles."),
                ManualBlock(ManualKind.Bullet, "**précis** : ±20 Hz, pour de tout petits décalages qui battent lentement."),
                ManualBlock(ManualKind.Bullet, "**écart** *(extra)* : décale les deux canaux dans des sens opposés. Quelques hertz rendent un son mono large et tournoyant."),
                ManualBlock(ManualKind.Bullet, "**réinjection** : renvoie la sortie dedans pour qu’elle soit décalée à chaque passage, pour des cascades métalliques."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son traité contre le son direct."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Sous 1 Hz, c’est une modulation très lente et large. Superbe sur les nappes."),
                ManualBlock(ManualKind.Bullet, "Quelques hertz ou plus font sonner les notes tenues fausses avec elles-mêmes, ce qui est superbe sur la batterie, les cloches et le bruit, et d’habitude raté sur les accords."),
                ManualBlock(ManualKind.Bullet, "La réinjection avec un petit décalage change un coup en échelle métallique qui monte."),
            )),
            ManualSection("Slicer", "La piste coupée sur le tempo, certaines tranches répétées, inversées ou omises.", listOf(
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**vitesse** : la tranche : une noire, une croche, une double ou une triple croche."),
                ManualBlock(ManualKind.Bullet, "**proba** : la probabilité qu’une tranche change."),
                ManualBlock(ManualKind.Bullet, "**répéter**, **inverser**, **omettre** : les proportions de ce que fait une tranche changée : répéter la précédente, la jouer à l’envers, ou se taire."),
                ManualBlock(ManualKind.Bullet, "**Gate** : raccourcit chaque tranche."),
                ManualBlock(ManualKind.Bullet, "**hauteur** *(extra)* : décale les répétitions, d’une octave dans chaque sens."),
                ManualBlock(ManualKind.Bullet, "**graine** *(extra)* : quelles tranches changent. Les mêmes changent à chaque lecture du morceau, et on peut écrire une partie autour."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son sec face au son tranché."),
                ManualBlock(ManualKind.Bullet, "**gain** : le niveau de sortie."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Sur une boucle de batterie, **Stutter** ajoute des breaks que vous n’avez pas programmés."),
                ManualBlock(ManualKind.Bullet, "Essayez des graines jusqu’à ce qu’une mesure sonne juste ; elle restera ainsi."),
                ManualBlock(ManualKind.Bullet, "Avec **proba** à 0, **Gate** seul hache une nappe en rythme."),
            )),
            ManualSection("Smash", "Trois bandes, chacune écrasée par le haut et relevée par le bas.", listOf(
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**prof.** : la part mélangée à la piste telle qu’elle était. Un peu, c’est de la densité et de la présence ; tout, c’est chaque queue et chaque souffle remontés au niveau des coups."),
                ManualBlock(ManualKind.Bullet, "**temps** : règle ensemble l’attaque et la relâche de chaque bande. Lent, c’est doux ; rapide, ça pompe et ça grince."),
                ManualBlock(ManualKind.Bullet, "**seuil** : le niveau vers lequel chaque bande est poussée, de -48 à 0 dB."),
                ManualBlock(ManualKind.Bullet, "**bas** : la force avec laquelle ce qui dépasse le seuil est poussé vers le bas."),
                ManualBlock(ManualKind.Bullet, "**haut** *(extra)* : la force avec laquelle ce qui est en dessous est remonté. Le souffle et le ronflement très bas restent en bas."),
                ManualBlock(ManualKind.Bullet, "**grave**, **médium**, **aigu** : le niveau de chaque bande après, ±12 dB. Les bandes sont coupées à 300 Hz et 5 kHz."),
                ManualBlock(ManualKind.Bullet, "**entrée** : le pousse plus fort, jusqu’à +24 dB."),
                ManualBlock(ManualKind.Bullet, "**gain** : le niveau de sortie."),
                ManualBlock(ManualKind.Para, "À une profondeur de 0, ou avec **haut** et **bas** à 0, la piste passe intacte."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Sur une basse qui disparaît dans le haut-parleur d’un téléphone, **Loud** la met devant."),
                ManualBlock(ManualKind.Bullet, "Sur un envoi de réverbération ou d’écho, **Air** remonte les queues sans toucher aux coups.", "Sur un envoi de réverbération ou d’écho, **Air** remonte les queues sans cliquer aux coups."),
                ManualBlock(ManualKind.Bullet, "Un **temps** rapide avec **entrée** montée fait grogner une basse."),
            )),
            ManualSection("Spectral", "La piste décomposée en fréquences et remise ensemble.", listOf(
                ManualBlock(ManualKind.Para, "Environ quarante fois par seconde, Spectral sépare le son en ses fréquences, les modifie et le reconstruit. Sans rien tourner, ce qui sort est ce qui est entré."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**figer** *(extra)* : **tenir** garde le son tel qu’il est à cet instant, un accord ou une voyelle qui dure tant qu’il est tenu. **marche** le relâche."),
                ManualBlock(ManualKind.Bullet, "**traîne** : laisse chaque fréquence s’éteindre au lieu de s’arrêter, si bien que les notes se fondent. Au maximum, une note traîne des secondes."),
                ManualBlock(ManualKind.Bullet, "**flou** : brouille le timing dans chaque tranche, pour un son lavé, lointain, chuchoté."),
                ManualBlock(ManualKind.Bullet, "**robot** : jette le timing, pour une voix plate et bourdonnante."),
                ManualBlock(ManualKind.Bullet, "**crêtes** *(extra)* : ne garde que les fréquences les plus fortes, un son vitreux et sifflant. Plus haut, il en reste moins."),
                ManualBlock(ManualKind.Bullet, "**pente** : penche le tout vers le sombre ou le brillant, autour de 1 kHz."),
                ManualBlock(ManualKind.Bullet, "**mélange** : la piste sèche face à la piste modifiée."),
                ManualBlock(ManualKind.Bullet, "**gain** : le niveau de sortie."),
                ManualBlock(ManualKind.Para, "Le son modifié suit la piste avec environ 40 ms de retard. Le son sec de **mélange** est retardé d’autant, pour que les deux restent ensemble."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Assignez **figer** à un bouton et tenez un accord sous la partie suivante."),
                ManualBlock(ManualKind.Bullet, "**Robot Voice** sur une piste chantée ou parlée, c’est le robot plat classique."),
                ManualBlock(ManualKind.Bullet, "**Ice** sur une nappe ou un piano laisse un scintillement vitreux de ses notes les plus fortes."),
            )),
            ManualSection("Swell", "Une compression vers le haut : les passages doux montent rejoindre les forts, sur une bande ou trois.", listOf(
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**plancher** : tout ce qui est plus fort que ce niveau est remonté, de -80 à 0 dB. Ce qui est plus de 12 dB en dessous reste exactement comme avant, donc le souffle et le ronflement au fond d’un enregistrement ne bougent pas."),
                ManualBlock(ManualKind.Bullet, "**plafond** : le niveau vers lequel tout ce qui dépasse le plancher est tiré, de -30 à 0 dB. Un son déjà au-dessus du plafond est ramené à lui."),
                ManualBlock(ManualKind.Bullet, "**intensité** : de combien. À 0 rien ne bouge, à 1 chaque son au-dessus du plancher arrive au plafond, et à mi-course il fait la moitié du chemin."),
                ManualBlock(ManualKind.Bullet, "**partage** *(extra)* : d’une bande (0) à trois (1), coupées à 300 Hz et 5 kHz. Partagé, un aigu discret ou un grave maigre remonte tout seul, et c’est de là que viennent l’air et le souffle. Les bandes se recombinent exactement en l’entrée, donc le partage ne change jamais un son qui n’est pas remonté."),
                ManualBlock(ManualKind.Bullet, "**relâche** : la vitesse à laquelle il relâche après un moment fort, de 5 ms à 2 s. Lent, c’est proche d’une normalisation et la forme d’une phrase est gardée. Rapide, il suit chaque coup, et très rapide, il suit la forme d’onde elle-même et devient une distorsion."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son sec face au son remonté."),
                ManualBlock(ManualKind.Bullet, "**gain** : le niveau de sortie, pour compenser ce qu’il ajoute."),
                ManualBlock(ManualKind.Para, "Il regarde quelques échantillons en avance, pour qu’un son fort soudain soit déjà baissé quand il arrive. C’est 8 échantillons, moins de 0,2 ms."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Partez du préréglage **Loud** sur un bus et montez **intensité** jusqu’à ce que les passages doux soient où vous les voulez."),
                ManualBlock(ManualKind.Bullet, "Pour la batterie, **Room** remonte tout ce qui se passe entre les coups. Baissez **plancher** pour remonter davantage la pièce."),
                ManualBlock(ManualKind.Bullet, "Pour un mur de son, poussez **intensité** à 1 et **relâche** sous 50 ms, puis baissez **mélange** jusqu’à ce que la dynamique revienne."),
                ManualBlock(ManualKind.Bullet, "Sur un envoi de réverbération ou d’écho, il remonte les queues, et une réverbération courte sonne comme une longue."),
                ManualBlock(ManualKind.Bullet, "Réglez **plafond** quelques dB sous celui du limiteur du master pour qu’ils ne se battent pas."),
            )),
            ManualSection("Tape", "Un magnétophone usé, et un bouton d’arrêt.", listOf(
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**wow** : une dérive lente de la vitesse, et donc de la hauteur."),
                ManualBlock(ManualKind.Bullet, "**flutter** : un tremblement rapide de la vitesse."),
                ManualBlock(ManualKind.Bullet, "**satur.** : de la saturation, comme une bande poussée fort."),
                ManualBlock(ManualKind.Bullet, "**ton** : où les aigus tombent, de 2 à 20 kHz."),
                ManualBlock(ManualKind.Bullet, "**sifflement** : le bruit dessous."),
                ManualBlock(ManualKind.Bullet, "**âge** : l’usure : le wow est moins régulier et le grave se gonfle."),
                ManualBlock(ManualKind.Bullet, "**arrêt** *(extra)* : ralentit la bande jusqu’à l’arrêt, la hauteur tombant avec elle. Coupé, elle repart aussitôt à vitesse normale."),
                ManualBlock(ManualKind.Bullet, "**durée arrêt** *(extra)* : combien de temps prend l’arrêt, de 0,1 à 4 s."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son sec face à la bande."),
                ManualBlock(ManualKind.Bullet, "**gain** : le niveau de sortie."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Assignez **arrêt** à un bouton et servez-vous-en à la fin d’une phrase."),
                ManualBlock(ManualKind.Bullet, "**Cassette** sur tout un mix le fait sonner comme une bande trouvée dans un tiroir."),
                ManualBlock(ManualKind.Bullet, "**Seasick** sur des claviers et des nappes les fait dériver."),
            )),
            ManualSection("Tremolo", "Le volume sur un LFO, ou un panoramique automatique.", listOf(
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**vitesse** : la vitesse des pulsations, en valeur de note."),
                ManualBlock(ManualKind.Bullet, "**prof.** : la profondeur de chaque creux. À fond, le son se coupe entre les pulsations."),
                ManualBlock(ManualKind.Bullet, "**forme** : sinus, triangle ou carré. Carré donne un son haché."),
                ManualBlock(ManualKind.Bullet, "**pano** *(extra)* : décale les deux canaux. À zéro, c’est un trémolo, à fond, un panoramique automatique, et entre les deux, ça ondule."),
                ManualBlock(ManualKind.Bullet, "**biais** *(extra)* : change la forme de chaque pulsation, soit une attaque sèche (descente rapide, remontée lente), soit une montée (descente lente, remontée rapide)."),
                ManualBlock(ManualKind.Bullet, "**mélange** : le son traité contre le son direct, ce qui sur un trémolo est en fait la profondeur."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "La forme carrée avec **biais** à fond à la double croche change un accord tenu en rythme."),
                ManualBlock(ManualKind.Bullet, "Essayez **pano** vers le tiers pour un mouvement qui ne s’arrête jamais d’un côté."),
            )),
            ManualSection("Width", "Plus large, plus étroit, mono sous une fréquence ou tourné.", listOf(
                ManualBlock(ManualKind.Para, "Règle l’image stéréo."),
                ManualBlock(ManualKind.Heading, "Les réglages"),
                ManualBlock(ManualKind.Bullet, "**largeur** : 0 est mono, 1 ne change rien et 2 est deux fois plus large. Ce qui est au centre reste au centre."),
                ManualBlock(ManualKind.Bullet, "**dessous** *(extra)* : rend mono tout ce qui est sous cette fréquence, de 20 à 500 Hz."),
                ManualBlock(ManualKind.Bullet, "**haas** *(extra)* : retarde un côté jusqu’à 20 ms. Quelques millisecondes élargissent un son sans changer son timbre."),
                ManualBlock(ManualKind.Bullet, "**rotation** : tourne toute l’image à gauche ou à droite sans changer sa largeur."),
                ManualBlock(ManualKind.Heading, "Astuces"),
                ManualBlock(ManualKind.Bullet, "Réglez **dessous** vers 120 Hz sur presque tout. La basse n’a pas besoin de stéréo, et une basse stéréo peut disparaître sur des haut-parleurs mono."),
                ManualBlock(ManualKind.Bullet, "**haas** tient mieux que **largeur** quand le mixage est joué en mono."),
            )),
        )),
        ManualSection("Les modificateurs", "", listOf(
            ManualBlock(ManualKind.Para, "Chaque piste a trois modificateurs, dans la rangée juste au-dessus du clavier. Touchez-en un pour l’activer ou le désactiver, et maintenez-le pour ouvrir ses réglages.", "Chaque piste a trois modificateurs, dans la rangée juste au-dessus du clavier. Cliquez-en un pour l’activer ou le désactiver, et maintenez-le pour ouvrir ses réglages."),
            ManualBlock(ManualKind.Para, "Un modificateur change ce que vous jouez avant que ce soit écrit. Jouez une touche avec le modificateur d’accord actif et vous entendez trois notes, et si vous enregistrez, le clip reçoit trois notes. Les notes d’un clavier ou d’un contrôleur MIDI passent aussi par les modificateurs."),
            ManualBlock(ManualKind.Heading, "Gamme"),
            ManualBlock(ManualKind.Para, "Trente-trois gammes, dans n’importe quelle tonalité. Avec une gamme active, le clavier ne montre que les notes de la gamme, ce qui donne plus d’étendue sur un petit écran et empêche les fausses notes. Les notes MIDI hors de la gamme vont à la plus proche qui convient."),
            ManualBlock(ManualKind.Para, "Le coin **gam** de la grille de notes choisit l’affichage de la gamme : toutes les notes, notes de la gamme en surbrillance ou seulement les notes de la gamme. Sur une piste sans gamme propre, la grille utilise la tonalité du morceau (réglée derrière le bouton du tempo)."),
            ManualBlock(ManualKind.Heading, "Accord"),
            ManualBlock(ManualKind.Para, "Change chaque note en accord, soit une forme fixe, soit l’accord que la gamme bâtit sur cette note pour rester dans la tonalité. **gratter** étale les notes dans le temps, et les enregistrements gardent l’effet."),
            ManualBlock(ManualKind.Heading, "Arpège"),
            ManualBlock(ManualKind.Para, "Joue une à la fois les notes que vous tenez. Vous choisissez l’ordre, la vitesse, l’étendue en octaves, la longueur des notes et une probabilité que chaque pas soit sauté."),
            ManualBlock(ManualKind.Para, "Enregistrer avec l’arpège actif écrit chaque note qu’il joue, donc un accord tenu devient une ligne que vous pouvez modifier ensuite."),
        )),
        ManualSection("MIDI et jeu avec d’autres", "", listOf(
            ManualBlock(ManualKind.Para, "Vous pouvez utiliser le MIDI avec toutes sortes de claviers et de contrôleurs, y compris MPE. L’Intuitive Instruments Exquis et le Novation Launchpad Pro MK3 ont un support particulier (je les ai moi-même)."),
            ManualBlock(ManualKind.Heading, "Jouer d’un clavier"),
            ManualBlock(ManualKind.Para, "Les claviers MIDI USB et Bluetooth fonctionnent tout de suite. Les notes vont à la piste ouverte, ou à une piste que vous fixez pour qu’elle reste la même peu importe ce que vous regardez."),
            ManualBlock(ManualKind.Para, "Si un contrôleur joue tout trop fort ou trop doux, tournez **vélocité** dans l’onglet **notes**. **plus doux** baisse le milieu de la plage et **plus fort** le monte, et les notes les plus douces et les plus fortes ne bougent pas. L’affichage à côté montre la vélocité de chaque note telle que l’appli la reçoit."),
            ManualBlock(ManualKind.Subheading, "MPE"),
            ManualBlock(ManualKind.Para, "Avec un contrôleur MPE, chaque doigt a son propre bend, sa pression et son glissé, donc plier une note laisse les autres tranquilles. Laissez **zone** sur **auto** et l’appli suit le contrôleur : elle prend la zone et la plage de bend qu’il annonce, ou les devine dès que deux doigts sont posés sur des canaux séparés. La carte dit ce qu’elle a trouvé. Choisissez **basse** ou **haute** pour régler la zone et la plage de bend à la main."),
            ManualBlock(ManualKind.Para, "Ce que fait chaque geste :"),
            ManualBlock(ManualKind.Bullet, "**Bend** change la hauteur de la note sur toutes les machines mélodiques sauf Reflux, l’orgue et Diction, qui plient en bloc. Sur un harmonica Draw joué comme par un joueur, plier vers le bas plie avec la langue, aussi loin que le trou le permet."),
            ManualBlock(ManualKind.Bullet, "**Pression** ouvre le son et le rend plus fort. Sur Brazen, Timber, Draw et Tongue, c’est le souffle, et sur Filament elle appuie aussi sur l’archet. Hammer n’en tient pas compte : un piano n’a plus rien à presser une fois la corde frappée. **pression** sur le panneau d’une machine règle la quantité."),
            ManualBlock(ManualKind.Bullet, "**Glissé** (CC 74) rend la note plus brillante. Il ouvre le filtre sur Trinity, Ratio et Mosaic, monte le point de pincement sur la corde de Filament, serre les lèvres ou l’anche sur Brazen et Timber, rapproche les anches de Draw de leurs fentes, serre l’anche de Tongue dans son cadre et déplace le morph de Cumulus. **glissé** sur le panneau règle la quantité. Dans Nexus, le module **touch** donne à chaque voix la pression et le glissé de son doigt, à brancher où vous voulez."),
            ManualBlock(ManualKind.Para, "Un clavier qui envoie de l’aftertouch polyphonique presse aussi chaque note séparément, sans zone. Les autres contrôleurs sur le canal d’un doigt, comme la molette de modulation ou la pédale de maintien, agissent sur toute la piste comme d’habitude."),
            ManualBlock(ManualKind.Para, "Le bend, la pression et le glissé de chaque note sont enregistrés avec les notes."),
            ManualBlock(ManualKind.Subheading, "Exquis"),
            ManualBlock(ManualKind.Para, "Branchez un Exquis en USB et ses pads montrent la gamme de la piste qu’il joue : le modificateur Scale de la piste s’il en a un, sinon la tonalité du morceau, comme la grille de notes. Elle change quand vous ouvrez une autre piste ou changez la gamme. Avec **fixe**, c’est la piste fixée, et avec **par canal**, c’est la piste du canal sur lequel joue l’Exquis. Les doigts MPE ne sont pas dirigés par canal, donc en MPE c’est la piste ouverte ou la piste fixée."),
            ManualBlock(ManualKind.Para, "**pads exquis** dans l’onglet appareils de la fenêtre MIDI choisit comment :"),
            ManualBlock(ManualKind.Bullet, "**ses couleurs** règle la tonique et la gamme de l’Exquis lui-même, donc les pads les montrent dans les couleurs que vous leur avez données. Une gamme que l’Exquis n’a pas s’affiche comme la plus proche qui contient toutes ses notes, ou chromatique."),
            ManualBlock(ManualKind.Bullet, "**surbrillance** allume plutôt les notes dans le vert de surbrillance de l’Exquis, un pad par note, par-dessus la gamme réglée sur l’Exquis."),
            ManualBlock(ManualKind.Bullet, "**non** laisse les pads tranquilles."),
            ManualBlock(ManualKind.Para, "Ses boutons commandent aussi l’appli : **play/stop** lance et arrête le morceau, **record** arme l’enregistrement, **loop** met la scène en boucle, **clips** passe en mode clip, et **undo** et **redo** font ce qu’ils disent. Leurs lumières suivent l’appli : play est vert pendant la lecture, record est rouge quand il est armé, et loop et clips sont allumés quand ils sont actifs. Les pads, les boutons rotatifs, le curseur et les boutons d’octave restent à l’Exquis. **boutons exquis** dans l’onglet appareils rend les boutons à l’Exquis, et fermer l’appli aussi."),
            ManualBlock(ManualKind.Subheading, "Launchpad Pro"),
            ManualBlock(ManualKind.Para, "Branchez un Launchpad Pro [MK3] en USB et Acidulous prend en charge tous les pads et boutons, allumés aux couleurs de vos pistes. **launchpad** dans l’onglet appareils de la fenêtre MIDI le rend, et fermer l’appli aussi. Les boutons du haut choisissent ce qu’est la grille :"),
            ManualBlock(ManualKind.Bullet, "**Note** - un clavier de piano comme celui à l’écran, avec les touches blanches sur une rangée et les noires sur la rangée du dessus, quatre octaves vers le haut de la grille. Les notes de la gamme (celle de la piste, ou la tonalité du morceau) sont allumées de la couleur de la piste, la tonique plus brillante, et les autres sont pâles mais jouent quand même. Quand la piste a son propre modificateur **Scale** actif, seules les notes de la gamme sont là, une octave par rangée à partir de la tonique, ce qui donne huit octaves. Sur une boîte à rythmes, ce sont les pads de la machine, placés comme à l’écran. Haut et bas changent l’octave."),
            ManualBlock(ManualKind.Bullet, "**Session** - la grille du morceau, placée comme à l’écran avec les pistes vers le bas et les scènes de gauche à droite. Un clip pulse pendant qu’il joue et clignote pendant qu’il attend. Touchez un clip pour le lancer en mode clip, ou pour jouer à partir de cette scène en mode morceau."),
            ManualBlock(ManualKind.Bullet, "**Sequencer** - le clip de la piste ouverte dans la scène courante, huit pas à la fois. Touchez un pad pour ajouter ou enlever une note. Gauche et droite avancent d’un pas à la fois, et haut et bas parcourent les notes. Les rangées d’une boîte à rythmes descendent à partir de la grosse caisse, comme sa grille à l’écran."),
            ManualBlock(ManualKind.Bullet, "**Custom** - le mixage, placé comme la grille du morceau, avec une rangée par piste et son volume de gauche à droite. **Volume**, **Pan** et **Sends** sur la rangée du bas choisissent ce que sont les curseurs, et **Device** fait des rangées les huit premiers boutons de la machine jouée."),
            ManualBlock(ManualKind.Bullet, "**Chord** - des accords dans la tonalité, une colonne par note de la gamme et une rangée par sorte d’accord."),
            ManualBlock(ManualKind.Bullet, "**Projects** - les effets de performance : répétition et gate en haut, inversion, arrêt de bande, la montée, les trois coupures et un pad XY. Maintenez pour jouer."),
            ManualBlock(ManualKind.Para, "Les boutons du pourtour fonctionnent sur toutes les pages :"),
            ManualBlock(ManualKind.Bullet, "**Play** et **Record** font ce qu’ils disent. **Shift** et **Play** arrête tout."),
            ManualBlock(ManualKind.Bullet, "**Shift** et **Clear** annule, et **Shift** et **Duplicate** rétablit."),
            ManualBlock(ManualKind.Bullet, "Maintenez **Clear** et touchez un clip pour le vider. Maintenez **Duplicate** et touchez un clip pour le copier dans la scène suivante si elle est vide, ou touchez un bouton de scène pour dupliquer la scène."),
            ManualBlock(ManualKind.Bullet, "Les boutons à droite sont les pistes, de haut en bas comme les rangées de la grille. Touchez-en un pour choisir la piste que joue le Launchpad. Maintenez **Mute** ou **Solo** et touchez-en un pour la rendre muette ou la mettre en solo."),
            ManualBlock(ManualKind.Bullet, "La rangée sous la grille, ce sont les scènes, de gauche à droite. Touchez-en une pour la jouer, comme quand vous touchez l’en-tête d’une scène."),
            ManualBlock(ManualKind.Bullet, "Sur **Session** et **Custom**, haut et bas parcourent les pistes et gauche et droite les scènes, une à la fois. Sur les autres pages, maintenez **Shift** pour faire de même. Une flèche est allumée quand il y a plus de ce côté."),
            ManualBlock(ManualKind.Bullet, "**Quantise** quantifie le clip ouvert selon le dernier réglage de la fenêtre de quantification."),
            ManualBlock(ManualKind.Bullet, "**Stop Clip** arrête les clips, ou le morceau."),
            ManualBlock(ManualKind.Para, "Ses pads envoient la vélocité et la pression, et les deux sont enregistrées comme pour n’importe quel clavier."),
            ManualBlock(ManualKind.Subheading, "Pédales"),
            ManualBlock(ManualKind.Para, "Une pédale branchée à votre clavier fonctionne sur toutes les machines mélodiques :"),
            ManualBlock(ManualKind.Bullet, "**Maintien** (la pédale de droite) fait durer les notes après que vous lâchez les touches, jusqu’à ce que vous la releviez. Sur Filament, elle lève aussi les étouffoirs, donc les cordes que vous ne jouez pas résonnent avec."),
            ManualBlock(ManualKind.Bullet, "**Sostenuto** (celle du milieu) tient seulement les touches enfoncées au moment où vous l’avez pressée, et les notes jouées ensuite s’arrêtent comme d’habitude."),
            ManualBlock(ManualKind.Bullet, "**Douce** (celle de gauche) joue les notes plus doucement tant qu’elle est enfoncée."),
            ManualBlock(ManualKind.Para, "Hammer prend une pédale enfoncée à moitié, comme un piano : une pédale de maintien à mi-course laisse les étouffoirs juste toucher les cordes. Toutes les autres machines entendent une pédale comme relevée ou enfoncée, et la mi-course compte comme enfoncée. La sortie MIDI envoie la pédale aussi loin qu’elle est enfoncée."),
            ManualBlock(ManualKind.Para, "Les pédales sont enregistrées comme couloirs dans la bande d’automatisation, un chacune, et vous pouvez aussi les y dessiner à la main. Sur Hammer, un couloir garde jusqu’où la pédale était enfoncée et où elle a bougé; sur tout le reste, c’est relevée ou enfoncée. Les boîtes à rythmes n’en tiennent pas compte."),
            ManualBlock(ManualKind.Heading, "Affecter un contrôleur"),
            ManualBlock(ManualKind.Para, "Maintenez rétablir pour entrer en mode affectation. Les commandes qu’on peut affecter sont mises en surbrillance. Touchez-en une, puis tournez un bouton ou appuyez sur une touche de votre contrôleur pour les relier. Les boutons, les curseurs, les commandes de mixage et les boutons de transport peuvent tous être affectés à un CC ou à une note.", "Maintenez le bouton de la souris sur rétablir, ou faites un clic droit dessus, pour entrer en mode affectation. Les commandes qu’on peut affecter sont mises en surbrillance. Cliquez-en une, puis tournez un bouton ou appuyez sur une touche de votre contrôleur pour les relier. Les boutons, les curseurs, les commandes de mixage et les boutons de transport peuvent tous être affectés à un CC ou à une note."),
            ManualBlock(ManualKind.Para, "Un bouton affecté s’enregistre dans l’automatisation comme si vous le tourniez à la main. Les boutons affectés comme jouer, arrêter et fill ne s’enregistrent pas."),
            ManualBlock(ManualKind.Heading, "Horloge"),
            ManualBlock(ManualKind.Para, "L’appli peut envoyer l’horloge MIDI (avec start, stop et song position) à du matériel, et suivre une horloge entrante en prenant son tempo de l’autre appareil."),
            ManualBlock(ManualKind.Para, "**suivre** dans l’onglet **contrôle** de la fenêtre MIDI a trois réglages :"),
            ManualBlock(ManualKind.Bullet, "**oui** suit toujours, même si rien n’arrive."),
            ManualBlock(ManualKind.Bullet, "**auto** suit une horloge quand elle arrive et revient au tempo du morceau une seconde après qu’elle s’arrête."),
            ManualBlock(ManualKind.Bullet, "**non** ignore l’horloge entrante."),
            ManualBlock(ManualKind.Para, "**envoyer**, à côté, active et désactive l’envoi de l’horloge. L’envoi des notes d’une piste se règle piste par piste, dans ses réglages ou sur sa tranche de mixage."),
            ManualBlock(ManualKind.Heading, "Link"),
            ManualBlock(ManualKind.Para, "Ableton Link partage le tempo et la position dans la mesure avec les autres apps Link du même réseau, dans les deux sens. Activez-le et le nombre d’apps connectées s’affiche. Il garde le premier temps de tout le monde ensemble sans que personne soit le chef."),
        )),
        ManualSection("Enregistrement et échantillons", "", listOf(
            ManualBlock(ManualKind.Heading, "La fenêtre d’enregistrement"),
            ManualBlock(ManualKind.Para, "Une seule fenêtre s’occupe de l’enregistrement, et elle s’ouvre partout où une machine a besoin d’audio : un pad de Forage, une boucle pour Dice, un tampon pour Pollen ou une prise pour Molt."),
            ManualBlock(ManualKind.Bullet, "**enregistrer** - choisissez l’entrée, surveillez le niveau et enregistrez. - **source** est **entrée** pour le microphone ou ce qui est branché, ou **rééchant.** pour enregistrer ce que joue l’appli. - **micro** est **brut** pour un instrument, ou **propre** pour une voix, avec réduction du bruit et contrôle du niveau. - L’accordeur dans la carte d’entrée montre la note la plus proche et de combien de cents vous êtes à côté, et devient vert à moins de quatre cents. Il écoute avant les effets d’entrée et n’affiche rien s’il n’est pas sûr de la note. - **gravé dans la prise** contient deux effets enregistrés dans le fichier, comme un ampli de guitare. Les effets d’une piste, eux, peuvent être changés n’importe quand.", "**enregistrer** - choisissez l’entrée, surveillez le niveau et enregistrez. - **source** est **entrée** pour le microphone ou ce qui est branché, ou **rééchant.** pour enregistrer ce que joue l’appli. - Dans un navigateur, **micro** est **brut** pour un instrument, ou **propre** pour une voix, avec réduction du bruit et contrôle du niveau. - L’accordeur dans la carte d’entrée montre la note la plus proche et de combien de cents vous êtes à côté, et devient vert à moins de quatre cents. Il écoute avant les effets d’entrée et n’affiche rien s’il n’est pas sûr de la note. - **gravé dans la prise** contient deux effets enregistrés dans le fichier, comme un ampli de guitare. Les effets d’une piste, eux, peuvent être changés n’importe quand."),
            ManualBlock(ManualKind.Bullet, "**modifier** - réécoutez la prise, coupez les bouts, réglez le niveau et coupez le grondement grave. **norm** et **inv** en haut normalisent et inversent tout le fichier. Les changements s’affichent et jouent tout de suite. **appliquer** les écrit dans le fichier, et **revenir** les annule tous."),
            ManualBlock(ManualKind.Bullet, "**bibliothèque** - tout ce que vous avez enregistré ou importé."),
            ManualBlock(ManualKind.Bullet, "**voix** - enregistre votre voix pour Diction, une courte consigne à la fois. - **nouvelle voix** en commence une, et **supprimer** supprime celle choisie, avec ses prises. **partager** l’envoie en zip, avec toutes ses prises, et **importer…** fait entrer une voix que quelqu’un a partagée. **note** est la note sur laquelle chaque consigne est chantée; choisissez-en une facile pour vous, car elle ne peut plus changer après la première prise. - Touchez **chanter** et écoutez la note. Il compte 3, 2, 1, puis la consigne devient rouge : chantez-la sur la note, dans l’octave qui convient à votre voix. La barre en dessous montre où va chaque partie. **ah-sah**, c’est ah, puis sah, d’un seul souffle, avec le s là où la barre le marque : c’est la consonne qui entre dans une voyelle et en sort qu’on enregistre. Une voyelle qui bouge, comme **eye**, tient sa première voyelle et passe à la deuxième à la marque près de la fin : aaah-ee. Il passe tout seul à la consigne suivante. - Chaque prise est vérifiée dès qu’elle est chantée. Une prise à rechanter reste à l’écran en rose et dit pourquoi, comme **trop fort** ou **aucune consonne entendue**. Les comptes ne comptent que les prises correctes. - **micro** montre le niveau. Chantez assez fort pour le garder bien haut dans la barre. Une prise enregistre toujours le micro brut, sans les effets gravés dans la prise. - **◀** et **▶** reculent et avancent, **jouer** fait réécouter une prise, et **encore** l’enregistre de nouveau. - **couper…** montre la prise avec la partie où elle a été coupée : la voyelle tenue, le mouvement d’une voyelle, ou la consonne. Glissez une marque pour la déplacer, et **partie** joue ce que les marques contiennent. **garder** l’enregistre, et une prise qui demandait d’être rechantée est utilisée comme vous l’avez marquée. **coupe auto** remet la coupe d’origine. - **à chanter** compte ce dont une voix a besoin : chaque voyelle, et chaque consonne entre des ah. Ensuite viennent les consonnes **entre les ee** et **entre les oo**, que vous pouvez laisser de côté. La fenêtre **depuis…** de Diction choisit entre elles pour chaque consonne. Une voix est enregistrée au fur et à mesure, donc vous pouvez arrêter et la finir un autre jour.", "**voix** - enregistre votre voix pour Diction, une courte consigne à la fois. - **nouvelle voix** en commence une, et **supprimer** supprime celle choisie, avec ses prises. **partager** l’envoie en zip, avec toutes ses prises, et **importer…** fait entrer une voix que quelqu’un a partagée. **note** est la note sur laquelle chaque consigne est chantée; choisissez-en une facile pour vous, car elle ne peut plus changer après la première prise. - Cliquez **chanter** et écoutez la note. Il compte 3, 2, 1, puis la consigne devient rouge : chantez-la sur la note, dans l’octave qui convient à votre voix. La barre en dessous montre où va chaque partie. **ah-sah**, c’est ah, puis sah, d’un seul souffle, avec le s là où la barre le marque : c’est la consonne qui entre dans une voyelle et en sort qu’on enregistre. Une voyelle qui bouge, comme **eye**, tient sa première voyelle et passe à la deuxième à la marque près de la fin : aaah-ee. Il passe tout seul à la consigne suivante. - Chaque prise est vérifiée dès qu’elle est chantée. Une prise à rechanter reste à l’écran en rose et dit pourquoi, comme **trop fort** ou **aucune consonne entendue**. Les comptes ne comptent que les prises correctes. - **micro** montre le niveau. Chantez assez fort pour le garder bien haut dans la barre. Une prise enregistre toujours le micro brut, sans les effets gravés dans la prise. - **◀** et **▶** reculent et avancent, **jouer** fait réécouter une prise, et **encore** l’enregistre de nouveau. - **couper…** montre la prise avec la partie où elle a été coupée : la voyelle tenue, le mouvement d’une voyelle, ou la consonne. Glissez une marque pour la déplacer, et **partie** joue ce que les marques contiennent. **garder** l’enregistre, et une prise qui demandait d’être rechantée est utilisée comme vous l’avez marquée. **coupe auto** remet la coupe d’origine. - **à chanter** compte ce dont une voix a besoin : chaque voyelle, et chaque consonne entre des ah. Ensuite viennent les consonnes **entre les ee** et **entre les oo**, que vous pouvez laisser de côté. La fenêtre **depuis…** de Diction choisit entre elles pour chaque consonne. Une voix est enregistrée au fur et à mesure, donc vous pouvez arrêter et la finir un autre jour."),
            ManualBlock(ManualKind.Para, "Le résultat est un fichier, donc le même enregistrement peut servir à plus d’une machine."),
            ManualBlock(ManualKind.Heading, "Importer"),
            ManualBlock(ManualKind.Para, "Vous pouvez importer du WAV, de l’AIFF, du FLAC et du MP3. Tout est converti en WAV une seule fois à l’entrée, pour que les morceaux se chargent vite."),
            ManualBlock(ManualKind.Heading, "Enregistrer sur une piste"),
            ManualBlock(ManualKind.Para, "**Bias** est la piste audio. Ouvrez une cellule Bias, touchez le point rouge à côté d’un couloir, armez l’enregistrement dans le transport et appuyez sur jouer. Le morceau joue pendant que vous enregistrez, et les autres couloirs continuent de jouer.", "**Bias** est la piste audio. Ouvrez une cellule Bias, cliquez le point rouge à côté d’un couloir, armez l’enregistrement dans le transport et appuyez sur jouer. Le morceau joue pendant que vous enregistrez, et les autres couloirs continuent de jouer."),
            ManualBlock(ManualKind.Para, "Quand vous arrêtez, la prise est coupée aux limites des scènes. Un enregistrement sur tout le morceau devient une cellule par scène, toutes pointant vers le même fichier, avec de nouvelles cellules dans les scènes où la piste était vide. L’enregistrement complet reste aussi dans la bibliothèque de sons, donc vous pouvez annuler le découpage et le placer à la main."),
            ManualBlock(ManualKind.Para, "La coupe, les fondus, les fondus enchaînés, l’aplatissement des couloirs et le suivi du tempo sont sur la page de **Bias**. Aucun d’eux ne change le fichier."),
            ManualBlock(ManualKind.Para, "Les prises peuvent durer jusqu’à une demi-heure. Tout ce qui dépasse deux minutes est converti une fois en arrière-plan et lu en continu depuis le stockage, donc il peut y avoir une courte attente la première fois qu’une longue prise sert."),
            ManualBlock(ManualKind.Para, "Un seul couloir enregistre à la fois, et armer un deuxième couloir désarme le premier."),
            ManualBlock(ManualKind.Para, "Si l’enregistreur a pris du retard et laissé un trou dans la prise, elle n’est pas découpée, et toute la prise reste dans la bibliothèque. Si le transport n’a jamais joué, rien n’a été enregistré sur une scène, et l’appli vous le dit."),
            ManualBlock(ManualKind.Heading, "Les machines qui utilisent l’audio"),
            ManualBlock(ManualKind.Bullet, "**Forage** - un échantillon par pad, avec un filtre, un crusher et une enveloppe de hauteur."),
            ManualBlock(ManualKind.Bullet, "**Mosaic** - des zones sur le clavier et la vélocité, à partir de vos propres fichiers ou d’une SoundFont."),
            ManualBlock(ManualKind.Bullet, "**Pollen** - des grains tirés d’un fichier ou de l’entrée en direct."),
            ManualBlock(ManualKind.Bullet, "**Dice** - une boucle coupée en tranches."),
            ManualBlock(ManualKind.Bullet, "**Molt** - une prise chantée, accordée par la grille de notes."),
            ManualBlock(ManualKind.Bullet, "**Cipher** et **Filament** peuvent utiliser l’entrée en direct."),
            ManualBlock(ManualKind.Bullet, "**Bias** - quatre couloirs d’enregistrements le long du morceau. Ses enregistrements appartiennent à ses cellules plutôt qu’à la machine."),
        )),
        ManualSection("Importer et exporter", "", listOf(
            ManualBlock(ManualKind.Para, "**Exporter…** dans le menu fichier fait le rendu du morceau plus vite qu’en temps réel, par le même moteur qui le joue, queues comprises."),
            ManualBlock(ManualKind.Para, "Vous pouvez exporter tout le morceau, la scène courante ou des pistes séparées."),
            ManualBlock(ManualKind.Heading, "Formats"),
            ManualBlock(ManualKind.Bullet, "**WAV** et **AIFF** - 16 ou 24 bits, ou 32 bits flottant."),
            ManualBlock(ManualKind.Bullet, "**FLAC** - sans perte et plus petit."),
            ManualBlock(ManualKind.Bullet, "**MP3** et **AAC** - au débit que vous choisissez.", "**MP3** - au débit que vous choisissez. AAC n’existe que sur le téléphone."),
            ManualBlock(ManualKind.Bullet, "**MIDI** - les notes sans le son, avec la transposition et la vélocité fixe de chaque piste appliquées, et ses couloirs de pédale, de molette de modulation et de pression. Les pistes de batterie vont sur le canal 10 comme batterie General MIDI, pour que les autres logiciels entendent les bons sons."),
            ManualBlock(ManualKind.Bullet, "**paquet** - le morceau et les échantillons qu’il utilise, dans un seul fichier que vous pouvez partager."),
            ManualBlock(ManualKind.Heading, "Pistes séparées"),
            ManualBlock(ManualKind.Para, "**par piste** écrit chaque piste dans son propre fichier en une seule passe, avec le mixage complet. Chaque groupe du mixage est aussi une piste séparée, et une piste dirigée vers un groupe fait partie du fichier du groupe au lieu d’avoir le sien, donc les pistes séparées s’additionnent pour donner le mixage."),
            ManualBlock(ManualKind.Heading, "Niveau"),
            ManualBlock(ManualKind.Para, "**niveau** est soit **tel que mixé**, soit **-14 LUFS**. Avec -14, le morceau est rendu deux fois : une fois pour le mesurer, puis avec le gain qui l’amène à -14 LUFS, à peu près le niveau des services de diffusion en continu. Le gain est retenu s’il pousse la crête vraie au-dessus de -1 dBTP, donc un morceau très dynamique peut finir un peu sous -14. Les pistes séparées reçoivent le même gain, donc elles s’additionnent toujours pour donner le mixage."),
            ManualBlock(ManualKind.Para, "La tranche de la sortie principale dans le mixage montre la même mesure pendant que vous jouez : les LUFS intégrés, et en dessous la mesure à court terme (**S**) et la crête vraie (**TP**). TP devient rouge au-dessus de -1 dBTP. Elle se remet à zéro chaque fois que vous appuyez sur jouer, ou quand vous la touchez.", "La tranche de la sortie principale dans le mixage montre la même mesure pendant que vous jouez : les LUFS intégrés, et en dessous la mesure à court terme (**S**) et la crête vraie (**TP**). TP devient rouge au-dessus de -1 dBTP. Elle se remet à zéro chaque fois que vous appuyez sur jouer, ou quand vous la cliquez."),
            ManualBlock(ManualKind.Heading, "Les exportations se répètent"),
            ManualBlock(ManualKind.Para, "Exporter deux fois le même morceau donne des fichiers identiques, car chaque machine est remise à zéro avant le début du rendu."),
            ManualBlock(ManualKind.Heading, "Importer"),
            ManualBlock(ManualKind.Para, "**Importer…** dans le menu fichier prend un fichier n’importe où sur le téléphone, et ce qui se passe dépend de ce que c’est :", "**Importer…** dans le menu fichier prend un fichier n’importe où sur l’ordinateur, et ce qui se passe dépend de ce que c’est :"),
            ManualBlock(ManualKind.Bullet, "**Un fichier MIDI** ouvre une fenêtre qui montre chaque partie du fichier avec une machine choisie pour elle. Touchez une machine pour la changer, ou choisissez **ignorer** pour laisser la partie de côté. La batterie sur le canal 10 va à Hexbeat, chaque instrument placé sur le son correspondant. Les parties qui disent de quel instrument il s’agit reçoivent une machine qui convient, comme un orgue qui va à Manual et les cuivres à Brazen.", "**Un fichier MIDI** ouvre une fenêtre qui montre chaque partie du fichier avec une machine choisie pour elle. Cliquez une machine pour la changer, ou choisissez **ignorer** pour laisser la partie de côté. La batterie sur le canal 10 va à Hexbeat, chaque instrument placé sur le son correspondant. Les parties qui disent de quel instrument il s’agit reçoivent une machine qui convient, comme un orgue qui va à Manual et les cuivres à Brazen."),
            ManualBlock(ManualKind.Bullet, "Le fichier est coupé en scènes de 4, 8 ou 16 mesures. Un passage identique au précédent devient une répétition, donc une boucle entre comme une seule scène jouée plusieurs fois. Le tempo et le chiffrage viennent du fichier, et là où le tempo change, les scènes qui suivent ont leur propre tempo."),
            ManualBlock(ManualKind.Bullet, "Les pédales, la molette de modulation et la pression entrent comme couloirs, et le pitch-bend comme bends sur les notes."),
            ManualBlock(ManualKind.Bullet, "Les paroles du fichier, y compris celles d’un fichier karaoké, vont sur les notes où elles commencent, et cette partie va à Diction pour les chanter."),
            ManualBlock(ManualKind.Bullet, "Il s’ouvre comme un nouveau morceau et est enregistré tout de suite."),
            ManualBlock(ManualKind.Bullet, "**Un paquet** (un .zip fait par Exporter) s’ouvre comme un morceau, avec ses échantillons. Si vous avez déjà un échantillon du même nom, le vôtre est gardé et celui du paquet entre sous un nouveau nom."),
            ManualBlock(ManualKind.Bullet, "**Un son** (WAV, AIFF, FLAC ou MP3) va dans la bibliothèque de sons, jusqu’à dix minutes."),
            ManualBlock(ManualKind.Bullet, "**Un accordage** (un fichier Scala .scl) s’ajoute à la liste des accordages, sous la tonalité dans la fenêtre du tempo et dans les réglages de chaque piste."),
            ManualBlock(ManualKind.Para, "Un morceau importé ne remplace jamais un morceau que vous avez enregistré. Si le nom est pris, il reçoit un numéro à la suite."),
            ManualBlock(ManualKind.Heading, "Partager"),
            ManualBlock(ManualKind.Para, "Quand une exportation est finie, **Partager** l’envoie tout de suite par le menu de partage du téléphone : courriel, Drive, une conversation ou une autre appli. Les pistes séparées partent avec tous leurs fichiers ensemble.", "Quand une exportation est finie, **Partager** ouvre le dossier où elle a été enregistrée, pour l’envoyer de là."),
            ManualBlock(ManualKind.Para, "**Partager le morceau…** dans le menu fichier envoie le morceau ouvert en paquet, échantillons compris, pour que quelqu’un d’autre l’ouvre dans Acidulous.", "**Partager le morceau…** dans le menu fichier enregistre le morceau ouvert en paquet, échantillons compris, et ouvre son dossier pour que vous puissiez l’envoyer."),
            ManualBlock(ManualKind.Para, "L’inverse fonctionne aussi. Ouvrez un fichier MIDI, un paquet, une voix partagée ou un son avec Acidulous, ou partagez-le vers l’appli, et il va là où **Importer…** l’aurait mis; une voix va à la page voix dans **Son**.", ""),
        )),
        ManualSection("Réglages", "", listOf(
            ManualBlock(ManualKind.Heading, "affichage"),
            ManualBlock(ManualKind.Bullet, "**thème** - sombre, clair, contraste élevé ou comme le téléphone. Le contraste élevé, c’est du blanc sur noir, avec des couleurs plus vives et un contour autour de chaque commande.", "**thème** - sombre, clair, contraste élevé ou comme le système. Le contraste élevé, c’est du blanc sur noir, avec des couleurs plus vives et un contour autour de chaque commande."),
            ManualBlock(ManualKind.Bullet, "**langue** - la langue de l’appli : celle du téléphone, l’anglais ou le français. Pas dans un navigateur, qui utilise la sienne."),
            ManualBlock(ManualKind.Bullet, "**taille** - agrandit tout, en quatre crans."),
            ManualBlock(ManualKind.Bullet, "", "**échelle d’écran** - la taille à laquelle toute la fenêtre est dessinée. **système** prend le réglage de l’ordinateur."),
            ManualBlock(ManualKind.Bullet, "**pendant la lecture** - si l’écran peut s’éteindre pendant la lecture.", ""),
            ManualBlock(ManualKind.Bullet, "**clavier** - **touches…** ouvre la liste des raccourcis, où vous pouvez les changer et choisir comment les lettres jouent des notes. Voir Un clavier."),
            ManualBlock(ManualKind.Heading, "audio"),
            ManualBlock(ManualKind.Bullet, "", "**sortie** - la sortie par laquelle jouer, ou celle du système par défaut. Sous Windows, le pilote propre d’une interface est aussi dans la liste, marqué **faible latence**. C’est le chemin le plus rapide vers l’interface, et pendant qu’il joue, les entrées de l’enregistreur sont celles de cette interface, deux à la fois."),
            ManualBlock(ManualKind.Bullet, "**tampon** - serré, équilibré ou sûr. Serré a la latence la plus basse mais peut craquer sur un téléphone lent, et sûr donne plus de temps au téléphone. Si le son coupe encore, le tampon grandit tout seul, puis redescend à la plus petite taille que l’appareil supporte, et s’en souvient pour la prochaine fois."),
            ManualBlock(ManualKind.Bullet, "**voix** - combien de notes une piste peut tenir à la fois. La note la plus ancienne est coupée en premier."),
            ManualBlock(ManualKind.Bullet, "**cœurs** - sur combien de cœurs les pistes sont calculées à la fois. **auto** utilise tous les cœurs rapides du téléphone sauf un, qu’il laisse à l’écran. **1** calcule toutes les pistes sur le même cœur. Un morceau léger reste sur un seul cœur de toute façon.", "**cœurs** - sur combien de cœurs les pistes sont calculées à la fois. **auto** utilise la moitié des cœurs de l’ordinateur. **1** calcule toutes les pistes sur le même cœur. Un morceau léger reste sur un seul cœur de toute façon."),
            ManualBlock(ManualKind.Bullet, "**qualité** - ce qu’on sacrifie quand le téléphone n’arrive pas à suivre. **légère** : - fait tourner l’**amp** et la **distortion** sans suréchantillonnage (environ la moitié du coût de l’amp) - réduit de moitié la taille de la **reverb** (environ la moitié de son coût) - réduit de moitié les partiels des sons **Resonance** qui en utilisent plus de douze - réduit de moitié les piles d’unisson de **Trinity** (jamais moins de deux), et laisse sonner au plus six notes relâchées à la fois, en faisant disparaître vite les queues plus anciennes. Les notes tenues ne sont pas touchées - réduit de moitié le nombre de grains dans **Pollen** **auto** passe en légère tout seul quand le téléphone peine. Les notes que vous tenez gardent la qualité avec laquelle elles ont commencé, et seules les queues que vous avez déjà lâchées peuvent être écourtées. Les exportations et le figeage utilisent toujours la pleine qualité.", "**qualité** - ce qu’on sacrifie quand l’ordinateur n’arrive pas à suivre. **légère** : - fait tourner l’**amp** et la **distortion** sans suréchantillonnage (environ la moitié du coût de l’amp) - réduit de moitié la taille de la **reverb** (environ la moitié de son coût) - réduit de moitié les partiels des sons **Resonance** qui en utilisent plus de douze - réduit de moitié les piles d’unisson de **Trinity** (jamais moins de deux), et laisse sonner au plus six notes relâchées à la fois, en faisant disparaître vite les queues plus anciennes. Les notes tenues ne sont pas touchées - réduit de moitié le nombre de grains dans **Pollen** **auto** passe en légère tout seul quand l’ordinateur peine. Les notes que vous tenez gardent la qualité avec laquelle elles ont commencé, et seules les queues que vous avez déjà lâchées peuvent être écourtées. Les exportations et le figeage utilisent toujours la pleine qualité."),
            ManualBlock(ManualKind.Heading, "enregistrer"),
            ManualBlock(ManualKind.Bullet, "**résolution** - la résolution en bits des enregistrements et des exportations."),
            ManualBlock(ManualKind.Bullet, "**décompte** - les mesures de clics avant le début de l’enregistrement."),
            ManualBlock(ManualKind.Bullet, "**quantifier** - place ce que vous jouez sur la grille du clip. **non** laisse les notes exactement où vous les avez jouées, et **force** ne les déplace qu’en partie."),
            ManualBlock(ManualKind.Bullet, "**prise** - **ajouter** met ce que vous jouez avec les notes déjà là. **remplacer** enlève les notes que la tête de lecture croise à partir de votre première note, donc il reste ce que vous avez joué. Dans les deux cas, la prise compte pour une seule étape d’annulation."),
            ManualBlock(ManualKind.Bullet, "**départ** - **à la lecture** enregistre dès que vous appuyez sur jouer. **1re note** attend : armez, puis jouez une note et le morceau démarre avec elle, sans décompte."),
            ManualBlock(ManualKind.Bullet, "**passages** - **boucle** continue d’enregistrer en boucle jusqu’à ce que vous arrêtiez. **une fois** arrête l’enregistrement après un passage du clip et le laisse jouer."),
            ManualBlock(ManualKind.Heading, "morceaux"),
            ManualBlock(ManualKind.Para, "Ce avec quoi un nouveau morceau commence : le tempo, le chiffrage, la machine de la première piste, et s’il commence avec une gamme réglée."),
            ManualBlock(ManualKind.Heading, "TalkBack", ""),
            ManualBlock(ManualKind.Para, "TalkBack s’active dans les réglages du téléphone. Quand il est actif, chaque commande dit ce qu’elle est et à quoi elle est réglée. Sur un bouton ou un curseur, balayez vers le haut ou le bas pour le changer. Tout ce que vous maintiendriez pour l’ouvrir, comme les réglages d’un clip, est dans le menu d’actions de TalkBack.", ""),
            ManualBlock(ManualKind.Para, "La grille de notes dit combien de notes a un clip, ainsi que la plus basse et la plus haute, mais pas chaque note. Pour ajouter des notes, enregistrez-les depuis le clavier.", ""),
            ManualBlock(ManualKind.Para, "Avec TalkBack actif, la grille du morceau montre autant de scènes qu’il en entre et ne défile pas de côté. **Scènes précédentes** et **Scènes suivantes** au-dessus avancent d’une page à la fois. Quand la dernière page est pleine, ajoutez une scène depuis le menu d’une scène.", ""),
        )),
        ManualSection("Un clavier", "", listOf(
            ManualBlock(ManualKind.Para, "Acidulous fonctionne avec un clavier intégré, USB ou Bluetooth.", "Acidulous fonctionne avec le clavier de l’ordinateur."),
            ManualBlock(ManualKind.Para, "Appuyez sur **Maj+/** (ou **Alt+Q**) n’importe quand pour voir les touches qui fonctionnent sur l’écran où vous êtes."),
            ManualBlock(ManualKind.Heading, "Mode jeu"),
            ManualBlock(ManualKind.Para, "Les lettres lancent soit des raccourcis, soit des notes. **`** (ou **Sym**) passe de l’un à l’autre, tout comme toucher le numéro d’octave dans la bande du clavier de l’éditeur. Le numéro est allumé quand les lettres jouent des notes.", "Les lettres lancent soit des raccourcis, soit des notes. **`** (ou **Sym**) passe de l’un à l’autre, tout comme cliquer le numéro d’octave dans la bande du clavier de l’éditeur. Le numéro est allumé quand les lettres jouent des notes."),
            ManualBlock(ManualKind.Para, "En mode jeu :"),
            ManualBlock(ManualKind.Bullet, "**A S D F G H J K L** sont les touches blanches, et **W E T Y U O P** les touches noires entre elles, comme sur un piano. A est un C."),
            ManualBlock(ManualKind.Bullet, "**Z** et **X** descendent et montent d’une octave. Dans l’éditeur, elles déplacent aussi le clavier à l’écran."),
            ManualBlock(ManualKind.Bullet, "**C** et **V** rendent les notes plus douces et plus fortes."),
            ManualBlock(ManualKind.Bullet, "Maj joue une note une octave plus haut."),
            ManualBlock(ManualKind.Para, "Les notes vont à la piste du dernier clip que vous avez ouvert, comme avec un clavier MIDI, donc elles s’enregistrent et l’accord, la gamme et l’arpège de la piste s’appliquent. Sur une boîte à rythmes, les touches sont ses pads, dans l’ordre."),
            ManualBlock(ManualKind.Para, "Espace joue et arrête toujours, et tout ce qui utilise Ctrl ou Alt fonctionne toujours comme raccourci."),
            ManualBlock(ManualKind.Subheading, "Disposition tracker"),
            ManualBlock(ManualKind.Para, "Un clavier complet a de la place pour deux octaves. Choisissez **tracker** sous **notes** dans la fenêtre des touches (voir **Changer les touches** plus bas) :"),
            ManualBlock(ManualKind.Bullet, "**Z** à **/** est l’octave du bas, avec **S D G H J** comme touches noires."),
            ManualBlock(ManualKind.Bullet, "**Q** à **P** est l’octave du haut, avec la rangée des chiffres comme touches noires."),
            ManualBlock(ManualKind.Bullet, "**-** et **=** changent l’octave, et **[** et **]** la force de frappe."),
            ManualBlock(ManualKind.Heading, "Raccourcis"),
            ManualBlock(ManualKind.Bullet, "jouer / arrêter - **Espace**"),
            ManualBlock(ManualKind.Bullet, "enregistrer - **R**, ou **Alt+R**"),
            ManualBlock(ManualKind.Bullet, "boucle - **L**, ou **Alt+L**"),
            ManualBlock(ManualKind.Bullet, "annuler - **Ctrl+Z**, ou **Alt+Z**"),
            ManualBlock(ManualKind.Bullet, "rétablir - **Ctrl+Maj+Z**, ou **Alt+Y**"),
            ManualBlock(ManualKind.Bullet, "tout arrêter - **Ctrl+.**, ou **Alt+P**"),
            ManualBlock(ManualKind.Bullet, "le clavier joue des notes - **`**, ou **Sym**"),
            ManualBlock(ManualKind.Bullet, "sauvegarder - **Ctrl+S**, ou **Alt+S**"),
            ManualBlock(ManualKind.Bullet, "menu fichier - **F**, ou **Alt+F**"),
            ManualBlock(ManualKind.Bullet, "pages mixage et performance - **M**, ou **Alt+M**"),
            ManualBlock(ManualKind.Bullet, "manuel - **F1**, ou **Alt+H**"),
            ManualBlock(ManualKind.Bullet, "la liste des touches - **Maj+/**, ou **Alt+Q**"),
            ManualBlock(ManualKind.Bullet, "retour - **Échap**"),
            ManualBlock(ManualKind.Bullet, "", "plein écran - **F11**"),
            ManualBlock(ManualKind.Para, "Dans l’éditeur :"),
            ManualBlock(ManualKind.Bullet, "page précédente / suivante - **[ et ]**, ou **Alt+B et Alt+N**"),
            ManualBlock(ManualKind.Bullet, "piste précédente / suivante - **Maj+[ et Maj+]**"),
            ManualBlock(ManualKind.Bullet, "dessiner ou sélectionner - **D**, ou **Alt+D**"),
            ManualBlock(ManualKind.Bullet, "vue des pas - **T**, ou **Alt+T**"),
            ManualBlock(ManualKind.Bullet, "verrouiller les pas - **K**, ou **Alt+K**"),
            ManualBlock(ManualKind.Bullet, "générer des notes - **G**, ou **Alt+G**"),
            ManualBlock(ManualKind.Bullet, "quantifier - **Q**, ou **Alt+U**"),
            ManualBlock(ManualKind.Bullet, "replier le panneau - **P**, ou **Alt+V**"),
            ManualBlock(ManualKind.Bullet, "replier le clavier - **B**, ou **Alt+J**"),
            ManualBlock(ManualKind.Para, "La première touche est pour un clavier complet et la deuxième pour un petit. Les touches sans Alt ni Ctrl ne servent de raccourcis que lorsque le mode jeu est désactivé."),
            ManualBlock(ManualKind.Para, "Dans une fenêtre à onglets, page précédente et page suivante passent d’un onglet à l’autre."),
            ManualBlock(ManualKind.Heading, "Se déplacer"),
            ManualBlock(ManualKind.Para, "Les flèches, ou des balayages sur un pavé tactile, passent d’une commande à l’autre. Tab et Maj+Tab aussi, et un anneau montre où vous êtes. **Entrée** appuie sur un bouton ou un interrupteur.", "Les flèches passent d’une commande à l’autre. Tab et Maj+Tab aussi, et un anneau montre où vous êtes. **Entrée** appuie sur un bouton ou un interrupteur."),
            ManualBlock(ManualKind.Para, "Sur un bouton rotatif ou un curseur, **Entrée** le saisit et l’anneau devient rose. Les flèches le tournent alors, Maj+flèches le tournent finement, Pg préc et Pg suiv à grands pas, et Origine et Fin vont à l’un ou l’autre bout. **Entrée** ou **Échap** le relâche. **+** et **-** tournent un bouton sans le saisir."),
            ManualBlock(ManualKind.Para, "Tout ce que vous maintiendriez offre les mêmes choix avec **Alt+Entrée** ou la touche Menu, comme les réglages d’un clip, le menu d’une scène ou la liste des valeurs d’un bouton."),
            ManualBlock(ManualKind.Para, "Une fenêtre ouverte au clavier vous place sur sa première commande, et **Échap** la ferme."),
            ManualBlock(ManualKind.Heading, "Dans l’éditeur"),
            ManualBlock(ManualKind.Para, "La grille de notes, les couloirs de notes en dessous et les couloirs d’automatisation prennent chacun **Entrée** pour commencer à modifier, et un curseur rose apparaît. **Échap** arrête."),
            ManualBlock(ManualKind.Para, "Dans la grille de notes :"),
            ManualBlock(ManualKind.Bullet, "les flèches déplacent le curseur d’un pas de grille, ou d’un demi-ton. Pg préc et Pg suiv le déplacent d’une octave."),
            ManualBlock(ManualKind.Bullet, "**Entrée** ajoute ou enlève une note, comme un toucher. **Suppr** enlève la note sous le curseur.", "**Entrée** ajoute ou enlève une note, comme un cliquer. **Suppr** enlève la note sous le curseur."),
            ManualBlock(ManualKind.Bullet, "**Maj+Gauche** et **Maj+Droite** raccourcissent et allongent la note sous le curseur."),
            ManualBlock(ManualKind.Bullet, "**Alt** et une flèche déplacent la note avec le curseur."),
            ManualBlock(ManualKind.Para, "Dans un couloir de notes, Gauche et Droite vont de note en note, et Haut et Bas changent la valeur de la note, finement avec Maj. Quand les paroles sont affichées, Entrée les ouvre."),
            ManualBlock(ManualKind.Para, "Dans un couloir d’automatisation, Gauche et Droite avancent d’un pas de grille, et Haut et Bas règlent la valeur à cet endroit, en ajoutant un point s’il n’y en a pas."),
            ManualBlock(ManualKind.Para, "Chaque changement est une étape d’annulation, comme au toucher.", "Chaque changement est une étape d’annulation, comme au cliquer."),
            ManualBlock(ManualKind.Heading, "Une manette de jeu"),
            ManualBlock(ManualKind.Para, "Les boutons d’une manette fonctionnent comme les touches, donc l’appli peut s’utiliser sans toucher l’écran, sur une console portable comme la Retroid Pocket.", "Les boutons d’une manette fonctionnent comme les touches, donc l’appli peut s’utiliser sans cliquer l’écran, sur une console portable comme la Retroid Pocket."),
            ManualBlock(ManualKind.Bullet, "**croix directionnelle** - passe d’une commande à l’autre, et déplace le curseur dans l’éditeur."),
            ManualBlock(ManualKind.Bullet, "**A** - appuie, comme Entrée. Sur un bouton rotatif, il le saisit, la croix le tourne, et **A** de nouveau le relâche."),
            ManualBlock(ManualKind.Bullet, "**B** - retour : ferme une fenêtre, ou quitte l’éditeur."),
            ManualBlock(ManualKind.Bullet, "**X** - ce que fait un appui long : la liste d’actions d’une commande."),
            ManualBlock(ManualKind.Bullet, "**Y** - jouer / arrêter."),
            ManualBlock(ManualKind.Bullet, "**L1** et **R1** - page précédente et suivante dans l’éditeur, et les onglets d’une fenêtre."),
            ManualBlock(ManualKind.Bullet, "**L2** et **R2** - piste précédente et suivante dans l’éditeur."),
            ManualBlock(ManualKind.Bullet, "**Start** - mode jeu."),
            ManualBlock(ManualKind.Bullet, "**Select** - le menu fichier."),
            ManualBlock(ManualKind.Bullet, "**stick gauche** - tourne le bouton ou le curseur en surbrillance, d’autant plus vite qu’il est poussé loin. Une poussée est une étape d’annulation."),
            ManualBlock(ManualKind.Bullet, "**stick droit** - une croix rapide : plus il est poussé loin, plus il va vite."),
            ManualBlock(ManualKind.Para, "Si rien n’est en surbrillance, le premier appui sur la croix ou sur **A** met quelque chose en surbrillance pour commencer."),
            ManualBlock(ManualKind.Para, "**Start** active et désactive le mode jeu. En mode jeu, la manette est un instrument pour la piste que joue le MIDI :"),
            ManualBlock(ManualKind.Bullet, "la **croix directionnelle** et les quatre boutons sont huit notes de la gamme de la piste (sa puce de gamme, ou la tonalité du morceau, sinon majeur), dans le sens horaire à partir du bas pour chacun : la croix a les quatre premières, les boutons les quatre suivantes. Sur une boîte à rythmes, ce sont ses huit premiers pads."),
            ManualBlock(ManualKind.Bullet, "**L1** et **R1** changent l’octave."),
            ManualBlock(ManualKind.Bullet, "le **stick droit** plie la hauteur de côté et ajoute de la modulation vers le haut, et le **stick gauche** poussé vers le haut donne la pression."),
            ManualBlock(ManualKind.Bullet, "tirez **R2** ou **L2** en partie pendant que vous jouez pour régler la force des notes."),
            ManualBlock(ManualKind.Bullet, "**Select** joue et arrête, car **Y** est une note."),
            ManualBlock(ManualKind.Heading, "Changer les touches"),
            ManualBlock(ManualKind.Para, "**Réglages › affichage › clavier › touches…** liste chaque raccourci avec ses touches, et chacun peut en avoir deux. Touchez une touche, ou allez-y et appuyez sur Entrée, puis appuyez sur la nouvelle touche ou combinaison. **+** ajoute une deuxième touche.", "**Réglages › affichage › clavier › touches…** liste chaque raccourci avec ses touches, et chacun peut en avoir deux. Cliquez une touche, ou allez-y et appuyez sur Entrée, puis appuyez sur la nouvelle touche ou combinaison. **+** ajoute une deuxième touche."),
            ManualBlock(ManualKind.Para, "Si la nouvelle touche appartenait déjà à autre chose, elle change de place, et la fenêtre vous dit ce qui l’a perdue. **Alt+Entrée** sur une touche la retire. **par défaut** remet toutes les touches comme elles étaient."),
            ManualBlock(ManualKind.Para, "La carte **manette** liste les boutons d’une manette et ce que fait chacun. Touchez-en un pour choisir dans une liste : **appuyer**, **retour**, **liste d’actions**, **rien**, ou n’importe quel raccourci. **par défaut** remet ceux-ci aussi. Les notes du mode jeu restent où elles sont.", "La carte **manette** liste les boutons d’une manette et ce que fait chacun. Cliquez-en un pour choisir dans une liste : **appuyer**, **retour**, **liste d’actions**, **rien**, ou n’importe quel raccourci. **par défaut** remet ceux-ci aussi. Les notes du mode jeu restent où elles sont."),
        )),
    )
}
